require 'procCondCommon'

-- 特定バフ付与
-- params[1]:バフ継続時間
-- params[2]:バフID
function process100(_target, params)
	Field:FrameUpdate(_target)
	target:SetBuff(params[2], {params[1]})
end

-- 指定スコア増減
-- params[1]:スコアID
-- params[2]:スコア変動値
function process101(_target, params)
local sc
	Field:FrameUpdate(_target)
	sc = Field:GetScore(params[1])
	sc:Add(params[2])
end

-- STRアップ物理攻撃
-- params[1]:STR加算値
-- params[2]:STR倍率
-- params[3]:ダメージ倍率
function process10001(_target, params)
	Field:FrameUpdate(_target)
	Bullet:EditSTR(params[1], params[2])
	Bullet:Damage(DAMAGE_TYPE_PHYSICAL, params[3])
end

-- 魔法剣（INTの一部をSTR加算に加算した状態で物理攻撃を行う。INTはSTR倍率を掛けた後に乗せる）
-- params[1]:STR加算値
-- params[2]:STR倍率
-- params[3]:INT倍率
-- params[4]:ダメージ倍率
-- params[5]:アリーナダメージ倍率
function process10002(_target, params)
	Field:FrameUpdate(_target)
	Bullet:EditINT(0, params[3], 0)
	Bullet:EditSTR(params[1], params[2], Bullet:INT())
	if Field:IsPvP() and params[5] ~= 0 then
		Bullet:Damage(DAMAGE_TYPE_PHYSICAL, params[5])
	else
		Bullet:Damage(DAMAGE_TYPE_PHYSICAL, params[4])
	end
end

-- STRアップ物理攻撃(演出付き)
-- params[1]:STR加算値
-- params[2]:STR倍率
-- params[3]:ダメージ倍率
-- params[4]:演出番号
function process10003(_target, params)
	Field:FrameUpdate(_target)
	Bullet:EditSTR(params[1], params[2])
	if params[4]~=0 then Process:PlayTimeline(params[4]) end
	Bullet:Damage(DAMAGE_TYPE_PHYSICAL, params[3])
end

-- 物魔切り替え魔法剣（INTの一部をSTR加算に加算した状態で攻撃を行う。INTはSTR倍率を掛けた後に乗せる。対象のDEF>MNDの場合は魔法攻撃、DEF<=MNDの場合は物理攻撃となる）
-- params[1]:STR加算値
-- params[2]:STR倍率
-- params[3]:INT倍率
-- params[4]:ダメージ倍率
-- params[5]:アリーナダメージ倍率
function process10004(_target, params)
	Field:FrameUpdate(_target)
	Bullet:EditINT(0, params[3], 0)
	Bullet:EditSTR(params[1], params[2], Bullet:INT())
	if Field:IsPvP() and params[5] ~= 0 then params[4] = params[5] end
	if Bullet:Target():DEF() > Bullet:Target():MND() then
		Bullet:Damage(DAMAGE_TYPE_PHYSICAL, params[4], STATUS_TYPE_STR, STATUS_TYPE_MND)
	else
		Bullet:Damage(DAMAGE_TYPE_PHYSICAL, params[4])
	end
end

