-- params[4]:INT加算値
-- params[5]:INT倍率
-- params[6]:ダメージ倍率
-- params[7]:演出レベル
function process10104(_target, params)
	Field:FrameUpdate(_target)
	if params[2] ~= 0 and target:SetBuff(DebuffIds.ElementEdgeFire + params[2] - 1, params, nil, MISS_TYPE_BUFF) and params[7] > 0 then Process:PlayTimeline(5 + params[2] - 1) end
end

-- 記憶HP使用魔法攻撃
-- params[1]:INT倍率
-- params[2]:記憶HP倍率
-- params[3]:記憶HP補正後INT加算値
-- params[4]:記憶HP補正後INT倍率
-- params[5]:ダメージ倍率
-- params[6]:アリーナダメージ倍率
function process10105(_target, params)
local val
	Field:FrameUpdate(_target)
	Bullet:EditINT(0, params[1])
	val = round((((Bullet:Parent():GetValue(UNIT_VALUE_SUDDEN_DEATH_HP) or 0) * params[2] * Per2Num) + params[3] + Bullet:INT()) * (1 + (params[4] * Per2Num)))
	Bullet:EditINT(0, 0, val)
	if Field:IsPvP() and params[6] ~= 0 then
		Bullet:Damage(DAMAGE_TYPE_MAGICAL, params[6])
	else
		Bullet:Damage(DAMAGE_TYPE_MAGICAL, params[5])
	end
end

-- 弱点属性刃
-- params[1]:継続時間
-- params[2]:属性耐性増減値
-- params[3]:INT加算値
-- params[4]:INT倍率
-- params[5]:ダメージ倍率
-- params[6]:演出レベル
function process10106(_target, params)
local elem, val = {}, math.maxinteger
	Field:FrameUpdate(_target)
	for i = ELEMENT_FIRE, ELEMENT_DARK do
		if target:ElemResist(i) < val then
			elem = {i}
			val = target:ElemResist(i)
		elseif target:ElemResist(i) == val then
			table.insert(elem, i)
		end
	end
	elem = elem[math.random(1, #elem)]
	if target:SetBuff(DebuffIds.ElementEdgeFire + ELEMENT_STRONG[elem] - 1, {params[1], ELEMENT_STRONG[elem], params[2], params[3], params[4], params[5], params[6]}, nil, MISS_TYPE_BUFF) and params[6] > 0 then Process:PlayTimeline(5 + ELEMENT_STRONG[elem] - 1) end
end

