	Field:FrameUpdate(_target)
	if params[2] ~= 0 and target:SetBuff(DebuffIds.ElementEdgeFour, {params[1], params[7], params[2], params[3], params[4], params[5], params[6]}, nil, MISS_TYPE_DEBUFF) and params[6] > 0 then Process:PlayTimeline(5) end
end

