-- SCT増減
-- params[1]:SCT増減値
-- params[2]:SCT増減倍率
-- params[3]:SCT増減倍率(1ストック)
-- params[4]:演出レベル
function process20200(_target, params)
local add = 0
local res = false
	Field:FrameUpdate(_target)
	for i = 1, target:SkillCount(SKILL_SKILL) do
		add = math.ceil((params[3] / Pct100) * (target:SKL_Cost(SKILL_SKILL, i) / 1000))
		res = target:EditSingleSCT(TARGSTAT_REAL, params[1] + add, params[2], i) or res
	end
	if res then Process:PlayTimelineLv(params[4], false, target, target) end
end

-- 薄っぺらな言葉
-- params[1]:SCT増減値
-- params[2]:SCT増減倍率
-- params[3]:SCT増減倍率(1ストック)
-- params[4]:演出レベル
function process20201(_target, params)
	Field:FrameUpdate(_target)
	if target:SetBuff(BuffIds.Gen_SctRecover, {-1, params[1], params[2], params[3]}, nil, MISS_TYPE_BUFF) and params[4] > 0 then Process:PlayTimelineLv(params[4]) end
end

-- 単独SCT回復
-- params[1]:特技INDEX
-- params[2]:回復値
-- params[3]:回復倍率
-- params[4]:回復倍率(1ストック)
-- params[5]:回復値(ストック補完)
function process20202(_target, params)
local skl
local add = 0
	Field:FrameUpdate(_target)
	if params[1] > 0 then
		skl = target:GetSkillFromIndexUI(params[1])
		if skl~= nil then
			add = math.ceil((params[4] / Pct100) * (skl:Cost() / 1000) + math.max((params[5] - (skl:Charge() * 1000) / skl:Cost()) * (skl:Cost() / 1000), 0))
			target:EditSingleSCT(TARGSTAT_REAL, params[2] + add, params[3], skl:Index())
		end
	elseif params[1] == 0 then
		for i = 1, target:SkillCount(SKILL_SKILL) do
			add = math.ceil((params[4] / Pct100) * (target:SKL_Cost(SKILL_SKILL, i) / 1000) + math.max((params[5] - (target:SKL_Charge(SKILL_SKILL, i) * 1000) / target:SKL_Cost(SKILL_SKILL, i)) * (target:SKL_Cost(SKILL_SKILL, i) / 1000), 0))
			target:EditSingleSCT(TARGSTAT_REAL, params[2] + add, params[3], i)
		end
	elseif params[1] == -1 then
		skl = target:GetSkill(SKILL_SKILL, math.random(1, target:SkillCount(SKILL_SKILL)))
		if skl~= nil then
			add = math.ceil((params[4] / Pct100) * (skl:Cost() / 1000) + math.max((params[5] - (skl:Charge() * 1000) / skl:Cost()) * (skl:Cost() / 1000), 0))
			target:EditSingleSCT(TARGSTAT_REAL, params[2] + add, params[3], skl:Index())
		end
	end
end

