		elseif params[5] < 0 or params[6] < 0 then
			if target:SetBuff(DebuffIds.IntEdit, {params[4], round(params[5] * coe), round(params[6] * coe)}, nil, MISS_TYPE_DEBUFF) then Process:PlayTimelineLv(params[7], true) end
		end
	end
end

