-- 特技ストック数増減
-- params[1]:WAVE毎制限回数
-- params[2]:クエスト毎制限回数
-- params[3]:特技INDEX
-- params[4]:ストック増減値
function process32300(_target, params)
Field:FrameUpdate(_target)
local skl
local cnt = Process:GetKeptParam(1) or 0
local qcnt = Process:GetKeptParam(2, true) or 0
	if (params[1] <= 0 or cnt < params[1]) and (params[2] <= 0 or qcnt < params[2]) then
		if params[3] == 0 then
			target:SetBuff(BuffIds.P_MaxSpEdit, {-1, params[4]})
		else
			skl = target:GetSkillFromIndexUI(params[3])
			if skl ~= nil then
				target:SetBuff(BuffIds.P_MaxSpEdit, {-1, params[4], skl:Index()})
			end
		end
		Process:KeepParam(1, 1, CALCULATE_ADD)
		Process:KeepParam(2, 1, CALCULATE_ADD, true)
	end
end

-- トランス
-- params[1]:継続時間
-- params[2]:汎用数値情報INDEX
-- params[3]:演出レベル
function process32600(_target, params)
local buid, cost
	Field:FrameUpdate(_target)
	cost = target:MP()
	if Bullet:SKL_Type(SKILL_MAGIC) then
		cost = cost + math.max(Bullet:SKL_BeforeCost() - Bullet:SKL_AfterCost(), 0)
	end
	if target:DecMp(0, Pct100) then
		buid = target:SetBuff(BuffIds.Trance, {params[1]})
		if buid then if params[2] ~= 0 then target:SetGeneralCount(params[2], cost) end Process:PlayTimelineLv(params[3]) end
	end
end

-- 特定の状態異常を付与する
-- params[1]:状態異常種類
-- params[2]:状態異常継続時間補正値
-- params[3]:状態異常継続時間倍率
function process40000(_target, params)
	Field:FrameUpdate(_target)
	if params[2]==0 and params[3]==0 then
		target:SetAilment(params[1], nil, true)
	else
		-- 状態異常継続時間の変動を可能にするため、外部プロセスからのみ渡せる継続時間補正パラメータを加味して計算する
		target:SetAilment(params[1], math.max(math.floor((AilmentLifeTimes[params[1]] + params[2]) * (1 + (params[3] * Per2Num))), 1), true)
	end
end

-- 予め決められたランダム効果を付与する
-- params[1]:状態異常継続時間補正値
-- params[2]:状態異常継続時間倍率
-- params[3]:即死確率
-- params[4]:HP吸収倍率
-- params[5]:MPダメージMIN
-- params[6]:MPダメージMAX
function process40001(_target, params)
local t = {1, 2, 3}
local ope, ailment
	Field:FrameUpdate(_target)
	if params[3] ~= 0 then table.insert(t, 4) end
	if params[4] ~= 0 then table.insert(t, 5) end
	if params[5] ~= 0 or params[6] ~= 0 then table.insert(t, 6) end
	ope = t[math.random(1, #t)]
	if ope <= 3 then
		ailment = (ope==1 and AILMENT_RAGE or ope==2 and AILMENT_POISON or AILMENT_BLIND)
		if params[1]==0 and params[2]==0 then
			target:SetAilment(ailment, nil, true)
		else
			-- 状態異常継続時間の変動を可能にするため、外部プロセスからのみ渡せる継続時間補正パラメータを加味して計算する
			target:SetAilment(ailment, math.max(math.floor((AilmentLifeTimes[ailment] + params[1]) * (1 + (params[2] * Per2Num))), 1), true)
		end
	elseif ope == 4 then
		if not Field:IsPvP() and not Bullet:Target():IsBoss() and lottery(params[3]) then target:Kill() end
	elseif ope == 5 then
		Bullet:Drain(params[4])
	elseif ope == 6 then
		target:FixMpDamage(params[5], params[6])
	end
end

-- 予め決められたランダム効果を付与する(ルナティック)
-- params[1]:全基本ステータスデバフ倍率
-- params[2]:HP回復時MDEF加算値
-- params[3]:HP回復時MDEF倍率
-- params[4]:HP回復時回復最低値
-- params[5]:HP回復時回復倍率
-- params[6]:MP回復時回復値
-- params[7]:MP回復時回復割合
-- params[8]:状態異常種類
-- params[9]:状態異常継続時間補正値
-- params[10]:状態異常継続時間倍率
function process40002(_target, params)
local t = {1, 2, 3, 4}
local ope
	Field:FrameUpdate(_target)
	ope = t[math.random(1, #t)]
	if ope == 1 then
		if params[9]==0 and params[10]==0 then
			for i,u in pairs(units:GetCondUnitList(TARGET_SIDE_ALL, TARGET_COND_ALIVE, UNIT_COND_NONE)) do
				u:SetAilment(params[8], nil, true)
			end
		else
			for i,u in pairs(units:GetCondUnitList(TARGET_SIDE_ALL, TARGET_COND_ALIVE, UNIT_COND_NONE)) do
				-- 状態異常継続時間の変動を可能にするため、外部プロセスからのみ渡せる継続時間補正パラメータを加味して計算する
				u:SetAilment(params[8], math.max(math.floor((AilmentLifeTimes[params[8]] + params[9]) * (1 + (params[10] * Per2Num))), 1), true)
			end
		end
	elseif ope == 2 then
		for i,u in pairs(units:GetCondUnitList(TARGET_SIDE_OPPONENT, TARGET_COND_ALIVE, UNIT_COND_NONE)) do
			u:SetBuff(DebuffIds.StrEdit, {2400, 0, params[1]}, nil, MISS_TYPE_DEBUFF)
			u:SetBuff(DebuffIds.DefEdit, {2400, 0, params[1]}, nil, MISS_TYPE_DEBUFF)
			u:SetBuff(DebuffIds.IntEdit, {2400, 0, params[1]}, nil, MISS_TYPE_DEBUFF)
			u:SetBuff(DebuffIds.MndEdit, {2400, 0, params[1]}, nil, MISS_TYPE_DEBUFF)
		end
	elseif ope == 3 then
		this:SwitchSource(TARGSTAT_WORK_LOCAL)
		this:EditMND(TARGSTAT_WORK_LOCAL, params[2], params[3], 0, LIFETYPE_TRANSIENT)
		for i,u in pairs(units:GetCondUnitList(TARGET_SIDE_ALL, TARGET_COND_ALIVE, UNIT_COND_NONE)) do
			this:Heal(u, params[4], params[5])
		end
	elseif ope == 4 then
		this:SwitchSource(TARGSTAT_REAL)
		this:HealMp(this, params[6], params[7])
	end
end

-- 特定の状態異常を二択で付与する
-- params[1]:状態異常種類1抽選確率
-- params[2]:状態異常種類1
-- params[3]:状態異常種類2
-- params[4]:状態異常継続時間補正値
-- params[5]:状態異常継続時間倍率
function process40003(_target, params)
local ailment = lottery(params[1]) and params[2] or params[3]
	Field:FrameUpdate(_target)
	if ailment == 0 then ailment = math.random(AILMENT_POISON, AILMENT_SILENCE) end
	if params[4]==0 and params[5]==0 then
		target:SetAilment(ailment, nil, true)
	else
		-- 状態異常継続時間の変動を可能にするため、外部プロセスからのみ渡せる継続時間補正パラメータを加味して計算する
		target:SetAilment(ailment, math.max(math.floor((AilmentLifeTimes[ailment] + params[4]) * (1 + (params[5] * Per2Num))), 1), true)
	end
end

