-- 特定の状態異常を回復する
-- params[1]:状態異常種類
function process40100(_target, params)
	Field:FrameUpdate(_target)
	if params[1] <= AILMENT_SILENCE then
		Process:PlayTimeline(params[1] + 5)
	else
		Process:PlayTimeline(5)
	end
	target:RemoveAilment(params[1], true)
end

-- 状態異常を複数回復する
-- params[n]:状態異常種類
function process40101(_target, params)
	Field:FrameUpdate(_target)
	for i,j in ipairs(params) do
		if j==0 then return 1 end
		if i==6 then Process:PlayTimeline(12) end
		target:RemoveAilment(j, true)
	end
end

-- 基本状態異常ランダム回復・耐性
-- params[1]:継続時間
-- params[2]:増減段階
-- params[3]:演出レベル
function process40102(_target, params)
local tbl = {}
local ailment
	Field:FrameUpdate(_target)
	for i,j in pairs(AILMENT_COMMON) do
		if target:IsAilment(j) then table.insert(tbl, j) end
	end
	if #tbl >= 1 then
		ailment = tbl[math.random(1, #tbl)]
		Process:SubProc(1, target, Pct100, {ailment})
		Process:SubProc(2, target, Pct100, {params[1], ailment, params[2], 0})
		if params[3] > 0 then Process:PlayTimeline(5) end
	end
end

-- カリスマ(ローランド)を付与
-- params[1]:STR加算値
-- params[2]:STR倍率
-- params[3]:INT加算値
-- params[4]:INT倍率
function process40300(_target, params)
local buid
	Field:FrameUpdate(_target)
	if this:Alive() then
		buid = target:SetBuff(BuffIds.C_Roland, {-1, params[1], params[2], params[3], params[4]}, nil, MISS_TYPE_BUFF)
		if buid then
			if target:ID()==this:ID() then
				target:SetBuff(BuffIds.C_AppendControl, {-1, buid, BuffIds.C_Roland, params[1], params[2], params[3], params[4]})
			else
				for i,j in pairs(target:GetBuff()) do
					if j[BUFF_INFO_CATEGORY] == BUFF_CATEGORY_CHARISMA_CONTROL_2 then
						target:ExpireBuff(j[BUFF_INFO_UID])
						break
					end
				end
			end
			target:SetBuff(BuffIds.C_Control, {-1, this:ID(), buid})
			Process:PlayTimeline(5)
		end
	end
end

