-- アニマ(ログシウス)を付与
-- params[1]:MND加算値
-- params[2]:MND倍率
function process40308(_target, params)
Field:FrameUpdate(_target)
local bCtrl = Field:GetValue(FIELD_VALUE_ANIMA_CONTROL_INFO)
local buid, cuid, flag
	if this:Alive() then
		buid = target:SetBuff(DebuffIds.C_Lougseus, {-1, params[1], params[2]}, nil, MISS_TYPE_DEBUFF)
		if buid then
			flag = false
			if isTableOrClass(bCtrl) then
				if bCtrl[1] ~= nil and bCtrl[2] ~= nil and bCtrl[1] ~= this:ID() then
					Field:ExpireBuff(bCtrl[2])
				elseif bCtrl[1] == this:ID() then
					flag = true
				end
			end
			if not flag then
				cuid = this:SetBuff(BuffIds.C_AnimaAppendControl, {-1, DebuffIds.C_Lougseus, params[1], params[2]})
				if cuid then
					Field:SetValue(FIELD_VALUE_ANIMA_CONTROL_INFO, {this:ID(), cuid})
				end
			end
			target:SetBuff(BuffIds.C_AnimaControl, {-1, this:ID(), buid})
			Process:PlayTimeline(6)
		end
	end
end

