-- params[2]:最大HP倍率補正
-- params[3]:物理攻撃ダメージ倍率
function process40352(_target, params)
local buid
	Field:FrameUpdate(_target)
	if this:Alive() then
		buid = target:SetBuff(BuffIds.C_Ainz, {-1, params[1], params[2], params[3]}, nil, MISS_TYPE_BUFF)
		if buid then
			if target:ID()==this:ID() then
				target:SetBuff(BuffIds.C_AppendControl, {-1, buid, BuffIds.C_Ainz, params[1], params[2], params[3]})
			else
				for i,j in pairs(target:GetBuff()) do
					if j[BUFF_INFO_CATEGORY] == BUFF_CATEGORY_CHARISMA_CONTROL_2 then
						target:ExpireBuff(j[BUFF_INFO_UID])
						break
					end
				end
			end
			target:SetBuff(BuffIds.C_Control, {-1, this:ID(), buid})
			Process:PlayTimeline(5)
		end
	end
end

-- アニマ(ロナード)を付与
-- params[1]:SCT自動回復加算値
-- params[2]:SCT自動回復倍率
-- params[3]:氷属性被ダメージ倍率
-- params[4]:氷属性被ダメージ上限増減値
-- params[5]:氷属性被ダメージ上限増減倍率
function process40353(_target, params)
Field:FrameUpdate(_target)
local bCtrl = Field:GetValue(FIELD_VALUE_ANIMA_CONTROL_INFO)
local buid, cuid, flag
	if this:Alive() then
		buid = target:SetBuff(DebuffIds.C_Lonardo, {-1, params[1], params[2], params[3], params[4], params[5]}, nil, MISS_TYPE_DEBUFF)
		if buid then
			flag = false
			if isTableOrClass(bCtrl) then
				if bCtrl[1] ~= nil and bCtrl[2] ~= nil and bCtrl[1] ~= this:ID() then
					Field:ExpireBuff(bCtrl[2])
				elseif bCtrl[1] == this:ID() then
					flag = true
				end
			end
			if not flag then
				cuid = this:SetBuff(BuffIds.C_AnimaAppendControl, {-1, DebuffIds.C_Lonardo, params[1], params[2], params[3], params[4], params[5]})
				if cuid then
					Field:SetValue(FIELD_VALUE_ANIMA_CONTROL_INFO, {this:ID(), cuid})
				end
			end
			target:SetBuff(BuffIds.C_AnimaControl, {-1, this:ID(), buid})
			Process:PlayTimeline(5)
		end
	end
end

