function process40371(_target, params)
Field:FrameUpdate(_target)
local bCtrl = Field:GetValue(FIELD_VALUE_ANIMA_CONTROL_INFO)
local buid, cuid, flag
	if this:Alive() then
		buid = target:SetBuff(DebuffIds.C_Kyna, {-1, params[1], params[2], params[3]}, nil, MISS_TYPE_DEBUFF)
		if buid then
			flag = false
			if isTableOrClass(bCtrl) then
				if bCtrl[1] ~= nil and bCtrl[2] ~= nil and bCtrl[1] ~= this:ID() then
					Field:ExpireBuff(bCtrl[2])
				elseif bCtrl[1] == this:ID() then
					flag = true
				end
			end
			if not flag then
				cuid = this:SetBuff(BuffIds.C_AnimaAppendControl, {-1, DebuffIds.C_Kyna, params[1], params[2], params[3]})
				if cuid then
					Field:SetValue(FIELD_VALUE_ANIMA_CONTROL_INFO, {this:ID(), cuid})
				end
			end
			target:SetBuff(BuffIds.C_AnimaControl, {-1, this:ID(), buid})
			Process:PlayTimeline(6)
		end
	end
end

-- カリスマ(ラダドール)を付与
-- params[1]:被ダメージ倍率
-- params[2]:与ダメージ倍率
-- params[3]:神専用与ダメージ倍率
function process40372(_target, params)
local buid
	Field:FrameUpdate(_target)
	if this:Alive() then
		buid = target:SetBuff(BuffIds.C_RadaDour, {-1, params[1], params[2], params[3]}, nil, MISS_TYPE_BUFF)
		if buid then
			if target:ID()==this:ID() then
				target:SetBuff(BuffIds.C_AppendControl, {-1, buid, BuffIds.C_RadaDour, params[1], params[2], params[3]})
			else
				for i,j in pairs(target:GetBuff()) do
					if j[BUFF_INFO_CATEGORY] == BUFF_CATEGORY_CHARISMA_CONTROL_2 then
						target:ExpireBuff(j[BUFF_INFO_UID])
						break
					end
				end
			end
			target:SetBuff(BuffIds.C_Control, {-1, this:ID(), buid})
			Process:PlayTimeline(5)
		end
	end
end

