-- 最弱点属性変化
function process50702(_target, params)
local elem, val = {}, math.maxinteger
	Field:FrameUpdate(_target)
	for i = ELEMENT_FIRE, ELEMENT_DARK do
		if Bullet:Target():ElemResist(i) < val then
			elem = {i}
			val = Bullet:Target():ElemResist(i)
		elseif Bullet:Target():ElemResist(i) == val then
			table.insert(elem, i)
		end
	end
	elem = elem[math.random(1, #elem)]
	if Bullet:EditElement(elem) then Process:ShowPassive() end
end

