-- 通常ステータスデバフ消去
-- params[1]:消去数
-- params[2]:STRデバフ可否
-- params[3]:DEFデバフ可否
-- params[4]:INTデバフ可否
-- params[5]:MNDデバフ可否
function process80402(_target, params)
local flag, cnt
local cateList = {}
local tbl, ctbl, rtbl = {}, {}, {}
local unq, res = {}, {}
	Field:FrameUpdate(_target)
	if params[2] ~= 0 then table.insert(cateList, BUFF_CATEGORY_STR_DOWN_1) end
	if params[3] ~= 0 then table.insert(cateList, BUFF_CATEGORY_DEF_DOWN_1) end
	if params[4] ~= 0 then table.insert(cateList, BUFF_CATEGORY_INT_DOWN_1) end
	if params[5] ~= 0 then table.insert(cateList, BUFF_CATEGORY_MND_DOWN_1) end
	for i,cate in pairs(cateList) do
		tbl[cate] = {}
		for j,bff in pairs(target:GetBuffCategoryBuffs(cate)) do
			table.insert(tbl[cate], bff[BUFF_INFO_UID])
			flag = false
			for k,r in ipairs(rtbl) do
				if r < bff[BUFF_INFO_REMAIN] then
					table.insert(ctbl, k, cate)
					table.insert(rtbl, k, bff[BUFF_INFO_REMAIN])
					flag = true
					break
				end
			end
			if not flag then
				table.insert(ctbl, cate)
				table.insert(rtbl, bff[BUFF_INFO_REMAIN])
			end
		end
	end
	for i,cate in ipairs(ctbl) do
		if unq[cate] == nil then
			unq[cate] = true
			table.insert(res, 1, cate)
		end
	end
	cnt = 0
	for i,cate in ipairs(res) do
		if params[1] <= 0 or params[1] > cnt then
			for j,buid in pairs(tbl[cate]) do
				target:ExpireBuff(buid)
			end
			cnt = cnt + 1
		else
			break
		end
	end
	Process:PlayTimeline(2)
end

