-- 操作禁止_ルキエル専用
-- params[1]:継続時間
function process81300(_target, params)
local t
local buid
	Field:FrameUpdate(_target)
	buid = target:SetBuff(DebuffIds.P_ForbidMagOrSkill, {params[1], 1})
	if buid then target:SetBuff(BuffIds.S_SkillEndBuffControl, {-1, Bullet:SKL_PUID(), buid}) end
	t = target:GetSkill(SKILL_ARK)
	if #t >= 1 then
		for i, j in pairs(t) do
			buid = target:SetBuff(DebuffIds.P_DisableSkill, {params[1], 1, j:Type(), j:Index()})
			if buid then target:SetBuff(BuffIds.S_SkillEndBuffControl, {-1, Bullet:SKL_PUID(), buid}) end
		end
	end
	t = target:GetSkill(SKILL_SPECIAL)
	if #t >= 1 then
		for i, j in pairs(t) do
			buid = target:SetBuff(DebuffIds.P_DisableSkill, {params[1], 1, j:Type(), j:Index()})
			if buid then target:SetBuff(BuffIds.S_SkillEndBuffControl, {-1, Bullet:SKL_PUID(), buid}) end
		end
	end
end

