-- 精霊力解放
-- params[1]:継続時間
-- params[2]:属性変化発生LV
-- params[3]:与ダメージ倍率MIN
-- params[4]:与ダメージ倍率MAX
-- params[5]:ダメージ上限増減値MIN
-- params[6]:ダメージ上限増減値MAX
-- params[7]:SCT自動回復倍率MIN
-- params[8]:SCT自動回復倍率MAX
-- params[9]:詠唱時間倍率MIN
-- params[10]:詠唱時間倍率MAX
function process81602(_target, params)
Field:FrameUpdate(_target)
local coe
local t = target:GetValue(UNIT_VALUE_ELEMENT_SPIRIT_INFO) or {}
local buid = target:GetValue(UNIT_VALUE_SPIRIT_OVER_DRIVE_CONTROL)
local skl = Bullet:GetParentSkill()
local tl = t[ELEMENT_SPIRIT_INFO_LV]
local te = t[ELEMENT_SPIRIT_INFO_EXP]
local condFunc = newCompare2(COMPARE_ORMORE)
local max_exp, max_elem = 0, 0
	if te ~= nil then
		for i,exp in pairs(te) do
			max_elem, max_exp = condFunc(i, exp)
		end
		if #max_elem > 0 then
			max_elem = max_elem[math.random(1, #max_elem)]
			if tl[max_elem] ~= nil and tl[max_elem] ~= 0 then
				coe = math.max(math.min((tl[max_elem] - 1) / (5 - 1), 1), 0)
				target:SetBuff(BuffIds.SpiritOverDrive[max_elem], {params[1], tl[max_elem] >= params[2] and 1 or 0, params[3] + round((params[4] - params[3]) * coe), params[5] + round((params[6] - params[5]) * coe), 0, 0, params[7] + round((params[8] - params[7]) * coe), params[9] + round((params[10] - params[9]) * coe)}, LIFETYPE_NORMAL, MISS_TYPE_BUFF)
				target:RemoveBuff(BUFF_GROUP_SPIRIT_POWER)
				target:SetValue(UNIT_VALUE_ELEMENT_SPIRIT_INFO, {}, true)
				Process:PlayTimeline(7)
				if skl then
					buid = target:SetBuff(DebuffIds.S_DisableSkill, {-1, skl:Type(), skl:Index()})
					target:SetValue(UNIT_VALUE_SPIRIT_OVER_DRIVE_CONTROL, buid, true)
				end
			end
		end
	end
end

