-- params[8]:Lv3継続時間
-- params[9]:Lv4継続時間
-- params[10]:SA値
function process81619(_target, params)
local buid, lv
	Field:FrameUpdate(_target)
	lv = 0
	for i = 4, 1, -1 do
		if params[i] > 0 then
			for j, buff in pairs(this:GetBuffIdBuffs(params[i])) do
				this:ExpireBuff(buff[BUFF_INFO_UID])
				if lv == 0 then lv = i end
			end
		end
	end
	if lv ~= 0 then buid = target:SetBuff(BuffIds.OverLimits, {params[6 + lv - 1], params[10]}) end
	if buid then if params[5] ~= 0 then target:SetGeneralCount(params[5], lv) end Process:PlayTimeline(5) end
end

