-- 永続常時指定方向移動
-- params[1]:継続時間
-- params[2]:移動方向
-- params[3]:移動量(mm/s)
-- params[4]:効果スロット
function process82001(_target, params)
local buid
	Field:FrameUpdate(_target)
	if params[4] ~= 0 then
		buid = target:GetValue({UNIT_VALUE_UNIT_DRIFT_SLOT, params[4]})
		if buid and Field:IsBuffExists(buid) then
			Field:ExpireBuff(buid)
		end
	end
	buid = target:SetBuff(BuffIds.P_UnitDrift, {params[1], params[2], params[3]})
	if buid and params[4] ~= 0 then target:SetValue({UNIT_VALUE_UNIT_DRIFT_SLOT, params[4]}, buid) end
end

-- 魔法陣展開
-- params[1]:継続時間
-- params[2]:魔法陣LV
function process82100(_target, params)
	Field:FrameUpdate(_target)
	target:SetBuff(BuffIds.PreCastMiddle + params[2] - 2, {params[1]})
end

-- 中級魔法陣展開バフ処理
function buff82100(_target, params)
Field:FrameUpdate(_target)
local cnt = Buff:GetKeptParam(1) or 0
	if cnt > 0 then target:HealMp(target, 1, 0) else Buff:KeepParam(1, 1) end
	target:PreCast(2, LIFETYPE_CONTINUOUS)
end

-- ラヴァーナチャージ
-- HPが20％未満の場合、チャージ解放は不可となる
-- params[1]:処理タイプ
function process82101(_target, params)
Field:FrameUpdate(_target)
local myCharge = this:GetValue(UNIT_VALUE_LAVANA_CHARGE) or 0
	if params[1] == 1 then
		if myCharge >= 2 then
			Process:PlayTimeline(7)
		elseif myCharge == 1 then
			Process:PlayTimeline(6)
		else
			Process:PlayTimeline(5)
		end
		this:SetValue(UNIT_VALUE_LAVANA_CHARGE, myCharge + 1)
	elseif params[1] == 2 and this:PerHP() >= 2000 then
		Process:PlayTimeline(8)
		this:SetValue(UNIT_VALUE_LAVANA_CHARGE, 0)
	end
end

-- 上級魔法陣展開バフ処理
function buff82101(_target, params)
Field:FrameUpdate(_target)
local cnt = Buff:GetKeptParam(1) or 0
	if cnt > 0 then target:HealMp(target, 3, 0) else Buff:KeepParam(1, 1) end
	target:PreCast(3, LIFETYPE_CONTINUOUS)
end

-- カウンタマジック
-- params[1]:継続時間
-- params[2]:有効回数
-- params[3]:演出レベル
function process82300(_target, params)
	Field:FrameUpdate(_target)
	if target:SetBuff(BuffIds.CounterMagic, params, nil, MISS_TYPE_BUFF) then Process:PlayTimeline(5 + ((params[3] - 1) * 3)) end
end

-- カウンタマジックバフ処理
-- params[1]:有効回数
-- params[2]:演出レベル
function buff82300(_target, params)
Field:FrameUpdate(_target)
local cnt = Buff:GetKeptParam(1) or 0
	if Process:EditTrigSkillTarget(TARGET_SIDE_ALLY, target) then
		cnt = cnt + 1
		if cnt >= params[1] then
			Process:PlayTimeline(7 + ((params[2] - 1) * 3), Buff:Target(), Buff:Target())
			Buff:Expire()
		else
			Process:PlayTimeline(6 + ((params[2] - 1) * 3), Buff:Target(), Buff:Target())
		end
		Buff:KeepParam(1, cnt)
	end
end

