-- 設定スキル永続使用不可
function process82700(_target, params)
local tbl, skl
	Field:FrameUpdate(_target)
	tbl = this:GetValue(UNIT_VALUE_DISABLE_SKILL_LIST) or {}
	skl = Bullet:GetParentSkill()
	if skl and not toBoolean(tbl[skl:ID()]) then
		this:SetBuff(DebuffIds.S_DisableSkill, {-1, skl:Type(), skl:Index()})
		tbl[skl:ID()] = true
		this:SetValue(UNIT_VALUE_DISABLE_SKILL_LIST, tbl, true)
	end
end

-- 設定スキル使用不可
-- params[1]:継続時間
function process82701(_target, params)
local tbl, skl
	Field:FrameUpdate(_target)
	tbl = this:GetValue(UNIT_VALUE_WAVE_DISABLE_SKILL_LIST) or {}
	skl = Bullet:GetParentSkill()
	if skl and not toBoolean(tbl[skl:ID()]) then
		if params[1] <= 0 then
			this:SetBuff(DebuffIds.S_DisableSkill_WAVE, {-1, skl:Type(), skl:Index()})
			tbl[skl:ID()] = true
			this:SetValue(UNIT_VALUE_WAVE_DISABLE_SKILL_LIST, tbl)
		else
			this:SetBuff(DebuffIds.S_DisableSkill_WAVE, {params[1], skl:Type(), skl:Index()})
		end
	end
end

-- 設定アイテム使用不可
-- params[1]:アイテムID
function process82702(_target, params)
local skl, buid
	Field:FrameUpdate(_target)
	skl = Bullet:GetParentSkill()
	if skl then
		buid = this:SetBuff(DebuffIds.S_DisableSkill_WAVE, {-1, skl:Type(), skl:Index()})
		this:SetPairingBuff('Item' .. tostring(params[1]), buid)
	end
end

-- ターゲット変更不可
-- params[1]:継続時間
function process83100(_target, params)
local buid
	Field:FrameUpdate(_target)
	buid = target:SetBuff(DebuffIds.TargetLock, params, nil, MISS_TYPE_DEBUFF)
	if buid then
		target:SetBuff(BuffIds.S_TargetLeaveFieldBuffControl, {-1, this:ID(), buid})
		Process:PlayTimeline(5)
	end
end

-- ステータス差分確率ターゲット変更不可
-- params[1]:自分比較ステータス
-- params[2]:相手比較ステータス
-- params[3]:確率最小ステータス比率
-- params[4]:確率最大ステータス比率
-- params[5]:発生確率MIN
-- params[6]:発生確率MAX
-- params[7]:継続時間
function process83101(_target, params)
local val, buid
	Field:FrameUpdate(_target)
	val = (this:Status(params[1]) / Bullet:Target():Status(params[2])) * Pct100
	coe = math.max(math.min((val - params[3]) / (params[4] - params[3]), 1), 0)
	if lottery(round((params[6] - params[5]) * coe + params[5])) then
		buid = target:SetBuff(DebuffIds.TargetLock, {params[7]}, nil, MISS_TYPE_DEBUFF)
		if buid then
			target:SetBuff(BuffIds.S_TargetLeaveFieldBuffControl, {-1, this:ID(), buid})
			Process:PlayTimeline(5)
		end
	end
end

-- チュートリアルプロセス
-- params[1]:HP回復
-- params[2]:根性付与
function process1000001(_target, params)
	Field:FrameUpdate(_target)
	if params[1] > 0 then if target:Alive() then target:HealPct(target, 0, Pct100) target:HealMp(target, 0, Pct100) else target:Revive(Pct100) end end
	if params[2] > 0 then target:SetBuff(BuffIds.S_Endure, {-1, 0, -1}) end
end

-- スタイリッシュランク初期化
-- params[1]:ゲージ時間減少量
-- params[2]:被ダメージ時ゲージ減少量
-- params[3]:ランク「なし」ゲージ総量
-- params[4]:ランク「D」ゲージ総量
-- params[5]:ランク「C」ゲージ総量
-- params[6]:ランク「B」ゲージ総量
-- params[7]:ランク「A」ゲージ総量
-- params[8]:ランク「S」ゲージ総量
-- params[9]:ランク「SS」ゲージ総量
-- params[10]:ランク「SSS」ゲージ総量
function process1000002(_target, params)
local rank, tbl, buid, pv
	Field:FrameUpdate(_target)
	pv = this:GetProcValue()
	if pv == nil then
		rank = Field:MakeNewRank(BATTLE_SCORE_DMC_RANK, BATTLE_SCORE_DMC_POINT)
		rank:SetName('DMC_Rank')
		rank:SetMaxRank(7)
		rank:SetMaxPoint(Pct100 * 100)
		rank:IsMultiRankUp(true)
		rank:SetRankDownPenalty(5000)
		tbl = {params[4], params[5], params[6], params[7], params[8], params[9], params[10]}
		tbl[0] = params[3]
		rank:SetPointMap(tbl)
		rank:SetAOT(params[1])
		buid = this:SetBuff(BuffIds.S_DMC_DamageRankPointCtrl, {-1, BATTLE_SCORE_DMC_RANK, BATTLE_SCORE_DMC_POINT, params[2]})
		this:SetProcValue(buid, true)
	-- 掛けたはずのバフが消えていたら再付与(AW_QA-21125応急処置)
	elseif not Field:IsBuffExists(pv) then
		buid = this:SetBuff(BuffIds.S_DMC_DamageRankPointCtrl, {-1, BATTLE_SCORE_DMC_RANK, BATTLE_SCORE_DMC_POINT, params[2]})
		this:SetProcValue(buid, true)
	end
end

-- スタイリッシュランク初期化2
-- params[1]:死亡時ゲージ減少量
-- params[2]:コンティニュー時ゲージ減少量
-- params[3]:ランク「なし」ランクボーナス
-- params[4]:ランク「D」ランクボーナス
-- params[5]:ランク「C」ランクボーナス
-- params[6]:ランク「B」ランクボーナス
-- params[7]:ランク「A」ランクボーナス
-- params[8]:ランク「S」ランクボーナス
-- params[9]:ランク「SS」ランクボーナス
-- params[10]:ランク「SSS」ランクボーナス
function process1000003(_target, params)
local rank, tbl, buid, pv
	Field:FrameUpdate(_target)
	pv = this:GetProcValue()
	if pv == nil then
		rank = Field:GetRank(BATTLE_SCORE_DMC_RANK, BATTLE_SCORE_DMC_POINT)
		tbl = {params[4], params[5], params[6], params[7], params[8], params[9], params[10]}
		tbl[0] = params[3]
		rank:SetRankBonus(tbl)
		buid = this:SetBuff(BuffIds.S_DMC_DeadRankPoint, {-1, BATTLE_SCORE_DMC_RANK, BATTLE_SCORE_DMC_POINT, params[1]})
		this:SetBuff(BuffIds.S_DMC_ContinueRankPoint, {-1, BATTLE_SCORE_DMC_RANK, BATTLE_SCORE_DMC_POINT, params[2]})
		this:SetProcValue(buid, true)
	-- 掛けたはずのバフが消えていたら再付与(AW_QA-21125応急処置)
	elseif not Field:IsBuffExists(pv) then
		buid = this:SetBuff(BuffIds.S_DMC_DeadRankPoint, {-1, BATTLE_SCORE_DMC_RANK, BATTLE_SCORE_DMC_POINT, params[1]})
		this:SetBuff(BuffIds.S_DMC_ContinueRankPoint, {-1, BATTLE_SCORE_DMC_RANK, BATTLE_SCORE_DMC_POINT, params[2]})
		this:SetProcValue(buid, true)
	end
end

-- スタイリッシュランク設定
-- params[1]:コンボ時ゲージ増加基本値
-- params[2]:コンボ時ゲージ増加係数
-- params[3]:空中コンボ時ゲージ増加係数
-- params[4]:スキル発動時ゲージ増加量
-- params[5]:スキル発動時ゲージ増加クールタイム
-- params[6]:指定スキル発動時ゲージ増加クールタイム
-- params[7]:特定スキル敵撃破時ゲージ増加量
-- params[8]:同一スキル敵撃破時ゲージ増加量
-- params[9]:ブレイク時ゲージ増加係数
-- params[10]:ブレイク発生時ゲージ増加量
function process1000004(_target, params)
local buid, pv
	Field:FrameUpdate(_target)
	pv = this:GetProcValue()
	-- 掛けたはずのバフが消えていたら再発火(AW_QA-21125応急処置)
	if pv == nil or not Field:IsBuffExists(pv) then
		buid = this:SetBuff(BuffIds.S_DMC_AttackRankPoint, {-1, BATTLE_SCORE_DMC_RANK, BATTLE_SCORE_DMC_POINT, params[1], params[2], params[3], params[9]})
		this:SetBuff(BuffIds.S_DMC_SkillRankPoint, {-1, BATTLE_SCORE_DMC_RANK, BATTLE_SCORE_DMC_POINT, params[5], params[4], params[6]})
		this:SetBuff(BuffIds.S_DMC_MagicRankPoint, {-1, BATTLE_SCORE_DMC_RANK, BATTLE_SCORE_DMC_POINT, params[5], params[4], params[6]})
		this:SetBuff(BuffIds.S_DMC_SpecialRankPoint, {-1, BATTLE_SCORE_DMC_RANK, BATTLE_SCORE_DMC_POINT, params[5], params[4], params[6]})
