-- SNリング初期化
-- params[1]:効果最小リング数
-- params[2]:効果最大リング数
-- params[3]:移動速度加算最大値
-- params[4]:ダメージ倍率最大補正
function process1000009(_target, params)
local oMst, oid
local coe, fpv, pv, buid1, buid2
	Field:FrameUpdate(_target)
	fpv, pv = Field:GetProcValue(), this:GetProcValue()
	if fpv == nil then
		oid = Field:OrnamentManageID()
		if oid ~= 0 then
			oMst = Field:GetOrnamentManageMstInfo(oid)
			Field:LoadSkill(oMst[ORNAMENT_MNG_MST_INFO_SKILL_ID])
			this:SetBuff(BuffIds.S_SN_RingControl, {-1, oMst[ORNAMENT_MNG_MST_INFO_SKILL_ID]})
			Field:CalcProcValue(nil, this:ID(), CALCULATE_OVR, true)
		end
	end
	if pv == nil then
		coe = calcCoe(Field:GetScore(BATTLE_SCORE_SN_RING):Get() or 0, params[1], params[2])
		if coe > 0 then
			buid1 = this:SetBuff(BuffIds.WP_ElementSkillSufferDamagePer, {-1, ELEMENT_UNMENTIONED, 0, round(params[4] * coe)})
			buid2 = this:SetBuff(BuffIds.WP_SpdEdit, {-1, round(params[3] * coe)})
			if buid1 then Process:KeepParam(1, buid1, nil, true) end
			if buid2 then Process:KeepParam(2, buid2, nil, true) end
		end
		this:SetBuff(BuffIds.S_SN_RingEffectControl, {-1, params[1], params[2], params[3], params[4]})
		this:SetProcValue({buid1, buid2}, true)
	end
end

-- 特定スキル被弾時指定スコア状況指定スコア増減
-- params[1]:属性条件
-- params[2]:スキルタイプ条件
-- params[3]:制限回数
-- params[4]:参照スコアID
-- params[5]:効果最小スコア値
-- params[6]:効果最大スコア値
-- params[7]:増減スコアID
-- params[8]:スコア変動値
-- params[9]:演出番号
-- params[10]:演出クールタイム
function process1000010(_target, params)
local sc, coe
local cnt, b4cnt, nowcnt
	Field:FrameUpdate(_target)
	cnt = Process:GetKeptParam(1) or 0
	if params[3] <= 0 or cnt < params[3] then
		if params[4] == 0 then coe = 1 else coe = calcCoe(Field:GetScore(params[4]):Get() or 0, params[5], params[6]) end
		if coe > 0 then
			sc = Field:GetScore(params[7])
			sc:Add(round(params[8] * coe))
			Process:KeepParam(1, 1, CALCULATE_ADD)
			nowcnt, b4cnt = this:Time(), this:GetValue({UNIT_VALUE_SCORE_EFFECT_COOL_TIME, Process:ID(), params[7], params[10]})
			if params[9] ~= 0 and (b4cnt == nil or nowcnt - b4cnt >= params[10]) then Process:PlayTimeline(params[9]) this:SetValue({UNIT_VALUE_SCORE_EFFECT_COOL_TIME, Process:ID(), params[7], params[10]}, nowcnt) end
		end
	end
end

