-- DOTダメージ
-- params[1]:ダメージ間隔(秒)
-- params[2]:ダメージタイプ(固定/割合)
-- params[3]:ダメージMIN
-- params[4]:ダメージMAX
-- params[5]:この効果によって死亡するか
function process1011103(_target, params)
Field:FrameUpdate(_target)
local dType_Fixed, dType_MaxHp, dType_NowHp = 0, 1, 2
local dCnt = Process:GetKeptParam(1) or 0
local val

	if params[3] > params[4] then params[4] = params[3] end
	if params[1] > 0 and params[1] <= dCnt then
		if params[2] == dType_Fixed then
			val = round(math.random(params[3], params[4]))
		elseif params[2] == dType_MaxHp then
			val = round(this:MaxHP() * math.random(params[3], params[4]) * Per2Num)
		elseif params[2] == dType_NowHp then
			val = round(this:HP() * math.random(params[3], params[4]) * Per2Num)
		end
		this:DotDamage(val, params[5]~=0)
		Process:KeepParam(1, 1)
	else
		Process:KeepParam(1, 1, CALCULATE_ADD)
	end
end

-- デバフ付与時ステータス依存対象HP減少
-- params[1]:STR加算値
-- params[2]:STR倍率
-- params[3]:INT加算値
-- params[4]:INT倍率
-- params[5]:ダメージ倍率
-- params[6]:アリーナダメージ倍率
-- params[7]:防御力タイプ 1:DEF 2:MND
-- params[8]:この効果によって死亡するか
function process1011104(_target, params)
local pow
	if params[7] == 1 or params[7] == 2 then
		Field:FrameUpdate(_target)
		pow = math.floor((this:STR() + params[1]) * (1 + (params[2] * Per2Num))) + math.floor((this:INT() + params[3]) * (1 + (params[4] * Per2Num)))
		if target:DotDamage(Process:CalcDamage(pow, params[7] == 1 and target:DEF() or target:MND(), (Field:IsPvP() and params[6] or params[5]) * Per2Num, true), params[8]~=0) then Process:ShowPassive() end
	end
end

