-- 女神リューさん
-- params[1]:距離条件MIN
-- params[2]:距離条件MAX
-- params[3]:ダメージ間隔(秒)
-- params[4]:バレット強化レベル
-- params[5]:即死発生確率
function process1011106(_target, params)
Field:FrameUpdate(_target)
local BUID
local res = false
local dCnt = Process:GetKeptParam(1) or 0
local ulist = {}
	if params[3] > 0 and params[3] <= dCnt then
		for i,u in pairs(units:GetCondUnitList(TARGET_SIDE_OPPONENT, TARGET_COND_ALIVE, UNIT_COND_NEAR, params[2])) do
			if this:Distance(u) >= params[1] then
				if not Field:IsPvP() and not Field:IsBoss() and lottery(params[5]) then
					u:Kill(false)
					res = true
				else
					table.insert(ulist, u)
				end
			end
		end
		if ulist[1] ~= nil then
			BUID = Process:GenerateBullet(100010 + params[4], ulist, 0, true, true, TARGET_STATUS_SUBJECT_WORK)
			if BUID then
				Process:SetBulletInfo(BUID, BULLET_PROPERTY_SKILL_ELEMENT, ELEMENT_DARK)
				Process:SetBulletInfo(BUID, BULLET_PROPERTY_SKILL_TYPE, SKILL_MAGIC)
				Process:SetBulletInfo(BUID, BULLET_PROPERTY_SKILL_ROLE, SKILL_ROLE_ATTACK)
				res = true
			end
		end
		if res then Process:ShowPassive() end
		Process:KeepParam(1, 1)
	else
		Process:KeepParam(1, 1, CALCULATE_ADD)
	end
end

