-- params[1]:ダメージ間隔(秒)
-- params[2]:ダメージタイプ(固定/割合)
-- params[3]:汎用数値情報番号(効果最小時間(秒))
-- params[4]:汎用数値情報番号(効果最大時間(秒))
-- params[5]:ダメージMIN最大値
-- params[6]:ダメージMAX最大値
-- params[7]:この効果によって死亡するか
function process1011108(_target, params)
local coe, tmin, tmax = 0, 0, 0
local dType_Fixed, dType_MaxHp, dType_NowHp = 0, 1, 2
local val
	Field:FrameUpdate(_target)
	if params[3] ~= 0 then tmin = this:GetGeneralCount(params[3]) or 0 end
	if params[4] ~= 0 then tmax = this:GetGeneralCount(params[4]) or 0 end
	coe = calcCoe((math.floor(Field:Time() / OneSec)), tmin, tmax)
	if params[5] > params[6] then params[6] = params[5] end
	if params[2] == dType_Fixed then
		val = round(math.random(params[5], params[6]) * coe)
	elseif params[2] == dType_MaxHp then
		val = round(this:MaxHP() * math.random(params[5], params[6]) * Per2Num * coe)
	elseif params[2] == dType_NowHp then
		val = round(this:HP() * math.random(params[5], params[6]) * Per2Num * coe)
	end
	this:DotDamage(val, params[7]~=0)
end

-- 生存人数条件HP減少
-- params[1]:発動回数
-- params[2]:敵・味方
-- params[3]:条件閾値方向
-- params[4]:味方生存人数閾値
-- params[5]:HP減少値
-- params[6]:HP減少割合
-- params[7]:この効果によって死亡するか
function process1011109(_target, params)
Field:FrameUpdate(_target)
local val
local cnt = this:GetProcValue() or 0
	if params[1] < 0 or cnt < params[1] then
		val = math.floor(this:MaxHP() * params[6] * Per2Num) + params[5]
		if val > 0 then if this:DotDamage(val, params[7]~=0) then this:SetProcValue(cnt + 1) Process:ShowPassive() end end
	end
end

-- 特定キャラ人数状況DOTダメージ
-- params[1]:ダメージ間隔(秒)
-- params[2]:ダメージタイプ(固定/割合)
-- params[3]:敵・味方
-- params[4]:自分/死者を含むか 0:含む 1:含まない +2:死者も含む
-- params[5]:キャラタイプ条件
-- params[6]:効果最小人数
-- params[7]:効果最大人数
-- params[8]:ダメージMIN最大値
-- params[9]:ダメージMAX最大値
-- params[10]:この効果によって死亡するか
function process1011110(_target, params)
local coe, cnt
local dType_Fixed, dType_MaxHp, dType_NowHp = 0, 1, 2
local val
	Field:FrameUpdate(_target)
	cnt = 0
	for i,u in pairs(units:GetCondUnitList(params[3], params[4]&2==2 and TARGET_COND_BOTH or TARGET_COND_ALIVE, UNIT_COND_NONE + (params[4]&1==1 and UNIT_COND_NOT_ME or 0))) do
		if u:Type(params[5]) then cnt = cnt + 1 end
	end
	coe = calcCoe(cnt, params[6], params[7])
	if coe > 0 then
		if params[8] > params[9] then params[9] = params[8] end
		if params[2] == dType_Fixed then
			val = round(math.random(params[8], params[9]) * coe)
		elseif params[2] == dType_MaxHp then
			val = round(this:MaxHP() * math.random(params[8], params[9]) * Per2Num * coe)
		elseif params[2] == dType_NowHp then
			val = round(this:HP() * math.random(params[8], params[9]) * Per2Num * coe)
		end
		this:DotDamage(val, params[10]~=0)
	end
end

-- MP条件特定汎用数値情報状況HP減少
-- params[1]:条件閾値方向
-- params[2]:条件MP閾値
-- params[3]:発動回数
-- params[4]:汎用数値情報番号
-- params[5]:効果最小数値
-- params[6]:効果最大数値
-- params[7]:HP減少値
-- params[8]:HP減少割合
-- params[9]:この効果によって死亡するか
function process1011111(_target, params)
Field:FrameUpdate(_target)
local coe, val
local cnt = Process:GetKeptParam(3) or 0
	if params[3] <= 0 or cnt < params[3] then
		coe = calcCoe(this:GetGeneralCount(params[4]), params[5], params[6])
		val = math.floor(this:MaxHP() * params[8] * Per2Num) + params[7]
		if coe > 0 then if this:DotDamage(round(val * coe), params[9]~=0) then Process:ShowPassive() Process:KeepParam(3, 1, CALCULATE_ADD) end end
	end
end

-- 特定バフ所持中DOTダメージ
-- params[1]:バフカテゴリ条件
-- params[2]:ダメージ間隔(秒)
-- params[3]:ダメージタイプ(固定/割合)
-- params[4]:ダメージMIN
-- params[5]:ダメージMAX
-- params[6]:この効果によって死亡するか
function process1011112(_target, params)
Field:FrameUpdate(_target)
local dType_Fixed, dType_MaxHp, dType_NowHp = 0, 1, 2
local dCnt = Process:GetKeptParam(1)
local val
	if dCnt == nil then dCnt = 1 Process:KeepParam(1, 1, nil, nil, true) end
	if not target:IsBuffCategory(params[1]) then
		Process:KeepParam(1, 1, nil, nil, true)
	else
		if params[4] > params[5] then params[5] = params[4] end
		if params[2] > 0 and params[2] <= dCnt then
			if params[3] == dType_Fixed then
				val = round(math.random(params[4], params[5]))
			elseif params[3] == dType_MaxHp then
				val = round(this:MaxHP() * math.random(params[4], params[5]) * Per2Num)
			elseif params[3] == dType_NowHp then
				val = round(this:HP() * math.random(params[4], params[5]) * Per2Num)
			end
			this:DotDamage(val, params[6]~=0)
			Process:KeepParam(1, 1, nil, nil, true)
		else
			Process:KeepParam(1, 1, CALCULATE_ADD, nil, true)
		end
	end
end

