-- params[1]:エネミータイプ条件
-- params[2]:発生確率
function process1012001(_target, params)
local flag
	Field:FrameUpdate(_target)
	for i,u in ipairs(units:GetCondUnitList(TARGET_SIDE_OPPONENT, TARGET_COND_ALIVE, UNIT_COND_NONE)) do
		if (u:IsBoss() and ENEMY_TYPE_BOSS or ENEMY_TYPE_NORMAL) == params[1] then
			-- if lottery(params[2]) then u:Break() end
			if lottery(params[2]) then u:SetBuff(DebuffIds.S_ForceVit0, {1}) end
			flag = true
		end
	end
	if flag then Process:ShowPassive() end
end

