-- HP条件MP消費HP回復
-- params[1]:条件閾値方向
-- params[2]:条件HP閾値
-- params[3]:発動回数
-- params[4]:消費MP値
-- params[5]:消費MP倍率
-- params[6]:回復値
-- params[7]:回復倍率
function process1020122(_target, params)
Field:FrameUpdate(_target)
local cost = math.ceil(params[4] + (this:MaxMP() * params[5] / Pct100))
local cnt = Process:GetKeptParam(1) or 0

	if cost == 0 or (this:MP() >= cost and this:DecMp(params[4], params[5])) then
		if this:HealPct(this, params[6], params[7]) then
			Process:ShowPassive()
		else
			Process:KeepParam(1, 1, CALCULATE_SUB)
		end
	else
		Process:KeepParam(1, 1, CALCULATE_SUB)
	end
end

