local buid
local ulist = this:GetProcValue() or {}
	for i,u in pairs(units:GetCondUnitList(TARGET_SIDE_ALLY, TARGET_COND_ALIVE, UNIT_COND_NONE)) do
		if not toBoolean(ulist[u:ID()]) and u:ID() ~= this:ID() then
			buid = u:SetBuff(BuffIds.S_HpCondSharingHp_Ally, {-1, params[1], params[2], params[3], this:ID(), params[4], params[5], params[6]})
			if buid then ulist[u:ID()] = buid end
		end
	end
	this:SetProcValue(ulist)
end

