-- 未来へ繋ぐバトン
-- params[1]:発動回数
-- params[2]:1人ごと発動回数
-- params[3]:回復値
-- params[4]:回復倍率
function process1020128(_target, params)
Field:FrameUpdate(_target)
local t = Process:TrigUnits()
local pv = this:GetProcValue() or {}
local cnt, ocnt = pv[1] or 0, pv[2] or {}
local uid
local skl, skl2
	if this:Alive() then
		if params[1] <= 0 or params[1] > cnt then
			this:SwitchSource(TARGSTAT_REAL)
			for i,u in pairs(t) do
				if this:RelativeSide(u, TARGET_SIDE_ALLY) and not u:Alive() then
					uid = u:ID()
					ocnt[uid] = ocnt[uid] or 0
					if params[2] <= 0 or params[2] > ocnt[uid] then
						if this:HealPct(this, params[3], params[4]) then
							for i = 1, u:SkillCount(SKILL_SKILL) do
								skl = u:GetSkill(SKILL_SKILL, i)
								if skl then
									skl2 = this:GetSkillFromIndexUI(skl:IndexUI())
									if skl2 then
										this:EditSingleSCT(TARGSTAT_REAL, (skl:Stock() * skl2:Cost() / 1000), 0, skl2:Index())
									end
								end
							end
							cnt = cnt + 1
							ocnt[uid] = ocnt[uid] + 1
							Process:ShowPassive()
						end
					end
				end
			end
			pv[1], pv[2] = cnt, ocnt
			this:SetProcValue(pv)
		end
	end
end

