-- スタイリッシュランク状況撃破時単独SCT回復
-- params[1]:効果最小ランク
-- params[2]:効果最大ランク
-- params[3]:特技INDEX
-- params[4]:回復値
-- params[5]:回復倍率
-- params[6]:回復倍率(1ストック)
function process1020234(_target, params)
local skl
local rank
local coe
local add = 0
local res = false
	Field:FrameUpdate(_target)
	rank = Field:GetRank(BATTLE_SCORE_DMC_RANK, BATTLE_SCORE_DMC_POINT)
	if rank ~= nil then
		coe = math.max(math.min((rank:GetRank() - params[1]) / (params[2] - params[1]), 1), 0)
		if coe > 0 then
			if params[3] > 0 then
				skl = this:GetSkillFromIndexUI(params[3])
				if skl~= nil then
					add = math.ceil((round(params[6] * coe) / Pct100) * (skl:Cost() / 1000))
					if this:EditSingleSCT(TARGSTAT_REAL, round(params[4] * coe) + add, round(params[5] * coe), skl:Index()) then Process:ShowPassive() end
				end
			elseif params[3] == 0 then
				for i = 1, this:SkillCount(SKILL_SKILL) do
					add = math.ceil((round(params[6] * coe) / Pct100) * (this:SKL_Cost(SKILL_SKILL, i) / 1000))
					res = this:EditSingleSCT(TARGSTAT_REAL, round(params[4] * coe) + add, round(params[5] * coe), i) or res
				end
				if res then Process:ShowPassive() end
			elseif params[3] == -1 then
				skl = this:GetSkill(SKILL_SKILL, math.random(1, this:SkillCount(SKILL_SKILL)))
				if skl~= nil then
					add = math.ceil((round(params[6] * coe) / Pct100) * (skl:Cost() / 1000))
					if this:EditSingleSCT(TARGSTAT_REAL, round(params[4] * coe) + add, round(params[5] * coe), skl:Index()) then Process:ShowPassive() end
				end
			end
		end
	end
end

-- 百の夜と千の空
-- params[1]:発動間隔(10秒単位)
-- params[2]:回復値1
-- params[3]:回復倍率1(1ストック)
-- params[4]:置き換え発生確率1
-- params[5]:回復値1
-- params[6]:回復倍率1(1ストック)
-- params[7]:置き換え発生確率2
-- params[8]:回復値1
-- params[9]:回復倍率
-- params[10]:回復倍率1(1ストック)
function process1020235(_target, params)
Field:FrameUpdate(_target)
local cnt = Process:GetKeptParam(2)
local skl
local add = 0
local res = false
local prm1, prm2, prm3
	if cnt == nil then cnt = 1 Process:KeepParam(2, 1) end
	if params[1] > 0 and params[1] <= cnt then
		if lottery(params[7]) then
			prm1, prm2, prm3 = params[8], params[9], params[10]
		elseif lottery(params[4]) then
			prm1, prm2, prm3 = params[5], 0, params[6]
		else
			prm1, prm2, prm3 = params[2], 0, params[3]
		end
		for i = 1, this:SkillCount(SKILL_SKILL) do
			add = math.ceil((prm3 / Pct100) * (this:SKL_Cost(SKILL_SKILL, i) / 1000))
			res = this:EditSingleSCT(TARGSTAT_REAL, prm1 + add, prm2, i) or res
		end
		if res then Process:ShowPassive() end
		Process:KeepParam(2, 1)
	else
		Process:KeepParam(2, 1, CALCULATE_ADD)
	end
end

