-- ボスブレイク時単独SCT回復
-- params[1]:制限回数
-- params[2]:特技INDEX
-- params[3]:回復値
-- params[4]:回復倍率
-- params[5]:回復倍率(1ストック)
-- params[6]:回復値(ストック補完)
function process1020245(_target, params)
-- t = 1:count 2:unitList 3:buidList 4:isEnd
local buid, t, cnt, ulist
	Field:FrameUpdate(_target)
	t = this:GetProcValue()
	if t == nil then
		t = {0, {}, {}, false}
		ulist = units:GetCondUnitList(TARGET_SIDE_OPPONENT, TARGET_COND_BOTH, UNIT_COND_NONE)
	else
		ulist = Process:TrigUnits()
	end
	if params[1] <= 0 or t[1] < params[1] then
		for i,u in pairs(ulist) do
			if u:RelativeSide(this)==TARGET_SIDE_OPPONENT and not toBoolean(t[2][u:ID()]) then
				buid = u:SetBuff(BuffIds.S_BreakTriggerSubProc, {-1, this:ID(), (1<<24) + (math.max(params[1], 0)<<16) + (Pct100<<2) + (1<<1) + 1, ENEMY_TYPE_BOSS, params[2], params[3], params[4], params[5], params[6]})
				if buid then
					table.insert(t[3], buid)
					t[2][u:ID()] = true
				end
			end
		end
		this:SetProcValue(t)
	end
end

