-- 味方死亡時単独SCT回復
-- params[1]:発動回数
-- params[2]:1人ごと発動回数
-- params[3]:特技INDEX
-- params[4]:回復値
-- params[5]:回復倍率
-- params[6]:回復倍率(1ストック)
-- params[7]:回復値(ストック補完)
function process1020249(_target, params)
Field:FrameUpdate(_target)
local t = Process:TrigUnits()
local pv = this:GetProcValue() or {}
local cnt, ocnt = pv[1] or 0, pv[2] or {}
local uid
	if this:Alive() then
		if params[1] <= 0 or params[1] > cnt then
			for i,u in pairs(t) do
				if this:RelativeSide(u, TARGET_SIDE_ALLY) then
					uid = u:ID()
					ocnt[uid] = ocnt[uid] or 0
					if params[2] <= 0 or params[2] > ocnt[uid] then
						if params[3] > 0 then
							skl = this:GetSkillFromIndexUI(params[3])
							if skl~= nil then
								add = math.ceil((params[6] / Pct100) * (skl:Cost() / 1000) + math.max((params[7] - (skl:Charge() * 1000) / skl:Cost()) * (skl:Cost() / 1000), 0))
								if this:EditSingleSCT(TARGSTAT_REAL, params[4] + add, params[5], skl:Index()) then Process:ShowPassive() cnt = cnt + 1 ocnt[uid] = ocnt[uid] + 1 end
							end
						elseif params[3] == 0 then
							for i = 1, this:SkillCount(SKILL_SKILL) do
								add = math.ceil((params[6] / Pct100) * (this:SKL_Cost(SKILL_SKILL, i) / 1000) + math.max((params[7] - (this:SKL_Charge(SKILL_SKILL, i) * 1000) / this:SKL_Cost(SKILL_SKILL, i)) * (this:SKL_Cost(SKILL_SKILL, i) / 1000), 0))
								res = this:EditSingleSCT(TARGSTAT_REAL, params[4] + add, params[5], i) or res
							end
							if res then Process:ShowPassive() cnt = cnt + 1 ocnt[uid] = ocnt[uid] + 1 end
						elseif params[3] == -1 then
							skl = this:GetSkill(SKILL_SKILL, math.random(1, this:SkillCount(SKILL_SKILL)))
							if skl~= nil then
								add = math.ceil((params[6] / Pct100) * (skl:Cost() / 1000) + math.max((params[7] - (skl:Charge() * 1000) / skl:Cost()) * (skl:Cost() / 1000), 0))
								if this:EditSingleSCT(TARGSTAT_REAL, params[4] + add, params[5], skl:Index()) then Process:ShowPassive() cnt = cnt + 1 ocnt[uid] = ocnt[uid] + 1 end
							end
						end
					end
				end
			end
			pv[1], pv[2] = cnt, ocnt
			this:SetProcValue(pv)
		end
	end
end

