-- 全体特定キャラ死亡時単独SCT回復
-- params[1]:発動回数
-- params[2]:1人ごと発動回数
-- params[3]:敵味方
-- params[4]:自分を含むか 0:含む 1:含まない
-- params[5]:キャラタイプ条件
-- params[6]:特技INDEX
-- params[7]:回復値
-- params[8]:回復倍率
-- params[9]:回復倍率(1ストック)
-- params[10]:回復値(ストック補完)
function process1020263(_target, params)
Field:FrameUpdate(_target)
local res
local t = Process:TrigUnits()
local pv = this:GetProcValue() or {}
local cnt, ocnt = pv[1] or 0, pv[2] or {}
local uid
	if params[1] <= 0 or params[1] > cnt then
		res = false
		for i,u in pairs(t) do
			uid = u:ID()
			ocnt[uid] = ocnt[uid] or 0
			if (params[4] == 0 or uid ~= this:ID()) and (params[2] <= 0 or params[2] > ocnt[uid]) and u:Type(params[5]) and this:RelativeSide(u, params[3]) then
				if this:EditSingleSCT2(TARGSTAT_REAL, params[6], params[7], params[8], params[9], params[10]) then
					cnt = cnt + 1
					ocnt[uid] = ocnt[uid] + 1
					res = true
				end
			end
		end
		pv[1], pv[2] = cnt, ocnt
		this:SetProcValue(pv)
		if res then Process:ShowPassive() end
	end
	if not res then Process:SetFailed() end
end

