	-- if params[5] ~= 0 then limit = this:GetGeneralCount(params[5]) end
	if coe > 0 then
		buid = this:SetBuff(BuffIds.S_IntervalSubProc, {-1, this:ID(), (1<<24) + (1<<16) + (Pct100<<2) + (0<<1) + 1, round(params[4] * coe), params[6], params[7], params[8], 0, params[9], params[10]})
		this:SetBuff(BuffIds.S_ArriveFieldBuffControl, {-1, buid})
