			if params[3] ~= 0 then _in = params[5] end
			if params[4] ~= 0 then _out = params[6] end
			if target:Revive(params[3], _in, _out) then Process:ShowPassive() Process:SetSubProcResult(true) return end
			Process:KeepParam(1, 1, CALCULATE_ADD, true)
		end
	end
	Process:SetFailed()
end

-- 自分死亡時味方全体回復・復活
-- params[1]:制限回数
-- params[2]:回復値
-- params[3]:回復倍率
-- params[4]:復活時HP割合
-- params[5]:フェードイン開始フレーム
-- params[6]:フェードイン終了フレーム
function process1020450(_target, params)
Field:FrameUpdate(_target)
local cnt = Process:GetKeptParam(1, true) or 0
	if params[1] <= 0 or cnt < params[1] then
		Process:KeepParam(1, 1, CALCULATE_ADD, true)
		for i,u in ipairs(units:GetCondUnitList(TARGET_SIDE_ALLY, TARGET_COND_BOTH, UNIT_COND_NONE)) do
			if u:ID() ~= this:ID() then
				if u:Alive() then
					Process:SubProc(1, u, Pct100, {params[2], params[3]})
				else
					Process:SubProc(2, u, Pct100, {params[4], -1, params[5], params[6]})
				end
			end
		end
		Process:ShowPassive()
	end
end

