-- ボス専用根性
-- params[1]:残りHP条件
-- params[2]:発生可能回数
function process1020603(_target, params)
Field:FrameUpdate(_target)
local cnt = Process:GetKeptParam(1) or 0
	this:SetEndure(TARGSTAT_WORK, params[1], params[2], LIFETYPE_TRANSIENT)
	if this:HP() <= Bullet:Damage() + 100 and not this:IsBuff(BuffIds.S_NoDamage) then
		this:HealPct(this, Bullet:Damage(), 0)
		Bullet:EditDamage(100 - this:HP())
		Process:KeepParam(1, 1)
		if cnt == 0 then this:SetBuff(BuffIds.S_NoDamage, {-1}) end
	end
