-- 対指定スキル中根性
-- params[1]:スキルタイプ条件
-- params[2]:残りHP条件
-- params[3]:発生可能回数
function process1020604(_target, params)
Field:FrameUpdate(_target)
local suid = this:GetValue(UNIT_VALUE_SKILL_COMBO_ENDURE) or {}
local cnt = Process:GetKeptParam(1) or 0
local del = {}
local n, flag
	if Bullet:SKL_Role(SKILL_ROLE_ATTACK) then
		n = 1
		flag = false
		while n <= #suid do
			if Field:IsSkillActive(suid[n]) then
				flag = true
			else
				table.remove(suid, n)
				n = n - 1
			end
			n = n + 1
		end
		if flag then
			if this:SetEndure(TARGSTAT_WORK, params[2], -1, LIFETYPE_TRANSIENT) then
				Process:ShowPassive()
			end
		elseif (params[3] < 0 or cnt < params[3]) and Bullet:SKL_Type(params[1]) and this:SetEndure(TARGSTAT_WORK, params[2], -1, LIFETYPE_TRANSIENT) then
			if params[4] > 0 or params[5] > 0 then this:HealPct(this, params[4], params[5]) end
			table.insert(suid, Bullet:SKL_PUID())
			this:SetValue(UNIT_VALUE_SKILL_COMBO_ENDURE, suid)
			Process:KeepParam(1, 1, CALCULATE_ADD)
			Process:ShowPassive()
		end
	end
end

