function process1020605(_target, params)
	Field:FrameUpdate(_target)
	if this:SetEndure(TARGSTAT_WORK, 0, params[1], LIFETYPE_TRANSIENT) then
		this:DecMp(0, Pct100)
		if params[2] > 0 or params[3] > 0 then this:HealPct(this, params[2], params[3]) end
		Process:SubProc(1, this, Pct100, {params[4], params[5], params[6]})
		Process:ShowPassive()
	end
end

-- MP消費根性
-- params[1]:被ダメージ変換率
function process1020606(_target, params)
Field:FrameUpdate(_target)
local val = math.ceil((Bullet:Damage() - this:HP() + 1) * params[1] * Per2Num)
	if val <= this:MP() then
		if this:SetEndure(TARGSTAT_WORK, 0, -1, LIFETYPE_TRANSIENT) then
			Bullet:EditDamage(this:HP() - 1)
		end
	end
	this:DecMp(val, 0)
	Process:ShowPassive()
end

-- 新MP消費根性
-- params[1]:消費MP値
-- params[2]:消費MP倍率
-- params[3]:発生可能回数
-- params[4]:HP回復値
-- params[5]:HP回復倍率
function process1020607(_target, params)
Field:FrameUpdate(_target)
local cnt = Process:GetKeptParam(1) or 0
local cost = math.max(math.ceil(params[1] + (this:MaxMP() * params[2] / Pct100)), 1)
	if (params[3] <= 0 or cnt < params[3]) and this:MP() >= cost then
		if this:SetEndure(TARGSTAT_WORK, 0, -1, LIFETYPE_TRANSIENT) then
			this:DecMp(params[1], params[2])
			if params[4] > 0 or params[5] > 0 then this:HealPct(this, params[4], params[5]) end
			Process:KeepParam(1, 1, CALCULATE_ADD)
			Process:ShowPassive()
		end
	end
end

