-- params[3]:発生可能回数
-- params[4]:クエスト毎発生可能回数
-- params[5]:クールタイム
function process1020613(_target, params)
Field:FrameUpdate(_target)
local pInfo = this:GetValue(UNIT_VALUE_PROCESS_1020613)
if pInfo ~= nil and pInfo ~= Process:UID() then Process:SetFailed() return end
local suid = this:GetValue(UNIT_VALUE_SKILL_COMBO_ENDURE) or {}
local cnt, qcnt = Process:GetKeptParam(1) or 0, Process:GetKeptParam(2, true) or 0
local nowTime, b4Time
local del = {}
local n, flag
	if Bullet:SKL_Role(SKILL_ROLE_ATTACK) then
		n = 1
		flag = false
		while n <= #suid do
			if Field:IsSkillActive(suid[n]) then
				flag = true
			else
				table.remove(suid, n)
				n = n - 1
			end
			n = n + 1
		end
		if flag then
			if this:SetEndure(TARGSTAT_WORK, params[2], -1, LIFETYPE_TRANSIENT) then
				Process:ShowPassive()
			end
		else
			nowTime, b4Time = this:Time(), Process:GetKeptParam(3)
			if (params[3] < 0 or cnt < params[3]) and (params[4] < 0 or qcnt < params[4]) and (b4Time == nil or nowTime - b4Time >= params[5]) and Bullet:SKL_Type(params[1]) and this:SetEndure(TARGSTAT_WORK, params[2], -1, LIFETYPE_TRANSIENT) then
				table.insert(suid, Bullet:SKL_PUID())
				this:SetValue(UNIT_VALUE_SKILL_COMBO_ENDURE, suid)
				this:SetValue(UNIT_VALUE_PROCESS_1020613, Process:UID(), true)
				Process:KeepParam(1, 1, CALCULATE_ADD)
				Process:KeepParam(2, 1, CALCULATE_ADD, true)
				Process:KeepParam(3, nowTime)
				Process:ShowPassive()
			end
		end
	end
end

