-- 常時味方全体リジェネ(バフと共存する)
-- params[1]:MDEF加算値
-- params[2]:MDEF倍率
-- params[3]:回復最低値
-- params[4]:回復倍率
function process1020806(_target, params)
local res = false
	Field:FrameUpdate(_target)
	this:SwitchSource(TARGSTAT_WORK_LOCAL)
	this:EditMND(TARGSTAT_WORK_LOCAL, params[1], params[2], 0, LIFETYPE_TRANSIENT)
	for i,u in pairs(units:GetCondUnitList(TARGET_SIDE_ALLY, TARGET_COND_ALIVE, UNIT_COND_NONE)) do
		if this:Heal(u, params[3], params[4]) then Process:PlayTimeline(5, u, u) res = true end
	end
	if res then Process:ShowPassive() end
end

-- 定期HP回復10
-- params[1]:発動間隔(10秒単位)
-- params[2]:回復値
-- params[3]:回復HP倍率
function process1020807(_target, params)
Field:FrameUpdate(_target)
local cnt = Process:GetKeptParam(2)
	if cnt == nil then cnt = 1 Process:KeepParam(2, 1) end
	if params[1] > 0 and params[1] <= cnt then
		this:HealPct(this, params[2], params[3])
		Process:KeepParam(2, 1)
	else
		Process:KeepParam(2, 1, CALCULATE_ADD)
	end
end

-- 常時リジェネ・MPリジェネ
