-- params[2]:MDEF倍率
-- params[3]:回復最低値
-- params[4]:回復倍率
-- params[5]:MP回復値
-- params[6]:最大MP割合
function process1020808(_target, params)
	Field:FrameUpdate(_target)
	Process:SubProc(1, this, Pct100, {params[1], params[2], params[3], params[4]})
	Process:SubProc(2, this, Pct100, {params[5], params[6]})
	Process:ShowPassive()
end

-- HP条件定期HP回復10
-- params[1]:発動間隔(10秒単位)
-- params[2]:発動条件方向
-- params[3]:残りHP閾値
-- params[4]:回復値
-- params[5]:回復HP倍率
function process1020809(_target, params)
Field:FrameUpdate(_target)
local Over,Under = 1,0
local cnt = Process:GetKeptParam(2)
	if cnt == nil then cnt = 1 Process:KeepParam(2, 1) end
	if params[1] > 0 and params[1] <= cnt then
		if (params[2]==Over and this:PerHP() >= params[3]) or (params[2]==Under and this:PerHP() < params[3]) then
			this:HealPct(this, params[4], params[5])
			Process:ShowPassive()
		end
		Process:KeepParam(2, 1)
	else
		Process:KeepParam(2, 1, CALCULATE_ADD)
	end
end

