-- 特定バフ所持中リジェネ
-- params[1]:バフカテゴリ条件
-- params[2]:MDEF加算値
-- params[3]:MDEF倍率
-- params[4]:回復最低値
-- params[5]:回復倍率
function process1020812(_target, params)
Field:FrameUpdate(_target)
local cnt = Process:GetKeptParam(1)
	if cnt == nil then cnt = 1 Process:KeepParam(1, 1) end
	if not target:IsBuffCategory(params[1]) then
		if cnt > 1 then Process:KeepParam(1, 1) end
	else
		if 6 <= cnt then
			this:SwitchSource(TARGSTAT_WORK_LOCAL)
			this:EditMND(TARGSTAT_WORK_LOCAL, params[2], params[3], 0, LIFETYPE_TRANSIENT)
			if this:Heal(this, params[4], params[5]) then Process:ShowPassive() Process:PlayTimeline(5) end
			Process:KeepParam(1, 1)
		else
			Process:KeepParam(1, 1, CALCULATE_ADD)
		end
	end
end

