-- 単独SCT回復量増減
-- params[1]:特技INDEX
-- params[2]:SCT自動回復加算値
-- params[3]:SCT自動回復倍率
-- 以下隠しパラメータ
-- params[4]:特技INDEX2
-- params[5]:SCT自動回復加算値2
-- params[6]:SCT自動回復倍率2
-- params[7]:特技INDEX3
-- params[8]:SCT自動回復加算値3
-- params[9]:SCT自動回復倍率3
function process1021009(_target, params)
Field:FrameUpdate(_target)
local skl
local res = false
	if params[1] > 0 then
		skl = target:GetSkillFromIndexUI(params[1])
		if skl~= nil then
			if target:EditRecoverSingleSCT(TARGSTAT_REAL, params[2], params[3], skl:Index()) then res = true end
		end
	elseif params[1] == 0 then
		if target:EditRecoverSCT(TARGSTAT_REAL, params[2], params[3]) then res = true end
	elseif params[1] == -1 then
		skl = target:GetSkill(SKILL_SKILL, math.random(1, target:SkillCount(SKILL_SKILL)))
		if skl~= nil then
			if target:EditRecoverSingleSCT(TARGSTAT_REAL, params[2], params[3], skl:Index()) then res = true end
		end
	end
	if params[4] > 0 then
		skl = target:GetSkillFromIndexUI(params[4])
		if skl~= nil then
			if target:EditRecoverSingleSCT(TARGSTAT_REAL, params[5], params[6], skl:Index()) then res = true end
		end
	end
	if params[7] > 0 then
		skl = target:GetSkillFromIndexUI(params[7])
		if skl~= nil then
			if target:EditRecoverSingleSCT(TARGSTAT_REAL, params[8], params[9], skl:Index()) then res = true end
		end
	end
	if res then Process:ShowPassive() end
end

-- 自身生存中味方全体SCT回復量増減
-- params[1]:自分を含むか 0:含む 1:含まない
-- params[2]:SCT自動回復加算値
-- params[3]:SCT自動回復倍率
function process1021010(_target, params)
local t, cnt, ulist
	Field:FrameUpdate(_target)
	t = this:GetProcValue() or {}
	if next(t) == nil then
		ulist = units:GetCondUnitList(TARGET_SIDE_ALLY, TARGET_COND_BOTH, UNIT_COND_NONE)
	else
		ulist = Process:TrigUnits()
	end
	for i,u in pairs(ulist) do
		if u:RelativeSide(this)==TARGET_SIDE_ALLY and (params[1]==0 or u:ID()~=this:ID()) and not toBoolean(t[u:ID()]) then
			if u:SetBuff(BuffIds.S_TargetUidAliveSctRcvVal, {-1, this:ID(), params[2], params[3]}) then t[u:ID()] = true end
		end
	end
	this:SetProcValue(t)
end

