	Field:FrameUpdate(_target)
	val = round(Bullet:Damage() * params[1] * Per2Num)
	this:SwitchSource(TARGSTAT_REAL)
	if this:HealMp(this, math.max(params[2] + val, 0), params[3]) then Process:ShowPassive() end
