-- params[4]:最大MP割合
function process1021215(_target, params)
Field:FrameUpdate(_target)
local before = Process:GetKeptParam(1) or 0
local MpOver,MpUnder = 1,0
local res = (params[1]==MpOver and this:PerMP() >= params[2]) or (params[1]==MpUnder and this:PerMP() < params[2])
	Process:KeepParam(1, res and 1 or 0)
	Process:KeepParam(2, before)
	if res then
