-- 死亡中MPリジェネ
-- params[1]:発動間隔
-- params[2]:回復値
-- params[3]:回復HP倍率
function process1021220(_target, params)
Field:FrameUpdate(_target)
local cnt = Process:GetKeptParam(1)
	if cnt == nil then cnt = 1 Process:KeepParam(1, 1) end
	if this:Alive() then
		if cnt > 1 then Process:KeepParam(1, 1) end
	else
		if params[1] > 0 and params[1] <= cnt then
			this:HealMp(this, params[2], params[3])
			Process:KeepParam(1, 1)
		else
			Process:KeepParam(1, 1, CALCULATE_ADD)
		end
	end
end

