	if not target:IsBuffCategory(params[1]) then
		if cnt > 1 then Process:KeepParam(1, 1) end
	else
		if params[2] > 0 and params[2] <= cnt then
			target:HealMp(target, params[3], params[4])
			Process:KeepParam(1, 1)
		else
			Process:KeepParam(1, 1, CALCULATE_ADD)
		end
	end
