-- 味方死亡時MP回復
-- params[1]:発動回数
-- params[2]:1人ごと発動回数
-- params[3]:MP回復値
-- params[4]:最大MP割合
function process1021228(_target, params)
Field:FrameUpdate(_target)
local t = Process:TrigUnits()
local pv = this:GetProcValue() or {}
local cnt, ocnt = pv[1] or 0, pv[2] or {}
local uid
	if this:Alive() then
		if params[1] <= 0 or params[1] > cnt then
			this:SwitchSource(TARGSTAT_REAL)
			for i,u in pairs(t) do
				if this:RelativeSide(u, TARGET_SIDE_ALLY) then
					uid = u:ID()
					ocnt[uid] = ocnt[uid] or 0
					if params[2] <= 0 or params[2] > ocnt[uid] then
						if this:HealMp(this, params[3], params[4]) then
							cnt = cnt + 1
							ocnt[uid] = ocnt[uid] + 1
							Process:ShowPassive()
						end
					end
				end
			end
			pv[1], pv[2] = cnt, ocnt
			this:SetProcValue(pv)
		end
	end
end

