function process1021229(_target, params)
local Over,Under = 1,0
local cost, val
	Field:FrameUpdate(_target)
	cost = TimeLine:ParentSkill():Cost()
	if (params[2]==Over and cost >= params[3]) or (params[2]==Under and cost < params[3]) then
		val = math.floor(cost * params[5] * Per2Num) + params[4]
		this:SwitchSource(TARGSTAT_REAL)
		if val > 0 and this:HealMp(this, val, 0) then Process:ShowPassive() end
	end
end

