	coe = math.max(math.min((Field:Wave() - params[1]) / (params[2] - params[1]), 1), 0)
	if this:EditSTR(TARGSTAT_REAL, round(params[3] * coe), round(params[4] * coe), 0, LIFETYPE_CONTINUOUS) then Process:ShowPassive() end
end

-- 残りHPに応じてSTRを増減
-- params[1]:効果最小HP割合
-- params[2]:効果最大HP割合
-- params[3]:STR加算最大値
-- params[4]:STR倍率最大値
function process1030005(_target, params)
local coe, noCutin
	Field:FrameUpdate(_target)
	noCutin = this:GetProcValue() or false
	coe = math.max(math.min((this:PerHP() - params[1]) / (params[2] - params[1]), 1), 0)
	if coe > 0 and this:EditSTR(TARGSTAT_REAL, round(params[3] * coe), round(params[4] * coe), 0, LIFETYPE_CONTINUOUS) then
		if not noCutin then Process:ShowPassive() this:SetProcValue(true) end
	else
		if noCutin then this:SetProcValue(false) end
	end
end

