-- HP条件でSTR変換
-- params[1]:発動条件方向
-- params[2]:残りHP閾値
-- params[3]:STR加算値
-- params[4]:STR倍率
-- params[5]:ステータス変換先1
-- params[6]:ステータス変換先2
-- params[7]:ステータス変換先3
function process1030009(_target, params)
local val
Field:FrameUpdate(_target)
local before = Process:GetKeptParam(1) or 0
local HpOver,HpUnder = 1,0
local res =  (params[1]==HpOver and this:PerHP() >= params[2]) or (params[1]==HpUnder and this:PerHP() < params[2])
local val = Process:GetKeptParam(3) or 0
	Process:KeepParam(1, res and 1 or 0)
	Process:KeepParam(2, before)
	if res then
		if val==0 then val = -(round((this:PureSTR() + params[3]) * params[4] / Pct100)) Process:ShowPassive() end
		this:EditSTR(TARGSTAT_REAL, 0, 0, -val, LIFETYPE_CONTINUOUS)
		if params[5]==STATUS_TYPE_DEF or params[6]==STATUS_TYPE_DEF or params[7]==STATUS_TYPE_DEF then
			this:EditDEF(TARGSTAT_REAL, 0, 0, val, LIFETYPE_CONTINUOUS)
		end
		if params[5]==STATUS_TYPE_INT or params[6]==STATUS_TYPE_INT or params[7]==STATUS_TYPE_INT then
			this:EditINT(TARGSTAT_REAL, 0, 0, val, LIFETYPE_CONTINUOUS)
		end
		if params[5]==STATUS_TYPE_MND or params[6]==STATUS_TYPE_MND or params[7]==STATUS_TYPE_MND then
			this:EditMND(TARGSTAT_REAL, 0, 0, val, LIFETYPE_CONTINUOUS)
		end
	else
		Process:KeepParam(3, 0)
	end
end

