-- 魔獣同盟
-- params[1]:パッシブスキルID条件
-- params[2]:効果最小種類数
-- params[3]:効果最大種類数
-- params[4]:全ステ加算最大値
-- params[5]:全ステ倍率最大値
function process1030021(_target, params)
local coe,cnt
	Field:FrameUpdate(_target)
	cnt = 0
	for i,u in pairs(units:GetCondUnitList(TARGET_SIDE_ALLY, TARGET_COND_BOTH, UNIT_COND_NONE)) do
		if not u:IsMonster() then
			for j,pid in pairs(u:PassiveList()) do
				if pid == params[1] then
					cnt = cnt + 1
					break
				end
			end
		end
	end
	coe = math.max(math.min((cnt - params[2]) / (params[3] - params[2]), 1), 0)
	if coe > 0 then
		this:EditSTR(TARGSTAT_REAL, round(params[4] * coe), round(params[5] * coe))
		this:EditDEF(TARGSTAT_REAL, round(params[4] * coe), round(params[5] * coe))
		this:EditINT(TARGSTAT_REAL, round(params[4] * coe), round(params[5] * coe))
		this:EditMND(TARGSTAT_REAL, round(params[4] * coe), round(params[5] * coe))
		Process:ShowPassive()
	end
end

