-- 味方全員生存中経過時間状況STR増減
-- params[1]:効果最小時間(秒)
-- params[2]:効果最大時間(秒)
-- params[3]:STR加算最大値
-- params[4]:STR倍率最大値
function process1030031(_target, params)
Field:FrameUpdate(_target)
local coe, flag, flag2
local cnt = this:GetProcValue() or 0
local buid = Process:GetKeptParam(2)
	if buid == nil or not Field:IsBuffExists(buid) then
		buid = this:SetBuff(BuffIds.S_AllyDeadResetPV, {-1})
		Process:KeepParam(2, buid)
	end
	flag, flag2 = true, false
	for i,u in pairs(units:GetCondUnitList(TARGET_SIDE_ALLY, TARGET_COND_BOTH, UNIT_COND_NONE)) do
		if u:Alive() then
			if u:ID() ~= this:ID() then flag2 = true end
		else
			flag = false
			break
		end
	end
	if flag and flag2 then
		cnt = cnt + 1
		this:SetProcValue(cnt)
	end
	coe = math.max(math.min((cnt - params[1]) / (params[2] - params[1]), 1), 0)
	if coe > 0 then this:EditSTR(TARGSTAT_REAL, round(params[3] * coe), round(params[4] * coe), 0, LIFETYPE_CONTINUOUS) end
end

