	if this:EditSTR(TARGSTAT_REAL, params[3], params[4], 0, LIFETYPE_CONTINUOUS) and before~=after then res = true end
	if this:EditDEF(TARGSTAT_REAL, params[5], params[6], 0, LIFETYPE_CONTINUOUS) and before~=after then res = true end
	if this:EditINT(TARGSTAT_REAL, params[7], params[8], 0, LIFETYPE_CONTINUOUS) and before~=after then res = true end
	if this:EditMND(TARGSTAT_REAL, params[9], params[10], 0, LIFETYPE_CONTINUOUS) and before~=after then res = true end
	if res then Process:ShowPassive() end
end

