-- params[6]:DEF倍率最大値
-- params[7]:INT倍率最大値
-- params[8]:MND倍率最大値
function process1030037(_target, params)
Field:FrameUpdate(_target)
local coe,cnt,res
local beforeCoe, icoe
local ulist
local t = this:GetProcValue()

	if t == nil then
		t = {}
		ulist = units:GetCondUnitList(TARGET_SIDE_ALLY, TARGET_COND_ALIVE, UNIT_COND_NONE)
		this:SetBuff(BuffIds.S_CharaCountChangeTrigger_1, {-1})
		if params[5] ~= 0 then this:SetBuff(BuffIds.P_CharaCategoryCountCondTargetStatusEdit, {-1, params[1], params[2], params[3] ,params[4], STATUS_TYPE_STR, 0, params[5]}) end
		if params[6] ~= 0 then this:SetBuff(BuffIds.P_CharaCategoryCountCondTargetStatusEdit, {-1, params[1], params[2], params[3] ,params[4], STATUS_TYPE_DEF, 0, params[6]}) end
		if params[7] ~= 0 then this:SetBuff(BuffIds.P_CharaCategoryCountCondTargetStatusEdit, {-1, params[1], params[2], params[3] ,params[4], STATUS_TYPE_INT, 0, params[7]}) end
		if params[8] ~= 0 then this:SetBuff(BuffIds.P_CharaCategoryCountCondTargetStatusEdit, {-1, params[1], params[2], params[3] ,params[4], STATUS_TYPE_MND, 0, params[8]}) end
	else
		ulist = Process:TrigUnits()
	end
	for i,u in pairs(ulist) do
		if u:RelativeSide(this) == TARGET_SIDE_ALLY and not toBoolean(t[u:ID()]) then
			if u:SetBuff(BuffIds.S_CharaCountChangeTrigger_2, {-1}) then
				t[u:ID()] = true
			end
		end
	end
	this:SetProcValue(t)
end

