function process1030040(_target, params)
	Field:FrameUpdate(_target)
	if this:Alive() then
	local pv = this:GetProcValue() or {}
	local cnt = (pv[1] or 0) + 1
	local beforeSbf, beforeRbf = pv[2], pv[3]
	local Sbf, Rbf
	local beforeCoe = math.max(math.min((cnt - 1 - params[1]) / (params[2] - params[1]), 1), 0)
	local coe = math.max(math.min((cnt - params[1]) / (params[2] - params[1]), 1), 0)
		if beforeSbf ~= nil then this:ExpireBuff(beforeSbf) end
		if beforeRbf ~= nil then this:ExpireBuff(beforeRbf) end
		if coe > 0 then Sbf = this:SetBuff(bitToBoolean(params[7], 1) and BuffIds.WP_StatusEdit or BuffIds.P_StatusEdit, {-1, 0, round(params[3] * coe), 0, round(params[4] * coe), 0, round(params[5] * coe), 0, round(params[6] * coe)}) end
		if Sbf then
			if bitToBoolean(params[7], 2) then Rbf = this:SetBuff(BuffIds.S_DefeatReset, {-1}) end
			if coe > 0 and beforeCoe ~= coe then Process:ShowPassive() end
		end
		pv[1] = cnt
		pv[2] = Sbf
		pv[3] = Rbf
		this:SetProcValue(pv, bitToBoolean(params[7], 1))
	end
end

