-- params[9]:MND倍率最大値
function process1030048(_target, params)
local coe,res
local cnt = 0
	Field:FrameUpdate(_target)
	for i,u in pairs(units:GetCondUnitList(params[1], TARGET_COND_BOTH, UNIT_COND_NONE + (params[2]&1==1 and UNIT_COND_NOT_ME or 0))) do
		if u:Type(params[3]) then cnt = cnt + 1 end
	end
	coe = calcCoe(cnt, params[4], params[5])
	if coe > 0 then
		res = false
		if params[6] ~= 0 then res = this:EditSTR(TARGSTAT_REAL, 0, round(params[6] * coe)) end
		if params[7] ~= 0 then res = this:EditDEF(TARGSTAT_REAL, 0, round(params[7] * coe)) or res end
		if params[8] ~= 0 then res = this:EditINT(TARGSTAT_REAL, 0, round(params[8] * coe)) or res end
		if params[9] ~= 0 then res = this:EditMND(TARGSTAT_REAL, 0, round(params[9] * coe)) or res end
		if res then Process:ShowPassive() end
	end
end

