-- 開始時STR変換
-- params[1]:STR加算値
-- params[2]:STR倍率
-- params[3]:ステータス変換効率
-- params[4]:ステータス変換先1
-- params[5]:ステータス変換先2
-- params[6]:ステータス変換先3
-- params[7]:変換するか
function process1030054(_target, params)
local val
	Field:FrameUpdate(_target)
	val = params[1] + ((this:PureSTR() + params[1]) * params[2] / Pct100)
	if params[7] == 0 then this:EditSTR(TARGSTAT_REAL, round(val), 0) end
	if params[4]==STATUS_TYPE_DEF or params[5]==STATUS_TYPE_DEF or params[6]==STATUS_TYPE_DEF then
		this:EditDEF(TARGSTAT_REAL, round(-val * params[3] * Per2Num), 0)
	end
	if params[4]==STATUS_TYPE_INT or params[5]==STATUS_TYPE_INT or params[6]==STATUS_TYPE_INT then
		this:EditINT(TARGSTAT_REAL, round(-val * params[3] * Per2Num), 0)
	end
	if params[4]==STATUS_TYPE_MND or params[5]==STATUS_TYPE_MND or params[6]==STATUS_TYPE_MND then
		this:EditMND(TARGSTAT_REAL, round(-val * params[3] * Per2Num), 0)
	end
	Process:ShowPassive()
end

