-- 属性付き特定スキル発動中生存味方全ステータス割合STR増減
-- params[1]:属性条件
-- params[2]:スキルタイプ条件
-- params[3]:味方STR倍率
-- params[4]:味方DEF倍率
-- params[5]:味方INT倍率
-- params[6]:味方MND倍率
function process1030059(_target, params)
local val = 0
	Field:FrameUpdate(_target)
	for i,u in pairs(units:GetCondUnitList(TARGET_SIDE_ALLY, TARGET_COND_ALIVE, UNIT_COND_NONE + UNIT_COND_NOT_ME)) do
		if params[3] ~= 0 then val = val + u:STR() * params[3] * Per2Num end
		if params[4] ~= 0 then val = val + u:DEF() * params[4] * Per2Num end
		if params[5] ~= 0 then val = val + u:INT() * params[5] * Per2Num end
		if params[6] ~= 0 then val = val + u:MND() * params[6] * Per2Num end
	end
	val = math.floor(val)
	if val ~= 0 and this:EditSTR(TARGSTAT_REAL, 0, 0, val, LIFETYPE_CONTINUOUS) then
		Process:ShowPassive()
	end
end

