-- バフ数状況全ステータス増減
-- params[1]:バフ/デバフ
-- params[2]:効果最小バフ数
-- params[3]:効果最大バフ数
-- params[4]:STR倍率最大値
-- params[5]:DEF倍率最大値
-- params[6]:INT倍率最大値
-- params[7]:MND倍率最大値
function process1030066(_target, params)
Field:FrameUpdate(_target)
local beforeCoe = Process:GetKeptParam(1) or 0
local cnt, coe, icoe, res
	
	if params[1] == 0 then
		cnt = this:VisibleBuffCount()
	elseif params[1] == 1 then
		cnt = this:VisibleBuffCount(false)
	elseif params[1] == 2 then
		cnt = this:VisibleBuffCount(true)
	end
	coe = calcCoe(cnt, params[2], params[3])
	icoe = math.floor(coe * Pct100)
	Process:KeepParam(1, icoe)
	res = this:EditSTR(TARGSTAT_REAL, 0, round(params[4] * coe), 0, LIFETYPE_CONTINUOUS)
	res = this:EditDEF(TARGSTAT_REAL, 0, round(params[5] * coe), 0, LIFETYPE_CONTINUOUS) or res
	res = this:EditINT(TARGSTAT_REAL, 0, round(params[6] * coe), 0, LIFETYPE_CONTINUOUS) or res
	res = this:EditMND(TARGSTAT_REAL, 0, round(params[7] * coe), 0, LIFETYPE_CONTINUOUS) or res
	if res and beforeCoe < icoe then Process:ShowPassive() end
end

