-- 開始時特定汎用数値情報状況STR変換
-- params[1]:汎用数値情報番号
-- params[2]:効果最小数値
-- params[3]:効果最大数値
-- params[4]:STR加算値
-- params[5]:STR倍率
-- params[6]:ステータス変換効率
-- params[7]:ステータス変換先1
-- params[8]:ステータス変換先2
-- params[9]:ステータス変換先3
-- params[10]:変換するか
function process1030068(_target, params)
local coe, val
	Field:FrameUpdate(_target)
	coe = calcCoe(this:GetGeneralCount(params[1]), params[2], params[3])
	val = math.floor(params[4] + ((this:PureSTR() + params[4]) * params[5] / Pct100) * coe)
	if val ~= 0 then
		if params[10] == 0 then this:EditSTR(TARGSTAT_REAL, round(val), 0) end
		if params[7]==STATUS_TYPE_DEF or params[8]==STATUS_TYPE_DEF or params[9]==STATUS_TYPE_DEF then
			this:EditDEF(TARGSTAT_REAL, round(-val * params[6] * Per2Num), 0)
		end
		if params[7]==STATUS_TYPE_INT or params[8]==STATUS_TYPE_INT or params[9]==STATUS_TYPE_INT then
			this:EditINT(TARGSTAT_REAL, round(-val * params[6] * Per2Num), 0)
		end
		if params[7]==STATUS_TYPE_MND or params[8]==STATUS_TYPE_MND or params[9]==STATUS_TYPE_MND then
			this:EditMND(TARGSTAT_REAL, round(-val * params[6] * Per2Num), 0)
		end
		Process:ShowPassive()
	end
end

-- 距離状況特定スキル魔転相
-- params[1]:効果発生距離
-- params[2]:効果最大距離
-- params[3]:属性条件
-- params[4]:スキルタイプ条件
-- params[5]:魔力変換率
function process1030069(_target, params)
local coe, res, val
	Field:FrameUpdate(_target)
	coe = calcCoe(this:Distance(Bullet:Target()), params[1], params[2])
	if coe > 0 then
		val = round(Bullet:INT() * params[5] * Per2Num * coe)
		if val ~= 0 then
			res = Bullet:EditSTR(0, 0, val)
			res = Bullet:EditINT(0, 0, val) or res
			if res then Process:ShowPassive() end
		end
	end
end

-- バトル開始時特定キャラ専用特定キャラ人数状況味方全体全ステータス増減
-- params[1]:自身キャラタイプ条件
-- params[2]:敵・味方
-- params[3]:自分/死者を含むか 0:含む 1:含まない +2:死者も含む
-- params[4]:キャラタイプ条件
-- params[5]:効果最小人数
-- params[6]:効果最大人数
-- params[7]:STR最大倍率
-- params[8]:DEF最大倍率
-- params[9]:INT最大倍率
-- params[10]:MND最大倍率
function process1030070(_target, params)
local coe,cnt
	Field:FrameUpdate(_target)
	cnt = 0
	for i,u in pairs(units:GetCondUnitList(params[2], params[3]&2==2 and TARGET_COND_BOTH or TARGET_COND_ALIVE, UNIT_COND_NONE + (params[3]&1==1 and UNIT_COND_NOT_ME or 0))) do
		if u:Type(params[4]) then cnt = cnt + 1 end
	end
	coe = calcCoe(cnt, params[5], params[6])
	if coe > 0 then
		for i,u in pairs(units:GetCondUnitList(TARGET_SIDE_ALLY, TARGET_COND_BOTH, UNIT_COND_NONE)) do
			u:SetBuff(BuffIds.P_StatusEdit, {-1, 0, round(params[7] * coe), 0, round(params[8] * coe), 0, round(params[9] * coe), 0, round(params[10] * coe)})
		end
		Process:ShowPassive()
	end
end

-- 敵撃破時STR累積増減
-- params[1]:スキルロール条件
-- params[2]:属性条件
-- params[3]:スキルタイプ条件
-- params[4]:効果最小累積トドメ人数
-- params[5]:効果最大累積トドメ人数
-- params[6]:STR加算値
-- params[7]:STR倍率
-- params[8]:オプション
function process1030071(_target, params)
Field:FrameUpdate(_target)
local pv = this:GetProcValue() or {}
local cnt = (pv[1] or 0) + 1
local beforeSbf, beforeRbf = pv[2], pv[3]
local Sbf, Rbf
local beforeCoe = math.max(math.min((cnt - 1 - params[4]) / (params[5] - params[4]), 1), 0)
local coe = math.max(math.min((cnt - params[4]) / (params[5] - params[4]), 1), 0)
	if beforeSbf ~= nil then this:ExpireBuff(beforeSbf) end
	if beforeRbf ~= nil then this:ExpireBuff(beforeRbf) end
	if coe > 0 then Sbf = this:SetBuff(bitToBoolean(params[8], 1) and BuffIds.WP_StrEdit or BuffIds.P_StrEdit, {-1, round(params[6] * coe), round(params[7] * coe)}) end
	if Sbf then
		if bitToBoolean(params[8], 2) then Rbf = this:SetBuff(BuffIds.S_DefeatReset, {-1}) end
		if coe > 0 and beforeCoe ~= coe then Process:ShowPassive() end
	end
	pv[1] = cnt
	pv[2] = Sbf
	pv[3] = Rbf
	this:SetProcValue(pv, bitToBoolean(params[8], 1))
end

