		this:EditSTR(TARGSTAT_REAL, round(-val * params[3] * Per2Num), 0)
	end
	if params[4]==STATUS_TYPE_INT or params[5]==STATUS_TYPE_INT or params[6]==STATUS_TYPE_INT then
		this:EditINT(TARGSTAT_REAL, round(-val * params[3] * Per2Num), 0)
	end
	if params[4]==STATUS_TYPE_MND or params[5]==STATUS_TYPE_MND or params[6]==STATUS_TYPE_MND then
		this:EditMND(TARGSTAT_REAL, round(-val * params[3] * Per2Num), 0)
	end
	Process:ShowPassive()
end

