-- 特定スキル使用数状況DEF増減
-- params[1]:スキルタイプ条件
-- params[2]:効果最小スキル使用数
-- params[3]:効果最大スキル使用数
-- params[4]:DEF加算最大値
-- params[5]:DEF倍率最大値
function process1030126(_target, params)
local cnt, coe, beforeCoe, icoe
local buid
	Field:FrameUpdate(_target)
	if not this:IsRemote() then
		cnt = (Process:GetKeptParam(1) or 0) + 1
		beforeCoe = Process:GetKeptParam(3) or 0
		coe = math.max(math.min((cnt - params[2]) / (params[3] - params[2]), 1), 0)
		icoe = math.floor(coe * Pct100)
		buid = Process:GetKeptParam(2)
		if buid and Field:IsBuffExists(buid) then Field:ExpireBuff(buid) end
		buid = this:SetBuff(BuffIds.P_DefEdit, {-1, round(params[4] * coe), round(params[5] * coe)})
		if buid then
			Process:KeepParam(1, 1, CALCULATE_ADD)
			Process:KeepParam(2, buid)
			Process:KeepParam(3, icoe)
			if beforeCoe < icoe then Process:ShowPassive() end
		end
	end
end

