-- 復活時DEF累積増減
-- params[1]:効果最小累積復活数
-- params[2]:効果最大累積復活数
-- params[3]:DEF加算値
-- params[4]:DEF倍率
-- params[5]:オプション
function process1030135(_target, params)
Field:FrameUpdate(_target)
local pv = this:GetProcValue() or {}
local cnt = (pv[1] or 0) + 1
local beforeSbf, beforeRbf = pv[2], pv[3]
local Sbf, Rbf
local beforeCoe = calcCoe(cnt - 1, params[1], params[2])
local coe = calcCoe(cnt, params[1], params[2])
	if beforeSbf ~= nil then this:ExpireBuff(beforeSbf) end
	if beforeRbf ~= nil then this:ExpireBuff(beforeRbf) end
	if coe > 0 then Sbf = this:SetBuff(bitToBoolean(params[5], 1) and BuffIds.WP_DefEdit or BuffIds.P_DefEdit, {-1, round(params[3] * coe), round(params[4] * coe)}) end
	if Sbf then
		if bitToBoolean(params[5], 2) then Rbf = this:SetBuff(BuffIds.S_DefeatReset, {-1}) end
		if coe > 0 and beforeCoe ~= coe then Process:ShowPassive() end
	end
	pv[1] = cnt
	pv[2] = Sbf
	pv[3] = Rbf
	this:SetProcValue(pv, bitToBoolean(params[5], 1))
end

