-- params[4]:INT倍率最大値
function process1030212(_target, params)
local coe, noCutin
	Field:FrameUpdate(_target)
	noCutin = this:GetProcValue() or false
	coe = math.max(math.min((this:PerHP() - params[1]) / (params[2] - params[1]), 1), 0)
	if coe > 0 and this:EditINT(TARGSTAT_REAL, round(params[3] * coe), round(params[4] * coe), 0, LIFETYPE_CONTINUOUS) then
		if not noCutin then Process:ShowPassive() this:SetProcValue(true) end
	else
		if noCutin then this:SetProcValue(false) end
	end
end

