-- 開始時特定汎用数値情報状況INT変換
-- params[1]:汎用数値情報番号
-- params[2]:効果最小数値
-- params[3]:効果最大数値
-- params[4]:INT加算値
-- params[5]:INT倍率
-- params[6]:ステータス変換効率
-- params[7]:ステータス変換先1
-- params[8]:ステータス変換先2
-- params[9]:ステータス変換先3
-- params[10]:変換するか
function process1030222(_target, params)
local coe, val
	Field:FrameUpdate(_target)
	coe = calcCoe(this:GetGeneralCount(params[1]), params[2], params[3])
	val = math.floor(params[4] + ((this:PureINT() + params[4]) * params[5] / Pct100) * coe)
	if val ~= 0 then
		if params[10] == 0 then this:EditINT(TARGSTAT_REAL, round(val), 0) end
		if params[7]==STATUS_TYPE_STR or params[8]==STATUS_TYPE_STR or params[9]==STATUS_TYPE_STR then
			this:EditSTR(TARGSTAT_REAL, round(-val * params[6] * Per2Num), 0)
		end
		if params[7]==STATUS_TYPE_DEF or params[8]==STATUS_TYPE_DEF or params[9]==STATUS_TYPE_DEF then
			this:EditDEF(TARGSTAT_REAL, round(-val * params[6] * Per2Num), 0)
		end
		if params[7]==STATUS_TYPE_MND or params[8]==STATUS_TYPE_MND or params[9]==STATUS_TYPE_MND then
			this:EditMND(TARGSTAT_REAL, round(-val * params[6] * Per2Num), 0)
		end
		Process:ShowPassive()
	end
end

