-- params[5]:効果最大累積トドメ人数
-- params[6]:MND加算値
-- params[7]:MND倍率
-- params[8]:オプション
function process1030325(_target, params)
Field:FrameUpdate(_target)
local pv = this:GetProcValue() or {}
local cnt = (pv[1] or 0) + 1
local beforeSbf, beforeRbf = pv[2], pv[3]
local Sbf, Rbf
local beforeCoe = math.max(math.min((cnt - 1 - params[4]) / (params[5] - params[4]), 1), 0)
local coe = math.max(math.min((cnt - params[4]) / (params[5] - params[4]), 1), 0)
	if beforeSbf ~= nil then this:ExpireBuff(beforeSbf) end
	if beforeRbf ~= nil then this:ExpireBuff(beforeRbf) end
	if coe > 0 then Sbf = this:SetBuff(bitToBoolean(params[8], 1) and BuffIds.WP_MndEdit or BuffIds.P_MndEdit, {-1, round(params[6] * coe), round(params[7] * coe)}) end
	if Sbf then
		if bitToBoolean(params[8], 2) then Rbf = this:SetBuff(BuffIds.S_DefeatReset, {-1}) end
		if coe > 0 and beforeCoe ~= coe then Process:ShowPassive() end
	end
	pv[1] = cnt
	pv[2] = Sbf
	pv[3] = Rbf
	this:SetProcValue(pv, bitToBoolean(params[8], 1))
end

-- 開始時特定汎用数値情報状況MND変換
-- params[1]:汎用数値情報番号
-- params[2]:効果最小数値
-- params[3]:効果最大数値
-- params[4]:MND加算値
-- params[5]:MND倍率
-- params[6]:ステータス変換効率
-- params[7]:ステータス変換先1
-- params[8]:ステータス変換先2
-- params[9]:ステータス変換先3
-- params[10]:変換するか
function process1030326(_target, params)
local coe, val
	Field:FrameUpdate(_target)
	coe = calcCoe(this:GetGeneralCount(params[1]), params[2], params[3])
	val = math.floor(params[4] + ((this:PureMND() + params[4]) * params[5] / Pct100) * coe)
	if val ~= 0 then
		if params[10] == 0 then this:EditMND(TARGSTAT_REAL, round(val), 0) end
		if params[7]==STATUS_TYPE_STR or params[8]==STATUS_TYPE_STR or params[9]==STATUS_TYPE_STR then
			this:EditSTR(TARGSTAT_REAL, round(-val * params[6] * Per2Num), 0)
		end
		if params[7]==STATUS_TYPE_DEF or params[8]==STATUS_TYPE_DEF or params[9]==STATUS_TYPE_DEF then
			this:EditDEF(TARGSTAT_REAL, round(-val * params[6] * Per2Num), 0)
		end
		if params[7]==STATUS_TYPE_INT or params[8]==STATUS_TYPE_INT or params[9]==STATUS_TYPE_INT then
			this:EditINT(TARGSTAT_REAL, round(-val * params[6] * Per2Num), 0)
		end
		Process:ShowPassive()
	end
end

