-- 経過時間状況クリティカル耐性
-- params[1]:効果発生間隔(秒)
-- params[2]:効果最小時間(秒)
-- params[3]:効果最大時間(秒)
-- params[4]:発生確率
function process1030424(_target, params)
Field:FrameUpdate(_target)
local beforeCoe = Process:GetKeptParam(4) or 0
local beforeBuid = Process:GetKeptParam(5) or 0
local called, coe, icoe, cnt, buid
	if params[1] > 0 and Process:IsSucceeded() then
		called = (Process:GetKeptParam(2) or 0) + 1
		cnt = Process:GetKeptParam(3) or 0
		if params[1] <= called then
			called = 0
			cnt = cnt + 1
		end
		Process:KeepParam(2, called)
		Process:KeepParam(3, cnt)
		coe = math.max(math.min((cnt * params[1] - params[2]) / (params[3] - params[2]), 1), 0)
		icoe = math.floor(coe * Pct100)
		Process:KeepParam(4, icoe)
		if coe > 0 then
			buid = this:SetBuff(BuffIds.P_ResistCrt, {-1, round(params[4] * coe)})
			if buid then
				Process:KeepParam(5, buid)
				if beforeBuid ~= 0 then this:ExpireBuff(beforeBuid) end
				if called == 0 and beforeCoe ~= icoe then Process:ShowPassive() end
			end
		end
	end
end

