-- 特定キャラタイプの味方人数に応じてHP増減
-- params[1]:キャラタイプ条件
-- params[2]:効果最小人数
-- params[3]:効果最大人数
-- params[4]:HP加算最大値
-- params[5]:HP倍率最大値
function process1030503(_target, params)
Field:FrameUpdate(_target)
local coe,cnt,res
local beforeCoe, icoe
local ulist
local t = this:GetProcValue()

	if t == nil then
		t = {}
		ulist = units:GetCondUnitList(TARGET_SIDE_ALLY, TARGET_COND_ALIVE, UNIT_COND_NONE)
		this:SetBuff(BuffIds.S_CharaCountChangeTrigger_1, {-1})
		this:SetBuff(BuffIds.P_CharaCountCondTargetStatusEdit, {-1, TARGET_SIDE_ALLY, params[1], params[2] ,params[3], STATUS_TYPE_HP, params[4], params[5]})
	else
		ulist = Process:TrigUnits()
	end
	for i,u in pairs(ulist) do
		if u:RelativeSide(this) == TARGET_SIDE_ALLY and not toBoolean(t[u:ID()]) then
			if u:SetBuff(BuffIds.S_CharaCountChangeTrigger_2, {-1}) then
				t[u:ID()] = true
			end
		end
	end
	this:SetProcValue(t)
end

