function process1030513(_target, params)
local coe,cnt,res
	Field:FrameUpdate(_target)
	cnt = #(units:GetCondUnitList(params[1], TARGET_COND_BOTH, UNIT_COND_CHARA_TYPE + (params[2] == 1 and UNIT_COND_NOT_ME or 0), params[3]))
	coe = math.max(math.min((cnt - params[4]) / (params[5] - params[4]), 1), 0)
	if this:EditMaxHP(TARGSTAT_REAL, round(params[6] * coe), round(params[7] * coe)) then Process:ShowPassive() end
end

-- バトル開始時特定キャラ存在人数状況全ステータス増減
-- params[1]:敵味方
-- params[2]:自分を含むか 0:含む 1:含まない
-- params[3]:キャラタイプ条件
-- params[4]:効果最小人数
-- params[5]:効果最大人数
-- params[6]:HP加算最大値
-- params[7]:HP倍率最大値
function process1030514(_target, params)
local coe,res
local cnt = 0
	Field:FrameUpdate(_target)
	for i,u in pairs(units:GetCondUnitList(params[1], TARGET_COND_BOTH, UNIT_COND_NONE + (params[2]&1==1 and UNIT_COND_NOT_ME or 0))) do
		if u:Type(params[3]) then cnt = cnt + 1 end
	end
	coe = math.max(math.min((cnt - params[4]) / (params[5] - params[4]), 1), 0)
	if this:EditMaxHP(TARGSTAT_REAL, round(params[6] * coe), round(params[7] * coe)) then Process:ShowPassive() end
end

-- LV状況HP増減
-- params[1]:効果最小ユニットLV
-- params[2]:効果最大ユニットLV
-- params[3]:HP加算最大値
-- params[4]:HP倍率最大値
-- params[5]:成長曲線係数
function process1030515(_target, params)
local coe
	Field:FrameUpdate(_target)
	if params[5] == 0 then params[5] = 10000 end
	coe = math.max(math.min(((this:Level() - params[1]) / (params[2] - params[1])) ^ (params[5] * Per2Num), 1), 0)
	if this:EditMaxHP(TARGSTAT_REAL, round(params[3] * coe), round(params[4] * coe), 0, LIFETYPE_CONTINUOUS) then Process:ShowPassive() end
end

