function process1030517(_target, params)
local coe, pv
	Field:FrameUpdate(_target)
	pv = this:GetProcValue()
	if pv == nil then
		coe = calcCoe(this:GetGeneralCount(params[1]), params[2], params[3])
		if coe > 0 then
			this:SetBuff(BuffIds.WP_MaxHpEdit, {-1, round(params[4] * coe), round(params[5] * coe)})
