-- 経過時間状況属性耐性増減
-- params[1]:効果発生間隔(秒)
-- params[2]:効果最小時間(秒)
-- params[3]:効果最大時間(秒)
-- params[4]:属性条件
-- params[5]:増減値
function process1030716(_target, params)
Field:FrameUpdate(_target)
local beforeCoe = Process:GetKeptParam(4) or 0
local called, coe, icoe, cnt, res
	if params[1] > 0 and Process:IsSucceeded() then
		called = (Process:GetKeptParam(2) or 0) + 1
		cnt = Process:GetKeptParam(3) or 0
		if params[1] <= called then
			called = 0
			cnt = cnt + 1
		end
		Process:KeepParam(2, called)
		Process:KeepParam(3, cnt)
		coe = math.max(math.min((cnt * params[1] - params[2]) / (params[3] - params[2]), 1), 0)
		icoe = math.floor(coe * Pct100)
		Process:KeepParam(4, icoe)
		if coe > 0 and this:EditElemResist(TARGSTAT_REAL, params[4], round(params[5] * coe), LIFETYPE_CONTINUOUS) then
			if called == 0 and beforeCoe ~= icoe then Process:ShowPassive() end
		end
	end
end

-- 同一スキル連続使用状況属性付き特定攻撃スキル敵属性耐性増減
-- params[1]:効果最小連続発動数
-- params[2]:効果最大連続発動数
-- params[3]:スキル属性条件
-- params[4]:スキルタイプ条件
-- params[5]:属性耐性増減最大値
function process1030717(_target, params)
Field:FrameUpdate(_target)
local skl = TimeLine:ParentSkill()
local pv = this:GetProcValue() or {0, 0}
local coe, buid
	if skl:Role(SKILL_ROLE_ATTACK) and skl:Element(params[3]) and skl:Type(params[4]) then
		if pv[1] ~= TimeLine:SKL_ID() then pv[1] = TimeLine:SKL_ID() pv[2] = 0 end
		pv[2] = pv[2] + 1
		coe = math.max(math.min((pv[2] - params[1]) / (params[2] - params[1]), 1), 0)
		if coe > 0 then
			buid = this:SetBuff(BuffIds.P_PenetrateElemResistPUID, {-1, TimeLine:SKL_PUID(), round(params[5] * coe)})
			if buid then this:SetBuff(BuffIds.S_SkillEndBuffControl, {-1, TimeLine:SKL_PUID(), buid}) end
			Process:ShowPassive()
		end
		this:SetProcValue(pv)
	else
		this:SetProcValue({0, 0})
	end
end

