-- ハッピーギビング
-- params[1]:ターゲットID
function process1030815(_target, params)
local u
local tbl, maxi, maxc
	Field:FrameUpdate(_target)
	tbl, maxi, maxc = {}, 0, {}
	for i,u in pairs(units:GetCondUnitList(TARGET_SIDE_OPPONENT, TARGET_COND_ALIVE, UNIT_COND_NONE)) do
		for j,k in pairs(u:Type()) do
			tbl[k] = (tbl[k] or 0) + 1
			if maxi < tbl[k] then
				maxi = tbl[k]
				maxc = {k}
			elseif maxi == tbl[k] then
				table.insert(maxc, k)
			end
		end
	end
	if maxc[1] ~= nil then maxc = maxc[math.random(1, #maxc)] else maxc = 0 end
	u = this:GetProcessTarget(params[1])
	if u ~= nil and maxc ~= 0 then
		u:SetBuff(BuffIds.S_TargetUidAliveElemSkillKiller, {-1, this:ID(), ELEMENT_UNMENTIONED, SKILL_PHYSIC, maxc})
	end
end

