-- 指定時間毎移動速度累積増減
-- params[1]:指定間隔
-- params[2]:効果最小累積復活数
-- params[3]:効果最大累積復活数
-- params[4]:移動速度最大加算値
-- params[5]:移動速度最大倍率
-- params[6]:オプション
function process1031016(_target, params)
Field:FrameUpdate(_target)
local pv = this:GetProcValue() or {}
local cnt = (pv[1] or 0) + 1
local beforeSbf, beforeRbf = pv[2], pv[3]
local Sbf, Rbf
local beforeCoe = calcCoe(cnt - 1, params[2], params[3])
local coe = calcCoe(cnt, params[2], params[3])
	if beforeSbf ~= nil then this:ExpireBuff(beforeSbf) end
	if beforeRbf ~= nil then this:ExpireBuff(beforeRbf) end
	if coe > 0 then Sbf = this:SetBuff(bitToBoolean(params[6], 1) and BuffIds.WP_SpdEdit or BuffIds.P_SpdEdit, {-1, round(params[4] * coe), round(params[5] * coe)}) end
	if Sbf then
		if bitToBoolean(params[6], 2) then Rbf = this:SetBuff(BuffIds.S_DefeatReset, {-1}) end
		if coe > 0 and beforeCoe ~= coe then Process:ShowPassive() end
	end
	pv[1] = cnt
	pv[2] = Sbf
	pv[3] = Rbf
	this:SetProcValue(pv, bitToBoolean(params[6], 1))
end

