-- params[2]:効果発生人数
-- params[3]:適正人数
-- params[4]:詠唱時間倍率
function process1031202(_target, params)
local cnt, coe
	Field:FrameUpdate(_target)
	cnt = #(units:GetCondUnitList(TARGET_SIDE_ALLY, TARGET_COND_BOTH, UNIT_COND_CHARA_TYPE, params[1]))
	coe = math.max(math.min((cnt - params[2]) / (params[3] - params[2]), 1), 0)
	if this:EditCastSpeed(math.floor(params[4] * coe), LIFETYPE_CONTINUOUS) then Process:ShowPassive() end
end

