function process1031206(_target, params)
local coe
	Field:FrameUpdate(_target)
	coe = calcCoe(this:GetGeneralCount(params[1]), params[2], params[3])
	if coe > 0 and this:EditCastSpeed(math.floor(params[5] * coe), LIFETYPE_CONTINUOUS) then Process:ShowPassive() end
end

