-- 特定キャラ以外全体VITダメージ増減
-- params[1]:敵・味方
-- params[2]:自分を含むか 0:含む 1:含まない
-- params[3]:キャラタイプ条件
-- params[4]:VITダメージ加算値
-- params[5]:VITダメージ倍率
function process1031418(_target, params)
local t, cnt, tu, ulist
	Field:FrameUpdate(_target)
	t = this:GetProcValue() or {}
	tu = t[2] or {}
	if next(tu) == nil then
		ulist = units:GetCondUnitList(params[1], TARGET_COND_BOTH, UNIT_COND_NONE)
	else
		ulist = Process:TrigUnits()
	end
	for i,u in pairs(ulist) do
		if (params[1] == TARGET_SIDE_ALL or u:RelativeSide(this) == params[1]) and (params[2] == 0 or u:ID() ~= this:ID()) and not u:Type(params[3]) and not toBoolean(tu[u:ID()]) then
			if u:SetBuff(DebuffIds.P_SufferVitEdit, {-1, params[4], params[5]}) then tu[u:ID()] = true end
		end
	end
	t[2] = tu
	this:SetProcValue(t)
end

-- 特定キャラタイプ以外味方生存人数状況VITダメージ増減
-- params[1]:キャラタイプ条件
-- params[2]:効果最小人数
-- params[3]:効果最大人数
-- params[4]:エネミータイプ
-- params[5]:VITダメージ加算値
-- params[6]:VITダメージ倍率
function process1031419(_target, params)
local coe,cnt,res
local cType
	Field:FrameUpdate(_target)
	cType = (params[1] == 0 and this:Type() or {params[1]})
	cnt = 0
	for i,u in pairs(units:GetCondUnitList(TARGET_SIDE_ALLY, TARGET_COND_ALIVE, UNIT_COND_NONE)) do
		res = true
		for j,k in pairs(cType) do
			if u:Type(k) then res = false break end
		end
		if res then cnt = cnt + 1 end
	end
	coe = math.max(math.min((cnt - params[2]) / (params[3] - params[2]), 1), 0)
	if coe > 0 and Bullet:EditVitDamage(round(params[5] * coe), round(params[6] * coe)) then Process:ShowPassive() end
end

