-- HP指定量変動毎特定対象属性付き特定スキル累積VITダメージ増減
-- params[1]:条件方向
-- params[2]:条件HP変動閾値
-- params[3]:効果最小回数
-- params[4]:効果最大回数
-- params[5]:エネミータイプ条件
-- params[6]:属性条件
-- params[7]:スキルタイプ条件
-- params[8]:VITダメージ加算値
-- params[9]:VITダメージ倍率
-- params[10]:オプション
function process1031423(_target, params)
Field:FrameUpdate(_target)
local pv = this:GetProcValue() or {}
local cnt = (pv[1] or 0) + (Process:GetKeptParam(1, bitToBoolean(params[10], 1)) or 1)
local beforeSbf, beforeRbf = pv[2], pv[3]
local Sbf, Rbf
local beforeCoe = math.max(math.min((cnt - 1 - params[3]) / (params[4] - params[3]), 1), 0)
local coe = math.max(math.min((cnt - params[3]) / (params[4] - params[3]), 1), 0)
	if beforeSbf ~= nil then this:ExpireBuff(beforeSbf) end
	if beforeRbf ~= nil then this:ExpireBuff(beforeRbf) end
	if coe > 0 then Sbf = this:SetBuff(bitToBoolean(params[10], 1) and BuffIds.WP_TargetSkillVitDamagePer or BuffIds.P_TargetSkillVitDamagePer, {-1, params[5], params[6], params[7], round(params[8] * coe), round(params[9] * coe)}) end
	if Sbf then
		if bitToBoolean(params[10], 2) then Rbf = this:SetBuff(BuffIds.S_DefeatReset, {-1}) end
		if coe > 0 and beforeCoe ~= coe then Process:ShowPassive() end
	end
	pv[1] = cnt
	pv[2] = Sbf
	pv[3] = Rbf
	this:SetProcValue(pv, bitToBoolean(params[10], 1))
end

