-- params[9]:VITダメージ加算最大値
-- params[10]:VITダメージ最大倍率
function process1031429(_target, params)
local coe,cnt
	Field:FrameUpdate(_target)
	cnt = 0
	for i,u in pairs(units:GetCondUnitList(params[1], params[2]&2==2 and TARGET_COND_BOTH or TARGET_COND_ALIVE, UNIT_COND_NONE + (params[2]&1==1 and UNIT_COND_NOT_ME or 0))) do
		if u:Type(params[3]) then cnt = cnt + 1 end
	end
	coe = calcCoe(cnt, params[4], params[5])
	if coe > 0 and Bullet:EditVitDamage(round(params[9] * coe), round(params[10] * coe)) then Process:ShowPassive() end
end

