-- 特技発動時指定時間スーパーアーマー
-- params[1]:特技INDEX
-- params[2]:継続時間
-- params[3]:スーパーアーマー値
-- params[4]:遅延時間
function process1031703(_target, params)
	Field:FrameUpdate(_target)
	if params[4] > 0 then
		this:SetBuff(BuffIds.S_IntervalSubProc, {-1, this:ID(), (1<<24) + (1<<16) + (Pct100<<2) + (0<<1) + 0, params[4], params[2], params[3]})
	else
		this:SetBuff(BuffIds.P_SuperArmor, {params[2], params[3]})
	end
end

