-- params[1]:汎用数値情報番号
-- params[2]:効果最小数値
-- params[3]:効果最大数値
-- params[4]:MP加算最大値
-- params[5]:MP倍率最大値
function process1031803(_target, params)
local coe, pv
	Field:FrameUpdate(_target)
	pv = this:GetProcValue()
	if pv == nil then
		coe = calcCoe(this:GetGeneralCount(params[1]), params[2], params[3])
		if coe > 0 then
			this:SetBuff(BuffIds.WP_MaxMpEdit, {-1, round(params[4] * coe), round(params[5] * coe)})
			this:SetProcValue(true, true)
			Process:ShowPassive()
		end
	end
end

