-- params[2]:ストック増減値
function process1032300(_target, params)
local skl
	Field:FrameUpdate(_target)
	if params[1] == 0 then
		this:EditSkillStock(params[2])
	else
		skl = this:GetSkillFromIndexUI(params[1])
		if skl ~= nil then
			this:EditSkillStock(params[2], skl:Index())
		end
	end
end

-- 特定IDスキル発動時特技ストック数増減
-- params[1]:スキルID条件
-- params[2]:制限回数
-- params[3]:特技INDEX
-- params[4]:ストック増減値
function process1032301(_target, params)
Field:FrameUpdate(_target)
local skl
local cnt = Process:GetKeptParam(1) or 0
	if params[2] <= 0 or cnt < params[2] then
		if params[3] == 0 then
			this:SetBuff(BuffIds.P_MaxSpEdit, {-1, params[4]})
		else
			skl = this:GetSkillFromIndexUI(params[3])
			if skl ~= nil then
				this:SetBuff(BuffIds.P_MaxSpEdit, {-1, params[4], skl:Index()})
			end
		end
		Process:KeepParam(1, 1, CALCULATE_ADD)
		Process:ShowPassive()
	end
end

