-- 気絶・ブレイク時累積VIT上限増減
-- params[1]:エネミータイプ条件
-- params[2]:効果最小累積気絶・ブレイク数
-- params[3]:効果最大累積気絶・ブレイク数
-- params[4]:VIT上限加算値
-- params[5]:VIT上限倍率
-- params[6]:オプション
function process1032700(_target, params)
Field:FrameUpdate(_target)
local pv = this:GetProcValue() or {}
local cnt = (pv[1] or 0) + 1
local beforeSbf, beforeRbf = pv[2], pv[3]
local Sbf, Rbf
local beforeCoe = calcCoe(cnt - 1, params[2], params[3])
local coe = calcCoe(cnt, params[2], params[3])
	if beforeSbf ~= nil then this:ExpireBuff(beforeSbf) end
	if beforeRbf ~= nil then this:ExpireBuff(beforeRbf) end
	if coe > 0 then Sbf = this:SetBuff(bitToBoolean(params[6], 1) and BuffIds.WP_MaxVitEdit or BuffIds.P_MaxVitEdit, {-1, round(params[4] * coe), round(params[5] * coe)}) end
	if Sbf then
		if bitToBoolean(params[6], 2) then Rbf = this:SetBuff(BuffIds.S_DefeatReset, {-1}) end
		if coe > 0 and beforeCoe ~= coe then Process:ShowPassive() end
	end
	pv[1] = cnt
	pv[2] = Sbf
	pv[3] = Rbf
	this:SetProcValue(pv, bitToBoolean(params[6], 1))
end

-- LV状況VIT上限増減
-- params[1]:効果最小ユニットLV
-- params[2]:効果最大ユニットLV
-- params[3]:VIT上限最大加算値
-- params[4]:VIT上限最大倍率
-- params[5]:成長曲線係数
function process1032701(_target, params)
local coe
	Field:FrameUpdate(_target)
	if params[5] == 0 then params[5] = 10000 end
	coe = math.max(math.min(((this:Level() - params[1]) / (params[2] - params[1])) ^ (params[5] * Per2Num), 1), 0)
	if this:EditMaxVIT(TARGSTAT_REAL, round(params[3] * coe), round(params[4] * coe), 0, LIFETYPE_CONTINUOUS) then Process:ShowPassive() end
end

