-- 属性耐性条件バトル開始時全体異常付与
-- params[1]:敵・味方
-- params[2]:発生確率
-- params[3]:属性耐性種別条件
-- params[4]:発動条件方向
-- params[5]:属性耐性閾値
-- params[6]:状態異常種類
-- params[7]:状態異常継続時間補正値
-- params[8]:状態異常継続時間倍率
function process1040005(_target, params)
local Over,Under = 1,0
local res = false
	Field:FrameUpdate(_target)
	if params[3] ~= ELEMENT_NONE then
		if params[7]==0 and params[8]==0 then
			for i,u in ipairs(units:GetCondUnitList(params[1], TARGET_COND_ALIVE, UNIT_COND_NONE)) do
				if (params[4]==Over and u:ElemResist(params[3]) >= params[5]) or (params[4]==Under and u:ElemResist(params[3]) < params[5]) then
					if lottery(params[2]) then u:SetAilment(params[6]) end
					res = true
				end
			end
		else
			-- 状態異常継続時間の変動を可能にするため、外部プロセスからのみ渡せる継続時間補正パラメータを加味して計算する
			for i,u in ipairs(units:GetCondUnitList(params[1], TARGET_COND_ALIVE, UNIT_COND_NONE)) do
				if (params[4]==Over and u:ElemResist(params[3]) >= params[5]) or (params[4]==Under and u:ElemResist(params[3]) < params[5]) then
					if lottery(params[2]) then u:SetAilment(params[6], math.max(math.floor((AilmentLifeTimes[params[6]] + params[7]) * (1 + (params[8] * Per2Num))), 1)) end
					res = true
				end
			end
		end
		if res then Process:ShowPassive() end
	end
end

