-- 自分死亡時相手ランダム基本状態異常付与
-- params[1]:基本状態異常数
-- params[2]:状態異常継続時間補正値
-- params[3]:状態異常継続時間倍率
function process1040007(_target, params)
local t, flag
local tbl = {{math.random(), AILMENT_POISON},{math.random(), AILMENT_PARALYSYS},{math.random(), AILMENT_SICK},{math.random(), AILMENT_BLIND},{math.random(), AILMENT_CURSE},{math.random(), AILMENT_SILENCE}}
	Field:FrameUpdate(_target)
	if params[1] <= 0 then return nil end
	t = Bullet:Parent()
	table.sort(tbl, function(a, b) return (a[1] < b[1]) end)
	flag = false
	if params[2]==0 and params[3]==0 then
		for i = 1, math.min(params[1], 6) do
			if t:SetAilment(tbl[i][2]) then flag = true end
		end
		if flag then Process:ShowPassive() end
	else
		for i = 1, math.min(params[1], 6) do
			-- 状態異常継続時間の変動を可能にするため、外部プロセスからのみ渡せる継続時間補正パラメータを加味して計算する
			if t:SetAilment(tbl[i][2], math.max(math.floor((AilmentLifeTimes[tbl[i][2]] + params[2]) * (1 + (params[3] * Per2Num))), 1)) then flag = true end
			if flag then Process:ShowPassive() end
		end
	end
end

