-- 特定状態異常発生時状態異常・HP回復
-- params[1]:状態異常条件
-- params[2]:HP回復値
-- params[3]:HP回復倍率
function process1040100(_target, params)
local res = false
	Field:FrameUpdate(_target)
	if params[1] > 0 then
		if this:RemoveAilment(params[1]) then
			this:HealPct(this, params[2], params[3])
			Process:ShowPassive()
		end
	else
		for i,j in pairs(bitBooleanList(Process:GetKeptParam(2) or 0, 2)) do
			if i > 0 and j and (params[1] == 0 or IS_AILMENT_COMMON[i]) then
				if this:RemoveAilment(i) then
					this:HealPct(this, params[2], params[3])
					res = true
				end
			end
		end
		if res then Process:ShowPassive() end
	end
	Process:KeepParam(1, bitBooleanListToVal(this:AilmentList()))
end

-- 撃破時基本状態異常ランダム回復
-- params[1]:状態異常回復数
function process1040101(_target, params)
local tbl = {}
local res = false
	Field:FrameUpdate(_target)
	if params[1] > 0 then
		for i,j in pairs(this:AilmentList()) do
			if j and IS_AILMENT_COMMON[i] then
				table.insert(tbl, i)
			end
		end
		tbl = arrayRandomize(tbl)
		for i = 1, params[1] do
			if tbl[i] ~= nil then
				res = this:RemoveAilment(tbl[i]) or res
			end
		end
	else
		for i,j in pairs(this:AilmentList()) do
			if j and IS_AILMENT_COMMON[i] then
				res = this:RemoveAilment(i) or res
			end
		end
	end
	if res then Process:ShowPassive() end
end

