-- 味方特定状態異常発生時状態異常回復
-- params[1]:発生確率
-- params[2]:制限回数
-- params[3]:自分を含むか 0:含む 1:含まない
-- params[4]:状態異常条件
-- params[5]:状態異常回復対象
function process1040103(_target, params)
local buid, tbl, ulist
	Field:FrameUpdate(_target)
	tbl = this:GetProcValue()
	if tbl == nil then
		tbl = {0, {}, {}, false}	-- 1:count 2:unitList 3:buidList 4:isEnd
		ulist = units:GetCondUnitList(TARGET_SIDE_ALLY, TARGET_COND_ALIVE, UNIT_COND_NONE + (params[3] == 1 and UNIT_COND_NOT_ME or 0))
	else
		ulist = Process:TrigUnits()
	end
	if params[1] <= 0 or tbl[1] < params[1] then
		for i,u in pairs(ulist) do
			if u:RelativeSide(this) == TARGET_SIDE_ALLY and (params[3] == 0 or u:ID() ~= this:ID()) and not toBoolean(tbl[2][u:ID()]) then
				buid = u:SetBuff(BuffIds.S_AilmentTriggerSubProc, {-1, this:ID(), (1<<24) + (math.max(params[2], 0)<<16) + params[1], params[4], params[5]})
				if buid then
					table.insert(tbl[3], buid)
					tbl[2][u:ID()] = true
				end
			end
		end
		this:SetProcValue(tbl)
	end
end

-- 撃破時基本状態異常ランダム回復
-- params[1]:発動間隔(10秒単位)
