Field:FrameUpdate(_target)
local tbl = {}
local res = false
local cnt = Process:GetKeptParam(2)
	if cnt == nil then cnt = 1 Process:KeepParam(2, 1) end
	if params[1] > 0 and params[1] <= cnt then
		if params[2] > 0 then
			for i,j in pairs(this:AilmentList()) do
				if j and IS_AILMENT_COMMON[i] then
					table.insert(tbl, i)
				end
			end
			tbl = arrayRandomize(tbl)
			for i = 1, params[2] do
				if tbl[i] ~= nil then
					res = this:RemoveAilment(tbl[i]) or res
				end
			end
		else
			for i,j in pairs(this:AilmentList()) do
				if j and IS_AILMENT_COMMON[i] then
					res = this:RemoveAilment(i) or res
				end
			end
		end
		if res then Process:ShowPassive() end
		Process:KeepParam(2, 1)
	else
		Process:KeepParam(2, 1, CALCULATE_ADD)
	end
end

