-- ボス死亡時特定モンスターボス化
-- params[1]～params[10]:モンスターID条件
function process1040401(_target, params)
local ulist
	Field:FrameUpdate(_target)
	ulist = units:GetCondUnitList(TARGET_SIDE_ALL, TARGET_COND_ALIVE, UNIT_COND_NONE)
	for i = 1,10 do
		if params[i] == 0 then return nil end
		for j,u in pairs(ulist) do
			if not u:IsBoss() and  u:MonsterID() == params[i] then
				Field:SetBossFlag(u, true)
				return nil
			end
		end
	end
end

