-- 指定領域内全体属性付き特定スキル被ダメージ増減
-- params[1]:領域番号条件
-- params[2]:敵・味方
-- params[3]:自分を含むか 0:含む 1:含まない
-- params[4]:属性条件
-- params[5]:スキルタイプ条件
-- params[6]:ダメージ倍率補正
function process1050229(_target, params)
local pv
	Field:FrameUpdate(_target)
	if params[1] == 0 then
		Process:SetFailed()
	else
		-- pv = {uid = buid, uid = buid}
		pv = this:GetProcValue() or {}
		for i,coll in pairs(Process:TrigCollisions()) do
			if coll:GroupIds(params[1]) then
				for j,u in pairs(coll:TrigUnits()) do
					if u:RelativeSide(this, params[2]) and (params[3] == 0 or this:ID() ~= u:ID()) then
						if coll:InsideTargetIds(u:ID()) then
							if not pv[u:ID()] then
								pv[u:ID()] = u:SetBuff(BuffIds.S_TargetUidAliveElemSkillSufferDmgPer,{-1, this:ID(), params[4], params[5], params[6]})
							end
						elseif pv[u:ID()] then
							u:ExpireBuff(pv[u:ID()])
							pv[u:ID()] = nil
						end
					end
				end
			end
		end
		this:SetProcValue(pv)
	end
end

