-- 指定回数特技与ダメージ増減
-- params[1]:特技INDEX
-- params[2]:制限回数
-- params[3]:ダメージ倍率補正
function process1050271(_target, params)
local pv, cnt, buid, skl
	Field:FrameUpdate(_target)
	skl = TimeLine:ParentSkill()
	if skl then
		pv = this:GetProcValue() or {}
		if params[1] > 0 then
			if skl:IndexUI() ~= params[1] then return end
			cnt = pv[params[1]] or 0
			pv[params[1]] = cnt + 1
		elseif params[1] == 0 then
			cnt = pv[1] or 0
			pv[1] = cnt + 1
		elseif params[1] == -1 then
			cnt = pv[skl:IndexUI()] or 0
			pv[skl:IndexUI()] = cnt + 1
		end
		if params[2] <= 0 or params[2] > cnt then
			buid = this:SetBuff(BuffIds.P_TargetSkillPUIDDmgPer, {-1, TimeLine:SKL_PUID(), params[3]})
			if buid then this:SetBuff(BuffIds.S_SkillEndBuffControl, {-1, TimeLine:SKL_PUID(), buid}) this:SetProcValue(pv) end
		end
	end
end

