-- 指定回数魔法与ダメージ増減
-- params[1]:制限回数
-- params[2]:ダメージ倍率補正
function process1050360(_target, params)
Field:FrameUpdate(_target)
local cnt = Process:GetKeptParam(1) or 0
local list = this:GetValue(UNIT_VALUE_PROCESS_1050360_LIST) or {del = {}}
local skl = this:ActSkill()
local sid, puids, puid, buid, flag
	if skl ~= nil then
		sid = skl:ID()
		if list[sid] == nil then list[sid] = {puid = {}, buid = {}, del = {}} end
		puids = skl:PUIDs()
		for i,j in pairs(list[sid].puid) do
			flag  = false
			for k,l in pairs(puids) do
				if j == l then
					flag = true
					break
				end
			end
			if not flag then
				list[sid].del[i] = true
			end
		end
		for i = #(list[sid].puid), 1, -1 do
			if list[sid].del[i] then
				-- バフ配列のずれによりクライアント側でNULLアクセスが発生するため、暫定対処
				-- this:ExpireBuff(list[sid].buid[i])
				table.insert(list.del, list[sid].buid[i])
				table.remove(list[sid].puid, i)
				table.remove(list[sid].buid, i)
				table.remove(list[sid].del, i)
			end
		end
		if params[1]>cnt then
			flag = false
			puid = TimeLine:SKL_PUID()
			for i,j in pairs(list[sid].puid) do
				if j == puid then
					flag = true
					break
				end
			end
			if not flag then
				buid = this:SetBuff(BuffIds.P_TargetSkillPUIDDmgPer, {-1, puid, params[2]})
				if buid then
					table.insert(list[sid].puid, puid)
					table.insert(list[sid].buid, buid)
					table.insert(list[sid].del, false)
					if not this:IsBuff(BuffIds.S_BuffControl_1050360) then this:SetBuff(BuffIds.S_BuffControl_1050360, {-1}) end
					Process:KeepParam(1, 1, CALCULATE_ADD)
					Process:ShowPassive()
				end
			end
		end
		this:SetValue(UNIT_VALUE_PROCESS_1050360_LIST, list)
	end
end

-- 魔法与ダメージランダム増減
-- params[1]:ダメージ倍率補正MIN
-- params[2]:ダメージ倍率補正MAX
function process1050361(_target, params)
local coe
	Field:FrameUpdate(_target)
	if params[1] >= 0 and params[2] >= 0 then
		coe = math.random(params[1], params[2])
	elseif params[1] < 0 and params[2] >= 0 then
		coe = math.random(0, params[2] - params[1]) + params[1]
	elseif params[1] < 0 and params[2] < 0 then
		coe = - math.random(- params[1], - params[2])
	end
	if Bullet:EditDamagePer(coe) then Process:ShowPassive() end
end

