-- params[1]:スキルタイプ条件
-- params[2]:ダメージ軽減量タイプ(固定/割合)
-- params[3]:ダメージ軽減量MIN
-- params[4]:ダメージ軽減量MAX
function process1050418(_target, params)
local Type_Fixed, Type_MaxHp, Type_NowHp = 0, 1, 2
local val
	Field:FrameUpdate(_target)
	if params[2] == Type_Fixed then
		val = round(math.random(params[3], params[4]))
	elseif params[2] == Type_MaxHp then
		val = round(this:MaxHP() * math.random(params[3], params[4]) * Per2Num)
	elseif params[2] == Type_NowHp then
		val = round(this:HP() * math.random(params[3], params[4]) * Per2Num)
	end
	if val > 0 and Bullet:EditDamage(math.max(Bullet:Damage() - val, 1)) then Process:PlayTimeline(2) Process:ShowPassive() end
end

