-- 劣化時間回復被ダメージ増減
-- params[1]:装備条件
-- params[2]:開始時劣化状況
-- params[3]:ダメージ倍率最大補正
-- params[4]:劣化発生率
-- params[5]:劣化加算補正
-- params[6]:劣化回復時間
function process1050423(_target, params)
Field:FrameUpdate(_target)
local DEGRADE_NONE, DEGRADE_HARF, DEGRADE_FULL = 0, 1, 2
local pv = this:GetProcValue()
local sign
	if pv == nil then
		if params[2] == DEGRADE_NONE then
			pv = {0, params[3]}
		elseif  params[2] == DEGRADE_HARF then
			pv = {0, params[3] / 2}
		elseif  params[2] >= DEGRADE_FULL then
			pv = {0, 0}
		end
		this:SetBuff(BuffIds.S_ProcessEventResetPV, {-1, PROC_TRIGGER_DETERIORATE_RECOVER, 1})
	end
	sign = params[3] / math.abs(params[3])
	pv[2] = math.min(math.abs(pv[2]) + (params[6] > 0 and ((Field:Time() - pv[1]) / params[6] * math.abs(params[3])) or 0), math.abs(params[3])) * sign
	pv[1] = Field:Time()
	if round(pv[2]) ~= 0 and Bullet:EditDamagePer(round(pv[2])) then Process:ShowPassive() end
	if params[4] > 0 and lottery(params[4]) then
		if math.abs(pv[2]) < math.abs(params[5]) then
			pv[2] = 0
		else
			pv[2] = pv[2] + params[5]
		end
	end
	this:SetProcValue(pv)
end

