-- 全体HP条件累積達成状況特定属性特定スキル与ダメージ増減
-- params[1]:敵味方
-- params[2]:条件閾値方向
-- params[3]:条件HP閾値
-- params[4]:効果最小回数
-- params[5]:効果最大回数
-- params[6]:属性条件
-- params[7]:スキルタイプ条件
-- params[8]:ダメージ倍率最大補正
function process1050431(_target, params)
local t, cnt, tu, ulist
	Field:FrameUpdate(_target)
	t = this:GetProcValue() or {}
	tu = t[2] or {}
	if next(tu) == nil then
		ulist = units:GetCondUnitList(params[1], TARGET_COND_ALIVE, UNIT_COND_NONE)
		this:SetBuff(BuffIds.S_WholeHpCondElemSkillDmgPerStep_Own, {-1, params[6], params[7], params[4], params[5], params[8]})
	else
		ulist = Process:TrigUnits()
	end
	for i,u in pairs(ulist) do
		if u:RelativeSide(this)==params[1] and u:Alive() and not toBoolean(tu[u:ID()]) then
			if u:SetBuff(BuffIds.S_WholeHpCondElemSkillDmgPerStep_Ally, {-1, params[2], params[3], params[4], params[5]}) then tu[u:ID()] = true end
		end
	end
	t[2] = tu
	this:SetProcValue(t)
end

