-- params[1]:効果発生人数
-- params[2]:適正人数
-- params[3]:スキルタイプ条件
-- params[4]:ダメージ倍率補正
function process1050433(_target, params)
local coe,cnt
	Field:FrameUpdate(_target)
	cnt = #(units:GetCondUnitList(TARGET_SIDE_OPPONENT, TARGET_COND_ALIVE, UNIT_COND_NONE))
	coe = math.max(math.min((cnt - params[1]) / (params[2] - params[1]), 1), 0)
	if coe > 0 and Bullet:EditDamagePer(round(params[4] * coe)) then Process:ShowPassive() end
end

-- 特定種別特定スキル累積与ダメージ増減
-- params[1]:スキル種別条件
-- params[2]:スキルタイプ条件
-- params[3]:効果最小発動数
-- params[4]:効果最大発動数
-- params[5]:ダメージ倍率最大補正
function process1050434(_target, params)
Field:FrameUpdate(_target)
local pv = this:GetProcValue() or 0
local coe, buid
	pv = pv + 1
	coe = math.max(math.min((pv - params[3]) / (params[4] - params[3]), 1), 0)
	if coe > 0 then
		buid = this:SetBuff(BuffIds.P_TargetSkillPUIDDmgPer, {-1, TimeLine:SKL_PUID(), round(params[5] * coe)})
		if buid then this:SetBuff(BuffIds.S_SkillEndBuffControl, {-1, TimeLine:SKL_PUID(), buid}) end
		Process:ShowPassive()
	end
	this:SetProcValue(pv)
end

