-- 同一スキル連続使用状況与ダメージ増減
-- params[1]:効果最小連続発動数
-- params[2]:効果最大連続発動数
-- params[3]:スキルタイプ条件
-- params[4]:ダメージ倍率最大補正
function process1050443(_target, params)
Field:FrameUpdate(_target)
local skl = TimeLine:ParentSkill()
local pv = this:GetProcValue() or {0, 0}
local coe, buid
	if skl:Role(SKILL_ROLE_ATTACK) and skl:Type(params[3]) then
		if pv[1] ~= TimeLine:SKL_ID() then pv[1] = TimeLine:SKL_ID() pv[2] = 0 end
		pv[2] = pv[2] + 1
		coe = math.max(math.min((pv[2] - params[1]) / (params[2] - params[1]), 1), 0)
		if coe > 0 then
			buid = this:SetBuff(BuffIds.P_TargetSkillPUIDDmgPer, {-1, TimeLine:SKL_PUID(), round(params[4] * coe)})
			if buid then this:SetBuff(BuffIds.S_SkillEndBuffControl, {-1, TimeLine:SKL_PUID(), buid}) end
			Process:ShowPassive()
		end
		this:SetProcValue(pv)
	else
		this:SetProcValue({0, 0})
	end
end

-- デバフ数状況特定スキル与ダメージ増減
-- params[1]:効果最小バフ数
-- params[2]:効果最大バフ数
-- params[3]:スキルタイプ条件
-- params[4]:ダメージ倍率補正
function process1050444(_target, params)
local t, cnt, coe
	Field:FrameUpdate(_target)
	t = {}
	cnt = 0
	for i,j in pairs(this:GetVisibleBuff(true)) do
		-- 同一バフカテゴリは1回のみカウント
		if t[j[BUFF_INFO_CATEGORY]] == nil then
			t[j[BUFF_INFO_CATEGORY]] = true
			cnt = cnt + 1
		end
	end
	coe = math.max(math.min((cnt - params[1]) / (params[2] - params[1]), 1), 0)
	if coe > 0 and Bullet:EditDamagePer(round(params[4] * coe)) then Process:ShowPassive() end
end

-- 特技ストック合計数状況特定スキル与ダメージ増減
-- params[1]:効果発生ストック合計数
-- params[2]:効果最大ストック合計数
-- params[3]:スキルタイプ条件
-- params[4]:ダメージ倍率補正
function process1050445(_target, params)
local coe,cnt
	Field:FrameUpdate(_target)
	cnt = 0
	for i,skl in pairs(this:GetSkill(SKILL_SKILL)) do
		cnt = cnt + skl:Stock()
	end
	coe = math.max(math.min((cnt - params[1]) / (params[2] - params[1]), 1), 0)
	if coe > 0 and Bullet:EditDamagePer(round(params[4] * coe)) then Process:ShowPassive() end
end

-- 敵同一キャラ存在人数状況特定スキル与ダメージ増減
-- params[1]:効果発生人数
-- params[2]:適正人数
-- params[3]:スキルタイプ条件
-- params[4]:ダメージ倍率補正
function process1050446(_target, params)
local coe,cnt,list
	Field:FrameUpdate(_target)
	list = {}
	cnt = 0
	for i,j in pairs(Bullet:Target():Type()) do
		list[j] = 0
	end
	for i,u in pairs(units:GetCondUnitList(TARGET_SIDE_OPPONENT, TARGET_COND_ALIVE, UNIT_COND_NONE)) do
		for j,k in pairs(u:Type()) do
			if list[k] ~= nil then
				list[k] = (list[k] or 0) + 1
				if cnt < list[k] then cnt = list[k] end
			end
		end
	end
	coe = math.max(math.min((cnt - params[1]) / (params[2] - params[1]), 1), 0)
	if coe > 0 and Bullet:EditDamagePer(round(params[4] * coe)) then Process:ShowPassive() end
end

