-- 特技発動時MP消費与ダメージ増加
-- params[1]:消費MP値
-- params[2]:消費MP倍率
-- params[3]:ダメージ倍率補正
function process1050471(_target, params)
Field:FrameUpdate(_target)
local list = this:GetValue(UNIT_VALUE_PROCESS_1050471_LIST) or {}
local cost = math.max(math.ceil(params[1] + (this:MaxMP() * params[2] / Pct100)), 1)
local sid, puid, buid, flag
local skl = this:ActSkill()
	if skl ~= nil and skl:Type(SKILL_SKILL) then
		sid = skl:ID()
		-- 同一スキルで発動済みの星眼スキルの存在チェック
		if list[sid] == nil then list[sid] = {puid = {}, buid = {}, del = {}} end
		puid = skl:PUIDs()
		for i,j in pairs(list[sid].puid) do
			flag = false
			for k,l in pairs(puid) do
				if j == l then
					flag = true
					break
				end
			end
			if not flag then
				list[sid].del[i] = true
			end
		end
		for i = #(list[sid].puid), 1, -1 do
			if list[sid].del[i] then
				this:ExpireBuff(list[sid].buid[i])
				table.remove(list[sid].puid, i)
				table.remove(list[sid].buid, i)
				table.remove(list[sid].del, i)
			end
		end

		-- ここからはメイン処理（MPを消費してダメージアップ）
		if this:MP() >= cost and this:DecMp(params[1], params[2]) then
			for i,j in pairs(puid) do
				flag = false
				for k, l in pairs(list[sid].puid) do
					if j == l then
						flag = true
						break
					end
				end
				if not flag then
					buid = this:SetBuff(BuffIds.P_TargetSkillPUIDDmgPer, {-1, j, params[3]})
					if buid then
						table.insert(list[sid].puid, j)
						table.insert(list[sid].buid, buid)
						table.insert(list[sid].del, false)
						Process:ShowPassive()
					end
				end
			end
		end
		this:SetValue(UNIT_VALUE_PROCESS_1050471_LIST, list)
	end
end

