-- params[2]:スキルタイプ条件
-- params[3]:消費MP値
-- params[4]:消費MP倍率
-- params[5]:ダメージ倍率補正
function process1050477(_target, params)
Field:FrameUpdate(_target)
local list = this:GetValue(UNIT_VALUE_PROCESS_1050477_LIST) or {}
local cost = math.max(math.ceil(params[3] + (this:MaxMP() * params[4] / Pct100)), 1)
local skl = this:ActSkill()
local sid, puid, buid, flag
	if skl ~= nil then
		sid = skl:ID()
		if list[sid] == nil then list[sid] = {puid = {}, buid = {}, del = {}} end
		puid = skl:PUIDs()
		for i,j in pairs(list[sid].puid) do
			flag  = false
			for k,l in pairs(puid) do
				if j == l then
					flag = true
					break
				end
			end
			if not flag then
				list[sid].del[i] = true
			end
		end
		for i = #(list[sid].puid), 1, -1 do
			if list[sid].del[i] then
				this:ExpireBuff(list[sid].buid[i])
				table.remove(list[sid].puid, i)
				table.remove(list[sid].buid, i)
				table.remove(list[sid].del, i)
			end
		end
		if this:MP() >= cost then
			if this:DecMp(params[3], params[4]) then
				for i,j in pairs(puid) do
					flag  = false
					for k,l in pairs(list[sid].puid) do
						if j == l then
							flag = true
							break
						end
					end
					if not flag then
						buid = this:SetBuff(BuffIds.P_TargetSkillPUIDDmgPer, {-1, j, params[5]})
						if buid then
							table.insert(list[sid].puid, j)
							table.insert(list[sid].buid, buid)
							table.insert(list[sid].del, false)
							Process:ShowPassive()
						end
					end
				end
			end
		end
		this:SetValue(UNIT_VALUE_PROCESS_1050477_LIST, list)
	end
end

