function process1050488(_target, params)
Field:FrameUpdate(_target)
local coe,cnt,list
	list = {}
	cnt = 0
	for i,u in pairs(units:GetCondUnitList(TARGET_SIDE_ALLY, TARGET_COND_BOTH, UNIT_COND_NONE)) do
		for j,k in pairs(u:Type()) do
			if not toBoolean(list[k]) then
				list[k] = true
				cnt = cnt + 1
			end
		end
	end
	coe = math.max(math.min((cnt - params[1]) / (params[2] - params[1]), 1), 0)
	if coe > 0 and Bullet:EditDamagePer(round(params[3] * coe)) then Process:ShowPassive() end
end

