-- 属性付き指定スキル喰い
-- params[1]:属性条件
-- params[2]:スキルタイプ条件
-- params[3]:特技INDEX
-- params[4]:回復値
-- params[5]:回復倍率
-- params[6]:回復倍率(1ストック)
-- params[7]:回復値(ストック補完)
-- params[8]:ダメージ倍率補正
function process1050501(_target, params)
Field:FrameUpdate(_target)
local skl
local add = 0
	if Bullet:NoDamage() then
		if params[3] > 0 then
			skl = this:GetSkillFromIndexUI(params[3])
			if skl~= nil then
				add = math.ceil((params[6] / Pct100) * (skl:Cost() / 1000) + math.max((params[7] - (skl:Charge() * 1000) / skl:Cost()) * (skl:Cost() / 1000), 0))
				this:EditSingleSCT(TARGSTAT_REAL, params[4] + add, params[5], skl:Index())
			end
		elseif params[3] == 0 then
			for i = 1, this:SkillCount(SKILL_SKILL) do
				add = math.ceil((params[6] / Pct100) * (this:SKL_Cost(SKILL_SKILL, i) / 1000) + math.max((params[7] - (this:SKL_Charge(SKILL_SKILL, i) * 1000) / this:SKL_Cost(SKILL_SKILL, i)) * (this:SKL_Cost(SKILL_SKILL, i) / 1000), 0))
				this:EditSingleSCT(TARGSTAT_REAL, params[4] + add, params[5], i)
			end
		elseif params[3] == -1 then
			skl = this:GetSkill(SKILL_SKILL, math.random(1, this:SkillCount(SKILL_SKILL)))
			if skl~= nil then
				add = math.ceil((params[6] / Pct100) * (skl:Cost() / 1000) + math.max((params[7] - (skl:Charge() * 1000) / skl:Cost()) * (skl:Cost() / 1000), 0))
				this:EditSingleSCT(TARGSTAT_REAL, params[4] + add, params[5], skl:Index())
			end
		end
		this:SetBuff(BuffIds.NextSkillDamagePer, {-1, 1, params[8]})
		Process:ShowPassive()
	end
end

