-- 指定ロール属性付き特定スキル使用数状況属性付き特定スキル被ダメージ増減
-- params[1]:スキルロール条件
-- params[2]:属性条件
-- params[3]:スキルタイプ条件
-- params[4]:効果最小スキル使用数
-- params[5]:効果最大スキル使用数
-- params[6]:被ダメージ属性条件
-- params[7]:被ダメージスキルタイプ条件
-- params[8]:ダメージ倍率補正
-- params[9]:オプション
function process1050520(_target, params)
Field:FrameUpdate(_target)
if not this:IsRemote() then
local pv = this:GetProcValue() or {}
local cnt = (pv[1] or 0) + 1
local beforeSbf, beforeRbf = pv[2], pv[3]
local Sbf, Rbf
local beforeCoe = math.max(math.min((cnt - 1 - params[4]) / (params[5] - params[4]), 1), 0)
local coe = math.max(math.min((cnt - params[4]) / (params[5] - params[4]), 1), 0)
	if beforeSbf ~= nil then this:ExpireBuff(beforeSbf) end
	if beforeRbf ~= nil then this:ExpireBuff(beforeRbf) end
	if coe > 0 then Sbf = this:SetBuff(BuffIds.P_ElementSkillSufferDamagePer, {-1, params[6], params[7], round(params[8] * coe)}) end
	if Sbf then
		if bitToBoolean(params[9], 1) then Rbf = this:SetBuff(BuffIds.S_DefeatReset, {-1}) end
		if coe > 0 and beforeCoe ~= coe then Process:ShowPassive() end
	end
	pv[1] = cnt
	pv[2] = Sbf
	pv[3] = Rbf
	this:SetProcValue(pv)
end
end

