-- HP指定量変動毎属性付き特定スキル累積与ダメージ増減
-- params[1]:条件方向
-- params[2]:条件HP変動閾値
-- params[3]:効果最小回数
-- params[4]:効果最大回数
-- params[5]:属性条件
-- params[6]:スキルタイプ条件
-- params[7]:ダメージ倍率最大補正
-- params[8]:オプション
function process1050543(_target, params)
Field:FrameUpdate(_target)
local pv = this:GetProcValue() or {}
local cnt = (pv[1] or 0) + (Process:GetKeptParam(1, bitToBoolean(params[8], 1)) or 1)
local beforeSbf, beforeRbf = pv[2], pv[3]
local Sbf, Rbf
local beforeCoe = math.max(math.min((cnt - 1 - params[3]) / (params[4] - params[3]), 1), 0)
local coe = math.max(math.min((cnt - params[3]) / (params[4] - params[3]), 1), 0)
	if beforeSbf ~= nil then this:ExpireBuff(beforeSbf) end
	if beforeRbf ~= nil then this:ExpireBuff(beforeRbf) end
	if coe > 0 then Sbf = this:SetBuff(bitToBoolean(params[8], 1) and BuffIds.WP_ElementSkillDamagePer or BuffIds.P_ElementSkillDamagePer, {-1, params[5], params[6], round(params[7] * coe)}) end
	if Sbf then
		if bitToBoolean(params[8], 2) then Rbf = this:SetBuff(BuffIds.S_DefeatReset, {-1}) end
		if coe > 0 and beforeCoe ~= coe then Process:ShowPassive() end
	end
	pv[1] = cnt
	pv[2] = Sbf
	pv[3] = Rbf
	this:SetProcValue(pv, bitToBoolean(params[8], 1))
end

