-- 特定装備特定スキル与ダメージランダム増減
-- params[1]:装備条件
-- params[2]:スキルタイプ条件
-- params[3]:ダメージ倍率補正MIN
-- params[4]:ダメージ倍率補正MAX
function process1050554(_target, params)
local coe
	Field:FrameUpdate(_target)
	if params[3] >= 0 and params[4] >= 0 then
		coe = math.random(params[3], params[4])
	elseif params[3] < 0 and params[4] >= 0 then
		coe = math.random(0, params[4] - params[3]) + params[3]
	elseif params[3] < 0 and params[4] < 0 then
		coe = - math.random(- params[3], - params[4])
	end
	if Bullet:EditDamagePer(coe) then Process:ShowPassive() end
end

