-- 対特定キャラ以外特定スキル与ダメージ増減
-- params[1]:スキルタイプ条件
-- params[2]:通常攻撃時与ダメージ倍率加算値
-- params[3]:特技攻撃時与ダメージ倍率加算値
-- params[4]:魔法攻撃時与ダメージ倍率加算値
-- params[5]:超必殺技攻撃時与ダメージ倍率加算値
-- params[6]:与ダメージ倍率最大値
function process1050565(_target, params)
Field:FrameUpdate(_target)
local pv = this:GetProcValue() or {}
local skl, buid
local val = 0
	pv[1] = pv[1] or 0
	if not this:IsRemote() and pv[1] < params[6] then
		skl = TimeLine:ParentSkill()
		if skl:Type(SKILL_ATTACK) then
			val = params[2]
		elseif skl:Type(SKILL_SKILL) then
			val = params[3]
		elseif skl:Type(SKILL_MAGIC) then
			val = params[4]
		elseif skl:Type(SKILL_SPECIAL) then
			val = params[5]
		end
		if val > 0 and pv[3] ~= TimeLine:SKL_PUID() then
			pv[1] = math.min(pv[1] + val, params[6])
			-- マルチで多重に掛かってしまうことがある件を応急処置
			-- buid = this:SetBuff(BuffIds.P_SkillDamagePer, {-1, params[1], pv[1]})
			if params[1] == SKILL_SKILL then
				buid = this:SetBuff(BuffIds.E_MultiFirstAid_1, {-1, params[1], pv[1]})
			elseif params[1] == SKILL_MAGIC then
				buid = this:SetBuff(BuffIds.E_MultiFirstAid_2, {-1, params[1], pv[1]})
			end
			if buid then
				if pv[2] ~= nil and Field:IsBuffExists(pv[2]) then
					this:ExpireBuff(pv[2])
				end
				pv[2] = buid
				pv[3] = TimeLine:SKL_PUID()
				this:SetProcValue(pv)
				Process:ShowPassive()
			end
		end
	end
end

