function process1050587(_target, params)
local t, cnt, ulist
	Field:FrameUpdate(_target)
	t = this:GetProcValue() or {}
	if next(t) == nil then
		ulist = units:GetCondUnitList(TARGET_SIDE_ALLY, TARGET_COND_BOTH, UNIT_COND_NONE)
	else
		ulist = Process:TrigUnits()
	end
	for i,u in pairs(ulist) do
		if u:RelativeSide(this)==TARGET_SIDE_ALLY and (params[1]==0 or u:ID()~=this:ID()) and not toBoolean(t[u:ID()]) then
			if u:SetBuff(BuffIds.S_TargetUidAliveElemSkillDmgPer, {-1, this:ID(), params[2], params[3], params[4]}) then t[u:ID()] = true end
		end
	end
	this:SetProcValue(t)
end

-- 特定種別特定スキル累計使用数状況属性付き特定スキル与ダメージ増減
-- params[1]:スキル種別条件
-- params[2]:スキルタイプ条件
-- params[3]:効果最小使用数
-- params[4]:効果最大使用数
-- params[5]:属性条件
-- params[6]:スキルタイプ条件
-- params[7]:与ダメージ倍率最大値
function process1050588(_target, params)
Field:FrameUpdate(_target)
local pv = this:GetProcValue() or {}
local cnt = (pv[1] or 0) + 1
local Sbf
local beforeSbf = pv[2]
local beforeCoe = pv[3] or 0
local coe = math.max(math.min((cnt - params[3]) / (params[4] - params[3]), 1), 0)
	if beforeCoe ~= coe then
		if beforeSbf ~= nil then this:ExpireBuff(beforeSbf) end
		if coe > 0 then
			Sbf = this:SetBuff(BuffIds.P_ElementSkillDamagePer, {-1, params[5], params[6], round(params[7] * coe)})
			if Sbf then Process:ShowPassive() end
		end
		pv[2] = Sbf
	end
	pv[1] = cnt
	pv[3] = coe
	this:SetProcValue(pv)
end

-- 同一属性特定スキル連続使用状況属性付き特定スキル与ダメージ増減
-- params[1]:効果最小連続発動数
-- params[2]:効果最大連続発動数
-- params[3]:制限時間
-- params[4]:属性条件
-- params[5]:スキルタイプ条件
-- params[6]:ダメージ倍率最大補正
function process1050589(_target, params)
Field:FrameUpdate(_target)
local skl = TimeLine:ParentSkill()
local pv = this:GetProcValue() or {0, 0, 0}
local coe, buid
	if skl:Role(SKILL_ROLE_ATTACK) and skl:Element(params[4]) then
		if pv[1] ~= 0 then if Field:IsBuffExists(pv[1]) then this:ExpireBuff(pv[1]) else pv[2] = 0 end end
		if pv[2] > 0 and not skl:Element(pv[3]) then pv[2] = 0 end
		if pv[2] == 0 then pv[3] = skl:Element() end
		pv[2] = pv[2] + 1
		coe = math.max(math.min((pv[2] - params[1]) / (params[2] - params[1]), 1), 0)
		if coe > 0 then
			buid = this:SetBuff(BuffIds.P_TargetSkillPUIDDmgPer, {-1, TimeLine:SKL_PUID(), round(params[6] * coe)})
			if buid then
				this:SetBuff(BuffIds.S_SkillEndBuffControl, {-1, TimeLine:SKL_PUID(), buid})
			end
			Process:ShowPassive()
		end
		buid = this:SetBuff(BuffIds.Control_UseBuffUid, {params[3]})
		if buid then pv[1] = buid end
		this:SetProcValue(pv)
	else
		this:SetProcValue({0, 0, 0})
	end
end

