-- MP消費魔法二属性比較変化
-- params[1]:消費MP値
-- params[2]:消費MP倍率
-- params[3]:消費MPコスト倍率
-- params[4]:発動条件属性
-- params[5]:変換対象属性
function process1050701(_target, params)
Field:FrameUpdate(_target)
local list = this:GetValue(UNIT_VALUE_PROCESS_1050701_LIST) or {}
local cost
local sid, puid, flag
local skl = Bullet:GetParentSkill()
	if skl ~= nil then
		sid = skl:ID()
		if list[sid] == nil then list[sid] = {puid = {}, del = {}} end
		puid = skl:PUIDs()
		for i,j in pairs(list[sid].puid) do
			flag = false
			for k,l in pairs(puid) do
				if j == l then
					flag = true
					break
				end
			end
			if not flag then
				list[sid].del[i] = true
			end
		end
		for i = #(list[sid].puid), 1, -1 do
			if list[sid].del[i] then
				table.remove(list[sid].puid, i)
				table.remove(list[sid].del, i)
			end
		end
		
		puid = Bullet:SKL_PUID()
		flag = false
		for i, j in pairs(list[sid].puid) do
			if j == puid then
				flag = true
				break
			end
		end
		if flag then
			Bullet:EditElement(params[5])
		else
			cost = math.max(math.ceil(params[1] + (this:MaxMP() * params[2] / Pct100) + (skl:Cost() * params[3] / Pct100)), 1)
			if this:MP() >= cost and this:DecMp(cost, 0) then
				if Bullet:EditElement(params[5]) then
					Process:ShowPassive()
				end
				table.insert(list[sid].puid, puid)
				table.insert(list[sid].del, false)
			end
		end
		this:SetValue(UNIT_VALUE_PROCESS_1050701_LIST, list)
	end
end

