-- HIT毎HP割合バリア
-- params[1]:バリアHPタイプ(固定/割合)
-- params[2]:バリアHPMIN
-- params[3]:バリアHPMAX
function process1050800(_target, params)
local Type_Fixed, Type_MaxHp, Type_NowHp = 0, 1, 2
local val
	Field:FrameUpdate(_target)
	if params[1] == Type_Fixed then
		val = round(math.random(params[2], params[3]))
	elseif params[1] == Type_MaxHp then
		val = round(this:MaxHP() * math.random(params[2], params[3]) * Per2Num)
	elseif params[1] == Type_NowHp then
		val = round(this:HP() * math.random(params[2], params[3]) * Per2Num)
	end
	this:Barrier(TARGSTAT_WORK, val, 0, LIFETYPE_TRANSIENT)
end

