-- 指定攻撃被弾時特技強制発動
-- params[1]:属性条件
-- params[2]:スキルタイプ条件
-- params[3]:特技INDEX
function process1070002(_target, params)
local puid, stat
local buid
	Field:FrameUpdate(_target)
	if params[3] > 0 then
		skl = this:GetSkillFromIndexUI(params[3])
	elseif params[3] == 0 then
		skl = this:GetSkill(SKILL_ATTACK, 1)
	elseif params[3] == -1 then
		skl = this:GetSkill(SKILL_SKILL, math.random(1, this:SkillCount(SKILL_SKILL)))
	end
	if skl ~= nil then
		puid, stat = skl:Play(Bullet:Parent(), PLAYSKILL_MODE_COUNTER, PLAYSKILL_OPTION_IGNORECOST, 0, PLAYSKILL_MOVE_WARP)
		if stat == PLAYSKILL_STAT_PLAY then
			Process:ShowPassive()
		elseif stat == PLAYSKILL_STAT_RESERVE then
			buid = this:SetBuff(BuffIds.S_SkillPuidShowPassive, {-1, puid})
			if buid then
				this:SetBuff(BuffIds.S_NotSkillPuidBuffControl, {-1, puid, buid})
			end
		end
	end
end

