-- WAVE開始指定時間後通常ステータスデバフ消去
-- params[1]:待機時間
-- params[2]:消去数
-- params[3]:STRデバフ可否
-- params[4]:DEFデバフ可否
-- params[5]:INTデバフ可否
-- params[6]:MNDデバフ可否
function process1080400(_target, params)
local buid, prm
	Field:FrameUpdate(_target)
	prm = (params[3]<<4) + (params[4]<<5) + (params[5]<<6) + (params[6]<<7)
	buid = this:SetBuff(BuffIds.Control_UseBuffUid, {params[1]})
	if buid then this:SetBuff(BuffIds.S_UidBuffEndRemoveStatusBuffDebuff, {-1, buid, params[2], prm}) end
end

-- 定期通常ステータスデバフ消去10
-- params[1]:発動間隔(10秒単位)
-- params[2]:消去数
-- params[3]:STRデバフ可否
-- params[4]:DEFデバフ可否
-- params[5]:INTデバフ可否
-- params[6]:MNDデバフ可否
function process1080401(_target, params)
Field:FrameUpdate(_target)
local flag, rcnt
local cateList = {}
local tbl, ctbl, rtbl = {}, {}, {}
local unq, res = {}, {}
local cnt = Process:GetKeptParam(2)
	if cnt == nil then cnt = 1 Process:KeepParam(2, 1) end
	if params[1] > 0 and params[1] <= cnt then
		if params[3] ~= 0 then table.insert(cateList, BUFF_CATEGORY_STR_DOWN_1) end
		if params[4] ~= 0 then table.insert(cateList, BUFF_CATEGORY_DEF_DOWN_1) end
		if params[5] ~= 0 then table.insert(cateList, BUFF_CATEGORY_INT_DOWN_1) end
		if params[6] ~= 0 then table.insert(cateList, BUFF_CATEGORY_MND_DOWN_1) end
		for i,cate in pairs(cateList) do
			tbl[cate] = {}
			for j,bff in pairs(this:GetBuffCategoryBuffs(cate)) do
				table.insert(tbl[cate], bff[BUFF_INFO_UID])
				flag = false
				for k,r in ipairs(rtbl) do
					if r < bff[BUFF_INFO_REMAIN] then
						table.insert(ctbl, k, cate)
						table.insert(rtbl, k, bff[BUFF_INFO_REMAIN])
						flag = true
						break
					end
				end
				if not flag then
					table.insert(ctbl, cate)
					table.insert(rtbl, bff[BUFF_INFO_REMAIN])
				end
			end
		end
		for i,cate in ipairs(ctbl) do
			if unq[cate] == nil then
				unq[cate] = true
				table.insert(res, 1, cate)
			end
		end
		rcnt = 0
		for i,cate in ipairs(res) do
			if params[2] <= 0 or params[2] > rcnt then
				for j,buid in pairs(tbl[cate]) do
					this:ExpireBuff(buid)
				end
				rcnt = rcnt + 1
			else
				break
			end
		end
		if rcnt > 0 then Process:ShowPassive() end
		Process:KeepParam(2, 1)
	else
		Process:KeepParam(2, 1, CALCULATE_ADD)
	end
end

-- 指定間隔アイテム入荷
-- params[1]:指定間隔
-- params[2]:ペアリングID
function process1080402(_target, params)
Field:FrameUpdate(_target)
	local res  = false
	local cnt = Process:GetKeptParam(1) or 0
	if params[1] > 0 and params[1] <= cnt then
		for i,buid in pairs(target:GetPairingBuffs('Item' .. tostring(params[2]))) do
			this:ExpireBuff(buid)
			res = true
		end
		if res then Process:ShowPassive() end
		Process:KeepParam(1, 1)
	else
		Process:KeepParam(1, 1, CALCULATE_ADD)
	end
end

