function process1081026(_target, params)
Field:FrameUpdate(_target)
local buid
local ulist = this:GetProcValue() or {}
	for i,u in pairs(units:GetCondUnitList(TARGET_SIDE_OPPONENT, TARGET_COND_BOTH, UNIT_COND_NONE)) do
		if not toBoolean(ulist[u:ID()]) then
			buid = u:SetBuff(DebuffIds.S_InvalidationTargetBuffActorSkillAvoid, {-1, params[2], this:ID(), params[1], params[4], params[5], params[3]})
			if buid then ulist[u:ID()] = buid end
		end
	end
	this:SetProcValue(ulist)
end

-- 指定ステータス値状況死神耐性
-- params[1]:ステータスタイプ
-- params[2]:効果最小数値
-- params[3]:効果最大数値
-- params[4]:発生最大確率
function process1081027(_target, params)
local coe
	Field:FrameUpdate(_target)
	coe = calcCoe(this:Status(params[1]), params[2], params[3])
	if lottery(round(params[4] * coe)) then if TrigProc:EditProb(0, -Pct100, 0) then Process:ShowPassive() end end
end

