-- 被カリスマパラメータ変更
-- params[1]:バフID条件
-- params[2]:変更パラメータINDEX
-- params[3]:演算内容
-- params[4]:フリーパラメータ1
-- params[5]:フリーパラメータ2
-- params[6]:フリーパラメータ3
-- params[7]:フリーパラメータ4
-- params[8]:フリーパラメータ5
function process1081139(_target, params)
local prm,calc,val,res
	Field:FrameUpdate(_target)
	prm = bitSplitArray(params[3], 4)
	res = 0
	for i,j in ipairs(prm) do
		if i%2 == 0 then
			if j == 0 then
				val = (calc == CALCULATE_MULT or calc == CALCULATE_DIV) and 1 or 0
			elseif j <= 10 then
				val = TrigProc:Param(j)
			else
				val = Process:Param(j - 7)
			end
			res = calculate(calc, res, val)
		else
			calc = j
		end
	end
	for i,j in ipairs(bitSplitArray(params[2], 4)) do
		TrigProc:EditProcParam(j, res)
	end
end

-- 特定汎用数値情報状況特定カテゴリバフ付与時時間延長
-- params[1]:汎用数値情報番号
-- params[2]:効果最小数値
-- params[3]:効果最大数値
-- params[4]:バフカテゴリ条件
-- params[5]:継続時間増減値
-- params[6]:継続時間倍率
function process1081140(_target, params)
local coe
	Field:FrameUpdate(_target)
	coe = calcCoe(this:GetGeneralCount(params[1]), params[2], params[3])
	if coe > 0 and TrigProc:EditParam(PARAM_BEHAV_FLAME, round(params[5] * coe), round(params[6] * coe)) then Process:ShowPassive() end
end

