-- 開始時キャラタイプランダム追加
-- params[1]:追加数
-- params[2]～params[9]:キャラクタータイプ
-- params[10]:キャラクタータイプ予備
function process1081402(_target, params)
local res = false
local tbl = {}
	Field:FrameUpdate(_target)
	if params[1] == 0 then
		for i = 2,9 do
			if params[i] ~= 0 then
				res = this:AddType(TARGSTAT_REAL, params[i]) or res
			else
				break
			end
		end
	elseif params[1] > 0 then
		for i = 2,9 do
			if params[i] ~= 0 then
				table.insert(tbl, params[i])
			else
				break
			end
		end
		tbl = arrayRandomize(tbl)
		for i = 1,math.min(params[1], #tbl) do
			res = this:AddType(TARGSTAT_REAL, tbl[i]) or res
		end
	end
	if res then Process:ShowPassive() end
end

