-- params[7]:発動毎情報数値
-- params[8]:演算オプション
function process1081622(_target, params)
Field:FrameUpdate(_target)
local cost = math.max(math.ceil(params[4] + (this:MaxHP() * params[5] / Pct100)), 1)
	if params[6]~=0 and this:HP() > 1 and this:DotDamage(math.min(cost, this:HP() - 1), false) then
		if TimeLine:SKL_SetValue(params[6], params[7], params[8]) then Process:ShowPassive() end
	end
end

