-- 魔王への覚醒
-- params[1]:属性被ダメージ補正1
-- params[2]:uiMsgID1
-- params[3]:属性被ダメージ補正2
-- params[4]:uiMsgID2
-- params[5]:属性被ダメージ補正3
-- params[6]:uiMsgID3
-- params[7]:属性被ダメージ補正4
-- params[8]:uiMsgID4
-- params[9]:属性被ダメージ補正5
-- params[10]:uiMsgID5
function process1081625(_target, params)
Field:FrameUpdate(_target)
local elem, cnt
local tbl = this:GetProcValue() or {}
	elem = Bullet:Element()
	if elem ~= ELEMENT_NONE then
		tbl[elem] = tbl[elem] or {}
		cnt = tbl[elem][1] or 0
		if cnt < 5 and params[(cnt + 1) * 2] ~= 0 then
			if cnt > 0 and Field:IsBuffExists(tbl[elem][2]) then this:ExpireBuff(tbl[elem][2]) end
			cnt = cnt + 1
			tbl[elem][1] = cnt
			tbl[elem][2] = this:SetBuff(BuffIds.P_ElementSkillSufferDamagePer, {-1, elem, 0, params[(cnt * 2) - 1]})
			Process:ShowMsg(nil, params[(cnt * 2)] + elem - 1)
			this:SetProcValue(tbl)
		end
	end
end

