-- 属性付き特定スキル発動時特技ストック消費スキル発動毎情報付与
-- params[1]:スキルロール条件
-- params[2]:属性条件
-- params[3]:スキルタイプ条件
-- params[4]:特技INDEX
-- params[5]:消費特技ストック値
-- params[6]:消費特技現在ストック割合
-- params[7]:消費特技最大ストック割合
-- params[8]:発動毎情報INDEX
-- params[9]:発動毎情報数値
-- params[10]:演算オプション
function process1081629(_target, params)
local skl, cost, cost2, flag
local n = {}
	Field:FrameUpdate(_target)
	if params[4] == 0 then
		cost = 0
		for i = 1, this:SkillCount(SKILL_SKILL) do
			n[i] = math.ceil(params[5] + (this:SKL_Stock(i) * params[6] / Pct100) + (this:SKL_MaxStock(i) * params[7] / Pct100))
			if this:SKL_Stock(i) < n[i] then return nil end
			cost = cost + n[i]
		end
		flag = false
		if cost ~= 0 then
			cost2 = 0
			-- 1つでも操作が失敗したら失敗
			for i = 1, this:SkillCount(SKILL_SKILL) do
				if n[i] ~= 0 then
					cost2 = cost2 + (n[i] * this:SKL_Cost(SKILL_SKILL, i) / 1000)
					flag = not this:EditSingleSCT(TARGSTAT_REAL, -(n[i] * this:SKL_Cost(SKILL_SKILL, i) / 1000), 0, i) or flag
				end
			end
			flag = not flag
		end
	else
		if params[4] > 0 then
			skl = this:GetSkillFromIndexUI(params[4])
		elseif params[4] == -1 then
			skl = this:GetSkill(SKILL_SKILL, math.random(1, this:SkillCount(SKILL_SKILL)))
		elseif params[4] == -2 then
			skl = {}
			for i = 1, this:SkillCount(SKILL_SKILL) do
				if this:SKL_Stock(i) >= math.ceil(params[5] + (this:SKL_Stock(i) * params[6] / Pct100) + (this:SKL_MaxStock(i) * params[7] / Pct100)) then
					table.insert(skl, this:GetSkill(SKILL_SKILL, i))
				end
			end
			if #skl > 0 then skl = skl[math.random(1, #skl)] else return nil end
		end
		if skl == nil then return nil end
		cost = math.max(math.ceil(params[5] + (skl:Stock() * params[6] / Pct100) + (skl:MaxStock() * params[7] / Pct100)), 1)
		if skl:Stock() < cost then return nil end
		cost2 = cost * skl:Cost() / 1000
		flag = this:EditSingleSCT(TARGSTAT_REAL, -(cost2), 0, skl:Index())
	end
	if params[8]~=0 and flag then
		if TimeLine:SKL_SetValue(params[8], params[9] + ((params[10]>>4)==1 and cost2 or ((params[10]>>3)==1 and cost or 0)), params[10]&3) then Process:ShowPassive() end
	end
end

