-- 属性付き特定スキル攻撃時熟練度蓄積型汎用数値情報付与
-- params[1]:属性条件
-- params[2]:スキルタイプ条件
-- params[3]:熟練度用汎用数値情報INDEX
-- params[4]:熟練度加算値
-- params[5]:汎用数値情報INDEX
-- params[6]:最大熟練度
-- params[7]:最大LV
-- params[8]:経験値曲線係数
-- params[9]:トリガ番号
function process1081643(_target, params)
local exp, lv, cnt
	Field:FrameUpdate(_target)
	if params[3] ~= 0 and params[5] ~= 0 and params[7] ~= 0 then
		lv = this:GetGeneralCount(params[5])
		if lv < params[7] then
			exp = select(2, this:AddGeneralCount(params[3], params[4]))
			cnt = 0
			while exp > math.floor(params[6] * ((lv + 1 + cnt) / params[7]) ^ (params[8] * Per2Num)) and lv + cnt < params[7] do
				cnt = cnt + 1
			end
			if cnt > 0 then
				this:AddGeneralCount(params[5], cnt)
				Process:SetProcEventValue(PROC_TRIGGER_GENERAL, params[9])
				this:RaiseTrigger(PROC_TRIGGER_GENERAL)
				Process:ShowPassive()
			end
		end
	end
end

-- 全体死亡時汎用数値情報付与
-- params[1]:敵味方
-- params[2]:自分を含むか 0:含む 1:含まない
