-- params[4]:汎用数値加算値
-- params[5]:オプション
-- params[6]:オプションパラメータ1
function process1081644(_target, params)
Field:FrameUpdate(_target)
local res
local t = Process:TrigUnits()
	if params[3] ~= 0 then
		res = false
		for i,u in pairs(t) do
			if this:RelativeSide(u, params[1]) and (params[2] == 0 or u:ID() ~= this:ID()) then
				res = (target:AddGeneralCount(params[3], params[4], params[5], {params[6]})) or res
			end
		end
		if res then Process:ShowPassiveForGeneralCount(params[3], target) end
	end
	if not res then Process:SetFailed() end
end

