function process1081651(_target, params)
local cnt = 0
	Field:FrameUpdate(_target)
	if params[4] ~= 0 then
		for i,u in pairs(units:GetCondUnitList(params[1], bitToBoolean(params[2], 2) and TARGET_COND_BOTH or TARGET_COND_ALIVE, UNIT_COND_NONE + (bitToBoolean(params[2], 1) and UNIT_COND_NOT_ME or 0))) do
			if not u:IsMonster() and (not bitToBoolean(params[2], 3) or u:Gender()~=GENDER_MALE) and (not bitToBoolean(params[2], 4) or u:Gender()~=GENDER_FEMALE) and (not bitToBoolean(params[2], 5) or u:Gender()~=GENDER_UNKNOWN) then
				for j,pid in pairs(u:PassiveList()) do
					if pid == params[3] then
						cnt = cnt + 1
						break
					end
				end
			end
		end
		if (this:AddGeneralCount(params[4], params[5] * cnt, params[6], {params[7]})) then Process:ShowPassiveForGeneralCount(params[4]) end
	end
end

