-- params[7]:汎用数値情報INDEX
-- params[8]:汎用数値加算値
-- params[9]:オプション
-- params[10]:オプションパラメータ1
function process1081656(_target, params)
local coe, val
	Field:FrameUpdate(_target)
	if params[2] ~= 0 and params[5] ~= 0 then
		coe = calcCoe(target:GetGeneralCount(params[2]), params[3], params[4])
		if coe > 0 then
			val = math.max(math.floor((target:MaxHP() * params[5] * Per2Num) * coe), 1)
			target:DotDamage(val, bitToBoolean(params[6], 1))
		end
	end
	if params[7] ~= 0 then
		if (target:AddGeneralCount(params[7], params[8] * (bitToBoolean(params[6], 2) and val or 1), params[9], {params[10]})) then Process:ShowPassiveForGeneralCount(params[7], target) end
	end
end

