-- params[1]:ユニット状態(0:不問 1:生存 2:死亡)
-- params[2]:指定間隔
-- params[3]:WAVE毎制限回数
-- params[4]:クエスト毎制限回数
-- params[5]:汎用数値情報INDEX
-- params[6]:汎用数値加算値
-- params[7]:オプション
-- params[8]:オプションパラメータ1
-- params[9]:トリガ番号
function process1081660(_target, params)
Field:FrameUpdate(_target)
	if params[1] == 0 or (params[1] == 1 and this:Alive()) or (params[1] == 2 and not this:Alive()) then
		local cnt = Process:GetKeptParam(2) or 0
		local qcnt = Process:GetKeptParam(3, true) or 0
		if (params[3] <= 0 or cnt < params[3]) and (params[4] <= 0 or qcnt < params[4]) then
			if params[5] ~= 0 then
				if (target:AddGeneralCount(params[5], params[6], params[7], {params[8]})) then Process:ShowPassiveForGeneralCount(params[5], target) end
				Process:SetProcEventValue(PROC_TRIGGER_GENERAL, params[9])
				this:RaiseTrigger(PROC_TRIGGER_GENERAL)
				Process:KeepParam(2, 1, CALCULATE_ADD)
				Process:KeepParam(3, 1, CALCULATE_ADD, true)
			end
		end
	end
end

