function process1081663(_target, params)
local coe
	Field:FrameUpdate(_target)
	if params[6] ~= 0 then
		if params[3] == 0 then coe = 1 else coe = calcCoe(this:GetGeneralCount(params[3]), params[4], params[5]) end
