		coe = calcCoe(target:LimitBreakLevel(), params[1], params[2])
		if coe > 0 and (target:AddGeneralCount(params[3], round(params[4] * coe), params[5], {params[6]})) then Process:ShowPassiveForGeneralCount(params[3], target) end
