-- 味方複数条件攻撃スキル発動時MP消費トリガ発行
-- params[1]:WAVE毎制限回数
-- params[2]:クエスト毎制限回数
-- params[3]:消費MP値
-- params[4]:消費MP割合
-- params[5]:スキル規模条件
-- params[6]:スキル属性条件
-- params[7]:スキルタイプ条件
-- params[8]:スキル種別条件
-- params[9]:スキル重複可否条件
-- params[10]:トリガ番号
function process1081667(_target, params)
Field:FrameUpdate(_target)
	local cnt = Process:GetKeptParam(1) or 0
	local qcnt = Process:GetKeptParam(2, true) or 0
	local skl = TimeLine:ParentSkill()
	local cost = 0
	if (params[1] <= 0 or cnt < params[1]) and (params[2] <= 0 or qcnt < params[2]) then
		if skl and (params[5] == 0 or skl:Scale() == params[5]) and (params[8] == -1 or skl:Kind() == params[8]) and (params[9] == -1 or skl:MultiCast() == params[9]) then
			if params[4] < 0 then
				if skl:Type(SKILL_MAGIC) then cost =  math.ceil(params[3] + (skl:Cost() * -params[4] / Pct100)) end
			else
				cost =  math.ceil(params[3] + (target:MaxMP() * params[4] / Pct100))
			end
			if cost <= 0 or (this:MP() >= cost and ((params[4] >= 0 and this:DecMp(params[3], params[4])) or (params[4] < 0 and this:DecMp(cost, 0)))) then
				Process:SetProcEventValue(PROC_TRIGGER_GENERAL, params[10], TimeLine:SKL_PUID())
				this:RaiseTrigger(PROC_TRIGGER_GENERAL)
				Process:ShowPassive()
				Process:KeepParam(1, 1, CALCULATE_ADD)
				Process:KeepParam(2, 1, CALCULATE_ADD, true)
			end
		end
	end
end

