-- params[4]:汎用数値情報INDEX
-- params[5]:汎用数値加算値
-- params[6]:オプション
-- params[7]:オプションパラメータ1
function process1081730(_target, params)
local cond, list, cnt
	Field:FrameUpdate(_target)
	if params[4] ~= 0 then
		cond = tableFlip(int32ToUnitTypeArray(params[3]), true)
		list, cnt = {}, 0
		for i,u in pairs(units:GetCondUnitList(params[1], params[2]&2==2 and TARGET_COND_BOTH or TARGET_COND_ALIVE, UNIT_COND_NONE + (params[2]&1==1 and UNIT_COND_NOT_ME or 0))) do
			for j,ct in pairs(u:Type()) do
				if not list[ct] and (params[3] == 0 or ((params[2]&4==0 and cond[ct]) or (params[2]&4==4 and not cond[ct]))) then
					list[ct] = true
					cnt = cnt + 1
				end
			end
		end
		if (this:AddGeneralCount(params[4], params[5] * cnt, params[6], {params[7]})) then Process:ShowPassiveForGeneralCount(params[4]) end
	end
end

