-- 対近特定時間毎外部スキル強制発動
-- params[1]:指定間隔MIN
-- params[2]:指定間隔MAX
-- params[3]:スキルID
function process1082111(_target, params)
Field:FrameUpdate(_target)
local puid, stat
local buid
local cnt = Process:GetKeptParam(1)
local interval = Process:GetKeptParam(2) or 1
local u = units:GetCondUnit(TARGET_SIDE_OPPONENT, TARGET_COND_ALIVE, UNIT_COND_NEAR)
	if params[3] > 0 then
		if cnt == nil then
			Field:LoadSkill(params[3])
			interval =  math.random(params[1], math.max(params[1], params[2]))
			Process:KeepParam(2, interval)
			cnt = 0
		end
		if interval > 0 and interval <= cnt then
			if u then
				puid, stat = this:SKL_PlayDirect(params[3], u, PLAYSKILL_MODE_FORCE_NONSTATE, PLAYSKILL_OPTION_IGNORECOST, 0, PLAYSKILL_MOVE_DIRECT)
				if stat == PLAYSKILL_STAT_PLAY then
					Process:ShowPassive()
				elseif stat == PLAYSKILL_STAT_RESERVE then
					buid = this:SetBuff(BuffIds.S_SkillPuidShowPassive, {-1, puid})
					if buid then
						this:SetBuff(BuffIds.S_NotSkillPuidBuffControl, {-1, puid, buid})
					end
				end
				Process:KeepParam(1, 1)
				Process:KeepParam(2, math.random(params[1], math.max(params[1], params[2])))
			end
		else
			Process:KeepParam(1, 1, CALCULATE_ADD)
		end
	end
end

-- 属性付き特定スキル発動時特定キャラ人数条件パッシブカットイン
