-- params[5]:キャラタイプ条件
-- params[6]:発動条件方向
-- params[7]:生存人数閾値
-- params[8]:uiMsgID
-- params[9]:パッシブID
-- params[10]:スキルID
function process1082112(_target, params)
local cnt, skl
	Field:FrameUpdate(_target)
	cnt = #(units:GetCondUnitList(params[4], TARGET_COND_ALIVE, UNIT_COND_CHARA_TYPE, params[5]))
	if procCompare(params[6], cnt, params[7]) then
		if params[8] ~= 0 then
			Process:ShowMsg(nil, params[8])
		elseif params[9] ~= 0 then
			Process:ShowMsg(nil, 'Not Supported')
		elseif params[10] ~= 0 then
			skl = this:GetSkillFromID(params[10])
			Process:ShowMsg(nil, skl:Name())
		else
			Process:ShowPassive()
		end
	end
end

