-- 指定時間毎領域展開
-- params[1]:初回発生時間
-- params[2]:発生間隔MIN
-- params[3]:発生間隔MAX
-- params[4]:継続時間
-- params[5]:コリジョンID
-- params[6]:敵味方
-- params[7]:領域番号
-- params[8]:演出番号
function process1082116(_target, params)
Field:FrameUpdate(_target)
local res, coll, interval
local pv = this:GetProcValue() or {}
local beforeBf, bid = pv[1], pv[2]
	if not this:Alive() then
		res = false
		if beforeBf ~= nil then
			for i,bff in pairs(this:GetBuffIdBuffs(BuffIds.Control_UseBuffUid_AE)) do
				if bff[BUFF_INFO_UID] == beforeBf then res = true break end
			end
			if not res then this:ExpireBuff(beforeBf) end
		end
		if not res then pv[1] = this:SetBuff(BuffIds.Control_UseBuffUid_AE, {-1}) end
	else
		res = (params[1]==0 and beforeBf == nil or false)
		if beforeBf ~= nil and not Field:IsBuffExists(beforeBf) then
			for i,bff in pairs(Process:TrigBuffs()) do
				if bff[BUFF_INFO_UID] == beforeBf then
					if bff[BUFF_INFO_ID] == BuffIds.Control_UseBuffUid_DE then res = true end
					break
				end
			end
		end
		if res then
			if bid ~= nil then 
				coll = Field:GetCollisionInstance(bid)
				if coll:Enable() then coll:Expire() end
			end
			interval = math.random(params[2], math.max(params[2], params[3]))
			coll = Field:CreateCollision(params[6], TARGET_SIDE_ME, nil, 0, nil, params[5], params[7])
			if interval <= params[4] then
				pv[2] = coll:ID()
			else
				pv[2] = nil
				this:SetBuff(BuffIds.S_UidBuffEndSubProc, {-1, this:ID(), (1<<24) + (1<<16) + (Pct100<<2) + (1<<1) + 0, this:SetBuff(BuffIds.Control_UseBuffUid, {params[4]}), coll:ID()})
			end
			pv[1] = this:SetBuff(BuffIds.Control_UseBuffUid_DE, {interval})
			Process:PlayTimeline(params[8])
		elseif beforeBf == nil then
			pv[1] = this:SetBuff(BuffIds.Control_UseBuffUid_DE, {params[1]})
		elseif not Field:IsBuffExists(beforeBf) then
			pv[1] = this:SetBuff(BuffIds.Control_UseBuffUid_DE, {math.random(params[2], math.max(params[2], params[3]))})
		else
			Process:SetFailed()
		end
	end
	if pv[1] ~= beforeBf or pv[2] ~= bid then this:SetProcValue(pv) end
end

-- 対特定バフ撃破時領域展開
-- params[1]:バフカテゴリ条件
