-- 指定時間毎外部スキル発動
-- params[1]:ターゲットID
-- params[2]:指定間隔MIN
-- params[3]:指定間隔MAX(現在は指定不可)
-- params[4]:スキルID
function process1082121(_target, params)
local isFirst, u
local puid, stat
local buid
	Field:FrameUpdate(_target)
	isFirst = (Process:GetKeptParam(1)==nil)
	if isFirst then
		Field:LoadSkill(params[4])
		Process:KeepParam(1, 1)
	elseif this:Alive() and not this:IsExcluded() then
		u = this:GetProcessTarget(params[1])
		if u ~= nil then
			puid, stat = this:SKL_PlayDirect(params[4], u, PLAYSKILL_MODE_FORCE_NONSTATE, PLAYSKILL_OPTION_IGNORECOST, 0, PLAYSKILL_MOVE_DIRECT)
			if stat == PLAYSKILL_STAT_PLAY then
				Process:ShowPassive()
			elseif stat == PLAYSKILL_STAT_RESERVE then
