	end
end

-- 特定攻撃被弾時特定汎用数値情報参照スロットスキル強制発動
-- params[1]:属性条件
-- params[2]:スキルタイプ条件
-- params[3]:発生確率
-- params[4]:制限回数
-- params[5]:クールタイム
-- params[6]:汎用数値情報番号(スキルスロット)
function process1082122(_target, params)
local puid, stat
local buid
local val, skl
local cnt, b4cnt, nowcnt
	Field:FrameUpdate(_target)
	if params[6] ~= 0 and lottery(params[3]) then
		cnt = Process:GetKeptParam(1) or 0
		if params[4] <= 0 or cnt < params[4] then
			nowcnt, b4cnt = this:Time(), Process:GetKeptParam(2)
			if b4cnt == nil or nowcnt - b4cnt >= params[5] then
				val = this:GetGeneralCount(params[6]) or 0
				if val ~= 0 then
					skl = this:GetSkill(SKILL_SLOT, val)
					if skl ~= nil then
						puid, stat = this:SKL_PlayDirect(skl:ID(), Bullet:Parent(), PLAYSKILL_MODE_FORCE_NONSTATE, PLAYSKILL_OPTION_IGNORECOST, 0, PLAYSKILL_MOVE_DIRECT)
						if stat == PLAYSKILL_STAT_PLAY then
							Process:ShowPassive()
							Process:KeepParam(1, 1, CALCULATE_ADD)
							Process:KeepParam(2, nowcnt)
							return
						elseif stat == PLAYSKILL_STAT_RESERVE then
							buid = this:SetBuff(BuffIds.S_SkillPuidShowPassive, {-1, puid})
							if buid then
								this:SetBuff(BuffIds.S_NotSkillPuidBuffControl, {-1, puid, buid})
							end
							Process:KeepParam(1, 1, CALCULATE_ADD)
							Process:KeepParam(2, nowcnt)
							return
						end
					end
				end
			end
		end
	end
	Process:SetFailed()
end

-- HP条件領域展開
-- params[1]:HP閾値方向
-- params[2]:HP割合条件
-- params[3]:継続時間
-- params[4]:コリジョンID
-- params[5]:敵味方
-- params[6]:領域番号
-- params[7]:演出番号
-- params[8]:オプション
function process1082123(_target, params)
Field:FrameUpdate(_target)
local coll
local pv = this:GetProcValue() or {}
	if this:PerHP() >= 0 and procCompare(params[1], this:PerHP(), params[2]) then
		if pv[2] ~= nil and Field:IsBuffExists(pv[2]) then
			Field:ExpireBuff(pv[2])
			pv[2] = nil
			this:SetProcValue(pv)
		end
		if pv[1] ~= nil then
			coll = Field:GetCollisionInstance(pv[1])
			if coll:Enable() then return end
		end
		if params[8] == 1 then
			coll = this:CreateFollowedCollision(params[5], TARGET_SIDE_ME, nil, nil, nil, params[4], params[6])
		else
			coll = Field:CreateCollision(params[5], TARGET_SIDE_ME, nil, 0, nil, params[4], params[6])
		end
		if true then
			this:SetBuff(BuffIds.S_HpCondCreateCollisionFirstAid, {-1, params[7]})
		else
			Process:PlayTimeline(params[7])
		end
		this:SetProcValue({coll:ID()})
	elseif pv[1] ~= nil then
		if params[3] > 0 then
			if pv[2] == nil then
				pv[2] = this:SetBuff(BuffIds.S_UidBuffEndSubProc, {-1, this:ID(), (1<<24) + (1<<16) + (Pct100<<2) + (1<<1) + 0, this:SetBuff(BuffIds.Control_UseBuffUid, {params[3]}), pv[1]})
				this:SetProcValue(pv)
			end
		else
			Field:RemoveCollision(pv[1])
			this:SetProcValue(nil)
		end
	end
end

