-- 開始時指定特技スキルロール詳細変更
-- params[1]:特技INDEX
-- params[2]:スキルロール詳細
function process1082129(_target, params)
local skl
	Field:FrameUpdate(_target)
	if params[1] == 0 then
		for i,s in pairs(this:GetSkill(SKILL_SKILL)) do
			s:SetRoleDtl(params[2])
		end
	else
		if params[1] > 0 then
			skl = this:GetSkillFromIndexUI(params[1])
		elseif params[1] == -1 then
			skl = this:GetSkill(SKILL_SKILL, math.random(1, this:SkillCount(SKILL_SKILL)))
		end
		if skl~= nil then
			skl:SetRoleDtl(params[2])
		end
	end
end

