-- 対特定敵タイプ特定性別人数状況属性付き特定スキルダメージ上限増減
-- params[1]:エネミータイプ条件
-- params[2]:敵味方
-- params[3]:条件オプション 1:自分を含まない +2:死者も含む +4:条件反転
-- params[4]:性別条件
-- params[5]:効果最小人数
-- params[6]:効果最大人数
-- params[7]:属性条件
-- params[8]:スキルタイプ条件
-- params[9]:ダメージ上限加算最大値
-- params[10]:ダメージ上限倍率最大補正
function process1082446(_target, params)
Field:FrameUpdate(_target)
local coe, cnt
	cnt = 0
	for i,u in pairs(units:GetCondUnitList(params[2], params[3]&2==2 and TARGET_COND_BOTH or TARGET_COND_ALIVE, UNIT_COND_NONE + (params[3]&1==1 and UNIT_COND_NOT_ME or 0))) do
		if (params[3]&4==0 and u:Gender()==params[4]) or (params[3]&4==4 and u:Gender()~=params[4]) then
			cnt = cnt + 1
		end
	end
	coe = calcCoe(cnt, params[5], params[6])
	if coe > 0 then Bullet:EditDamageLimit(round(params[9] * coe), round(params[10] * coe)) end
end

-- 特定キャラカテゴリキャラ種類数状況属性付き特定スキルダメージ上限増減
-- params[1]:エネミータイプ条件
-- params[2]:敵・味方
-- params[3]:自分を含むか
-- params[4]:キャラカテゴリ条件
-- params[5]:効果最小種類数
-- params[6]:効果最大種類数
-- params[7]:属性条件
-- params[8]:スキルタイプ条件
-- params[9]:ダメージ上限加算最大値
-- params[10]:ダメージ上限倍率最大補正
function process1082447(_target, params)
Field:FrameUpdate(_target)
local coe,cnt,ulist,list
	if params[4] == 0 then
		ulist = units:GetCondUnitList(params[2], TARGET_COND_BOTH, UNIT_COND_NONE + (params[3] == 1 and UNIT_COND_NOT_ME or 0))
	else
		ulist = units:GetCondUnitList(params[2], TARGET_COND_BOTH, UNIT_COND_CHARA_CATEGORY + (params[3] == 1 and UNIT_COND_NOT_ME or 0), params[4])
	end
	list = {}
	cnt = 0
	for i,u in pairs(ulist) do
		for j,k in pairs(u:Type()) do
			if (params[4] == 0 or unitTypeToCategory(k) == params[4]) and not toBoolean(list[k]) then
				list[k] = true
				cnt = cnt + 1
			end
		end
	end
	coe = calcCoe(cnt, params[5], params[6])
	if coe > 0 then Bullet:EditDamageLimit(round(params[9] * coe), round(params[10] * coe)) end
end

