-- 同一スキル連続使用状況ダメージ上限増減
-- params[1]:効果最小連続発動数
-- params[2]:効果最大連続発動数
-- params[3]:スキルタイプ条件
-- params[4]:ダメージ上限加算最大値
-- params[5]:ダメージ上限倍率最大補正
function process1082463(_target, params)
Field:FrameUpdate(_target)
local skl = TimeLine:ParentSkill()
local pv = this:GetProcValue() or {0, 0}
local coe, buid
	if skl:Role(SKILL_ROLE_ATTACK) and skl:Type(params[3]) then
		if pv[1] ~= TimeLine:SKL_ID() then pv[1] = TimeLine:SKL_ID() pv[2] = 0 end
		pv[2] = pv[2] + 1
		coe = calcCoe(pv[2], params[1], params[2])
		if coe > 0 then
			buid = this:SetBuff(BuffIds.P_TargetSkillPUIDDamageLimit, {-1, TimeLine:SKL_PUID(), round(params[4] * coe), round(params[5] * coe)})
			if buid then this:SetBuff(BuffIds.S_SkillEndBuffControl, {-1, TimeLine:SKL_PUID(), buid}) end
			Process:ShowPassive()
		end
		this:SetProcValue(pv)
	else
		this:SetProcValue({0, 0})
	end
end

-- 自身生存中味方全体キラー発生時属性付き特定スキルダメージ上限増減
-- params[1]:自分を含むか 0:含む 1:含まない
-- params[2]:キャラタイプ条件
-- params[3]:属性条件
-- params[4]:スキルタイプ条件
-- params[5]:ダメージ上限加算値
-- params[6]:ダメージ上限倍率補正
function process1082464(_target, params)
local t, cnt, ulist
	Field:FrameUpdate(_target)
	t = this:GetProcValue() or {}
	if next(t) == nil then
		ulist = units:GetCondUnitList(TARGET_SIDE_ALLY, TARGET_COND_BOTH, UNIT_COND_NONE)
	else
		ulist = Process:TrigUnits()
	end
	for i,u in pairs(ulist) do
		if u:RelativeSide(this)==TARGET_SIDE_ALLY and (params[1]==0 or u:ID()~=this:ID()) and not toBoolean(t[u:ID()]) then
			if u:SetBuff(BuffIds.S_TargetUidAliveTargetCharaKillerElemSkillDmgLimitBreak, {-1, this:ID(), params[2], params[3], params[4], params[5], params[6]}) then t[u:ID()] = true end
		end
	end
	this:SetProcValue(t)
end

