-- 対象壁距離状況特定汎用数値情報状況特定スキルダメージ上限増減
-- params[1]:対象壁方向
-- params[2]:効果発生壁距離
-- params[3]:効果最大壁距離
-- params[4]:汎用数値情報番号
-- params[5]:効果最小数値
-- params[6]:効果最大数値
-- params[7]:属性条件
-- params[8]:スキルタイプ条件
-- params[9]:ダメージ上限加算最大値
-- params[10]:ダメージ上限倍率最大補正
function process1082480(_target, params)
local coe, val
	Field:FrameUpdate(_target)
	if params[1] ~= 0 then
		val = -1
		if bitToBoolean(params[1], 1) then val = Bullet:Target():DistWallLeft() end
		if bitToBoolean(params[1], 2) then val = (val==-1 and Bullet:Target():DistWallRight() or math.min(val, Bullet:Target():DistWallRight())) end
		if bitToBoolean(params[1], 3) then val = (val==-1 and Bullet:Target():DistWallTop() or math.min(val, Bullet:Target():DistWallTop())) end
		if bitToBoolean(params[1], 4) then val = (val==-1 and Bullet:Target():DistWallDown() or math.min(val, Bullet:Target():DistWallDown())) end
		if val >= 0 then
			coe = (params[4]==0 and 1 or calcCoe(this:GetGeneralCount(params[4]), params[5], params[6])) * calcCoe(val, params[2], params[3])
			if coe > 0 then Bullet:EditDamageLimit(round(params[9] * coe), round(params[10] * coe)) end
		end
	end
end

-- 特定キャラ人数状況ヒット数状況属性付き特定スキルダメージ上限増減
-- params[1]:敵・味方
-- params[2]:自分/死者を含むか 0:含む 1:含まない +2:死者も含む
-- params[3]:キャラタイプ条件
-- params[4]:効果最小人数
-- params[5]:効果最大人数
-- params[6]:効果発生ヒット数
-- params[7]:効果最大ヒット数
-- params[8]:属性条件
-- params[9]:スキルタイプ条件
-- params[10]:ダメージ上限加算値
function process1082481(_target, params)
local coe,cnt
	Field:FrameUpdate(_target)
	cnt = 0
	for i,u in pairs(units:GetCondUnitList(params[1], params[2]&2==2 and TARGET_COND_BOTH or TARGET_COND_ALIVE, UNIT_COND_NONE + (params[2]&1==1 and UNIT_COND_NOT_ME or 0))) do
		if u:Type(params[3]) then cnt = cnt + 1 end
	end
	coe = calcCoe(cnt, params[4], params[5]) * calcCoe(Bullet:Target():Hits(), params[6], params[7])
	if coe > 0 then Bullet:EditDamageLimit(round(params[10] * coe), 0) end
end

