local buid
	Field:FrameUpdate(_target)
	buid = target:SetBuff(BuffIds.S_LotterySingleWeaponCritical, {-1, params[1], params[2], params[3], params[4]})
	if buid then
		target:SetBuff(BuffIds.S_InitializeLottery, {-1, buid})
		target:SetBuff(BuffIds.S_LotteryTargetUidBuffDmgLimitBreak, {-1, buid, params[5], params[6]})
		target:SetBuff(BuffIds.S_LotteryTargetUidBuffDmgPer, {-1, buid, params[7], 1})
	end
end

-- 特定キャラ生存人数状況特定スキルダメージ上限増減
-- params[1]:敵・味方
-- params[2]:自分を含むか
-- params[3]:キャラタイプ条件
-- params[4]:効果最小人数
-- params[5]:効果最大人数
-- params[6]:属性条件
-- params[7]:スキルタイプ条件
-- params[8]:ダメージ上限加算最大値
-- params[9]:ダメージ上限倍率最大補正
function process1082618(_target, params)
local coe,cnt
	Field:FrameUpdate(_target)
	cnt = 0
	for i,u in pairs(units:GetCondUnitList(params[1], TARGET_COND_ALIVE, UNIT_COND_NONE)) do
		if params[2] == 0 or u:ID() ~= this:ID() then
			if u:Type(params[3]) then cnt = cnt + 1 end
		end
	end
	coe = math.max(math.min((cnt - params[4]) / (params[5] - params[4]), 1), 0)
	if coe > 0 then Bullet:EditDamageLimit(round(params[8] * coe), round(params[9] * coe)) end
end

-- 特定味カテゴリ撃破時特定スキルダメージ上限累積増減
-- params[1]:味カテゴリ条件
-- params[2]:効果最小累積トドメ人数
-- params[3]:効果最大累積トドメ人数
-- params[4]:属性条件
-- params[5]:スキルタイプ条件
-- params[6]:ダメージ上限加算最大値
-- params[7]:ダメージ上限倍率最大補正
-- params[8]:オプション
function process1082619(_target, params)
Field:FrameUpdate(_target)
local pv = this:GetProcValue() or {}
local cnt = (pv[1] or 0) + 1
local beforeSbf, beforeRbf = pv[2], pv[3]
local Sbf, Rbf
local beforeCoe = math.max(math.min((cnt - 1 - params[2]) / (params[3] - params[2]), 1), 0)
local coe = math.max(math.min((cnt - params[2]) / (params[3] - params[2]), 1), 0)
	if beforeSbf ~= nil then this:ExpireBuff(beforeSbf) end
	if beforeRbf ~= nil then this:ExpireBuff(beforeRbf) end
	if coe > 0 then Sbf = this:SetBuff(bitToBoolean(params[8], 1) and BuffIds.WP_TargetSkillDamageLimit or BuffIds.P_TargetSkillDamageLimit, {-1, params[4], params[5], round(params[6] * coe), round(params[7] * coe)}) end
	if Sbf then
		if bitToBoolean(params[8], 2) then Rbf = this:SetBuff(BuffIds.S_DefeatReset, {-1}) end
		if coe > 0 and beforeCoe ~= coe then Process:ShowPassive() end
	end
	pv[1] = cnt
	pv[2] = Sbf
	pv[3] = Rbf
	this:SetProcValue(pv, bitToBoolean(params[8], 1))
end

