-- 自身生存中味方全体属性付き特定スキルダメージ上限増減
-- params[1]:自分を含むか 0:含む 1:含まない
-- params[2]:属性条件
-- params[3]:スキルタイプ条件
-- params[4]:ダメージ上限加算値
-- params[5]:ダメージ上限倍率補正
function process1082641(_target, params)
local t, cnt, ulist
	Field:FrameUpdate(_target)
	t = this:GetProcValue() or {}
	if next(t) == nil then
		ulist = units:GetCondUnitList(TARGET_SIDE_ALLY, TARGET_COND_BOTH, UNIT_COND_NONE)
	else
		ulist = Process:TrigUnits()
	end
	for i,u in pairs(ulist) do
		if u:RelativeSide(this)==TARGET_SIDE_ALLY and (params[1]==0 or u:ID()~=this:ID()) and not toBoolean(t[u:ID()]) then
			if u:SetBuff(BuffIds.S_TargetUidAliveElemSkillDmgLimitBreak, {-1, this:ID(), params[2], params[3], params[4], params[5]}) then t[u:ID()] = true end
		end
	end
	this:SetProcValue(t)
end

