-- 特定キャラカテゴリキャラ種類数状況属性付き特定スキルダメージ上限増減
-- params[1]:敵・味方
-- params[2]:自分を含むか
-- params[3]:キャラカテゴリ条件
-- params[4]:効果最小種類数
-- params[5]:効果最大種類数
-- params[6]:属性条件
-- params[7]:スキルタイプ条件
-- params[8]:ダメージ上限加算最大値
-- params[9]:ダメージ上限倍率最大補正
function process1082643(_target, params)
Field:FrameUpdate(_target)
local coe,cnt,ulist, list
	if params[3] == 0 then
		ulist = units:GetCondUnitList(params[1], TARGET_COND_BOTH, UNIT_COND_NONE + (params[2] == 1 and UNIT_COND_NOT_ME or 0))
	else
		ulist = units:GetCondUnitList(params[1], TARGET_COND_BOTH, UNIT_COND_CHARA_CATEGORY + (params[2] == 1 and UNIT_COND_NOT_ME or 0), params[3])
	end
	list = {}
	cnt = 0
	for i,u in pairs(ulist) do
		for j,k in pairs(u:Type()) do
			if (params[3] == 0 or unitTypeToCategory(k) == params[3]) and not toBoolean(list[k]) then
				list[k] = true
				cnt = cnt + 1
			end
		end
	end
	coe = math.max(math.min((cnt - params[4]) / (params[5] - params[4]), 1), 0)
	if coe > 0 then Bullet:EditDamageLimit(round(params[8] * coe), round(params[9] * coe)) end
end

-- 属性付き特定スキル累積ダメージ上限増減
-- params[1]:属性条件
-- params[2]:スキルタイプ条件
-- params[3]:効果最小発動数
-- params[4]:効果最大発動数
-- params[5]:ダメージ上限加算最大値
-- params[6]:ダメージ上限倍率最大補正
function process1082644(_target, params)
Field:FrameUpdate(_target)
local pv = this:GetProcValue() or 0
local coe, buid
	pv = pv + 1
	coe = math.max(math.min((pv - params[3]) / (params[4] - params[3]), 1), 0)
	if coe > 0 then
		buid = this:SetBuff(BuffIds.P_TargetSkillPUIDDamageLimit, {-1, TimeLine:SKL_PUID(), round(params[5] * coe), round(params[6] * coe)})
		if buid then this:SetBuff(BuffIds.S_SkillEndBuffControl, {-1, TimeLine:SKL_PUID(), buid}) end
	end
	this:SetProcValue(pv)
end

