-- params[5]:スキルタイプ条件
-- params[6]:ダメージ上限加算最大値
-- params[7]:ダメージ上限倍率最大補正
function process1082646(_target, params)
local coe,cnt
	Field:FrameUpdate(_target)
	cnt = 0
	for i,u in pairs(units:GetCondUnitList(TARGET_SIDE_ALLY, TARGET_COND_BOTH, UNIT_COND_NONE)) do
		if not u:IsMonster() then
			for j,pid in pairs(u:ArkPassiveList()) do
				if pid == params[1] then
					cnt = cnt + 1
					break
				end
			end
		end
	end
	coe = math.max(math.min((cnt - params[2]) / (params[3] - params[2]), 1), 0)
	if coe > 0 then Bullet:EditDamageLimit(round(params[6] * coe), round(params[7] * coe)) end
end

