-- params[7]:ダメージ上限加算最大値
-- params[8]:ダメージ上限倍率最大補正
-- params[9]:オプション
function process1082660(_target, params)
Field:FrameUpdate(_target)
local pv = this:GetProcValue() or {}
local cnt = (pv[1] or 0) + (Process:GetKeptParam(1, bitToBoolean(params[9], 1)) or 1)
local beforeSbf, beforeRbf = pv[2], pv[3]
local Sbf, Rbf
local beforeCoe = math.max(math.min((cnt - 1 - params[3]) / (params[4] - params[3]), 1), 0)
local coe = math.max(math.min((cnt - params[3]) / (params[4] - params[3]), 1), 0)
	if beforeSbf ~= nil then this:ExpireBuff(beforeSbf) end
	if beforeRbf ~= nil then this:ExpireBuff(beforeRbf) end
	if coe > 0 then Sbf = this:SetBuff(bitToBoolean(params[9], 1) and BuffIds.WP_TargetSkillDamageLimit or BuffIds.P_TargetSkillDamageLimit, {-1, params[5], params[6], round(params[7] * coe), round(params[8] * coe)}) end
	if Sbf then
		if bitToBoolean(params[9], 2) then Rbf = this:SetBuff(BuffIds.S_DefeatReset, {-1}) end
		if coe > 0 and beforeCoe ~= coe then Process:ShowPassive() end
	end
	pv[1] = cnt
	pv[2] = Sbf
	pv[3] = Rbf
	this:SetProcValue(pv, bitToBoolean(params[9], 1))
end

