-- params[7]:効果対象スキルタイプ条件
-- params[8]:ダメージ上限加算値
-- params[9]:ダメージ上限倍率補正
function process1082669(_target, params)
Field:FrameUpdate(_target)
if not this:IsRemote() then
local pv = this:GetProcValue() or {}
local cnt = (pv[1] or 0) + 1
local beforeSbf, beforeRbf = pv[2], pv[3]
local Sbf, Rbf
local coe = math.max(math.min((cnt - params[4]) / (params[5] - params[4]), 1), 0)
	if beforeSbf ~= nil then this:ExpireBuff(beforeSbf) end
	if beforeRbf ~= nil then this:ExpireBuff(beforeRbf) end
	if coe > 0 then Sbf = this:SetBuff(BuffIds.S_SkillCountCondNextSkillDmgLimitBreak, {-1, params[6], params[7], round(params[8] * coe), round(params[9] * coe)}) end
	if Sbf then
		if bitToBoolean(params[9], 1) then Rbf = this:SetBuff(BuffIds.S_DefeatReset, {-1}) end
	end
	pv[1] = cnt
	pv[2] = Sbf
	pv[3] = Rbf
	this:SetProcValue(pv)
end
end

