-- 錬金術
-- params[1]:消費MP値
-- params[2]:消費MP倍率
-- params[3]:消費MPコスト倍率
-- params[4]:ダメージ上限増減値
-- params[5]:ダメージ上限増減倍率
-- params[6]:与ダメージ倍率
function process1083200(_target, params)
local pv, flag
	Field:FrameUpdate(_target)
	pv = this:GetProcValue()
	if pv == nil then
		pv = {}
		for i,skl in pairs(this:GetSkill(SKILL_SKILL)) do
			pv[skl:Index()] = {math.floor(params[1] + (this:MaxMP() * params[2] * Per2Num) + (skl:Cost() / 1000 * params[3] * Per2Num))}
		end
	end
	flag = false
	for i,tbl in pairs(pv) do
		if this:MP() < tbl[1] then
			if tbl[2] ~= nil then
				this:ExpireBuff(tbl[2])
				pv[i][2] = nil
				flag = true
			end
		else
			if tbl[2] == nil then
				buid = this:SetBuff(BuffIds.S_Alchemy, {-1, i, tbl[1], params[4], params[5], params[6]})
				if buid then
					pv[i][2] = buid
					flag = true
				end
			end
			this:ActivateSkill(i, LIFETYPE_CONTINUOUS)
		end
	end
	if flag then this:SetProcValue(pv) end
end

-- 指定特技コスト無視
-- params[1]:特技INDEX
-- params[2]:消費MP値
-- params[3]:消費MP倍率
-- params[4]:消費MPコスト倍率
function process1083201(_target, params)
local pv, flag, skl
	Field:FrameUpdate(_target)
	pv = this:GetProcValue()
	if pv == nil then
		pv = {}
		if params[1] == 0 then
			for i,s in pairs(this:GetSkill(SKILL_SKILL)) do
				pv[s:Index()] = {math.floor(params[2] + (this:MaxMP() * params[3] * Per2Num) + (s:Cost() / 1000 * params[4] * Per2Num))}
			end
		else
			if params[1] > 0 then
				skl = this:GetSkillFromIndexUI(params[1])
			elseif params[1] == -1 then
				skl = this:GetSkill(SKILL_SKILL, math.random(1, this:SkillCount(SKILL_SKILL)))
			end
			if skl~= nil then
				pv[skl:Index()] = {math.floor(params[2] + (this:MaxMP() * params[3] * Per2Num) + (skl:Cost() / 1000 * params[4] * Per2Num))}
			end
		end
	end
	flag = false
	for i,tbl in pairs(pv) do
		if this:MP() < tbl[1] then
			if tbl[2] ~= nil then
				this:ExpireBuff(tbl[2])
				pv[i][2] = nil
				flag = true
			end
		else
			if tbl[2] == nil then
				buid = this:SetBuff(BuffIds.S_Alchemy, {-1, i, tbl[1]})
				if buid then
					pv[i][2] = buid
					flag = true
				end
			end
			this:ActivateSkill(i, LIFETYPE_CONTINUOUS)
		end
	end
	if flag then this:SetProcValue(pv) end
end

