-- MP条件超必殺技コスト無視
-- params[1]:クエスト毎制限回数
-- params[2]:発動条件方向
-- params[3]:残りMP閾値
-- params[4]:残りMP閾値(万分率)
-- params[5]:消費MP値
-- params[6]:消費MP倍率(現在MP)
-- params[7]:消費MPコスト倍率
-- params[8]:ダメージ上限増減値
-- params[9]:ダメージ上限増減倍率
-- params[10]:与ダメージ倍率
function process1083900(_target, params)
Field:FrameUpdate(_target)
local pv, flag, flag2, idx, val
local isFirst = Process:GetKeptParam(1)
	flag = false
	pv = this:GetProcValue()
	if pv == nil then pv = {cnt = 0, data = {}} Process:KeepParam(1, 1) elseif isFirst == nil then pv.data = {} Process:KeepParam(1, 1) elseif  pv.data == nil then pv.data = {} end
	for i,skl in pairs(this:GetSkill(SKILL_SPECIAL)) do
		val = math.floor(params[5] + (this:MP() * params[6] * Per2Num) + (skl:Cost() * params[7] * Per2Num))
		idx = skl:Index()
		if pv.data[idx] == nil then pv.data[idx] = {} end
		if pv.data[idx][1] ~= val then
			pv.data[idx][1] = val
			flag = true
		end
	end
	flag2 = false
	for i,tbl in pairs(pv.data) do
		if not procCompare(params[2], this:MP(), math.ceil(params[3] + (this:MaxMP() * params[4] / Pct100))) or this:MP() < tbl[1] then
			if tbl[2] ~= nil then
				this:ExpireBuff(tbl[2])
				pv.data[i][2] = nil
				flag2 = true
			end
		elseif (params[1] <= 0 or pv.cnt < params[1]) then
			if flag and tbl[2] ~= nil then this:ExpireBuff(tbl[2]) tbl[2] = nil end
			if tbl[2] == nil then
				buid = this:SetBuff(BuffIds.S_AlchemySpecial, {-1, params[1], i, tbl[1], params[8], params[9], params[10]})
				if buid then
					pv.data[i][2] = buid
					flag2 = true
				end
			end
			this:ActivateSpecial(i, LIFETYPE_CONTINUOUS)
		end
	end
	if flag or flag2 then this:SetProcValue(pv, true) end
end

