-- 味方死亡時ステータス増減復活
-- params[1]:制限回数
-- params[2]:復活時HP割合
-- params[3]:フェードイン開始フレーム
-- params[4]:フェードイン終了フレーム
-- params[5]:継続時間
-- params[6]:STR倍率
-- params[7]:DEF倍率
-- params[8]:INT倍率
-- params[9]:MND倍率
function process2020450(_target, params)
Field:FrameUpdate(_target)
local cnt = this:GetProcValue() or 0
local behav, bid
	if params[1] < 0 or cnt < params[1] then
		bid = {}
		bid[6], bid[7], bid[8], bid[9] = BuffIds.StrEdit, BuffIds.DefEdit, BuffIds.IntEdit, BuffIds.MndEdit
		for i,u in pairs(Process:TrigUnits()) do
			if params[1] < 0 or cnt < params[1] then
				if u:RelativeSide(this) == TARGET_SIDE_ALLY and not u:Alive() and u:ID() ~= this:ID() then
					if Process:SubProc(1, u, Pct100, {params[2], -1, params[3], params[4]}) then
						u:SetBuff(BuffIds.S_ResurrectCallBack, {-1})
						for i = 6,9 do
							if params[i] > 0 then
								behav = BuffParamBehavior[bid[i]]
								table.insert(behav, 1, PARAM_BEHAV_PROCESS_1)
								table.insert(behav, 1, PARAM_BEHAV_PROCESS_1)
								table.insert(behav, 1, PARAM_BEHAV_PROCESS_1)
								this:SetBuff(BuffIds.S_FatalityReservSetBuff, {-1, u:ID(), bid[i], params[5], 0, params[i]}, nil, nil, behav)
							end
						end
						cnt = cnt + 1
					end
				end
			else
				break
			end
		end
		this:SetProcValue(cnt)
		Process:ShowPassive()
	end
end

