-- 根性＆DEF・MNDバフorデバフ
-- params[1]:残りHP条件
-- params[2]:発生可能回数
-- params[3]:継続時間
-- params[4]:DEF加算値
-- params[5]:DEF倍率
-- params[6]:MND加算値
-- params[7]:MND倍率
-- params[8]:回復最低値
-- params[9]:回復倍率
-- params[10]:演出レベル
function process2020600(_target, params)
local flag = 0
	Field:FrameUpdate(_target)
	if this:SetEndure(TARGSTAT_WORK, params[1], params[2], LIFETYPE_TRANSIENT) then
		if params[4] > 0 or params[5] > 0 then
			if this:SetBuff(BuffIds.DefEdit, {params[3], params[4], params[5]}) then flag = 1 end
		elseif params[4] < 0 or params[5] < 0 then
			if this:SetBuff(DebuffIds.DefEdit, {params[3], params[4], params[5]}) then flag = 2 end
		end
		if params[6] > 0 or params[7] > 0 then
			if this:SetBuff(BuffIds.MndEdit, {params[3], params[6], params[7]}) and flag == 0 then flag = 1 end
		elseif params[6] < 0 or params[7] < 0 then
			if this:SetBuff(DebuffIds.MndEdit, {params[3], params[6], params[7]}) and flag == 0 then flag = 2 end
		end
		if params[8] > 0 or params[9] > 0 then this:HealPct(this, params[8], params[9]) end
		if flag ~= 0 then Process:PlayTimelineLv(params[10], flag == 2) end
		Process:ShowPassive()
	end
end

