-- params[5]:継続時間
-- params[6]:残りHP条件
-- params[7]:発生可能回数
-- params[8]:演出レベル
function process2020602(_target, params)
Field:FrameUpdate(_target)
local cost
local cnt = Process:GetKeptParam(3) or 0
	if params[2] <= 0 or cnt < params[2] then
		cost = math.ceil(params[3] + (this:MaxMP() * params[4] / Pct100))
		if cost == 0 or (this:MP() >= cost and this:DecMp(params[3], params[4])) then
			if this:SetBuff(BuffIds.NextPhysicalSkillEndure, {params[5], params[6], params[7]}) then Process:ShowPassive() Process:PlayTimelineLv(params[8]) end
			Process:KeepParam(3, 1, CALCULATE_ADD)
		end
	end
end

-- 味方ステータス増減根性
-- params[1]:発生可能回数
-- params[2]:回復最低値
-- params[3]:回復倍率
-- params[4]:継続時間
-- params[5]:STR倍率
-- params[6]:DEF倍率
-- params[7]:INT倍率
-- params[8]:MND倍率
-- params[9]:演出レベル
function process2020650(_target, params)
Field:FrameUpdate(_target)
local buid, ulist
-- t = 1:count 2:unitList 3:buidList 4:isEnd
local t = this:GetProcValue()
	if t == nil then
		t = {0, {}, {}, false}
		ulist = units:GetCondUnitList(TARGET_SIDE_ALLY, TARGET_COND_ALIVE, UNIT_COND_NONE)
	else
		ulist = Process:TrigUnits()
	end
	for i,u in pairs(ulist) do
		if u:RelativeSide(this) == TARGET_SIDE_ALLY and u:ID() ~= this:ID() and not toBoolean(t[2][u:ID()]) then
			buid = u:SetBuff(BuffIds.S_AllyStatusEditEndureControl, {-1, params[1], params[2], params[3], params[4], params[5], params[6], params[7], params[8], params[9]})
			if buid then
				table.insert(t[3], buid)
				t[2][u:ID()] = true
			end
		end
	end
	this:SetProcValue(t)
end

