-- オートMPリジェネ
-- params[1]:MP回復値
-- params[2]:MP回復倍率
-- params[3]:演出番号
function process2021202(_target, params)
Field:FrameUpdate(_target)
local myInfo = this:GetProcValue()
	if myInfo == nil and this:Alive() and not this:IsExcluded() then
		myInfo = {}
		if not target:IsBuffCategory(BUFF_CATEGORY_MP_REGENE_1) then if target:SetBuff(BuffIds.MpRegene, {-1, params[1], params[2]}) and params[3] > 0 then Process:PlayTimeline(params[3]) end end
		myInfo[1] = target:SetBuff(BuffIds.AutoSkillControl, {-1, BUFF_CATEGORY_MP_REGENE_1, BuffIds.MpRegene, params[1], params[2]})
		myInfo[2] = target:SetBuff(BuffIds.AutoSkillControl2, {-1, target:ID(), BUFF_CATEGORY_MP_REGENE_1, BuffIds.MpRegene, params[1], params[2]})
		Process:ShowPassive()
		this:SetProcValue(myInfo)
	end
end

