function process2030003(_target, params)
Field:FrameUpdate(_target)
local prevBuff = Buff:GetKeptParam(1)
local buffUID, isDebuff
	if params[3] > 0 or params[4] > 0 then
		isDebuff = false
		buffUID = this:SetBuff(BuffIds.StrEdit, {params[2], params[3], params[4]})
	elseif params[3] < 0 or params[4] < 0 then
		isDebuff = true
		buffUID = this:SetBuff(DebuffIds.StrEdit, {params[2], params[3], params[4]})
	end
	if buffUID then
		if prevBuff then this:ExpireBuff(prevBuff) end
		Buff:KeepParam(1, buffUID)
		Process:ShowPassive()
		Process:PlayTimelineLv(params[5], isDebuff)
	end
end

