-- ラストソング(90秒経過後に一度だけ味方全体に全ステバフ)
-- params[1]:継続時間
-- params[2]:全ステ加算値
-- params[3]:全ステ倍率
-- params[4]:演出レベル
function process2030007(_target, params)
Field:FrameUpdate(_target)
local res, sp = false, false
local cnt = Process:GetKeptParam(2) or 0
	if cnt<=0 and Field:Time() >= 90 * OneSec then
		if params[2] > 0 or params[3] > 0 then
			for i,u in ipairs(units:GetCondUnitList(TARGET_SIDE_ALLY, TARGET_COND_ALIVE, UNIT_COND_NONE)) do
				res = false
				res = u:SetBuff(BuffIds.E_StrEdit, {params[1], params[2], params[3]}) or res
				res = u:SetBuff(BuffIds.E_DefEdit, {params[1], params[2], params[3]}) or res
				res = u:SetBuff(BuffIds.E_IntEdit, {params[1], params[2], params[3]}) or res
				res = u:SetBuff(BuffIds.E_MndEdit, {params[1], params[2], params[3]}) or res
				if res then Process:PlayTimelineLv(params[4], false, u, u) sp = true end
			end
		elseif params[2] < 0 or params[3] < 0 then
			for i,u in ipairs(units:GetCondUnitList(TARGET_SIDE_ALLY, TARGET_COND_ALIVE, UNIT_COND_NONE)) do
				res = false
				res = u:SetBuff(DebuffIds.E_StrEdit, {params[1], params[2], params[3]}) or res
				res = u:SetBuff(DebuffIds.E_DefEdit, {params[1], params[2], params[3]}) or res
				res = u:SetBuff(DebuffIds.E_IntEdit, {params[1], params[2], params[3]}) or res
				res = u:SetBuff(DebuffIds.E_MndEdit, {params[1], params[2], params[3]}) or res
				if res then Process:PlayTimelineLv(params[4], true, u, u) sp = true end
			end
		end
		if sp then Process:ShowPassive() end
		Process:KeepParam(2, 1)
	end
end

