-- 指定攻撃特技発動時MP消費未付与STR・DEF・INT・MND増減
-- params[1]:特技INDEX
-- params[2]:消費MP値
-- params[3]:消費MP倍率
-- params[4]:継続時間
-- params[5]:STR倍率
-- params[6]:DEF倍率
-- params[7]:INT倍率
-- params[8]:MND倍率
function process2030024(_target, params)
Field:FrameUpdate(_target)
local tbl, cateList = {}, {}
local proc = math.random(1, 4)
local cost = math.ceil(params[2] + (this:MaxMP() * params[3] / Pct100))
	if this:MP() >= cost then
		if params[5] > 0 then cateList[1] = BUFF_CATEGORY_STR_UP_1
		elseif params[5] < 0 then cateList[1] = BUFF_CATEGORY_STR_DOWN_1 end
		if params[6] > 0 then cateList[2] = BUFF_CATEGORY_DEF_UP_1
		elseif params[6] < 0 then cateList[2] = BUFF_CATEGORY_DEF_DOWN_1 end
		if params[7] > 0 then cateList[3] = BUFF_CATEGORY_INT_UP_1
		elseif params[7] < 0 then cateList[3] = BUFF_CATEGORY_INT_DOWN_1 end
		if params[8] > 0 then cateList[4] = BUFF_CATEGORY_MND_UP_1
		elseif params[8] < 0 then cateList[4] = BUFF_CATEGORY_MND_DOWN_1 end
		for i,cate in pairs(cateList) do
			if #(TimeLine:Target():GetBuffCategoryBuffs(cate)) == 0 then
				table.insert(tbl, i)
			end
		end
		if #tbl > 0 then
			if cost == 0 or this:DecMp(params[2], params[3]) then
				proc = tbl[math.random(1, #tbl)]
				Process:SubProc(proc, TimeLine:Target(), Pct100, {params[4], 0, params[5 + proc - 1]})
				Process:ShowPassive()
			end
		end
	end
end

