-- 開始時純粋ステ比較人数状況STR増減
-- params[1]:条件種別
-- params[2]:自分ステータス条件
-- params[3]:相手ステータス条件
-- params[4]:敵味方
-- params[5]:効果最小人数
-- params[6]:効果最大人数
-- params[7]:継続時間
-- params[8]:STR加算最大値
-- params[9]:STR倍率最大値
-- params[10]:演出レベル
function process2030027(_target, params)
local cnt = 0
local coe
	Field:FrameUpdate(_target)
	for i,u in pairs(units:GetCondUnitList(params[4], TARGET_COND_ALIVE, UNIT_COND_NONE)) do
		if u:ID() ~= this:ID() and procCompare(params[1], this:PureStatus(params[2]), u:PureStatus(params[3])) then
			cnt = cnt + 1
		end
	end
	coe = math.max(math.min((cnt - params[5]) / (params[6] - params[5]), 1), 0)
	if coe > 0 then
		if params[8] > 0 or params[9] > 0 then
			if this:SetBuff(BuffIds.StrEdit, {params[7], round(params[8] * coe), round(params[9] * coe)}) then Process:ShowPassive() Process:PlayTimelineLv(params[10]) end
		elseif params[8] < 0 or params[9] < 0 then
			if this:SetBuff(DebuffIds.StrEdit, {params[7], round(params[8] * coe), round(params[9] * coe)}) then Process:ShowPassive() Process:PlayTimelineLv(params[10], true) end
		end
	end
end

