-- params[7]:MND倍率
function process2030029(_target, params)
Field:FrameUpdate(_target)
local cnt = Process:GetKeptParam(1) or 0
local t = Bullet:Target()
local flag = 0
	if params[1] <= 0 or cnt < params[1] then
		if params[4] > 0 then
			if t:SetBuff(BuffIds.StrEdit, {params[3], 0, params[4]}) then flag = 1 end
		elseif params[4] < 0 then
			if t:SetBuff(DebuffIds.StrEdit, {params[3], 0, params[4]}) then flag = 2 end
		end
		if params[5] > 0 then
			if t:SetBuff(BuffIds.DefEdit, {params[3], 0, params[5]}) then flag = 1 end
		elseif params[5] < 0 then
			if t:SetBuff(DebuffIds.DefEdit, {params[3], 0, params[5]}) then flag = 2 end
		end
		if params[6] > 0 then
			if t:SetBuff(BuffIds.IntEdit, {params[3], 0, params[6]}) then flag = 1 end
		elseif params[6] < 0 then
			if t:SetBuff(DebuffIds.IntEdit, {params[3], 0, params[6]}) then flag = 2 end
		end
		if params[7] > 0 then
			if t:SetBuff(BuffIds.MndEdit, {params[3], 0, params[7]}) then flag = 1 end
		elseif params[7] < 0 then
			if t:SetBuff(DebuffIds.MndEdit, {params[3], 0, params[7]}) then flag = 2 end
		end
		if flag ~= 0 then Process:KeepParam(1, 1, CALCULATE_ADD) Process:PlayTimelineLv(1, flag == 2, this, t) Process:ShowPassive() end
	end
end

