-- params[9]:STR倍率
-- params[10]:演出レベル
function process2030035(_target, params)
Field:FrameUpdate(_target)
local cost = math.ceil(params[5] + (this:MaxMP() * params[6] / Pct100))
	if cost == 0 or (this:MP() >= cost and this:DecMp(params[5], params[6])) then
		if params[8] > 0 or params[9] > 0 then
			if target:SetBuff(BuffIds.StrEdit, {params[7], params[8], params[9]}) then Process:ShowPassive() Process:PlayTimelineLv(params[10]) end
		elseif params[8] < 0 or params[9] < 0 then
			if target:SetBuff(DebuffIds.StrEdit, {params[7], params[8], params[9]}) then Process:ShowPassive() Process:PlayTimelineLv(params[10], true) end
