-- 千変万化
-- params[1]:指定間隔
-- params[2]:継続時間
-- params[3]:STR倍率
-- params[5]:INT倍率
-- params[4]:DEF倍率
-- params[6]:MND倍率
-- params[7]:MND加算値(リジェネ)
-- params[8]:MND倍率(リジェネ)
-- params[9]:回復最低値
-- params[10]:回復倍率
function process2030053(_target, params)
Field:FrameUpdate(_target)
local flag = false
local cnt = Process:GetKeptParam(1) or params[1]
local pv = this:GetProcValue() or 0
	if params[1] > 0 and params[1] <= cnt then
		for i,u in pairs(units:GetCondUnitList(TARGET_SIDE_ALLY, TARGET_COND_ALIVE, UNIT_COND_NONE)) do
			if u:PerHP() < 3000 then flag = true break end
		end
		if (pv ~= 1 and flag) or (pv ~= 2 and not flag) then
			for i,u in pairs(units:GetCondUnitList(TARGET_SIDE_ALLY, TARGET_COND_ALIVE, UNIT_COND_NONE)) do
				if flag then
					Process:SubProc(2, u, Pct100, {params[2], 0, params[5], 0, params[6], params[7], params[8], params[9], params[10]})
				else
					Process:SubProc(1, u, Pct100, {params[2], 0, params[3], 0, params[4]})
				end
			end
			Process:ShowPassive()
		end
		if flag then this:SetProcValue(1) else this:SetProcValue(2) end
		Process:KeepParam(1, 1)
	else
		Process:KeepParam(1, 1, CALCULATE_ADD)
	end
end

