			boss = u:IsBoss() and ENEMY_TYPE_BOSS or ENEMY_TYPE_NORMAL
			if params[2] == 0 or boss == params[2] then
				Process:SubProc(1, u, Pct100, {params[3], params[4], params[5], params[6]})
				res = true
			end
		end
		if res then Process:ShowPassive() end
	end
end

