-- 対特定バフ特定スキル攻撃基本ステータス増減付与
-- params[1]:制限回数
-- params[2]:バフカテゴリ条件
-- params[3]:属性条件
-- params[4]:スキルタイプ条件
-- params[5]:モード
-- params[6]:継続時間
-- params[7]:ステータス加算値
-- params[8]:ステータス倍率
-- params[9]:演出レベル
function process2030057(_target, params)
Field:FrameUpdate(_target)
local t
local cnt = Process:GetKeptParam(1) or 0
	if params[1] <= 0 or cnt < params[1] then
		if params[5] > 0 and params[5] <= 4 then
			t = {params[5]}
		elseif params[5] == 0 then
			t = {1, 2, 3, 4}
		elseif params[5] == -1 then
			t = {5}
		elseif params[5] == -2 then
			t = {math.random(1,4)}
		elseif params[5] == -3 then
			t = {}
			if not target:IsBuffCategory(BUFF_CATEGORY_STR_DOWN_1) then table.insert(t, 1) end
			if not target:IsBuffCategory(BUFF_CATEGORY_DEF_DOWN_1) then table.insert(t, 2) end
			if not target:IsBuffCategory(BUFF_CATEGORY_INT_DOWN_1) then table.insert(t, 3) end
			if not target:IsBuffCategory(BUFF_CATEGORY_MND_DOWN_1) then table.insert(t, 4) end
			if #t > 0 then t = {t[math.random(1, #t)]} end
		end
		if #t > 0 then
			for i, j in pairs(t) do
				Process:SubProc(j, target, Pct100, {params[6], params[7], params[8], params[9]})
			end
			Process:KeepParam(1, 1, CALCULATE_ADD)
			Process:ShowPassive()
		end
	end
end

