		if params[5] ~= 0 or params[6] ~= 0 then res = Process:SubProc(2, u, Pct100, {params[2], params[5], params[6], 1}) or res end
		if params[7] ~= 0 or params[8] ~= 0 then res = Process:SubProc(3, u, Pct100, {params[2], params[7], params[8], 1}) or res end
		if params[9] ~= 0 or params[10] ~= 0 then res = Process:SubProc(4, u, Pct100, {params[2], params[9], params[10], 1}) or res end
		if res then Process:ShowPassive() end
	end
end

