-- DEFデバフ付与時DEF増減
-- params[1]:継続時間
-- params[2]:DEF加算値
-- params[3]:DEF倍率
-- params[4]:演出レベル
function process2030106(_target, params)
local prm2, prm3 = 0, 0
	Field:FrameUpdate(_target)
	if params[2] == 0 and params[3] == 0 then
		for i,j in pairs(TrigProc:Behav()) do
			if j == PARAM_BEHAV_ADD then
				prm2 = -(TrigProc:Param(i))
			elseif j == PARAM_BEHAV_PER then
				prm3 = -(TrigProc:Param(i))
			end
		end
	else
		prm2, prm3 = params[2], params[3]
	end
	if prm2 > 0 or prm3 > 0 then
		if this:SetBuff(BuffIds.DefEdit, {params[1], prm2, prm3}) then Process:ShowPassive() Process:PlayTimelineLv(params[4]) end
	elseif prm2 < 0 or prm3 < 0 then
		if this:SetBuff(DebuffIds.DefEdit, {params[1], prm2, prm3}) then Process:ShowPassive() Process:PlayTimelineLv(params[4], true) end
	end
end

