-- 全は世界！
-- params[1]:効果最小時間(秒)
-- params[2]:効果最大時間(秒)
-- params[3]:DEF加算最大値
-- params[4]:DEF倍率最大値
function process2030153(_target, params)
Field:FrameUpdate(_target)
local coe, icoe, res
local interval = 10
local pv = this:GetProcValue() or {}
local cnt = (pv[this:ID()] or 0) + 1
local buid = Process:GetKeptParam(2)
local beforeCoe = Process:GetKeptParam(3) or 0
	if buid == nil or not Field:IsBuffExists(buid) then
		buid = this:SetBuff(BuffIds.S_FaDefReset, {-1})
		Process:KeepParam(2, buid)
	end
	pv[this:ID()] = cnt
	this:SetProcValue(pv)
	coe = math.max(math.min((cnt * interval - params[1]) / (params[2] - params[1]), 1), 0)
	icoe = math.floor(coe * Pct100)
	Process:KeepParam(3, icoe)
	if coe > 0 then
		res = false
		for i,u in pairs(units:GetCondUnitList(TARGET_SIDE_ALLY, TARGET_COND_BOTH, UNIT_COND_NONE)) do
			if u:ID() ~= this:ID() then
				Process:SubProc(1, u, Pct100, {-1, round(params[3] * coe), round(params[4] * coe), beforeCoe < icoe and 1 or 0})
				res = true
			end
		end
		if res and beforeCoe < icoe then Process:ShowPassive() end
	end
end

-- 味方復活時対象DEF増減
-- params[1]:制限回数
-- params[2]:継続時間
-- params[3]:DEF加算値
-- params[4]:DEF倍率
-- params[5]:演出レベル
function process2030154(_target, params)
local prm, res, pv -- pv = {1:cnt 2:{uid = cnt} 3:qcnt 4:{uid = qcnt}}
	Field:FrameUpdate(_target)
	pv = this:GetProcValue()
	if Process:GetKeptParam(3) == nil then
		if pv == nil then
			pv = {}
		else
			pv[1] = 0
			pv[2] = {}
		end
		Process:KeepParam(3, 1)
		this:SetProcValue(pv, true)
	end
	prm = arrayInit(bitSplitArray(params[1], 8), 4, 0)
	for i,u in pairs(Process:TrigUnits()) do
		if u:ID() ~= this:ID() and u:RelativeSide(this, TARGET_SIDE_ALLY) then
			if (prm[1] <= 0 or (pv[1] or 0) < prm[1]) and (prm[2] <= 0 or (tableGetValue(pv, {2, u:ID()}) or 0) < prm[2]) and (prm[3] <= 0 or (pv[3] or 0) < prm[3]) and (prm[4] <= 0 or (tableGetValue(pv, {4, u:ID()}) or 0) < prm[4]) then
				res = Process:SubProc(1, u, Pct100, {params[2], params[3], params[4], params[5]}) or res
				if prm[1] > 0 then this:CalcProcValue({1}, 1, CALCULATE_ADD, true) pv[1] = (pv[1] or 0) + 1 end
				if prm[2] > 0 then this:CalcProcValue({2, u:ID()}, 1, CALCULATE_ADD, true) end
				if prm[3] > 0 then this:CalcProcValue({3}, 1, CALCULATE_ADD, true) pv[3] = (pv[3] or 0) + 1 end
				if prm[4] > 0 then this:CalcProcValue({4, u:ID()}, 1, CALCULATE_ADD, true) end
			end
		end
	end
	if res then Process:ShowPassive() end
end

