-- 味方蘇生時INT増減追加
-- params[1]:制限回数
-- params[2]:継続時間
-- params[3]:INT加算値
-- params[4]:INT倍率
-- params[5]:演出レベル
function process2030213(_target, params)
Field:FrameUpdate(_target)
local behav
local cnt = Process:GetKeptParam(1) or 0
	if params[1] <= 0 or cnt < params[1] then
		target:SetBuff(BuffIds.S_ResurrectCallBack, {-1})
		if params[3] > 0 or params[4] > 0 then
			behav = BuffParamBehavior[BuffIds.IntEdit]
			table.insert(behav, 1, PARAM_BEHAV_PROCESS_1)
			table.insert(behav, 1, PARAM_BEHAV_PROCESS_1)
			table.insert(behav, 1, PARAM_BEHAV_PROCESS_1)
			this:SetBuff(BuffIds.S_FatalityReservSetBuff, {-1, target:ID(), BuffIds.IntEdit, params[2], params[3], params[4]}, nil, nil, behav)
			Process:KeepParam(1, 1, CALCULATE_ADD)
			Process:PlayTimelineLv(params[5])
			Process:ShowPassive()
		elseif params[3] < 0 or params[4] < 0 then
			behav = BuffParamBehavior[DebuffIds.IntEdit]
			table.insert(behav, 1, PARAM_BEHAV_PROCESS_1)
			table.insert(behav, 1, PARAM_BEHAV_PROCESS_1)
			table.insert(behav, 1, PARAM_BEHAV_PROCESS_1)
			this:SetBuff(BuffIds.S_FatalityReservSetBuff, {-1, target:ID(), DebuffIds.IntEdit, params[2], params[3], params[4]}, nil, nil, behav)
			Process:KeepParam(1, 1, CALCULATE_ADD)
			Process:PlayTimelineLv(params[5], true)
			Process:ShowPassive()
		end
	end
end

-- 復活時MP消費INT増減
-- params[1]:発動回数
-- params[2]:消費MP値
-- params[3]:消費MP倍率
-- params[4]:継続時間
-- params[5]:INT加算値
-- params[6]:INT倍率
-- params[7]:演出レベル
function process2030214(_target, params)
Field:FrameUpdate(_target)
local cnt = Process:GetKeptParam(3) or 0
local cost = math.max(math.ceil(params[2] + (this:MaxMP() * params[3] / Pct100)), 1)
	if params[1] <= 0 or cnt < params[1] then
		if this:MP() >= cost and this:DecMp(params[2], params[3]) then
			if params[5] > 0 or params[6] > 0 then
				if this:SetBuff(BuffIds.IntEdit, {params[4], params[5], params[6]}) then Process:PlayTimelineLv(params[7]) Process:ShowPassive() Process:KeepParam(3, 1, CALCULATE_ADD) end
			elseif params[5] < 0 or params[6] < 0 then
				if this:SetBuff(DebuffIds.IntEdit, {params[4], params[5], params[6]}) then Process:PlayTimelineLv(params[7], true) Process:ShowPassive() Process:KeepParam(3, 1, CALCULATE_ADD) end
			end
		end
	end
end

