-- params[3]:MND倍率
-- params[4]:演出レベル
function process2030303(_target, params)
Field:FrameUpdate(_target)
local myInfo = this:GetProcValue()
	if myInfo == nil and this:Alive() and not this:IsExcluded() then
		if params[1] == 0 or Field:BgTerrain() == params[1] then
			if params[2] > 0 or params[3] > 0 then
				if target:SetBuff(BuffIds.E_MndEdit, {-1, params[2], params[3]}) then Process:ShowPassive() if params[4] > 0 then Process:PlayTimelineLv(params[4]) end end
			elseif params[2] < 0 or params[3] < 0 then
				if target:SetBuff(DebuffIds.E_MndEdit, {-1, params[2], params[3]}) then Process:ShowPassive() if params[4] > 0 then Process:PlayTimelineLv(params[4], true) end end
			end
		end
		myInfo = true
		this:SetProcValue(myInfo)
	end
end

