function process2030351(_target, params)
local boss, res
	Field:FrameUpdate(_target)
	if this:Alive() then
		res = false
		for i,u in ipairs(units:GetCondUnitList(params[1], TARGET_COND_ALIVE, UNIT_COND_NONE)) do
			boss = u:IsBoss() and ENEMY_TYPE_BOSS or ENEMY_TYPE_NORMAL
			if params[2] == 0 or boss == params[2] then
				Process:SubProc(1, u, Pct100, {params[3], params[4], params[5], params[6]})
				res = true
			end
		end
		if res then Process:ShowPassive() end
	end
end

