-- 味方復活時対象MND増減
-- params[1]:制限回数
-- params[2]:継続時間
-- params[3]:MND加算値
-- params[4]:MND倍率
-- params[5]:演出レベル
function process2030353(_target, params)
local prm, res, pv -- pv = {1:cnt 2:{uid = cnt} 3:qcnt 4:{uid = qcnt}}
	Field:FrameUpdate(_target)
	pv = this:GetProcValue()
	if Process:GetKeptParam(3) == nil then
		if pv == nil then
			pv = {}
		else
			pv[1] = 0
			pv[2] = {}
		end
		Process:KeepParam(3, 1)
		this:SetProcValue(pv, true)
	end
	prm = arrayInit(bitSplitArray(params[1], 8), 4, 0)
	for i,u in pairs(Process:TrigUnits()) do
		if u:ID() ~= this:ID() and u:RelativeSide(this, TARGET_SIDE_ALLY) then
			if (prm[1] <= 0 or (pv[1] or 0) < prm[1]) and (prm[2] <= 0 or (tableGetValue(pv, {2, u:ID()}) or 0) < prm[2]) and (prm[3] <= 0 or (pv[3] or 0) < prm[3]) and (prm[4] <= 0 or (tableGetValue(pv, {4, u:ID()}) or 0) < prm[4]) then
				res = Process:SubProc(1, u, Pct100, {params[2], params[3], params[4], params[5]}) or res
				if prm[1] > 0 then this:CalcProcValue({1}, 1, CALCULATE_ADD, true) pv[1] = (pv[1] or 0) + 1 end
				if prm[2] > 0 then this:CalcProcValue({2, u:ID()}, 1, CALCULATE_ADD, true) end
				if prm[3] > 0 then this:CalcProcValue({3}, 1, CALCULATE_ADD, true) pv[3] = (pv[3] or 0) + 1 end
				if prm[4] > 0 then this:CalcProcValue({4, u:ID()}, 1, CALCULATE_ADD, true) end
			end
		end
	end
	if res then Process:ShowPassive() end
end

