-- 味方HP条件鬼族の角
-- params[1]:条件閾値方向
-- params[2]:条件HP閾値
-- params[3]:発動回数
-- params[4]:発生確率
-- params[5]:継続時間
-- params[6]:HP加算値
-- params[7]:HP倍率
-- params[8]:HP回復値
-- params[9]:SCT増減倍率(1ストック)
function process2030503(_target, params)
local t, cnt, tu, ulist
	Field:FrameUpdate(_target)
	t = this:GetProcValue() or {}
	cnt = t[1] or 0
	tu = t[2] or {}
	if params[3] <= 0 or cnt < params[3] then
		if next(tu) == nil then
			ulist = units:GetCondUnitList(TARGET_SIDE_ALLY, TARGET_COND_ALIVE, UNIT_COND_NONE)
		else
			ulist = Process:TrigUnits()
		end
		for i,u in pairs(ulist) do
			if u:RelativeSide(this)==TARGET_SIDE_ALLY and u:ID()~=this:ID() and u:Alive() and not toBoolean(tu[u:ID()]) then
				if u:SetBuff(BuffIds.S_DemonizationAlly, {-1, params[1], params[2], params[3], params[4], params[5], params[6], params[7], params[8], params[9]}) then tu[u:ID()] = true end
			end
		end
		t[2] = tu
		this:SetProcValue(t)
	end
end

