-- params[9]:HP加算値
-- params[10]:演出レベル
function process2030508(_target, params)
Field:FrameUpdate(_target)
local coe
local cnt = Process:GetKeptParam(3) or 0
	if params[1] <= 0 or cnt < params[1] then
		coe = calcCoe(TimeLine:SKL_GetValue(params[5]) or 0, params[6], params[7])
		if coe > 0 then
			if params[9] > 0 then
				if this:SetBuff(BuffIds.MaxHpEdit, {params[8], round(params[9] * coe), 0}) then Process:ShowPassive() Process:KeepParam(3, 1, CALCULATE_ADD) Process:PlayTimelineLv(params[10]) end
			elseif params[9] < 0 then
				if this:SetBuff(DebuffIds.MaxHpEdit, {params[8], round(params[9] * coe), 0}) then Process:ShowPassive() Process:KeepParam(3, 1, CALCULATE_ADD) Process:PlayTimelineLv(params[10], true) end
			end
		end
	end
end

