		Process:SubProc(1, u, Pct100, {params[2], params[3], params[4], params[5]})
	end
	Process:ShowPassive()
end

-- 特定スキル発動時スキル発動毎情報状況全体最大HP増減
-- params[1]:制限回数
-- params[2]:スキルタイプ条件
-- params[3]:敵・味方
-- params[4]:自分を含むか 0:含む 1:含まない
-- params[5]:スキル発動毎情報INDEX
-- params[6]:効果最小スキル発動毎情報値
-- params[7]:効果最大スキル発動毎情報値
-- params[8]:継続時間
-- params[9]:HP加算値
-- params[10]:演出レベル
function process2030553(_target, params)
Field:FrameUpdate(_target)
local coe
local cnt = Process:GetKeptParam(3) or 0
	if params[1] <= 0 or cnt < params[1] then
		coe = calcCoe(TimeLine:SKL_GetValue(params[5]) or 0, params[6], params[7])
		for i,u in pairs(units:GetCondUnitList(params[3], TARGET_COND_ALIVE, UNIT_COND_NONE + (params[4] == 1 and UNIT_COND_NOT_ME or 0))) do
			Process:SubProc(1, u, Pct100, {params[8], round(params[9] * coe), 0, params[10]})
		end
		Process:ShowPassive()
		Process:KeepParam(3, 1, CALCULATE_ADD)
	end
end

-- 属性付き特定スキル発動時状態異常耐性を付与
