function process2030600(_target, params)
	Field:FrameUpdate(_target)
	if params[4]<=6 then
		if params[5] > 0 then
			if target:SetBuff(BuffIds.PoisonResist + params[4] - 1, {params[3], params[4], params[5]}) then Process:ShowPassive() Process:PlayTimelineLv(params[6]) end
		elseif params[5] < 0 then
			if target:SetBuff(DebuffIds.PoisonResist + params[4] - 1, {params[3], params[4], params[5]}) then Process:ShowPassive() Process:PlayTimelineLv(params[6], true) end
		end
	end
end

-- 特定状態異常発動時、状態異常耐性を付与
-- params[1]:状態異常条件
-- params[2]:状態異常回数条件最小
