function process2030601(_target, params)
Field:FrameUpdate(_target)
local cnt = (Process:GetKeptParam(3) or 0) + 1
	if params[5]<=6 and params[2]<=cnt and cnt<=params[3] then
		if params[6] > 0 then
			if target:SetBuff(BuffIds.PoisonResist + params[5] - 1, {params[4], params[5], params[6]}) then Process:ShowPassive() Process:PlayTimelineLv(params[7]) end
		elseif params[6] < 0 then
			if target:SetBuff(DebuffIds.PoisonResist + params[5] - 1, {params[4], params[5], params[6]}) then Process:ShowPassive() Process:PlayTimelineLv(params[7], true) end
		end
		Process:KeepParam(3, 1, CALCULATE_ADD)
	end
end

-- 特定状態異常被治療時、状態異常耐性を付与
-- params[1]:継続時間
-- params[2]:状態異常ID
-- params[3]:増減段階
-- params[4]:演出レベル
function process2030602(_target, params)
local flag
local baseBuff, isDebuff
local trigParam = {}

	Field:FrameUpdate(_target)
	
	if params[3] > 0 then
		baseBuff = BuffIds.PoisonResist - 1
		isDebuff = false
	elseif params[3] < 0 then
		baseBuff = DebuffIds.PoisonResist - 1
		isDebuff = true
	else
		return false
	end
	
	flag = false
	for i, j in ipairs(TrigProc:Behav()) do
		if j == PARAM_BEHAV_COND_KIND_1 then
			if TrigProc:Param(i) == 0 then
				-- if not flag then
				-- 	for k = AILMENT_POISON, AILMENT_SILENCE do
				-- 		trigParam[k] = true
				-- 	end
				-- end
			else
				trigParam[TrigProc:Param(i)] = true
			end
			flag = true
		end
	end
	
	flag = false
	if params[2] == 0 then
		for i = AILMENT_POISON, AILMENT_SILENCE do
			if trigParam[i] and this:IsAilment(i) then
				if this:SetBuff(baseBuff + i, {params[1], i, params[3]}) then flag = true end
			end
		end
	else
		if trigParam[params[2]] and this:IsAilment(params[2]) then
			if this:SetBuff(baseBuff + params[2], {params[1], params[2], params[3]}) then flag = true end
		end
	end
	if flag then Process:ShowPassive() Process:PlayTimelineLv(params[4], isDebuff) end
end

