-- 飢餓暴走
-- params[1]:発動時間
-- params[2]:継続時間
-- params[3]:スキルタイプ条件
-- params[4]:ダメージ倍率
-- params[5]:ダメージ上限加算値
-- params[6]:ダメージ上限倍率補正
-- params[7]:移動速度加算値
-- params[8]:移動速度倍率
-- params[9]:HP減少間隔
-- params[10]:HP減少倍率
function process2031009(_target, params)
Field:FrameUpdate(_target)
local cnt = this:GetProcValue() or 0
local sbf = Process:GetKeptParam(1)
local bff = Process:GetKeptParam(2)
	if sbf == nil or not Field:IsBuffExists(sbf) then
		sbf = this:SetBuff(BuffIds.S_HungryAngryControl, {-1})
		if sbf then Process:KeepParam(1, sbf) end
	end
	if bff == nil or not Field:IsBuffExists(bff) then
		if params[1] > 0 and params[1] <= cnt then
			bff = this:SetBuff(BuffIds.HungryAngry, {params[2], params[3], params[4], params[5], params[6], params[7], params[8], params[9], params[10]})
			if bff then
				Process:KeepParam(2, bff)
				Process:ShowPassive()
			end
			this:SetProcValue(1)
		else
			this:SetProcValue(cnt + 1)
		end
	end
end

