-- 被弾蓄積ソウル変換
-- params[1]:スキルID上限
-- params[2]:最大蓄積数
-- params[3]:ダメージ倍率
-- params[4]:VITダメージ加算値
-- params[5]:VITダメージ倍率
function process2031402(_target, params)
Field:FrameUpdate(_target)
local coe
local cnt = this:GetProcValue() or 0
	if not this:IsBuff(BuffIds.MeredyCharge) then cnt = 0 end
	if cnt < params[2] then
		cnt = cnt + 1
		this:SetProcValue(cnt)
		coe = math.max(math.min(cnt / params[2], 1), 0)
		if coe > 0 then
			this:SetBuff(BuffIds.MeredyCharge, {-1, params[1], round(params[3] * coe), round(params[4] * coe), round(params[5] * coe)})
			Process:ShowPassive()
		end
	end
end

