-- 黄金の威信
-- params[1]:発動条件方向
-- params[2]:残りHP条件
-- params[3]:狙われやすさ加算値
-- params[4]:DEF加算値
-- params[5]:DEF倍率
-- params[6]:MND加算値
-- params[7]:MND倍率
function process2032000(_target, params)
Field:FrameUpdate(_target)
local buid
local cnt = 0
local Over,Under = 1,0
-- t = 1:unitList 2:buid
local t = this:GetProcValue() or {{}}
	for i,u in pairs(units:GetCondUnitList(TARGET_SIDE_ALLY, TARGET_COND_ALIVE, UNIT_COND_NONE)) do
		if u:ID() ~= this:ID() then
			if not toBoolean(t[1][u:ID()]) then
				u:SetBuff(BuffIds.S_GoldenPrestigeAlly, {-1, this:ID(), params[1], params[2], params[3], params[4], params[5], params[6], params[7]})
				t[1][u:ID()] = true
			end
			if (params[1]==Over and u:PerHP() >= params[2]) or (params[1]==Under and u:PerHP() < params[2]) then
				cnt = cnt + 1
			end
		end
	end
	if cnt > 0 then
		if not toBoolean(t[2]) then
			buid = this:SetBuff(BuffIds.GoldenPrestige, {-1, params[3], params[4], params[5], params[6], params[7]})
			if buid then t[2] = buid end
		end
	elseif toBoolean(t[2]) then
		this:ExpireBuff(t[2])
		t[2] = nil
	end
	this:SetProcValue(t)
end

