-- ロックオン
-- params[1]:スキルタイプ条件
-- params[2]:継続時間
-- params[3]:狙われやすさ加算値
-- params[4]:物理被ダメージ倍率
-- params[5]:回復値
-- params[6]:回復倍率
-- params[7]:MP回復値
-- params[8]:最大MP割合
function process2032003(_target, params)
local buid, beforeBuids
local t, bff
	Field:FrameUpdate(_target)
	buid = TimeLine:Target():SetBuff(DebuffIds.LockOn, {params[2], params[3]})
	if buid then
		beforeBuids = this:GetProcValue() or {}
		for i, uid in pairs(beforeBuids) do
			Field:ExpireBuff(uid)
		end
		t = {buid}
		table.insert(t, TimeLine:Target():SetBuff(BuffIds.S_HaveBuffUidSufferSkillDmgPer, {-1, buid, SKILL_PHYSIC, params[4]}))
		table.insert(t, TimeLine:Target():SetBuff(BuffIds.S_LockOnControl, {-1, buid, params[5], params[6], params[7], params[8]}))
		this:SetProcValue(t)
		Process:ShowPassive()
		Process:PlayTimeline(5)
	end
end

