-- 全体死亡時狙われやすさ増減
-- params[1]:敵味方
-- params[2]:自分を含むか 0:含む 1:含まない
-- params[3]:発動回数
-- params[4]:継続時間
-- params[5]:狙われやすさ加算値
function process2032006(_target, params)
Field:FrameUpdate(_target)
local cnt = Process:GetKeptParam(3) or 0
	if params[3] <= 0 or cnt < params[3] then
		local t = Process:TrigUnits()
		for i,u in pairs(t) do
			if this:RelativeSide(u, params[1]) and (params[2] == 0 or u:ID() ~= this:ID()) then
				if params[5] > 0 then
					if target:SetBuff(BuffIds.HateUp, {params[4], params[5]}) then Process:ShowPassive() Process:KeepParam(3, 1, CALCULATE_ADD) break end
				elseif params[5] < 0 then
					if target:SetBuff(BuffIds.HateDown, {params[4], params[5]}) then Process:ShowPassive() Process:KeepParam(3, 1, CALCULATE_ADD) break end
				end
			end
		end
	end
end

