-- 味方特定状態異常発生時対象異常回復・異常耐性増減
-- params[1]:制限回数
-- params[2]:状態異常条件
-- params[3]:状態異常種類
-- params[4]:継続時間
-- params[5]:耐性付与状態異常ID
-- params[6]:増減段階
-- params[7]:演出レベル
function process2040150(_target, params)
local buid, tbl, ulist
	Field:FrameUpdate(_target)
	tbl = this:GetProcValue()
	if tbl == nil then
		tbl = {0, {}, {}, false}	-- 1:count 2:unitList 3:buidList 4:isEnd
		ulist = units:GetCondUnitList(TARGET_SIDE_ALLY, TARGET_COND_ALIVE, UNIT_COND_NONE)
	else
		ulist = Process:TrigUnits()
	end
	if params[1] <= 0 or tbl[1] < params[1] then
		for i,u in pairs(ulist) do
			if u:RelativeSide(this) == TARGET_SIDE_ALLY and not toBoolean(tbl[2][u:ID()]) then
				if params[2] < 0 and params[5] < 0 then
					for i,ail in pairs(AILMENT_COMMON) do
						buid = u:SetBuff(BuffIds.S_AilmentTriggerSubProc, {-1, this:ID(), (1<<24) + (math.max(params[1], 0)<<16) + Pct100, ail, params[3], params[4], ail, params[6], params[7]})
						if buid then
							table.insert(tbl[3], buid)
							tbl[2][u:ID()] = true
						end
					end
				else
					buid = u:SetBuff(BuffIds.S_AilmentTriggerSubProc, {-1, this:ID(), (1<<24) + (math.max(params[1], 0)<<16) + Pct100, params[2], params[3], params[4], params[5] < 0 and params[2] or params[5], params[6], params[7]})
					if buid then
						table.insert(tbl[3], buid)
						tbl[2][u:ID()] = true
					end
				end
			end
		end
		this:SetProcValue(tbl)
	end
end

