	if myInfo == nil and this:Alive() and not this:IsExcluded() then
		myInfo = {}
		if not target:IsBuffCategory(BUFF_CATEGORY_RESIST_PHYSICAL_DAMAGE_UP_1) then if target:SetBuff(BuffIds.SufferPhysDmgPer, {-1, params[1]}) and params[2] > 0 then Process:PlayTimelineLv(params[2]) end end
		myInfo[1] = target:SetBuff(BuffIds.AutoSkillControl, {-1, BUFF_CATEGORY_RESIST_PHYSICAL_DAMAGE_UP_1, BuffIds.SufferPhysDmgPer, params[1]})
		myInfo[2] = target:SetBuff(BuffIds.AutoSkillControl2, {-1, target:ID(), BUFF_CATEGORY_RESIST_PHYSICAL_DAMAGE_UP_1, BuffIds.SufferPhysDmgPer, params[1]})
		Process:ShowPassive()
		this:SetProcValue(myInfo)
	end
end

