local coe,hpPer
	Field:FrameUpdate(_target)
	if target:Alive() then
		hpPer = target:GetProcValue()
		if hpPer ~= nil then
			coe = math.max(math.min((hpPer - params[2]) / (params[3] - params[2]), 1), 0)
			if coe > 0 and target:SetBuff(BuffIds.PhysicalDamagePer, {params[1], round(params[4] * coe)}) then Process:PlayTimelineLv(params[5]) Process:ShowPassive() end
		end
	end
	target:SetBuff(BuffIds.S_WaveEndHpPerMemory, {-1})
end

