-- リムルの剣
function process2050354(_target, params)
local buffs = {BuffIds.S_Rimuru_Sword_1, BuffIds.S_Rimuru_Sword_2, BuffIds.S_Rimuru_Sword_3, BuffIds.S_Rimuru_Sword_4, BuffIds.S_Rimuru_Sword_5, BuffIds.S_Rimuru_Sword_6, BuffIds.S_Rimuru_Sword_7, BuffIds.S_Rimuru_Sword_8, BuffIds.S_Rimuru_Sword_9, BuffIds.S_Rimuru_Sword_10}
	Field:FrameUpdate(_target)
	for i,id in ipairs(buffs) do
		if this:IsBuff(id) then
			if i < #buffs then
				if this:SetBuff(buffs[i + 1], {-1}) then Process:PlayTimeline(5) end
			end
			return nil
		end
	end
	if this:SetBuff(buffs[1], {-1}) then Process:PlayTimeline(5) end
end

