-- params[5]:自分を含むか 0:含む 1:含まない
-- params[6]:継続時間
-- params[7]:ダメージ倍率
-- params[8]:演出レベル
function process2050358(_target, params)
Field:FrameUpdate(_target)
local cost
local cnt = Process:GetKeptParam(3) or 0
	if params[1] <= 0 or cnt < params[1] then
		cost = math.ceil(params[2] + (this:MaxMP() * params[3] / Pct100))
		if cost == 0 or (this:MP() >= cost and this:DecMp(params[2], params[3])) then
			for i,u in pairs(units:GetCondUnitList(params[4], TARGET_COND_ALIVE, UNIT_COND_NONE + (params[5] == 1 and UNIT_COND_NOT_ME or 0))) do
				Process:SubProc(1, u, Pct100, {params[6], params[7], params[8]})
			end
			Process:ShowPassive()
			Process:KeepParam(3, 1, CALCULATE_ADD)
		end
	end
end

