-- ユグドラシルの聖護
-- process2050203とprocess2050303を1つにしたもの
-- スキル発動前トリガで複数プロセスが呼び出せない不具合に対応するために追加
-- params[1]:スキルID
-- params[2]:バレットID
-- params[3]:継続時間
-- params[4]:ダメージ倍率
-- params[5]:演出レベル
function process2050401(_target, params)
Field:FrameUpdate(_target)
local before1, before2 = Process:GetKeptParam(1), Process:GetKeptParam(2)
local buid1, buid2
	if target:IsDummy() then
		buid1 = target:SetBuff(BuffIds.S_DetectBulletSufferPhysDmgPer, {-1, TimeLine:SKL_PUID(), params[2], params[3], params[4], params[5]})
		buid2 = target:SetBuff(BuffIds.S_DetectBulletSufferMagDmgPer, {-1, TimeLine:SKL_PUID(), params[2], params[3], params[4], params[5]})
		if buid1 or buid2 then
			if before1 then target:ExpireBuff(before1) end
			if before2 then target:ExpireBuff(before2) end
			Process:ShowPassive()
			if buid1 then Process:KeepParam(1, buid1) end
			if buid2 then Process:KeepParam(2, buid2) end
		end
	end
end

-- ホリデームード
-- params[1]:リジェネ継続時間
-- params[2]:継続時間
-- params[3]:MND加算値
-- params[4]:MND倍率
-- params[5]:回復最低値
-- params[6]:回復倍率
-- params[7]:物理ダメージ倍率補正
-- params[8]:魔法ダメージ倍率補正
-- params[9]:最大HP加算値
-- params[10]:最大HP倍率
function process2050402(_target, params)
local t = {1, 2, 3, 4}
local ope
	Field:FrameUpdate(_target)
	for i,u in pairs(units:GetCondUnitList(TARGET_SIDE_ALLY, TARGET_COND_ALIVE, UNIT_COND_NONE)) do
		ope = t[math.random(1, #t)]
		if ope == 1 then
			if u:SetBuff(BuffIds.Regene, {params[1], params[3], params[4], params[5], params[6]}) then Process:PlayTimeline(6, u, u) end
		elseif ope == 2 then
			if u:SetBuff(BuffIds.SufferPhysDmgPer, {params[2], params[7]}) then Process:PlayTimeline(7, u, u) end
		elseif ope == 3 then
			if u:SetBuff(BuffIds.SufferMagDmgPer, {params[2], params[8]}) then Process:PlayTimeline(8, u, u) end
		elseif ope == 4 then
			if u:SetBuff(BuffIds.MaxHpEdit, {params[2], params[9], params[10]}) then Process:PlayTimeline(5, u, u) end
		end
	end
	Process:ShowPassive()
end

-- WAVE開始時属性被ダメージ増減バフorデバフを全体に付与
-- params[1]:敵・味方
-- params[2]:継続時間
-- params[3]:属性ID
-- params[4]:ダメージ倍率補正
-- params[5]:演出レベル
function process2050403(_target, params)
local flag = false
	Field:FrameUpdate(_target)
	if params[4] < 0 then
		for i,u in ipairs(units:GetCondUnitList(params[1], TARGET_COND_ALIVE, UNIT_COND_NONE)) do
			if u:SetBuff(BuffIds.SufferNonElementDmgPer + params[3], {params[2], params[4]}) then flag = true if params[5] > 0 then Process:PlayTimeline(5 + (params[3]==ELEMENT_NONE and 12 or (params[3] - 1)), u, u) end end
		end
	elseif params[4] > 0 then
		for i,u in ipairs(units:GetCondUnitList(params[1], TARGET_COND_ALIVE, UNIT_COND_NONE)) do
			if u:SetBuff(DebuffIds.SufferNonElementDmgPer + params[3], {params[2], params[4]}) then flag = true if params[5] > 0 then Process:PlayTimeline(11 + (params[3]==ELEMENT_NONE and 7 or (params[3] - 1)), u, u) end end
		end
	end
	if flag then Process:ShowPassive() end
end

-- イルミネーション改
-- params[1]:付与間隔(秒)
-- params[2]:継続時間
-- params[3]:ダメージ倍率補正
-- params[4]:演出レベル
function process2050404(_target, params)
Field:FrameUpdate(_target)
local cnt = Process:GetKeptParam(1) or params[1]
local wave = Process:GetKeptParam(2, true) or 0
local elem
	-- print('<color=yellow>wave=', Field:Wave(), ' time=', Field:Time(), ' cnt=', cnt, '</color>')
	if params[1] > 0 and params[1] <= cnt then
		-- WAVE開始前に複数回呼ばれる場合があるので応急処置
		-- TODO：クライアント側で呼ばれないよう直してもらう
		if Field:Time() ~= 0 or wave ~= Field:Wave() then
			if params[3] < 0 then
				elem = math.random(ELEMENT_FIRE, ELEMENT_DARK)
				if this:SetBuff(BuffIds.SufferNonElementDmgPer + elem, {params[2], params[3]}) then Process:ShowPassive() if params[4] > 0 then Process:PlayTimeline(5 + elem - 1) end end
			end
		end
		Process:KeepParam(1, 1)
		Process:KeepParam(2, Field:Wave(), nil, true)
	else
		Process:KeepParam(1, 1, CALCULATE_ADD)
	end
end

