-- 闘気
-- params[1]:闘気蓄積SCT倍率
-- params[2]:Lv1必要闘気
-- params[3]:Lv2必要闘気
-- params[4]:Lv3必要闘気
-- params[5]:被ダメージ時闘気加算値
-- params[6]:継続時間
-- params[7]:物理攻撃ダメージ倍率最大補正
-- params[8]:超必殺技ダメージ倍率最大補正
-- params[9]:ダメージ上限最大加算値
-- params[10]:ダメージ上限倍率最大補正
function process2050416(_target, params)
Field:FrameUpdate(_target)
local exp_map = {}
-- t = 1:level 2:exp 3:buid 4:cbuid 5:rpuid 6:rbuid
local t = this:GetProcValue() or {}
local skl = TimeLine:ParentSkill()
local coe
local exp, lv, maxlv, buid
	if skl:Type(SKILL_SKILL) then
		if params[2] > 0 then table.insert(exp_map, params[2])
		if params[3] > 0 then table.insert(exp_map, params[3])
		if params[4] > 0 then table.insert(exp_map, params[4]) end end end
		maxlv = #exp_map
		lv = t[1] or 0
		exp = t[2] or 0
		if t[3] ~= nil and not Field:IsBuffExists(t[3]) then
			lv, exp = 0, 0
			t[3] = nil
		end
		if maxlv > 0 then
			exp = exp + math.max(math.floor(TimeLine:ParentSkill():Cost() / 1000 * params[1] * Per2Num), 1)
			if lv < maxlv and exp_map[lv + 1] <= exp then
				lv = lv + 1
				exp = 0
				coe = math.max(math.min((2 ^ (lv - 1)) / (2 ^ (maxlv - 1)), 1), 0)
				buid = this:SetBuff(BuffIds.FightingSpirit[lv], {params[6], SKILL_PHYSIC, SKILL_SPECIAL, round(params[7] * coe), round(params[8] * coe)})
				if buid then
					this:SetBuff(BuffIds.S_HaveBuffUidDmgLimitBreak, {-1, buid, ELEMENT_UNMENTIONED, SKILL_SPECIAL, round(params[9] * coe), round(params[10] * coe)})
					Process:PlayTimeline(5)
					Process:ShowPassive()
					if t[3] ~= nil then this:ExpireBuff(t[3]) end
					if t[6] ~= nil and Field:IsBuffExists(t[6]) then
						this:ExpireBuff(t[6])
						t[6] = this:SetBuff(BuffIds.S_SkillEndBuffControl, {-1, t[5], buid})
					end
				end
				t[3] = buid
			end
			t[1], t[2] = lv, exp
			if t[4] == nil then
				t[4] = this:SetBuff(BuffIds.S_FightingSpiritControl, {-1, params[5]})
			end
			this:SetProcValue(t)
		end
	elseif t[3] and skl:Type(SKILL_SPECIAL) then
		t[5] = TimeLine:SKL_PUID()
		t[6] = this:SetBuff(BuffIds.S_SkillEndBuffControl, {-1, t[5], t[3]})
		this:SetProcValue(t)
	end
end

-- オート属性被ダメージ増減
-- params[1]:属性ID
-- params[2]:ダメージ倍率
-- params[3]:演出レベル
function process2050417(_target, params)
Field:FrameUpdate(_target)
local exne, invStr, invWeak
local myInfo = this:GetProcValue()
	if myInfo == nil and this:Alive() and not this:IsExcluded() then
		myInfo = {}
		if params[1] < 0 then
			params[1] = -params[1]
			params[1], exne, invStr, invWeak = bitToInt(params[1], 4, 4), bitToBoolean(params[1], 5), bitToBoolean(params[1], 6), bitToBoolean(params[1], 7)
			params[1] = ({this:WeaponElem(), this:SubWeaponElem()})[params[1]]
			if exne and params[1] == ELEMENT_NONE then params[1] = nil end
			if invStr then params[1] = ELEMENT_STRONG[params[1]] end
			if invWeak then params[1] = ELEMENT_WEAK[params[1]] end
		end
		if params[1] then
			if not target:IsBuffCategory(BUFF_CATEGORY_RESIST_ELEMENT_DAMAGE_UP_1_LIST[params[1]]) then if target:SetBuff(BuffIds.SufferNonElementDmgPer + params[1], {-1, params[2]}) and params[3] > 0 then Process:PlayTimeline(5 + (params[1]==ELEMENT_NONE and 14 or (params[1] - 1))) end end
			myInfo[1] = target:SetBuff(BuffIds.AutoSkillControl, {-1, BUFF_CATEGORY_RESIST_ELEMENT_DAMAGE_UP_1_LIST[params[1]], BuffIds.SufferNonElementDmgPer + params[1], params[2]})
			myInfo[2] = target:SetBuff(BuffIds.AutoSkillControl2, {-1, target:ID(), BUFF_CATEGORY_RESIST_ELEMENT_DAMAGE_UP_1_LIST[params[1]], BuffIds.SufferNonElementDmgPer + params[1], params[2]})
			Process:ShowPassive()
			this:SetProcValue(myInfo)
		end
	end
end

