-- クリスマスキャロル
-- params[1]:被ダメージ倍率最大補正
-- params[2]:劣化間隔(フレーム)
-- params[3]:劣化加算補正
function process2050420(_target, params)
Field:FrameUpdate(_target)
local val
local cnt = Process:GetKeptParam(1) or 0
local buid = Process:GetKeptParam(2) or 0
	if params[1] < 0 then
		val = params[1] + (params[3] * cnt)
		if buid ~= 0 and Field:IsBuffExists(buid) then this:ExpireBuff(buid) end
		if val < 0 then
			buid = this:SetBuff(BuffIds.ChristmasCarol, {-1, val}, nil, nil, nil, {math.abs(round(val * Pml2Pct))})
			if buid then
				Process:KeepParam(2, buid)
				Process:ShowPassive()
			end
			Process:KeepParam(1, 1, CALCULATE_ADD)
		end
	end
end

-- 術式構築
-- params[1]:効果最小連続発動数
-- params[2]:効果最大連続発動数
-- params[3]:制限時間
-- params[4]:スキルロール条件
-- params[5]:属性条件
-- params[6]:スキルタイプ条件
-- params[7]:ダメージ倍率最大補正
function process2050421(_target, params)
Field:FrameUpdate(_target)
local skl = TimeLine:ParentSkill()
local pv = this:GetProcValue() or {0, 0, 0, 0}	-- {buid, sisBuid, count, elem}
local coe, buid
	if pv[1] ~= 0 and Field:IsBuffExists(pv[1]) then this:ExpireBuff(pv[1]) end
	if skl:Element(params[5]) then
		if pv[2] ~= 0 then if Field:IsBuffExists(pv[2]) then this:ExpireBuff(pv[2]) else pv[3] = 0 end end
		if pv[3] > 0 and not skl:Element(pv[4]) then pv[3] = 0 end
		if pv[3] == 0 then pv[4] = skl:Element() end
		pv[3] = pv[3] + 1
		coe = math.max(math.min((pv[3] - params[1]) / (params[2] - params[1]), 1), 0)
		if coe > 0 then
			if BuffIds.TechConst[skl:Element()] ~= nil then
				buid = this:SetBuff(BuffIds.TechConst[skl:Element()], {params[3], round(params[7] * coe)})
				if buid then pv[1] = buid Process:ShowPassive() end
			end
		end
		buid = this:SetBuff(BuffIds.Control_UseBuffUid_DE, {params[3]})
		if buid then pv[2] = buid end
		this:SetProcValue(pv)
	else
		this:SetProcValue({0, 0, 0, 0})
	end
end

