-- 信託の導き
-- params[1]:付与間隔(秒)
-- params[2]:継続時間
-- params[3]:ダメージ倍率補正
-- params[4]:演出レベル
function process2050450(_target, params)
Field:FrameUpdate(_target)
local tbl, maxi, maxc
local cnt = Process:GetKeptParam(1) or params[1]
	if params[1] > 0 and params[1] <= cnt then
		tbl, maxi, maxc = {}, 0, {}
		for i,u in pairs(units:GetCondUnitList(TARGET_SIDE_OPPONENT, TARGET_COND_ALIVE, UNIT_COND_NONE)) do
			for j,k in pairs(u:Type()) do
				tbl[k] = (tbl[k] or 0) + 1
				if maxi < tbl[k] then
					maxi = tbl[k]
					maxc = {k}
				elseif maxi == tbl[k] then
					table.insert(maxc, k)
				end
			end
		end
		if maxc[1] ~= nil then maxc = maxc[math.random(1, #maxc)] else maxc = 0 end
		for i,u in pairs(units:GetCondUnitList(TARGET_SIDE_ALLY, TARGET_COND_ALIVE, UNIT_COND_NONE)) do
			Process:SubProc(1, u, Pct100, {params[2], 1, params[4]})
			if maxc ~= 0 then Process:SubProc(2, u, Pct100, {params[2], maxc, params[3], params[4]}) end
		end
		Process:ShowPassive()
		Process:KeepParam(1, 1)
	else
		Process:KeepParam(1, 1, CALCULATE_ADD)
	end
end

-- ウォークライ
-- params[1]:自分被ダメージ倍率
-- params[2]:味方被ダメージ倍率
function process2050451(_target, params)
Field:FrameUpdate(_target)
local ulist, prm
local t = this:GetProcValue()
	if t == nil then
		t = {}
		ulist = units:GetCondUnitList(TARGET_SIDE_ALLY, TARGET_COND_ALIVE, UNIT_COND_NONE)
		this:SetBuff(BuffIds.S_TargetUidAliveSufferDmgPer, {-1, this:ID(), SKILL_SCALE_WHOLE, 0, params[1], 1})
		t[this:ID()] = true
	else
		ulist = Process:TrigUnits()
	end
	for i,u in pairs(ulist) do
		if u:RelativeSide(this) == TARGET_SIDE_ALLY and not toBoolean(t[u:ID()]) then
			prm = {-1, 0, 0, 0, 0, 0, 0, SKILL_SCALE_WHOLE, 0, params[2]}
			if u:IsBuff(BuffIds.S_WarCry_Ally) then
				for j,bff in pairs(u:GetBuff(false)) do
					if bff[BUFF_INFO_ID] == BuffIds.S_WarCry_Ally then
						prm = bff[BUFF_INFO_PARAM]
						table.insert(prm, 1, -1)
						u:ExpireBuff(bff[BUFF_INFO_UID])
						break
					end
				end
			end
			for j = 2,7 do
				if prm[j] == 0 then
					prm[j] = this:ID()
					break
				end
			end
			if u:SetBuff(BuffIds.S_WarCry_Ally, prm) then
				t[u:ID()] = true
			end
		end
	end
	this:SetProcValue(t)
end

