-- 味方死亡時敵ランダム被ダメージ増減
-- params[1]:対象人数
-- params[2]:発動回数
-- params[3]:継続時間
-- params[4]:ダメージ倍率
-- params[5]:演出レベル
function process2050453(_target, params)
Field:FrameUpdate(_target)
local ulist, res
local cnt = Process:GetKeptParam(3) or 0
	if params[2] <= 0 or cnt < params[2] then
		ulist = units:GetCondUnitList(TARGET_SIDE_OPPONENT, TARGET_COND_ALIVE, UNIT_COND_NONE)
		if params[1] > 0 then
			ulist = arrayRandomize(ulist)
			for i = 1, params[1] do
				if ulist[i] ~= nil then
					Process:SubProc(1, ulist[i], Pct100, {params[3], params[4], params[5]})
					res = true
				end
			end
		else
			for i,u in pairs(ulist) do
				Process:SubProc(1, u, Pct100, {params[3], params[4], params[5]})
				res = true
			end
		end
		if res then Process:KeepParam(3, 1, CALCULATE_ADD) Process:ShowPassive() end
	end
end

