-- 騎士王
-- params[1]:制限回数
-- params[2]:継続時間
function process2050550(_target, params)
local buid, tbl
	Field:FrameUpdate(_target)
	tbl = {0, {}, false, {}}	-- 1:count 2:buidList 3:isEnd 4:unitList
	buid = this:SetBuff(BuffIds.S_KingOfKnightControl_2, {-1, params[1], params[2]})
	table.insert(tbl[2], buid)
	tbl[4][this:ID()] = true
	for i,u in ipairs(units:GetCondUnitList(TARGET_SIDE_ALLY, TARGET_COND_BOTH, UNIT_COND_NONE)) do
		if u:ID() ~= this:ID() then
			buid = u:SetBuff(BuffIds.S_KingOfKnightControl_1, {-1, params[1], params[2]})
			if buid then
				table.insert(tbl[2], buid)
				tbl[4][u:ID()] = true
			end
		end
	end
	this:SetProcValue(tbl)
end

