-- エレメントイーター
-- params[1]:経験値蓄積量
-- params[2]:Lv1必要経験値
-- params[3]:Lv2必要経験値
-- params[4]:Lv3必要経験値
-- params[5]:Lv4必要経験値
-- params[6]:Lv5必要経験値
-- params[7]:継続時間
-- params[8]:属性耐性最低増減値
-- params[9]:属性耐性最大増減値
-- params[10]:演出レベル
function process2081604(_target, params)
Field:FrameUpdate(_target)
local exp_map = {}
local t = this:GetValue(UNIT_VALUE_ELEMENT_SPIRIT_INFO) or {}
local buid = this:GetValue(UNIT_VALUE_SPIRIT_OVER_DRIVE_CONTROL)
local tl = t[ELEMENT_SPIRIT_INFO_LV] or {}
local te = t[ELEMENT_SPIRIT_INFO_EXP] or {}
local coe
local exp, lv, maxlv
	if params[2] > 0 then table.insert(exp_map, params[2])
	if params[3] > 0 then table.insert(exp_map, params[3] + exp_map[1])
	if params[4] > 0 then table.insert(exp_map, params[4] + exp_map[2])
	if params[5] > 0 then table.insert(exp_map, params[5] + exp_map[3])
	if params[6] > 0 then table.insert(exp_map, params[6] + exp_map[4]) end end end end end
	maxlv = #exp_map
	if maxlv > 0 and not this:IsBuffCategory(BUFF_CATEGORY_SPIRIT_OVER_DRIVE) and not Bullet:Element(ELEMENT_NONE) then
		lv = tl[Bullet:Element()] or 0
		exp = te[Bullet:Element()] or 0
		coe = math.max(math.min(lv / maxlv, 1), 0)
		Process:SubProc(1, Bullet:Target(), Pct100, {params[7], Bullet:Element(), params[8] + round((params[9] - params[8]) * coe), params[10]})
		exp = exp + params[1]
		if lv < maxlv and exp_map[lv + 1] <= exp then
			lv = lv + 1
			this:SetBuff(BuffIds.P_SpiritPower[Bullet:Element()][lv], {-1})
			Process:PlayTimeline(5)
			if buid ~= nil then this:ExpireBuff(buid) this:SetValue(UNIT_VALUE_SPIRIT_OVER_DRIVE_CONTROL, {}, true) end
		end
		tl[Bullet:Element()] = lv
		te[Bullet:Element()] = exp
		t[ELEMENT_SPIRIT_INFO_LV] = tl
		t[ELEMENT_SPIRIT_INFO_EXP] = te
		this:SetValue(UNIT_VALUE_ELEMENT_SPIRIT_INFO, t, true)
		Process:ShowPassive()
	end
end

-- デビルブレイカー制御
-- params[1]:DB1設定パッシブ
-- params[2]:DB2設定パッシブ
-- params[3]:DB3設定パッシブ
-- params[4]:DB4設定パッシブ
-- params[5]:DB装備順
-- params[6]:DB破損確率
function process2081605(_target, params)
Field:FrameUpdate(_target)
local triggers = {PROC_TRIGGER_DEVIL_BREAKER_1, PROC_TRIGGER_DEVIL_BREAKER_2, PROC_TRIGGER_DEVIL_BREAKER_3, PROC_TRIGGER_DEVIL_BREAKER_4}
local flag
local tbl = {}
	if this:GetProcValue() == nil then
		if params[5] >= 1234 and params[5] <= 4321 then
			tbl = {params[5] // 1000, (params[5] % 1000) // 100, (params[5] % 100) // 10, params[5] % 10}
		elseif params[5] == 0 then
			tbl = {{math.random(), 1},{math.random(), 2},{math.random(), 3},{math.random(), 4}}
			table.sort(tbl, function(a, b) return (a[1] < b[1]) end)
			tbl = {tbl[1][2], tbl[2][2], tbl[3][2], tbl[4][2]}
		else
			return
		end
		for i = 4, 1 , -1 do
			flag = false
			for j, pid in pairs(this:PassiveList()) do
				if pid == params[tbl[i]] then
					flag = true
					break
				end
			end
			if not flag then table.remove(tbl, i) end
		end
		if tbl[1] ~= nil then
			this:RaiseTrigger(triggers[tbl[1]])
			this:SetBuff(BuffIds.S_DevilBreakerControl, {-1, tbl[2] or 0, tbl[3] or 0, tbl[4] or 0, params[6]})
		end
		this:SetProcValue(true, true)
	end
end

