function process2081613(_target, params)
local u, hpUp, defUp
	Field:FrameUpdate(_target)
	u = this:GetProcessTarget(params[1])
	if u ~= nil then
		Process:SubProc(1, u, Pct100, {})
		hpUp = math.floor(this:PureMaxHP() * params[2] * Per2Num)
		defUp = math.floor(this:PureDEF() * params[3] * Per2Num)
		if this:Alive() and u:Alive() then
			Process:SubProc(2, u, Pct100, {-1, hpUp, 0, 1, 1})
			Process:SubProc(3, u, Pct100, {-1, defUp, 0, 1, 1})
		end
		if params[4] ~= 0 then
			this:SetBuff(BuffIds.S_RebootGuardian, {-1, params[1], hpUp, defUp})
		end
	end
	Process:ShowPassive()
end

