-- 帯電
-- params[1]:Lv1時雷属性与ダメージ倍率
-- params[2]:Lv1時雷属性ダメージ上限増減値
-- params[3]:Lv2時雷属性与ダメージ倍率
-- params[4]:Lv2時雷属性ダメージ上限増減値
-- params[5]:Lv3時雷属性与ダメージ倍率
-- params[6]:Lv3時雷属性ダメージ上限増減値
-- params[7]:Lv3時樹属性以外魔法被ダメージ倍率
function process2081623(_target, params)
local lv, flag, buid, val
	Field:FrameUpdate(_target)
	val = Process:GetProcEventValue(PROC_TRIGGER_CHARGED) or 0
	if val ~= 0 then
		flag = false
		lv, buid = 0, 0
		for i,bff in pairs(this:GetBuff(false)) do
			for j,k in pairs(BuffIds.Charged) do
				if bff[BUFF_INFO_ID] == k then
					lv = j
					buid = bff[BUFF_INFO_UID]
					flag = true
					break
				end
			end
			if flag then break end
		end
		lv = math.min(lv + val, 3)
		if lv > 0 then
			buid = this:SetBuff(BuffIds.Charged[lv], {-1, params[2 * lv - 1], params[2 * lv], 0, (lv >= 3 and params[7] or 0)})
			if buid then
				Process:ShowPassive()
				Process:PlayTimeline(EFFECT_TIMELINE_SEGMENT_ELEMENT[ELEMENT_THUNDER])
			end
		elseif buid ~= 0 then
			this:ExpireBuff(buid)
			Process:ShowPassive()
		end
	end
end

