-- キャッチザウェーブ
-- params[1]:ビッグウェーブ発生確率
-- params[2]:ウェーブ時回復倍率
-- params[3]:ウェーブ時特技ダメージ倍率補正
-- params[4]:ウェーブ時氷属性ダメージ倍率補正
-- params[5]:ビッグウェーブ時回復倍率
-- params[6]:ビッグウェーブ時特技ダメージ倍率補正
-- params[7]:ビッグウェーブ時氷属性ダメージ倍率補正
-- params[8]:ビッグウェーブ時特技ダメージ上限加算値
-- params[9]:ビッグウェーブ時氷属性ダメージ上限加算値
function process2081625(_target, params)
Field:FrameUpdate(_target)
local flg
local cnt = Process:GetKeptParam(1)
	if cnt == nil then cnt = 1 Process:KeepParam(1, 1) end
	if cnt >= 2 then
		flg = lottery(params[1])
		for i,u in pairs(units:GetCondUnitList(TARGET_SIDE_ALLY, TARGET_COND_ALIVE, UNIT_COND_NONE)) do
			if flg then 
				Process:SubProc(1, u, Pct100, {1200, 1, params[6], params[7], params[8], 0, params[9]})
				Process:SubProc(2, u, Pct100, {0, params[5]})
			else
				Process:SubProc(1, u, Pct100, {600, 0, params[3], params[4]})
				Process:SubProc(2, u, Pct100, {0, params[2]})
			end
		end
		Process:ShowPassive()
		Process:KeepParam(1, 1)
	else
		Process:KeepParam(1, 1, CALCULATE_ADD)
	end
end

