-- params[2]:発生確率
-- params[3]:継続時間
-- params[4]:追加ダメージ数
-- params[5]:追加ダメージ倍率MIN
-- params[6]:追加ダメージ倍率MAX
function process2081638(_target, params)
-- t = 1:count 2:unitList 3:buidList 4:isEnd
local buid, t, cnt, ulist
	Field:FrameUpdate(_target)
	t = this:GetProcValue()
	if t == nil then
		t = {0, {}, {}, false}
		ulist = units:GetCondUnitList(TARGET_SIDE_ALLY, TARGET_COND_BOTH, UNIT_COND_NONE)
	else
		ulist = Process:TrigUnits()
	end
	for i,u in pairs(ulist) do
		if u:RelativeSide(this)==TARGET_SIDE_ALLY and not toBoolean(t[2][u:ID()]) then
			for j = ELEMENT_FIRE, ELEMENT_DARK do
				buid = u:SetBuff(BuffIds.S_AttackSkillSubProc, {-1, this:ID(), (1<<24) + (params[2]<<2) + (1<<1) + 1, j, params[1], params[3], j, params[4], params[5], params[6]})
				if buid then
					table.insert(t[3], buid)
					t[2][u:ID()] = true
				end
			end
		end
	end
	this:SetProcValue(t)
end

-- オーバーリミッツ
-- params[1]:バフカテゴリ条件
-- params[2]:ポイント蓄積SCT倍率
-- params[3]:Lv1必要ポイント
-- params[4]:Lv2必要ポイント
-- params[5]:Lv3必要ポイント
-- params[6]:Lv4必要ポイント
function process2081639(_target, params)
Field:FrameUpdate(_target)
local exp_map = {}
-- t = 1:level 2:exp 3:buid
local t = this:GetProcValue() or {}
local exp, lv, maxlv, buid
	if params[3] > 0 then table.insert(exp_map, params[3])
	if params[4] > 0 then table.insert(exp_map, params[4])
	if params[5] > 0 then table.insert(exp_map, params[5])
	if params[6] > 0 then table.insert(exp_map, params[6]) end end end end
	maxlv = #exp_map
	lv = t[1] or 0
	exp = t[2] or 0
	if t[3] ~= nil and not Field:IsBuffExists(t[3]) then
		lv, exp = 0, 0
		t[3] = nil
	end
	if maxlv > 0 then
		exp = exp + math.max(math.floor(TimeLine:ParentSkill():Cost() / 1000 * params[2] * Per2Num), 1)
		if lv < maxlv and exp_map[lv + 1] <= exp then
			lv = lv + 1
			exp = 0
			buid = this:SetBuff(BuffIds.OverLimitsGauge[lv], {-1})
			if buid then
				Process:PlayTimeline(5)
				Process:ShowPassive()
				if t[3] ~= nil then this:ExpireBuff(t[3]) end
			end
			t[3] = buid
		end
		t[1], t[2] = lv, exp
		this:SetProcValue(t)
	end
end

