-- プレゼントストック未所持状態指定時間経過後プレゼントストック
-- params[1]:ストック間隔
-- params[2]:継続時間
-- params[3]:情報番号(赤)
-- params[4]:情報番号(緑)
-- params[5]:情報番号(紫)
function process2081642(_target, params)
Field:FrameUpdate(_target)
local res
local beforeBf = this:GetProcValue()
	if this:IsBuffCategory(BUFF_CATEGORY_EXCLUSIVE_35) then
		res = false
		if beforeBf ~= nil then this:ExpireBuff(beforeBf) res = true end
		if res then this:SetProcValue(nil) end
	elseif not this:Alive() then
		beforeBf = this:SetBuff(BuffIds.Control_UseBuffUid_AE, {-1})
		this:SetProcValue(beforeBf)
	else
		res = false
		if beforeBf ~= nil and not Field:IsBuffExists(beforeBf) then
			for i,bff in pairs(Process:TrigBuffs()) do
				if bff[BUFF_INFO_UID] == beforeBf then
					if bff[BUFF_INFO_ID] == BuffIds.Control_UseBuffUid_DE then res = true end
					break
				end
			end
		end
		if res then
			this:SubProc(1, this, Pct100, {params[2], params[3], params[4], params[5]})
		elseif beforeBf == nil or not Field:IsBuffExists(beforeBf) then
			beforeBf = this:SetBuff(BuffIds.Control_UseBuffUid_DE, {params[1]})
			this:SetProcValue(beforeBf)
		else
			Process:SetFailed()
		end
	end
end

