-- 縮地
-- params[1]:継続時間
-- params[2]:移動速度加算値
-- params[3]:付与間隔
function process2081648(_target, params)
Field:FrameUpdate(_target)
local res
local pv = this:GetProcValue() or {}
local beforeBf, controlBf = pv[1], pv[2]
	if Process:GetKeptParam(1) == nil then
		if this:Alive() then
			if this:SetBuff(BuffIds.ShorteningDistances, {params[1], params[2]}) then Process:PlayTimeline(5) Process:ShowPassive() end
		else
			beforeBf = this:SetBuff(BuffIds.Control_UseBuffUid_AE, {-1})
			this:SetProcValue({beforeBf})
		end
		Process:KeepParam(1, 1)
	else
		if this:IsBuffCategory(BUFF_CATEGORY_EXCLUSIVE_43) then
			res = false
			if beforeBf ~= nil then this:ExpireBuff(beforeBf) res = true end
			if res then this:SetProcValue({}) end
		elseif not this:Alive() then
			beforeBf = this:SetBuff(BuffIds.Control_UseBuffUid_AE, {-1})
			this:SetProcValue({beforeBf})
		else
			res = false
			if beforeBf ~= nil and not Field:IsBuffExists(beforeBf) and controlBf ~= nil and Field:IsBuffExists(controlBf) then
				for i,bff in pairs(Process:TrigBuffs()) do
					if bff[BUFF_INFO_UID] == beforeBf then
						if bff[BUFF_INFO_ID] == BuffIds.Control_UseBuffUid_DE then res = true end
						break
					end
				end
			end
			if res then
				if this:SetBuff(BuffIds.ShorteningDistances, {params[1], params[2]}) then Process:PlayTimeline(5) Process:ShowPassive() end
			elseif beforeBf == nil or not Field:IsBuffExists(beforeBf) or controlBf == nil or not Field:IsBuffExists(controlBf) then
				beforeBf = this:SetBuff(BuffIds.Control_UseBuffUid_DE, {params[3]})
				controlBf = this:SetBuff(BuffIds.Control_UseBuffUid, {-1})
				this:SetBuff(BuffIds.S_DamageCountCondBuffControl, {-1, ELEMENT_UNMENTIONED, 0, 1, controlBf})
				this:SetProcValue({beforeBf, controlBf})
			else
				Process:SetFailed()
			end
		end
	end
end

-- ウィッチタイム
-- params[1]:発生確率
-- params[2]:スキルタイプ条件
-- params[3]:継続時間
-- params[4]:スーパーアーマー値
-- params[5]:汎用数値情報(デバフ継続時間)
-- params[6]:汎用数値情報(物理被ダメージ倍率)
-- params[7]:汎用数値情報(魔法被ダメージ倍率)
function process2081649(_target, params)
local list, skl, sid, spuid, buid, val, val2, val3
	Field:FrameUpdate(_target)
	skl = Bullet:GetParentSkill()
	if skl ~= nil then
		sid, spuid = skl:ID(), Bullet:SKL_PUID()
		list = this:GetProcValue() or {}
		if list[sid] == nil then list[sid] = {puid = {}, del = {}} end
		for i,j in pairs(list[sid].puid) do
			if j == spuid then return end
			if not skl:PUIDs(j) then list[sid].del[i] = true end
		end
		for i = #(list[sid].puid), 1, -1 do
			if list[sid].del[i] then
				table.remove(list[sid].puid, i)
				table.remove(list[sid].del, i)
			end
		end
		if #(this:GetBuffIdBuffs(BuffIds.WitchTime)) == 0 and lottery(params[1]) then
			buid = this:SetBuff(BuffIds.WitchTime, {params[3], params[4]}) 
			if buid then
				Process:PlayTimeline(5)
				Process:ShowPassive()
				val = this:GetGeneralCount(params[5])
				if val ~= 0 then
					val2, val3 = this:GetGeneralCount(params[6]), this:GetGeneralCount(params[7])
					if val2 ~= 0 then Process:SubProc(1, Bullet:Parent(), Pct100, {val, val2, 1}) end
					if val3 ~= 0 then Process:SubProc(2, Bullet:Parent(), Pct100, {val, val3, 1}) end
				end
			end
		end
		table.insert(list[sid].puid, spuid)
		table.insert(list[sid].del, false)
		this:SetProcValue(list)
	end
end

