-- ゼロ
-- params[1]:指定間隔(フレーム)
-- params[2]:スキルタイプ条件
-- params[3]:与ダメージ倍率補正
-- params[4]:ダメージ上限増減値
-- params[5]:スキルタイプ条件
-- params[6]:被ダメージ倍率補正
-- params[7]:DEF倍率
-- params[8]:MND倍率(リジェネ)
-- params[9]:回復最低値
-- params[10]:回復倍率
function process2081656(_target, params)
Field:FrameUpdate(_target)
local flag = false
local pv = this:GetProcValue() or 0
	for i,u in pairs(units:GetCondUnitList(TARGET_SIDE_ALLY, TARGET_COND_ALIVE, UNIT_COND_NONE)) do
		if u:PerHP() < 3000 then flag = true break end
	end
	if (pv ~= 1 and flag) or (pv ~= 2 and not flag) then
		for i,u in pairs(units:GetCondUnitList(TARGET_SIDE_ALLY, TARGET_COND_ALIVE, UNIT_COND_NONE)) do
			if flag then
				Process:SubProc(2, u, Pct100, {-1, 0, params[7], params[5], params[6], 0, params[8], params[9], params[10], 1})
			else
				Process:SubProc(1, u, Pct100, {-1, params[2], params[3], params[4], 0, 1})
			end
		end
		Process:ShowPassive()
	end
	if flag then this:SetProcValue(1) else this:SetProcValue(2) end
end

