local buid
local cnt = Process:GetKeptParam(3) or 0
	if params[6] ~= 0 and (params[3] <= 0 or cnt < params[3]) then
		if (target:AddGeneralCount(params[6], params[7])) then
			buid = target:SetBuff(params[5]==0 and BuffIds.Control_UseBuffUid or BuffIds.Control_UseBuffUid_DE, {params[4]})
			if buid then target:SetBuff(BuffIds.S_UidBuffEndAddGeneralCount, {-1, buid, params[6], params[7], 2, 2}) end
			Process:ShowPassiveForGeneralCount(params[6], target)
		end
		Process:KeepParam(3, 1, CALCULATE_ADD)
	end
end

