-- エンゲージリング
-- params[1]:ターゲットID
-- params[2]:継続時間
-- params[3]:効果発生距離
-- params[4]:効果最大距離
-- params[5]:属性条件
-- params[6]:スキルタイプ条件
-- params[7]:与ダメージ最大倍率
-- params[8]:ダメージ上限増減最大値
-- params[9]:ダメージ上限増減最大倍率
-- params[10]:演出レベル
function process2081659(_target, params)
local u, buid1, buid2
	Field:FrameUpdate(_target)
	u = this:GetProcessTarget(params[1])
	if u ~= nil and u:Alive() then
		for i,u in pairs(units:GetCondUnitList(TARGET_SIDE_ALLY, TARGET_COND_ALIVE, UNIT_COND_NONE)) do
			-- 自分以外にも花嫁ティリアが居る場合、INDEXが若い方のみ発火
			if u:UnitID() == 100033 and u:Index() < this:Index() then return end
			if u:IsBuff(BuffIds.EngagementRing) then return end
		end
		Process:SubProc(1, this, Pct100, {params[2], params[3], params[4], params[5], params[6], params[7], params[8], params[9], params[10]})
		buid1 = Process:GetSubProcResult()
		Process:SubProc(1, u, Pct100, {params[2], params[3], params[4], params[5], params[6], params[7], params[8], params[9], params[10]})
		buid2 = Process:GetSubProcResult()
		if buid1 ~= nil and buid2 ~= nil then
			this:SetBuff(BuffIds.S_UidBuffEndBuffControl, {-1, buid1, buid2})
			u:SetBuff(BuffIds.S_UidBuffEndBuffControl, {-1, buid2, buid1})
		end
		Process:ShowPassive()
	end
end

