-- params[9]:超必殺技ダメージ上限増減倍率
-- params[10]:デバフ継続時間
function process2081669(_target, params)
local buff, cnt
	Field:FrameUpdate(_target)
	buff = (target:GetBuffCategoryBuffs(BUFF_CATEGORY_EXCLUSIVE_56))[1]
	if buff==nil then cnt = 1 else cnt = (buff[BUFF_INFO_PARAM][1]) + 1 end
	if cnt > 5 then
		Process:EditDamageLimit(99990000, 0, 0, true)
		target:ExpireBuffCategory(BUFF_CATEGORY_EXCLUSIVE_56)
		target:DotDamage(math.floor(target:MaxHP() / 2), false)
		-- Process:SubProc(1, target, Pct100, {ENEMY_TYPE_NORMAL})
		Process:SubProc(1, target, Pct100, {params[10], 0, -5000, 1})
		Process:ShowPassive()
	else
		if target:SetBuff(BuffIds.TS_Magicules, {params[2], cnt, params[3], params[4], params[5], params[6], params[7], params[8], params[9]}, nil, nil, nil, nil, BUFF_ICON_ID_TS_MAGICULES[cnt]) then Process:ShowPassive() Process:PlayTimeline(5) end
	end
end

