-- SNリング増加
-- params[1]:属性条件
-- params[2]:スキルタイプ条件
-- params[3]:継続時間
-- params[4]:Lv1付与確率
-- params[5]:Lv2付与確率
-- params[6]:Lv3付与確率
-- params[7]:Lv4付与確率
-- params[8]:Lv5付与確率
-- params[9]:Lv5再付与確率
function process2081684(_target, params)
local lv, rate = 1, 0
	Field:FrameUpdate(_target)
	if target:IsBuffCategory(BUFF_CATEGORY_EXCLUSIVE_66) then
		if target:IsBuff(BuffIds.SN_Ring[5]) then
			lv, rate = 5, params[9]
		elseif target:IsBuff(BuffIds.SN_Ring[4]) then
			lv, rate = 5, params[8]
		elseif target:IsBuff(BuffIds.SN_Ring[3]) then
			lv, rate = 4, params[7]
		elseif target:IsBuff(BuffIds.SN_Ring[2]) then
			lv, rate = 3, params[6]
		elseif target:IsBuff(BuffIds.SN_Ring[1]) then
			lv, rate = 2, params[5]
		end
	else
		lv, rate = 1, params[4]
	end
	if lottery(rate) then
		target:SetBuff(BuffIds.SN_Ring[lv], {params[3], lv})
	end
end

