-- 指定領域内腐魔術理論体系
-- params[1]:領域番号条件
-- params[2]:制限回数
-- params[3]:継続時間
-- params[4]:ステータス加算値
-- params[5]:ステータス倍率
-- params[6]:4属性ダメージ倍率補正
-- params[7]:移動速度加算値
-- params[8]:演出レベル
function process2081692(_target, params)
local buid, prm, pv
	Field:FrameUpdate(_target)
	if params[1] == 0 then
		Process:SetFailed()
	else
		-- pv = 1:{collId = {uid = cnt}} 2:{collId = cnt} 3:{uid = cnt} 4:cnt}
		pv = this:GetProcValue() or {}
		prm = arrayInit(bitSplitArray(params[2], 8), 4, 0)
		for i,coll in pairs(Process:TrigCollisions()) do
			if coll:GroupIds(params[1]) then
				for j,u in pairs(coll:TrigUnits()) do
					if u:RelativeSide(this, TARGET_SIDE_OPPONENT) and coll:InsideTargetIds(u:ID()) then
						buid = {}
						if not u:IsBuff(DebuffIds.Corrosion) then
							if (prm[1] <= 0 or (tableGetValue(pv, {1, coll:ID(), u:ID()}) or 0) < prm[1]) and (prm[2] <= 0 or (tableGetValue(pv, {2, coll:ID()}) or 0) < prm[2]) and (prm[3] <= 0 or (tableGetValue(pv, {3, u:ID()}) or 0) < prm[3]) and (prm[4] <= 0 or (tableGetValue(pv, {4}) or 0) < prm[4]) then
								Process:SubProc(1, u, Pct100, {params[3], params[4], params[5], params[6], params[7], params[8]})
								if prm[1] > 0 then this:CalcProcValue({1, coll:ID(), u:ID()}, 1, CALCULATE_ADD) end
								if prm[2] > 0 then this:CalcProcValue({2, coll:ID()}, 1, CALCULATE_ADD) end
								if prm[3] > 0 then this:CalcProcValue({3, u:ID()}, 1, CALCULATE_ADD) end
								if prm[4] > 0 then this:CalcProcValue({4}, 1, CALCULATE_ADD) end
								buid = Process:GetSubProcResult()
								if buid then this:SetBuff(BuffIds.S_SkillDetectionSubProc, {-1, this:ID(), (3<<24) + (1<<16) + (Pct100<<2) + (0<<1) + 0, ELEMENT_UNMENTIONED, SKILL_SPECIAL, buid}) end
								buid = {buid}
							end
						else
							for k,buff in pairs(u:GetBuffIdBuffs(DebuffIds.Corrosion)) do
								table.insert(buid, buff[BUFF_INFO_UID])
							end
						end
						if buid[1]~=nil then this:SetBuff(BuffIds.S_CollisionOutSubProc, {-1, u:ID(), (2<<24) + (1<<16) + (Pct100<<2) + (1<<1) + 0, coll:ID(), u:ID(), params[1], table.unpack(buid)}) end
					end
				end
			end
		end
		Process:ShowPassive()
	end
end

