			val[4] = val[4] + math.floor(u:PureMND() * params[7] * Per2Num)
		end
	end
	if target:SetBuff(BuffIds.SacrificeOfPower, {params[5], val[1], val[2], val[3], val[4], params[8], params[9], params[10], 0}) then Process:ShowPassive() Process:PlayTimelineLv(1) end
