-- params[8]:ダメージ上限倍率補正
-- params[9]:演出レベル
function process2082609(_target, params)
Field:FrameUpdate(_target)
local pv = this:GetProcValue() or {}
local rFunc = function(t,k,e) return (this:Time()-t[k]<=params[4]) end
	pv = arrayRemove(pv, rFunc)
	if #pv >= params[5] then
		if this:SetBuff(BuffIds.NextSpecialDamageLimit, {params[6], 1, params[7], params[8]}) then Process:ShowPassive() Process:PlayTimelineLv(params[9]) end
