-- params[6]:ダメージ上限倍率補正
-- params[7]:演出レベル
function process2082663(_target, params)
	Field:FrameUpdate(_target)
	for i,u in pairs(units:GetCondUnitList(params[1], TARGET_COND_ALIVE, UNIT_COND_NONE + (params[2] == 1 and UNIT_COND_NOT_ME or 0))) do
		Process:SubProc(1, u, Pct100, {params[3], params[4], params[5], params[6], params[7]})
	end
	Process:ShowPassive()
end

-- 精霊力解放制御用
-- params[1]:スキルID
function process2082700(_target, params)
local buid, skl
	Field:FrameUpdate(_target)
	buid = this:GetValue(UNIT_VALUE_SPIRIT_OVER_DRIVE_CONTROL)
	skl = this:GetSkillFromID(params[1])
	if buid == nil and skl then
		buid = this:SetBuff(DebuffIds.S_DisableSkill, {-1, skl:Type(), skl:Index()})
		this:SetValue(UNIT_VALUE_SPIRIT_OVER_DRIVE_CONTROL, buid, true)
	end
end

-- 指定スキル使用不可_HP条件解除
-- params[1]:スキルID
-- params[2]:条件閾値方向
-- params[3]:条件HP閾値
-- params[4]:クエスト中発動回数
function process2082701(_target, params)
Field:FrameUpdate(_target)
local cnt = this:GetProcValue() or 0
local buid, skl
	skl = this:GetSkillFromID(params[1])
	if skl then
		buid = this:SetBuff(DebuffIds.S_DisableSkill_WAVE, {-1, skl:Type(), skl:Index()})
		if params[4] < 0 or cnt < params[4] then
			if buid then 
				this:SetProcValue(cnt + 1, true)
				this:SetBuff(BuffIds.S_HpCondBuffControl, {-1, params[2], params[3], buid})
			end
		end
	end
end

-- アリーナ開始時指定スキル永続使用不可
-- params[1]:スキルID
function process2082702(_target, params)
local tbl, skl
	Field:FrameUpdate(_target)
	tbl = this:GetValue(UNIT_VALUE_DISABLE_SKILL_LIST) or {}
	skl = this:GetSkillFromID(params[1])
	if skl and not toBoolean(tbl[skl:ID()]) then
		this:SetBuff(DebuffIds.S_DisableSkill, {-1, skl:Type(), skl:Index()})
		tbl[skl:ID()] = true
		this:SetValue(UNIT_VALUE_DISABLE_SKILL_LIST, tbl, true)
	end
end

-- 開始時アイテム使用不可
-- params[1]:アイテムID
-- params[2]:スキルID
function process2082703(_target, params)
local skl, buid
	Field:FrameUpdate(_target)
	skl = this:GetSkillFromID(params[2])
	if skl then
		buid = this:SetBuff(DebuffIds.S_DisableSkill_WAVE, {-1, skl:Type(), skl:Index()})
		this:SetPairingBuff('Item' .. tostring(params[1]), buid)
	end
end

-- 特定IDパッシブ未所持時指定スキル永続使用不可
-- params[1]:パッシブID条件
-- params[2]:スキルID
function process2082704(_target, params)
local tbl, skl
	Field:FrameUpdate(_target)
	if not this:HavePassive(params[1]) then
		tbl = this:GetValue(UNIT_VALUE_DISABLE_SKILL_LIST) or {}
		skl = this:GetSkillFromID(params[2])
		if skl and not toBoolean(tbl[skl:ID()]) then
			this:SetBuff(DebuffIds.S_DisableSkill, {-1, skl:Type(), skl:Index()})
			tbl[skl:ID()] = true
			this:SetValue(UNIT_VALUE_DISABLE_SKILL_LIST, tbl, true)
		end
	end
end

