-- WAVE開始時HP減少無効化
-- params[1]:ペアリングID
-- params[2]:HP閾値
-- params[3]:継続時間
function process2082800(_target, params)
local buid, buid2
	Field:FrameUpdate(_target)
	buid = target:SetBuff(BuffIds.P_ClampHp, {-1, 0, params[2], 1})
	if buid then
		target:SetHpStopperUI(params[2], buid)
		if params[1] ~= 0 then
			if params[3] > 0 then
				target:SetBuff(BuffIds.S_HpCondTimeLimitBuffControl, {-1, 0, params[2] + 1, params[3], buid})
			end
			target:SetPairingBuff(params[1], buid)
		end
	end
end

