-- 指定援護効果制御
-- params[1]:援護ID
-- params[2]:援護カテゴリ
-- params[3]:援護LV
-- params[4]:制御操作 1:有効化 2:無効化
function process3000000(_target, params)
local tbl
	Field:FrameUpdate(_target)
	if params[4] == 1 then
		tbl = this:GetValue({UNIT_VALUE_SUPPORT_PASSIVE_INFO, params[1], params[2], params[3]})
		if isTableOrClass(tbl) then Field:AddSupportPassive(params[1], params[2], params[3], tbl.ID, tbl.Params) end
	elseif params[4] == 2 then
		Field:RemoveSupportPassive(params[1], params[2], params[3])
	end
end

-- 特定キャラ専用援護対象STR増減
-- params[1]:キャラタイプ条件
-- params[2]:援護ID
-- params[3]:援護カテゴリ
-- params[4]:援護LV
-- params[5]:STR加算値
-- params[6]:STR倍率
function process3030000(_target, params)
local tbl
	Field:FrameUpdate(_target)
	if not this:GetValue({UNIT_VALUE_SUPPORT_PASSIVE_INFO, params[2], params[3], params[4]}) then
		tbl = {ID = BuffIds.P_StrEdit, Params = {-1, params[5], params[6]}}
		this:SetValue({UNIT_VALUE_SUPPORT_PASSIVE_INFO, params[2], params[3], params[4]}, tbl)
		if this:Type(params[1]) then
			Field:AddSupportPassive(params[2], params[3], params[4], tbl.ID, tbl.Params, not Field:GetValue({FIELD_VALUE_SUPPORT_PASSIVE_INFO, this:Side(), 'Enable'}))
		end
		this:SetBuff(BuffIds.S_CharaTypeAddSubProc, {-1, this:ID(), (1<<24) + (0<<16) + (Pct100<<2) + (0<<1) + 0, params[1], params[2], params[3], params[4], 1})
		this:SetBuff(BuffIds.S_CharaTypeRemoveSubProc, {-1, this:ID(), (1<<24) + (0<<16) + (Pct100<<2) + (0<<1) + 0, params[1], params[2], params[3], params[4], 2})
	end
end

