-- P_特技発動時MP消費与ダメージ増加判定_特技1
-- params[1]:スキルID
-- params[2]:ダメージ倍率
function buff300(_target, params)
Field:FrameUpdate(_target)
local puid1 = Buff:GetKeptParam(1) or 0
local puid2 = Buff:GetKeptParam(2) or 0
local puid3 = Buff:GetKeptParam(3) or 0
local puid4 = Buff:GetKeptParam(4) or 0
local puid5 = Buff:GetKeptParam(5) or 0

	if this:IsBuff(BuffIds.P_MpDecDmgPerFlag1) and Bullet:SKL_PUID() ~= puid1 and Bullet:SKL_PUID() ~= puid2 and Bullet:SKL_PUID() ~= puid3 and Bullet:SKL_PUID() ~= puid4 and Bullet:SKL_PUID() ~= puid5 then
		this:SetBuff(BuffIds.P_MpDecDmgPer1, {500, params[1], Bullet:SKL_PUID(), params[2]})
		Buff:KeepParam(1, Bullet:SKL_PUID())
		Buff:KeepParam(2, puid1)
		Buff:KeepParam(3, puid2)
		Buff:KeepParam(4, puid3)
		Buff:KeepParam(5, puid4)
	end
end

