-- 炎刃
-- params[1]:属性条件
-- params[2]:属性耐性増減値
-- params[3]:INT増減値
-- params[4]:INT倍率
-- params[5]:ダメージ倍率
-- params[6]:演出レベル
function buff10100(_target, params)
Field:FrameUpdate(_target)
local BUID
local isFirst = Buff:GetKeptParam(1) or 0
	this:EditElemResist(TARGSTAT_REAL, ELEMENT_ICE, params[2], LIFETYPE_CONTINUOUS)
	if isFirst==0 then
		Buff:KeepParam(1, 1)
	else
		Process:PlayTimeline(12, Buff:Parent(), Buff:Target())
		BUID = Buff:GenerateBullet(3401201, 32)
		Process:SetBulletInfo(BUID, BULLET_PROPERTY_SKILL_ELEMENT, ELEMENT_FIRE)
		Process:SetBulletInfo(BUID, BULLET_PROPERTY_SKILL_TYPE, SKILL_MAGIC)
		Process:SetBulletInfo(BUID, BULLET_PROPERTY_SKILL_ROLE, SKILL_ROLE_ATTACK)
	end
end

