-- 四属性刃
-- params[1]:ダメージ属性選択方法(0:順番 1:ランダム 2:最弱点)
-- params[2]:属性耐性増減値
-- params[3]:INT増減値
-- params[4]:INT倍率
-- params[5]:ダメージ倍率
-- params[6]:演出レベル
function buff10106(_target, params)
Field:FrameUpdate(_target)
local BUID
local compareFunc, elem, min_resist
local cnt = Buff:GetKeptParam(1) or 0
local etbl = {ELEMENT_FIRE, ELEMENT_ICE, ELEMENT_TREE, ELEMENT_THUNDER}
local tbl = {[ELEMENT_FIRE] = {12, 3401201}, [ELEMENT_ICE] = {13, 3401301}, [ELEMENT_TREE] = {14, 3401401}, [ELEMENT_THUNDER] = {15, 3401501}}
	this:EditElemResist(TARGSTAT_REAL, ELEMENT_FIRE, params[2], LIFETYPE_CONTINUOUS)
	this:EditElemResist(TARGSTAT_REAL, ELEMENT_ICE, params[2], LIFETYPE_CONTINUOUS)
	this:EditElemResist(TARGSTAT_REAL, ELEMENT_TREE, params[2], LIFETYPE_CONTINUOUS)
	this:EditElemResist(TARGSTAT_REAL, ELEMENT_THUNDER, params[2], LIFETYPE_CONTINUOUS)
	if cnt==0 then
		Buff:KeepParam(1, 1)
	else
		if params[1] == 0 then
			elem = etbl[((cnt - 1) % 4) + 1]
			Buff:KeepParam(1, 1, CALCULATE_ADD)
		elseif params[1] == 1 then
			elem = etbl[math.random(1, 4)]
		elseif params[1] == 2 then
			compareFunc = newCompare2(COMPARE_UNDER)
			elem, min_resist = 0, math.maxinteger
			for e,n in pairs(this:ElemResist()) do
				if e == ELEMENT_FIRE or e == ELEMENT_ICE or e == ELEMENT_TREE or e == ELEMENT_THUNDER then
					elem, min_resist = compareFunc(e, n)
				end
			end
			if #elem > 0 then elem = elem[math.random(1, #elem)] else elem = 0 end
		end
		if elem ~= 0 then
			Process:PlayTimeline(tbl[elem][1], Buff:Parent(), Buff:Target())
			BUID = Buff:GenerateBullet(tbl[elem][2], 32)
			Process:SetBulletInfo(BUID, BULLET_PROPERTY_SKILL_ELEMENT, elem)
			Process:SetBulletInfo(BUID, BULLET_PROPERTY_SKILL_TYPE, SKILL_MAGIC)
			Process:SetBulletInfo(BUID, BULLET_PROPERTY_SKILL_ROLE, SKILL_ROLE_ATTACK)
		end
	end
end

