local cnt = Buff:GetKeptParam(1) or 0
	if cnt==0 then
		if not this:IsRemote() then
			this:SetBuff(BuffIds.S_HaveBuffUidSkillDmgPer, {-1, Buff:UID(), 0, params[6]})
			this:SetBuff(BuffIds.S_NotMultiAilmentBuffControl, {-1, params[1], params[2], params[3], 0, Buff:UID()})
		end
		Buff:KeepParam(1, 1)
	else
		-- Process:PlayTimeline(17, Buff:Parent(), Buff:Target())
		BUID = Buff:GenerateBullet(tbl[math.min(((params[4] * cnt) // params[5]) + 1, #tbl)], 0)
		Process:SetBulletInfo(BUID, BULLET_PROPERTY_SKILL_ELEMENT, ELEMENT_DARK)
