-- DOTダメージ
-- params[1]:ダメージ間隔(秒)
-- params[2]:ダメージタイプ(固定/割合)
-- params[3]:ダメージMIN
-- params[4]:ダメージMAX
function buff11100(_target, params)
Field:FrameUpdate(_target)
local dType_Fixed, dType_MaxHp, dType_NowHp = 0, 1, 2
local dCnt = Buff:GetKeptParam(1) or 0
local val

	if params[1] > 0 and params[1] <= dCnt then
		if params[2] == dType_Fixed then
			val = round(math.random(params[3], params[4]))
		elseif params[2] == dType_MaxHp then
			val = round(target:MaxHP() * math.random(params[3], params[4]) * Per2Num)
		elseif params[2] == dType_NowHp then
			val = round(target:HP() * math.random(params[3], params[4]) * Per2Num)
		end
		Buff:DotDamage(target, val)
		Buff:KeepParam(1, 0)
	else
		Buff:KeepParam(1, 1, CALCULATE_ADD)
	end
end

