-- 破滅ノ歌声
-- params[1]:距離条件MIN
-- params[2]:距離条件MAX
-- params[3]:ダメージ間隔(秒)
function buff11116(_target, params)
Field:FrameUpdate(_target)
local BUID
local res = false
local dCnt = Buff:GetKeptParam(1) or 0
local ulist = {}
	if params[3] > 0 and params[3] <= dCnt then
		for i,u in pairs(units:GetCondUnitList(TARGET_SIDE_ALLY, TARGET_COND_ALIVE, UNIT_COND_NEAR, params[2])) do
			if this:Distance(u) >= params[1] and u:ID() ~= this:ID() then
				table.insert(ulist, u)
			end
		end
		if ulist[1] ~= nil then
			BUID = Process:GenerateBullet(100110, ulist, 0, true, true, TARGET_STATUS_SUBJECT_WORK)
			if BUID then
				Process:SetBulletInfo(BUID, BULLET_PROPERTY_SKILL_TYPE, SKILL_MAGIC)
				Process:SetBulletInfo(BUID, BULLET_PROPERTY_SKILL_ROLE, SKILL_ROLE_ATTACK)
				res = true
			end
		end
		Buff:KeepParam(1, 1)
	else
		Buff:KeepParam(1, 1, CALCULATE_ADD)
	end
end

-- 天山の構え【翠】
-- params[1]:MDEF加算値
