-- params[4]:回復倍率
-- params[5]:DEF加算値
-- params[6]:DEF倍率
-- params[7]:MDEF加算値
-- params[8]:MDEF倍率
function buff20005(_target, params)
	Field:FrameUpdate(_target)
	this:EditDEF(TARGSTAT_REAL, params[5], params[6], 0, LIFETYPE_CONTINUOUS)
	this:EditMND(TARGSTAT_REAL, params[7], params[8], 0, LIFETYPE_CONTINUOUS)
	if toBoolean(Buff:GetKeptParam(1)) then
		Buff:EditMND(nil, params[1], params[2])
		Process:PlayTimeline(5)
		Buff:Heal(nil, params[3], params[4])
	else
		Buff:KeepParam(1, 1)
	end
end

