-- 肉の晩餐
-- params[1]:発動間隔(秒)
-- params[2]:バフHP
-- params[3]:参照ステータス
-- params[4]:回復倍率
-- params[5]:演出番号
function buff20100(_target, params)
Field:FrameUpdate(_target)
local val
local cnt = Buff:GetKeptParam(1) or 0
local total = Buff:GetKeptParam(2) or 0
	if params[1] > 0 and params[1] <= cnt then
		val = math.min(round(target:Status(params[3]) * params[4] * Per2Num), params[2] - total, target:MaxHP() - target:HP(), 9999)
		if val > 0 then
			if Buff:Parent():HealPct(target, val, 0) and params[5] ~= 0 then
				Process:PlayTimeline(params[5])
			end
			total = total + val
			if total >= params[2] then Buff:Expire() end
			Buff:KeepParam(2, total)
			Buff:KeepParam(1, 1)
		end
	else
		Buff:KeepParam(1, 1, CALCULATE_ADD)
	end
end

-- 時間経過HP回復
