local val
local total = Buff:GetKeptParam(2) or 0
	val = math.min(round(target:Status(params[3]) * params[4] * Per2Num), params[2] - total, target:MaxHP() - target:HP(), 9999)
	if val > 0 then
		if Buff:Parent():HealPct(target, val, 0) and params[5] ~= 0 then
			Process:PlayTimeline(params[5])
		end
		total = total + val
		if total >= params[2] then Buff:Expire() end
		Buff:KeepParam(2, val, CALCULATE_ADD)
	end
end

-- 薄っぺらな言葉
-- params[1]:SCT増減値
-- params[2]:SCT増減倍率
-- params[3]:SCT増減倍率(1ストック)
function buff20200(_target, params)
local add = 0
	Field:FrameUpdate(_target)
	for i = 1, this:SkillCount(SKILL_SKILL) do
		add = math.ceil((params[3] / Pct100) * (this:SKL_Cost(SKILL_SKILL, i) / 1000))
		this:EditSingleSCT(TARGSTAT_REAL, params[1] + add, params[2], i)
	end
	Buff:Expire()
end

