		Process:PlayTimeline(5)
	end
end

-- 根性
-- params[1]:発生可能回数
function buff20600(_target, params)
Field:FrameUpdate(_target)
local cnt = Buff:GetKeptParam(1) or 0
	if params[1]>cnt then
		if this:SetEndure(TARGSTAT_WORK, 0, -1, LIFETYPE_TRANSIENT) then
			this:HealPct(this, 0, 1000)
			if params[1] > 0 and params[1] <= cnt + 1 then
				this:SetBuff(BuffIds.S_BuffControl, {-1, Buff:UID()})
			else
				Buff:KeepParam(1, 1, CALCULATE_ADD)
			end
		end
	else
		Buff:Expire()
	end
end

-- 回数制限付き対物理スキル中根性
-- params[1]:残りHP条件
-- params[2]:発生可能回数
function buff20601(_target, params)
Field:FrameUpdate(_target)
local suid = this:GetValue(UNIT_VALUE_SKILL_COMBO_ENDURE) or {}
local cnt = Buff:GetKeptParam(1) or 0
	if Bullet:SKL_Role(SKILL_ROLE_ATTACK) then
		suid = arrayRemove(suid, function(t,k,e) return Field:IsSkillActive(t[k]) end)
		if suid[1] ~= nil then
			if this:SetEndure(TARGSTAT_WORK, 0, -1, LIFETYPE_TRANSIENT) then
				Process:ShowPassive()
			end
		elseif (params[2] < 0 or cnt < params[2]) and Bullet:SKL_Type(SKILL_PHYSIC) and this:SetEndure(TARGSTAT_WORK, params[1], -1, LIFETYPE_TRANSIENT) then
			if params[2] >= 0 and cnt + 1 >= params[2] then this:SetBuff(BuffIds.S_SkillEndBuffControl, {-1, Bullet:SKL_PUID(), Buff:UID()}) end
			table.insert(suid, Bullet:SKL_PUID())
			this:SetValue(UNIT_VALUE_SKILL_COMBO_ENDURE, suid)
			Buff:KeepParam(1, 1, CALCULATE_ADD)
			Process:ShowPassive()
		elseif params[2] >= 0 and cnt >= params[2] then
			Buff:Expire()
		end
	end
end

-- 回数制限付き特技攻撃時指定確率HP吸収
-- params[1]:発動回数
-- params[2]:発生確率
-- params[3]:吸収率
-- params[4]:演出番号
function buff20701(_target, params)
Field:FrameUpdate(_target)
local cnt = Buff:GetKeptParam(1) or 0
local buid
	if params[1]>cnt then
		buid = this:SetBuff(BuffIds.P_TargetSkillPUIDDrain, {-1, params[2], TimeLine:SKL_PUID(), params[3], params[4]})
		if buid then
			this:SetBuff(BuffIds.S_SkillEndBuffControl, {-1, TimeLine:SKL_PUID(), buid})
			if params[1] > 0 and params[1] <= cnt + 1 then
				Buff:Expire()
			else
				Buff:KeepParam(1, 1, CALCULATE_ADD)
			end
		end
	end
end

