-- 竜魔人
-- params[1]:発動条件方向
-- params[2]:残りHP閾値
-- params[3]:効果最小時間(秒)
-- params[4]:効果最大時間(秒)
-- params[5]:STR加算最大値
-- params[6]:STR倍率最大値
function buff30010(_target, params)
Field:FrameUpdate(_target)
local coe
local HpOver,HpUnder = 1,0
local cnt = Buff:GetKeptParam(4) or 0
	if (params[1]==HpOver and this:PerHP() >= params[2]) or (params[1]==HpUnder and this:PerHP() < params[2]) then
		cnt = cnt + 1
		Buff:KeepParam(4, 1, CALCULATE_ADD)
	end
	coe = math.max(math.min((cnt - params[3]) / (params[4] - params[3]), 1), 0)
	if coe > 0 and this:EditSTR(TARGSTAT_REAL, round(params[5] * coe), round(params[6] * coe), 0, LIFETYPE_CONTINUOUS) then Process:ShowPassive() end
end

