-- 特定キャラ生存人数状況指定ステータス増減
-- params[1]:敵味方
-- params[2]:キャラタイプ条件
-- params[3]:効果最小人数
-- params[4]:効果最大人数
-- params[5]:ステータスタイプ
-- params[6]:ステータス加算最大値
-- params[7]:ステータス倍率最大値
function buff30013(_target, params)
local coe,cnt,buid
local beforeCoe, icoe
	Field:FrameUpdate(_target)
	beforeCoe = Buff:GetKeptParam(3) or 0
	buid = Buff:GetKeptParam(4) or 0
	if buid ~= 0 then this:ExpireBuff(buid) buid = 0 end
	cnt = #(units:GetCondUnitList(params[1], TARGET_COND_ALIVE, UNIT_COND_CHARA_TYPE, params[2]))
	coe = math.max(math.min((cnt - params[3]) / (params[4] - params[3]), 1), 0)
	icoe = math.floor(coe * Pct100)
	Buff:KeepParam(3, icoe)
	if coe > 0 then
		buid = this:SetBuff(BuffIds.P_TargetStatusEdit, {-1, params[5], round(params[6] * coe), round(params[7] * coe)})
		if buid then
			if beforeCoe ~= icoe then Process:ShowPassive() end
		else
			buid = 0
		end
	end
	Buff:KeepParam(4, buid)
end

