	cnt = #(units:GetCondUnitList(params[1], TARGET_COND_ALIVE, params[2] == 0 and UNIT_COND_NONE or UNIT_COND_CHARA_CATEGORY, params[2]))
	coe = math.max(math.min((cnt - params[3]) / (params[4] - params[3]), 1), 0)
	icoe = math.floor(coe * Pct100)
	Buff:KeepParam(3, icoe)
	if coe > 0 then
		buid = this:SetBuff(BuffIds.P_TargetStatusEdit, {-1, params[5], round(params[6] * coe), round(params[7] * coe)})
		if buid then
			if beforeCoe ~= icoe then Process:ShowPassive() end
		else
			buid = 0
		end
	end
	Buff:KeepParam(4, buid)
end

