-- 一定回数基本異常無効化
-- params[1]:回数制限
-- params[2]:演出レベル
function buff30607(_target, params)
Field:FrameUpdate(_target)
local cnt = Buff:GetKeptParam(1) or 0
	if AILMENT_POISON <= TrigProc:ProcParam(1) and TrigProc:ProcParam(1) <= AILMENT_SILENCE then
		TrigProc:EditProcFlag(PROC_FLAG_AILMENT_SUCCEEDED, false)
		cnt = cnt + 1
		if cnt >= params[1] then
			Process:PlayTimeline(7 + ((params[2] - 1) * 3))
			Buff:Expire()
		else
			Process:PlayTimeline(6 + ((params[2] - 1) * 3))
			Buff:KeepParam(1, cnt)
		end
	end
end

