function buff31001(_target, params)
	Field:FrameUpdate(_target)
	this:EditSpeed(params[1], params[2])
	this:EditSTR(TARGSTAT_REAL, params[3], params[4])
	this:EditDEF(TARGSTAT_REAL, params[5], params[6])
	this:EditINT(TARGSTAT_REAL, params[3], params[4])
	this:EditMND(TARGSTAT_REAL, params[5], params[6])
