-- params[5]:移動速度加算値
-- params[6]:移動速度倍率
-- params[7]:HP減少間隔
-- params[8]:HP減少倍率
function buff31004(_target, params)
	Field:FrameUpdate(_target)
	this:SetBuff(BuffIds.S_HaveBuffUidSkillDmgPer, {-1, Buff:UID(), params[1], params[2]})
	this:SetBuff(BuffIds.S_HaveBuffUidDmgLimitBreak, {-1, Buff:UID(), ELEMENT_UNMENTIONED, params[1], params[3], params[4]})
	this:SetBuff(BuffIds.S_HaveBuffUidDotDamage, {-1, Buff:UID(), params[7], 1, params[8], params[8]})
	this:SetBuff(BuffIds.S_EnemyKillBuffControl, {-1, Buff:UID()})
	this:EditSpeed(params[5], params[6])
end

