-- 被弾蓄積ソウル変換
-- params[1]:スキルID条件
-- params[2]:ダメージ倍率補正
-- params[3]:VITダメージ加算値
-- params[4]:VITダメージ倍率
function buff31403(_target, params)
local buid
	Field:FrameUpdate(_target)
	buid = this:SetBuff(BuffIds.P_TargetSkillPUIDDmgPer, {-1, TimeLine:SKL_PUID(), params[2]})
	if buid then
		this:SetBuff(BuffIds.S_SkillEndBuffControl, {-1, TimeLine:SKL_PUID(), buid})
		buid = this:SetBuff(BuffIds.P_TargetSkillPUIDBreakEdit, {-1, TimeLine:SKL_PUID(), params[3], params[4]})
		if buid then
			this:SetBuff(BuffIds.S_SkillEndBuffControl, {-1, TimeLine:SKL_PUID(), buid})
		end
		Buff:Expire()
	end
end

