-- 特定PUIDスキル指定確率異常付与
-- params[1]:スキルPUID
-- params[2]:発生確率
-- params[3]:状態異常種類
-- params[4]:状態異常継続時間補正値
-- params[5]:状態異常継続時間倍率
function buff40000(_target, params)
	Field:FrameUpdate(_target)
	if lottery(params[2]) then
		if params[4]==0 and params[5]==0 then
			Bullet:Target():SetAilment(params[3])
		else
			-- 状態異常継続時間の変動を可能にするため、外部プロセスからのみ渡せる継続時間補正パラメータを加味して計算する
			Bullet:Target():SetAilment(params[3], math.max(math.floor((AilmentLifeTimes[params[3]] + params[4]) * (1 + (params[5] * Per2Num))), 1))
		end
	end
end

-- P_指定回数気絶・ブレイク回復速度増減
-- params[1]:発動回数
-- params[2]:気絶・ブレイク回復速度倍率
function buff40600(_target, params)
Field:FrameUpdate(_target)
local cnt = Buff:GetKeptParam(1) or 0
	if this:IsBreak() then
		this:EditBreakTime(params[2])
		Buff:KeepParam(1, 1, CALCULATE_ADD)
	elseif params[1] > 0 and cnt >= params[1] then
		Buff:Expire()
	end
end

-- フィジカルシールド
-- params[1]:バフHP
-- params[2]:ダメージ倍率補正
function buff50200(_target, params)
Field:FrameUpdate(_target)
local dmg = Buff:GetKeptParam(1) or 0
	dmg = dmg + Bullet:Damage() - Bullet:EditDamagePer(params[2])
	if dmg >= params[1] then
		Process:PlayTimeline(6)
		Buff:Expire()
	else
		Process:PlayTimeline(7)
		Buff:KeepParam(1, dmg)
	end
end

