-- ランナーズハイ
-- params[1]:発動回数
-- params[2]:ダメージ倍率
-- params[3]:親ユニットUID
-- params[4]:親プロセスUID
-- params[5]:親プロセスID
function buff50218(_target, params)
Field:FrameUpdate(_target)
local u = units:GetUnit(params[3])
local cnt = Buff:GetKeptParam(1) or 0
local buid = this:SetBuff(BuffIds.P_TargetSkillPUIDDmgPer, {-1, TimeLine:SKL_PUID(), params[2]})
local pv
	if buid then
		pv = u:GetProcValue(Process:Affiliation(params[4]), Process:localID(params[4]), params[5]) or {}
		pv[1] = 0
		u:SetProcValue(pv, false, Process:Affiliation(params[4]), Process:localID(params[4]), params[5])
		this:SetBuff(BuffIds.S_SkillEndBuffControl, {-1, TimeLine:SKL_PUID(), buid})
		if params[1] > 0 and params[1] >= cnt + 1 then
			Buff:Expire()
		else
			Buff:KeepParam(1, 1, CALCULATE_ADD)
		end
	end
end

