-- 回数制限付き特技1・2与ダメージ増加
-- params[1]:発動回数
-- params[2]:ダメージ倍率
function buff50239(_target, params)
Field:FrameUpdate(_target)
local skl = TimeLine:ParentSkill()
local cnt = Buff:GetKeptParam(1) or 0
local buid
	if params[1]>cnt and skl ~= nil and (skl:IndexUI() == 1 or skl:IndexUI() == 2) then
		buid = this:SetBuff(BuffIds.P_TargetSkillPUIDDmgPer, {-1, TimeLine:SKL_PUID(), params[2]})
		if buid then
			this:SetBuff(BuffIds.S_SkillEndBuffControl, {-1, TimeLine:SKL_PUID(), buid})
			if params[1] > 0 and params[1] <= cnt + 1 then
				Buff:Expire()
			else
				Buff:KeepParam(1, 1, CALCULATE_ADD)
			end
		end
	end
end

