-- ドライビングハイ
-- params[1]:発動回数
-- params[2]:ダメージ倍率
-- params[3]:親ユニットUID
-- params[4]:親プロセスUID
-- params[5]:親プロセスID
function buff50311(_target, params)
Field:FrameUpdate(_target)
local u = units:GetUnit(params[3])
local cnt = Buff:GetKeptParam(1) or 0
local buid = this:SetBuff(BuffIds.P_TargetSkillPUIDDmgPer, {-1, TimeLine:SKL_PUID(), params[2]})
local pv
	if buid then
		pv = u:GetProcValue(Process:Affiliation(params[4]), Process:localID(params[4]), params[5]) or {}
		pv[1] = 0
		u:SetProcValue(pv, false, Process:Affiliation(params[4]), Process:localID(params[4]), params[5])
		this:SetBuff(BuffIds.S_SkillEndBuffControl, {-1, TimeLine:SKL_PUID(), buid})
		if params[1] > 0 and params[1] >= cnt + 1 then
			Buff:Expire()
		else
			Buff:KeepParam(1, 1, CALCULATE_ADD)
		end
	end
end

-- AS_リラハムル
-- params[1]:MP回復値
-- params[2]:コスト割合
-- params[3]:ダメージ上限加算値
-- params[4]:ダメージ上限倍率補正
-- params[5]:ダメージ倍率
function buff50312(_target, params)
local buid, buid2
local val, skl
	Field:FrameUpdate(_target)
	buid = this:SetBuff(BuffIds.P_TargetSkillPUIDDmgPer, {-1, TimeLine:SKL_PUID(), params[5]})
	buid2 = this:SetBuff(BuffIds.P_TargetSkillPUIDDamageLimit, {-1, TimeLine:SKL_PUID(), params[3], params[4]})
	if buid or buid2 then
		this:SetBuff(BuffIds.S_SkillEndBuffControl, {-1, TimeLine:SKL_PUID(), buid or buid2, (buid and buid2) or nil})
	end
	skl = TimeLine:ParentSkill()
	if skl then
		val = math.floor(skl:Cost() * params[2] * Per2Num) + params[1]
		this:SwitchSource(TARGSTAT_REAL)
		if val > 0 then this:HealMp(this, val, 0) end
	end
	Buff:Expire()
end

