-- 指定回数特定スキル発動時与ダメージ増減
-- params[1]:発動回数
-- params[2]:属性条件
-- params[3]:スキルタイプ条件
-- params[4]:ダメージ倍率
function buff50425(_target, params)
Field:FrameUpdate(_target)
local cnt = Buff:GetKeptParam(1) or 0
local buid
	if params[1]>cnt then
		buid = this:SetBuff(BuffIds.P_TargetSkillPUIDDmgPer, {-1, TimeLine:SKL_PUID(), params[4]})
		if buid then
			this:SetBuff(BuffIds.S_SkillEndBuffControl, {-1, TimeLine:SKL_PUID(), buid})
			Process:ShowPassive()
			if params[1] > 0 and params[1] >= cnt + 1 then
				Buff:Expire()
			else
				Buff:KeepParam(1, 1, CALCULATE_ADD)
			end
		end
	end
end

