-- デバフ無効(ユグドラシル専用)
function buff81000(_target, params)
	Field:FrameUpdate(_target)
	TrigProc:EditProb(0, -Pct100)
end

-- 一定回数死神無効
-- params[1]:制限回数
function buff81001(_target, params)
local cnt
	Field:FrameUpdate(_target)
	if TrigProc:Succeeded() then
		TrigProc:SetFailed()
		cnt = (Buff:GetKeptParam(1) or 0) + 1
		if params[1] > 0 and cnt >= params[1] then
			Buff:Expire()
		else
			Buff:KeepParam(1, cnt)
		end
	end
end

