-- 精霊力解放_炎
-- params[1]:属性変化するかどうか(1:True 0:False)
-- params[2]:与ダメージ倍率
-- params[3]:ダメージ上限増減値
-- params[4]:ダメージ上限増減倍率
-- params[5]:SCT自動回復加算値
-- params[6]:SCT自動回復倍率
-- params[7]:詠唱時間倍率
function buff81644(_target, params)
	Field:FrameUpdate(_target)
	if params[1] >= 1 then this:SetBuff(BuffIds.S_HaveBuffUidChangeSkillElem, {-1, Buff:UID(), SKILL_SKILL, ELEMENT_FIRE}) this:SetBuff(BuffIds.S_HaveBuffUidChangeSkillElem, {-1, Buff:UID(), SKILL_SPECIAL, ELEMENT_FIRE}) end
	this:SetBuff(BuffIds.S_HaveBuffUidElemDmgPer, {-1, Buff:UID(), ELEMENT_FIRE, params[2]})
	this:SetBuff(BuffIds.S_HaveBuffUidDmgLimitBreak, {-1, Buff:UID(), ELEMENT_FIRE, 0, params[3], params[4]})
	this:EditRecoverSCT(TARGSTAT_REAL, params[5], params[6])
	this:EditCastSpeed(params[7])
end

