-- AT_ガス
-- params[1]:ガス残り回数
-- params[2]:移動速度加算値
-- params[3]:移動速度倍率
-- params[4]:ダメージ倍率補正
function buff81666(_target, params)
local skl, buid1, buid2
	Field:FrameUpdate(_target)
	buid1 = this:SetBuff(BuffIds.P_SpdEdit, {-1, params[2], params[3]})
	skl = this:ActSkill()
	buid2 = this:SetBuff(BuffIds.P_TargetSkillDmgPerTrig, {-1, 1, ELEMENT_UNMENTIONED, SKILL_SKILL, params[4]})
	if buid1 or buid2 then
		this:SetBuff(BuffIds.S_ATGusControl, {-1, Buff:UID(), params[1], skl:Type(), skl:Index(), buid1, buid2})
		if params[1] > 1 then this:SetBuff(BuffIds.AT_Gus, {-1, params[1] - 1, params[2], params[3], params[4]}, nil, nil, nil, nil, BUFF_ICON_ID_AT_GUS[params[1] - 1]) end
	end
end

-- AT_スナップブレード
-- params[1]:破損確率
-- params[2]:破損内部スタック
function buff81667(_target, params)
local cnt
	Field:FrameUpdate(_target)
	cnt = Buff:GetKeptParam(1) or 0
	if lottery(params[1]) then
		cnt = cnt + 1
		if cnt >= params[2] then
			Buff:Expire()
		else
			Buff:KeepParam(1, cnt)
		end
	end
end

