local cnt
	Field:FrameUpdate(_target)
	cnt = Buff:GetKeptParam(1) or 0
	if cnt <= 0 then
		this:EditSTR(TARGSTAT_REAL, 0, params[1], 0)
		this:EditDEF(TARGSTAT_REAL, 0, params[1], 0)
		this:EditINT(TARGSTAT_REAL, 0, params[1], 0)
		this:EditMND(TARGSTAT_REAL, 0, params[1], 0)
		this:BreakSetting(1, 0, 4, 1, 1, 502501, 0)
		Buff:KeepParam(1, 1)
	elseif this:IsBoss() and this:IsBreak() then
		this:SetBuff(DebuffIds.Reform, {-1, params[2]})
		this:SetBuff(BuffIds.S_BuffControl, {-1, Buff:UID()})
	end
end

