-- 監獄
-- params[1]:ダメージ変換倍率
-- params[2]:最大HP加算最大値
-- params[3]:最大HP最大倍率
function buff81679(_target, params)
local  pv, max
	Field:FrameUpdate(_target)
	if not this:IsRemote() then
		pv = Buff:GetProcValue() or {}
		max = -math.floor(params[2] + this:PureMaxHP() * params[3] * Per2Num)
		if (pv[1] or 0) < max or pv[2] == nil or not Field:IsBuffExists(pv[2]) then
			if pv[2] ~= nil and Field:IsBuffExists(pv[2]) then Field:ExpireBuff(pv[2]) end
			if pv[3] ~= nil and Field:IsBuffExists(pv[3]) then Field:ExpireBuff(pv[3]) end
			pv[1] = math.min(math.floor((pv[1] or 0) + Bullet:Damage() * params[1] * Per2Num), max)
			pv[2] = this:SetBuff(BuffIds.P_MaxHpEdit, {-1, -(pv[1]), 0})
			pv[3] = this:SetBuff(BuffIds.S_UidBuffEndBuffControl, {-1, Buff:UID(), pv[2]})
			Buff:SetProcValue(pv)
		end
	end
end

