-- 魔導結界
-- params[1]:ダメージ軽減量タイプ(固定/割合)
-- params[2]:ダメージ軽減量MIN
-- params[3]:ダメージ軽減量MAX
function buff81683(_target, params)
local Type_Fixed, Type_PureMND, Type_MND = 0, 1, 2
local val
	Field:FrameUpdate(_target)
	if params[1] == Type_Fixed then
		val = round(math.random(params[2], params[3]))
	elseif params[1] == Type_PureMND then
		val = round(this:PureMND() * math.random(params[2], params[3]) * Per2Num)
	elseif params[1] == Type_MND then
		val = round(this:MND() * math.random(params[2], params[3]) * Per2Num)
	end
	if val > 0 and Bullet:EditDamage(math.max(Bullet:Damage() - val, 1)) then Process:PlayTimeline(2) end
end

-- 神剣
-- params[1]:発動回数
-- params[2]:ダメージ倍率
-- params[3]:ダメージ上限加算値
-- params[4]:ダメージ上限倍率補正
function buff81684(_target, params)
Field:FrameUpdate(_target)
local cnt = Buff:GetKeptParam(1) or 0
local buid
	if params[1] < 0 or params[1] > cnt then
		buid = this:SetBuff(BuffIds.P_TargetSkillPUIDDmgPer, {-1, TimeLine:SKL_PUID(), params[2]})
		if buid then
			this:SetBuff(BuffIds.S_SkillEndBuffControl, {-1, TimeLine:SKL_PUID(), buid})
			buid = this:SetBuff(BuffIds.P_TargetSkillPUIDDamageLimit, {-1, TimeLine:SKL_PUID(), params[3], params[4]})
			if buid then this:SetBuff(BuffIds.S_SkillEndBuffControl, {-1, TimeLine:SKL_PUID(), buid}) end
			if params[1] > 0 and params[1] <= cnt + 1 then
				Buff:Expire()
			else
				Buff:KeepParam(1, 1, CALCULATE_ADD)
			end
		end
	end
end

