-- TS_魔素
-- params[1]:魔素カウント
-- params[2]:特技強化発生確率
-- params[3]:特技ダメージ倍率補正
-- params[4]:特技ダメージ上限増減値
-- params[5]:特技ダメージ上限増減倍率
-- params[6]:超必殺技ダメージ倍率補正
-- params[7]:超必殺技ダメージ上限増減値
-- params[8]:超必殺技ダメージ上限増減倍率
function buff81721(_target, params)
local skl, buid, buid2
	Field:FrameUpdate(_target)
	skl = TimeLine:ParentSkill()
	if skl then
		if skl:Type(SKILL_SPECIAL) then
			buid = this:SetBuff(BuffIds.P_TargetSkillPUIDDmgPer, {-1, TimeLine:SKL_PUID(), params[6]})
			buid2 = this:SetBuff(BuffIds.P_TargetSkillPUIDDamageLimit, {-1, TimeLine:SKL_PUID(), params[7], params[8]})
			if buid or buid2 then this:SetBuff(BuffIds.S_SkillEndBuffControl, {-1, TimeLine:SKL_PUID(), buid or buid2, (buid and buid2) or nil}) Process:ShowPassive() end
			Buff:Expire()
			return
		elseif skl:Type(SKILL_SKILL) and lottery(params[2]) then
			buid = this:SetBuff(BuffIds.P_TargetSkillPUIDDmgPer, {-1, TimeLine:SKL_PUID(), params[3]})
			buid2 = this:SetBuff(BuffIds.P_TargetSkillPUIDDamageLimit, {-1, TimeLine:SKL_PUID(), params[4], params[5]})
			if buid or buid2 then this:SetBuff(BuffIds.S_SkillEndBuffControl, {-1, TimeLine:SKL_PUID(), buid or buid2, (buid and buid2) or nil}) Process:ShowPassive() end
			if params[1] <= 1 then Buff:Expire() else if this:SetBuff(BuffIds.TS_Magicules, {Buff:Remain(), params[1] - 1, params[2], params[3], params[4], params[5], params[6], params[7], params[8]}, nil, nil, nil, nil, BUFF_ICON_ID_TS_MAGICULES[params[1] - 1]) then Process:PlayTimeline(5) end end
			return
		end
	end
	Process:SetFailed()
end

