-- 魔術理論体系
-- params[1]:ステータス加算値
-- params[2]:ステータス倍率
-- params[3]:4属性ダメージ倍率補正
-- params[4]:移動速度加算値
function buff81738(_target, params)
local compareFunc, stat
	Field:FrameUpdate(_target)
	compareFunc = newCompare2(COMPARE_ORMORE)
	compareFunc(STATUS_TYPE_STR, this:STR())
	compareFunc(STATUS_TYPE_DEF, this:DEF())
	compareFunc(STATUS_TYPE_INT, this:INT())
	stat = compareFunc(STATUS_TYPE_MND, this:MND())
	stat = stat[math.random(1,#stat)]
	this:EditStatus(stat, TARGSTAT_REAL, params[1], params[2])
	this:EditSpeed(params[4])
	this:SetBuff(BuffIds.S_HaveBuffUidSufferMultiElemSkillDmgPer, {-1, Buff:UID(), ELEMENT_FIRE, ELEMENT_ICE, ELEMENT_TREE, ELEMENT_THUNDER, ELEMENT_THUNDER, ELEMENT_THUNDER, 0, params[3]})
end

