-- OVERLORD
-- params[1]:ダメージ倍率
-- params[2]:ダメージ上限加算値
-- params[3]:ダメージ上限倍率補正
function buff81742(_target, params)
local skl, buid1, buid2
	Field:FrameUpdate(_target)
	skl = TimeLine:ParentSkill()
	if skl:Type(SKILL_MAGIC) and skl:Kind() ~= SKILL_KIND_TIER then Process:SetFailed() return end
	buid1 = this:SetBuff(BuffIds.P_TargetSkillPUIDDmgPer, {-1, TimeLine:SKL_PUID(), params[1]})
	buid2 = this:SetBuff(BuffIds.P_TargetSkillPUIDDamageLimit, {-1, TimeLine:SKL_PUID(), params[2], params[3]})
	if buid1 or buid2 then
		this:SetBuff(BuffIds.S_SkillEndBuffControl, {-1, TimeLine:SKL_PUID(), buid1, buid2})
		Buff:Expire()
	end
end

