function buff81756(_target, params)
local t, buid
	Field:FrameUpdate(_target)
	t = {}
	buid = this:SetBuff(BuffIds.P_TargetSkillPUIDDmgPer, {-1, TimeLine:SKL_PUID(), params[1]})
	if buid then table.insert(t, buid) end
	buid = this:SetBuff(BuffIds.P_TargetSkillPUIDDamageLimit, {-1, TimeLine:SKL_PUID(), params[2], 0})
	if buid then table.insert(t, buid) end
	buid = this:SetBuff(BuffIds.P_TargetSkillPUIDFatalBlowEdit, {-1, TimeLine:SKL_PUID(), params[3], params[4]})
	if buid then table.insert(t, buid) end
	if t[1] ~= nil then this:SetBuff(BuffIds.S_SkillEndBuffControl, {-1, TimeLine:SKL_PUID(), table.unpack(t)}) end
	TimeLine:SKL_SetValue(50211011, 1, 0)
	Buff:Expire()
end

