-- 死亡確定時外部スキル発動
-- params[1]:クエストを通じての制限回数
-- params[2]:スキルID
function buff82102(_target, params)
local puid, stat
local buid, cnt
	Field:FrameUpdate(_target)
	puid, stat = this:SKL_PlayDirect(params[2], Bullet:Parent(), PLAYSKILL_MODE_FORCE_GODMODE, PLAYSKILL_OPTION_IGNORECOST, 0, PLAYSKILL_MOVE_DIRECT)
	if stat == PLAYSKILL_STAT_PLAY then
		Field:PendJudge(3, PEND_JUDGE_TYPE_OWNER, PEND_JUDGE_MODE_FIRST)
		Process:ShowPassive()
		cnt = (Buff:GetKeptParam(1) or 0) + 1
		if params[1] > 0 and params[1] <= cnt then
			Buff:Expire()
		else
			Buff:KeepParam(1, cnt)
		end
	elseif stat == PLAYSKILL_STAT_RESERVE then
		Field:PendJudge(3, PEND_JUDGE_TYPE_OWNER, PEND_JUDGE_MODE_FIRST)
		buid = this:SetBuff(BuffIds.S_SkillPuidShowPassive, {-1, puid})
		if buid then
			this:SetBuff(BuffIds.S_NotSkillPuidBuffControl, {-1, puid, buid})
		end
		cnt = (Buff:GetKeptParam(1) or 0) + 1
		if params[1] > 0 and params[1] <= cnt then
			Buff:Expire()
		else
			Buff:KeepParam(1, cnt)
		end
	end
end

