		cnt = (Buff:GetKeptParam(1) or 0) + 1
		if params[4] > 0 and params[4] <= cnt then
			Buff:Expire()
		else
			Buff:KeepParam(1, cnt)
		end
	end
end

-- 味方複数条件スキル発動時外部スキル発動
-- params[1]:スキル規模条件
-- params[2]:スキルロール条件
-- params[3]:スキル属性条件
-- params[4]:スキルタイプ条件
-- params[5]:スキル種別条件
-- params[6]:スキル重複可否条件
-- params[7]:発生確率
-- params[8]:クールタイム
-- params[9]:スキルID
function buff82104(_target, params)
local puid, stat
	Field:FrameUpdate(_target)
	local cnt, b4cnt = this:Time(), Buff:GetKeptParam(1)
	if b4cnt == nil or cnt - b4cnt >= params[8] then
		local skl = TimeLine:ParentSkill()
		if skl and (params[1] == 0 or skl:Scale() == params[1]) and (params[5] == -1 or skl:Kind() == params[5]) and (params[6] == -1 or skl:MultiCast() == params[6]) then
			if lottery(params[7]) then
				puid, stat = this:SKL_PlayDirect(params[9], TimeLine:Target(), PLAYSKILL_MODE_FORCE_NONSTATE, PLAYSKILL_OPTION_IGNORECOST, 0, PLAYSKILL_MOVE_DIRECT)
				Process:ShowPassive()
				Buff:KeepParam(1, cnt)
				return
			end
		end
	end
	Process:SetFailed()
end

