-- 指定回数与ダメージ固定
-- params[1]:制限回数
-- params[2]:ダメージタイプ(固定/割合)
-- params[3]:ダメージMIN
-- params[4]:ダメージMAX
function buff82400(_target, params)
local dType_Fixed, dType_MaxHp, dType_NowHp = 0, 1, 2
local cnt, val, t
	Field:FrameUpdate(_target)
	t = Bullet:Target()
	if params[3] > params[4] then params[4] = params[3] end
	if params[2] == dType_Fixed then
		val = round(math.random(params[3], params[4]))
	elseif params[2] == dType_MaxHp then
		val = round(t:MaxHP() * math.random(params[3], params[4]) * Per2Num)
	elseif params[2] == dType_NowHp then
		val = round(t:HP() * math.random(params[3], params[4]) * Per2Num)
	end
	if Bullet:EditDamage(val) then
		Process:ShowPassive()
		cnt = (Buff:GetKeptParam(1) or 0) + 1
		if params[1]>0 and params[1]<=cnt then
			Buff:Expire()
		else
			Process:KeepParam(1, cnt)
		end
	end
end

