	Bullet:EditDamageLimit(params[2], params[3])
end

-- 親pv1値状況特定スキルダメージ上限増減
-- params[1]:属性条件
-- params[2]:スキルタイプ条件
-- params[3]:効果pv値
-- params[4]:効果最大pv値
-- params[5]:ダメージ上限加算最大値
-- params[6]:ダメージ上限倍率最大補正
function buff82614(_target, params)
Field:FrameUpdate(_target)
local t = this:GetProcValue(Process:Affiliation(Process:UID(true)), Process:localID(Process:UID(true)), Process:Index(true)) or {}
local coe = math.max(math.min(((t[1] or 0) - params[3]) / (params[4] - params[3]), 1), 0)
	if coe > 0 then Bullet:EditDamageLimit(round(params[5] * coe), round(params[6] * coe)) end
end

-- P_発動数制限付き特定スキル与ダメージ増加
-- params[1]:発動回数
-- params[2]:属性条件
-- params[3]:スキルタイプ条件
-- params[4]:ダメージ上限加算値
-- params[5]:ダメージ上限倍率補正
function buff82615(_target, params)
local cnt
	Field:FrameUpdate(_target)
	cnt = (Buff:GetKeptParam(1) or 0) + 1
	if params[1] >= 0 and cnt > params[1] then
		Buff:Expire()
	else
		Bullet:EditDamageLimit(params[4], params[5])
		Buff:KeepParam(1, cnt)
	end
end

