-- 指定回数特定スキル発動時ダメージ上限増減
-- params[1]:発動回数
-- params[2]:属性条件
-- params[3]:スキルタイプ条件
-- params[4]:ダメージ上限加算値
-- params[5]:ダメージ上限倍率補正
function buff82619(_target, params)
Field:FrameUpdate(_target)
local cnt = Buff:GetKeptParam(1) or 0
local buid
	if params[1]>cnt then
		buid = this:SetBuff(BuffIds.P_TargetSkillPUIDDamageLimit, {-1, TimeLine:SKL_PUID(), params[4], params[5]})
		if buid then
			this:SetBuff(BuffIds.S_SkillEndBuffControl, {-1, TimeLine:SKL_PUID(), buid})
			if params[1] > 0 and params[1] >= cnt + 1 then
				Buff:Expire()
			else
				Buff:KeepParam(1, 1, CALCULATE_ADD)
			end
		end
	end
end

-- 回数制限付き特技ダメージ上限増減
-- params[1]:発動回数
-- params[2]:ダメージ上限加算値
-- params[3]:ダメージ上限倍率補正
function buff82620(_target, params)
Field:FrameUpdate(_target)
local cnt = Buff:GetKeptParam(1) or 0
local buid
	if params[1]>cnt then
		buid = this:SetBuff(BuffIds.P_TargetSkillPUIDDamageLimit, {-1, TimeLine:SKL_PUID(), params[2], params[3]})
		if buid then
