-- 与ダメージ時ランクポイント増減
-- params[1]:ランクID
-- params[2]:ポイントID
-- params[3]:ポイント加算基本値
-- params[4]:5HIT毎係数加算値
-- params[5]:空中ヒット係数
-- params[6]:ブレイク時係数
function buff1000004(_target, params)
local rank, coe, u
	Field:FrameUpdate(_target)
	coe = ((((Bullet:Target():Hits() // 5) * params[4]) + Pct100) * Per2Num)
	if Bullet:Target():PosY() > 0 then coe = coe * ((params[5] + Pct100) * Per2Num) end
	u = Field:GetBoss()
	if u and u:IsBreak() then coe = coe * ((params[6] + Pct100) * Per2Num) end
	rank = Field:GetRank(params[1], params[2])
	rank:AddPoint(params[3] * coe, false)
end

-- 特技発動時ランクポイント増減
-- params[1]:ランクID
-- params[2]:ポイントID
-- params[3]:クールタイム
-- params[4]:ポイント加算基本値
-- params[5]:ボーナスクールタイム
function buff1000005(_target, params)
local bonusPoint = 12
local roleCoe = {}
local scaleCoe = {}
local costSep = 5
local costCoe = 1000
local tbl, rank, skl
local coe = 0
	Field:FrameUpdate(_target)
	skl = TimeLine:ParentSkill()
	if skl ~= nil then
		tbl = Buff:GetProcValue() or {{}, {}, 0}
		if tbl[3] ~= skl:ID() and skl:Type(SKILL_SKILL) then
			rank = Field:GetRank(params[1], params[2])
			if tbl[1][skl:ID()] == nil or Field:Time() - tbl[1][skl:ID()] > params[3] then
				rank:AddPoint(params[4], false)
				tbl[1][skl:ID()] = Field:Time()
			end
			if bonusPoint > 0 and (tbl[2][skl:ID()] == nil or Field:Time() - tbl[2][skl:ID()] > params[5]) then
				for i,j in pairs(roleCoe) do
					if skl:Role(i) then coe = coe + j end
				end
				coe = coe + (scaleCoe[skl:Scale()] or 0)
				coe = coe + (((skl:Cost() / 1000) // costSep) * costCoe)
				coe = (coe + Pct100) * Per2Num
				rank:AddPoint(bonusPoint * coe, true)
				tbl[2][skl:ID()] = Field:Time()
			end
		end
		tbl[3] = skl:ID()
		Buff:SetProcValue(tbl)
	end
end

