--ブレイク発生時ランクポイント増減_制御
-- params[1]:ランクID
-- params[2]:ポイントID
-- params[3]:ポイント加算値
function buff1000014(_target, params)
local tbl
	Field:FrameUpdate(_target)
	if not this:IsRemote() then
		tbl = Field:GetValue(UNIT_VALUE_BUFF_1000014_LIST)
		if tbl == nil then
			tbl = {}
			ulist = units:GetCondUnitList(TARGET_SIDE_OPPONENT, TARGET_COND_BOTH, UNIT_COND_NONE)
		else
			ulist = Process:TrigUnits()
		end
		for i,u in pairs(ulist) do
			if u:RelativeSide(this)==TARGET_SIDE_OPPONENT and not toBoolean(tbl[u:ID()]) then
				if u:SetBuff(BuffIds.S_DMC_BossBreakRankPointProc, {-1, params[1], params[2], params[3]}) then
					tbl[u:ID()] = true
				end
			end
		end
		Field:SetValue(UNIT_VALUE_BUFF_1000014_LIST, tbl)
	end
end

