-- SNリング配置管理用
-- params[1]:スキルID
function buff1000018(_target, params)
local isFirst, cnt
local oMst, lMst, pMst, oid
local v, n, r
local puid
local x, z, minX, minZ, maxX, maxZ
	Field:FrameUpdate(_target)
	isFirst = not toBoolean(Buff:GetProcValue())
	oid = Field:OrnamentManageID()
	if oid ~= 0 then
		Buff:SetProcValue(true)
		oMst = Field:GetOrnamentManageMstInfo(oid)
		cnt = math.random(isFirst and oMst[ORNAMENT_MNG_MST_INFO_FIRST_POP_TRY_MIN] or oMst[ORNAMENT_MNG_MST_INFO_REPOP_TRY_MIN], isFirst and oMst[ORNAMENT_MNG_MST_INFO_FIRST_POP_TRY_MAX] or oMst[ORNAMENT_MNG_MST_INFO_REPOP_TRY_MAX])
		lMst = Field:GetOrnamentPosLotteryMstInfo(oMst[ORNAMENT_MNG_MST_INFO_ORNAMENT_POS_LOTTERY_ID])
		lMst = lMst[ORNAMENT_POS_LOTTERY_MST_INFO_RATE_INFO]
		for v = 1, cnt do
			r = math.random(1, lMst[ORNAMENT_POS_LOTTERY_MST_INFO_RATE_INFO_RATE_SUM])
			n = 0
			for i,rInfo in ipairs(lMst[ORNAMENT_POS_LOTTERY_MST_INFO_RATE_INFO_RATE]) do
				n = n + rInfo
				if r <= n then
					pMst = Field:GetBattlePosMstInfo(lMst[ORNAMENT_POS_LOTTERY_MST_INFO_RATE_INFO_POS_ID][i])
					minX, minZ, maxX, maxZ = 0, 0 ,0 ,0
					for j,pInfo in pairs(pMst[BATTLE_POS_MST_INFO_POSITION_LIST]) do
						minX, minZ, maxX, maxZ = math.min(minX, pInfo.X), math.min(minZ, pInfo.Z), math.max(maxX, pInfo.X), math.max(maxZ, pInfo.Z)
					end
					x, z = Field:GetRandomPos(-minX, -minZ, -maxX, -maxZ)
					for j,pInfo in pairs(pMst[BATTLE_POS_MST_INFO_POSITION_LIST]) do
						puid = this:SKL_PlayDirect(params[1], this, PLAYSKILL_MODE_FORCE_GODMODE, PLAYSKILL_OPTION_IGNORECOST, 0, PLAYSKILL_MOVE_DIRECT)
						this:SetValue({UNIT_VALUE_ORNAMENT_INFO, puid}, {pInfo.X + x, pInfo.Y, pInfo.Z + z})
					end
					break
				end
			end
		end
	end
end

-- SNリング効果管理用
-- params[1]:効果最小リング数
-- params[2]:効果最大リング数
-- params[3]:移動速度加算最大値
-- params[4]:ダメージ倍率最大補正
function buff1000019(_target, params)
Field:FrameUpdate(_target)
local coe
local buid = this:GetProcValue(Process:Affiliation(Process:UID(true)), Process:localID(Process:UID(true)), Process:Index(true)) or {}
	if buid[1] ~= nil and Field:IsBuffExists(buid[1]) then Field:ExpireBuff(buid[1]) end
	if buid[2] ~= nil and Field:IsBuffExists(buid[2]) then Field:ExpireBuff(buid[2]) end
	coe = calcCoe(Field:GetScore(BATTLE_SCORE_SN_RING):Get() or 0, params[1], params[2])
	if coe > 0 then
		buid[1] = this:SetBuff(BuffIds.WP_ElementSkillSufferDamagePer, {-1, ELEMENT_UNMENTIONED, 0, round(params[4] * coe)})
		buid[2] = this:SetBuff(BuffIds.WP_SpdEdit, {-1, round(params[3] * coe)})
		if buid[1] or buid[2] then this:SetProcValue(buid, true, Process:Affiliation(Process:UID(true)), Process:localID(Process:UID(true)), Process:Index(true)) end
	end
end

-- 援護効果管理用
-- params[1]:援護ID
function buff1000020(_target, params)
Field:FrameUpdate(_target)
local buid, buids
local valid = {}
local info = this:GetProcValue(Process:Affiliation(Process:UID(true)), Process:localID(Process:UID(true)), Process:Index(true)) or {}
local tbl = this:GetSupportPassiveInfo(params[1]) or {}
	Field:SetValue({FIELD_VALUE_SUPPORT_PASSIVE_INFO, this:Side(), 'Enable'}, true)
	for i,t in pairs(tbl) do
		if tableGetValue(info, {t[1], t[2]}) then
			tableSetValue(valid, {t[1], t[2]}, true)
		else
			buids = {}
			for j,bff in pairs(t[3]) do
				buid = this:SetBuff(bff.ID, bff.Params)
				if buid then table.insert(buids, buid) end
			end
			if #buids > 0 then tableSetValue(valid, {t[1], t[2]}, true) tableSetValue(info, {t[1], t[2]}, buids) end
		end
	end
	for i,c in pairs(info) do
		for j,l in pairs(c) do
			if not tableGetValue(valid, {i, j}) then
				for k,bff in pairs(l) do
					this:ExpireBuff(bff)
				end
				info[i][j] = nil
			end
		end
	end
	this:SetProcValue(info, false, Process:Affiliation(Process:UID(true)), Process:localID(Process:UID(true)), Process:Index(true))
end

