-- 羅刹の構え【蒼】_制御用
-- params[1]:対象 最大HP/現在HP
-- params[2]:ダメージ割合(MIN)
-- params[3]:ダメージ割合(MAX)
function buff1011102(_target, params)
local dType_Fixed, dType_MaxHp, dType_NowHp = 0, 1, 2
local val
	Field:FrameUpdate(_target)
	if target:IsBuff(BuffIds.StyleBlue) then
		if target:HP() > 1 then
			if params[2] > params[3] then params[3] = params[2] end
			if params[1] == dType_Fixed then
				val = round(math.random(params[2], params[3]))
			elseif params[1] == dType_MaxHp then
				val = round(target:MaxHP() * math.random(params[2], params[3]) * Per2Num)
			elseif params[1] == dType_NowHp then
				val = round(target:HP() * math.random(params[2], params[3]) * Per2Num)
			end
			Buff:DotDamage(target, math.min(val, target:HP() - 1))
		end
	else
		Buff:Expire()
	end
end

