-- 特定UIDバフ効果中DOTダメージ
-- params[1]:バフUID
-- params[2]:ダメージ間隔(秒)
-- params[3]:ダメージタイプ(固定/割合)
-- params[4]:ダメージMIN
-- params[5]:ダメージMAX
-- params[6]:この効果によって死亡するか
function buff1011105(_target, params)
Field:FrameUpdate(_target)
local dType_Fixed, dType_MaxHp, dType_NowHp = 0, 1, 2
local dCnt = Buff:GetKeptParam(1) or 0
local val

	if not Field:IsBuffExists(params[1]) then
		Buff:Expire()
	else
		if params[4] > params[5] then params[5] = params[4] end
		if params[2] > 0 and params[2] <= dCnt then
			if params[3] == dType_Fixed then
				val = round(math.random(params[4], params[5]))
			elseif params[3] == dType_MaxHp then
				val = round(target:MaxHP() * math.random(params[4], params[5]) * Per2Num)
			elseif params[3] == dType_NowHp then
				val = round(target:HP() * math.random(params[4], params[5]) * Per2Num)
			end
			target:DotDamage(val, params[6]~=0)
			Buff:KeepParam(1, 1)
		else
			Buff:KeepParam(1, 1, CALCULATE_ADD)
		end
	end
end

