-- S_シリーズ効果応急処置
-- params[1]:シリーズID条件
-- params[2]:条件方向
-- params[3]:シリーズ装備数閾値
-- params[4]:特技INDEX
-- params[5]:回復値
-- params[6]:回復倍率
-- params[7]:回復倍率(1ストック)
-- params[8]:回復値(ストック補完)
function buff1020200(_target, params)
local Over,Under = 1,0
local u
local skl
local add = 0
local res = false
	Field:FrameUpdate(_target)
	u = Buff:Target()
	if (params[2]==Over and u:GetSeriesCount(params[1]) >= params[3]) or (params[2]==Under and u:GetSeriesCount(params[1]) < params[3]) then
		if params[4] > 0 then
			skl = u:GetSkillFromIndexUI(params[4])
			if skl~= nil then
				add = math.ceil((params[7] / Pct100) * (skl:Cost() / 1000) + math.max((params[8] - (skl:Charge() * 1000) / skl:Cost()) * (skl:Cost() / 1000), 0))
				if u:EditSingleSCT(TARGSTAT_REAL, params[5] + add, params[6], skl:Index()) then Process:ShowPassive() end
			end
		elseif params[4] == 0 then
			for i = 1, u:SkillCount(SKILL_SKILL) do
				add = math.ceil((params[7] / Pct100) * (u:SKL_Cost(SKILL_SKILL, i) / 1000) + math.max((params[8] - (u:SKL_Charge(SKILL_SKILL, i) * 1000) / u:SKL_Cost(SKILL_SKILL, i)) * (u:SKL_Cost(SKILL_SKILL, i) / 1000), 0))
				res = u:EditSingleSCT(TARGSTAT_REAL, params[5] + add, params[6], i) or res
			end
			if res then Process:ShowPassive() end
		elseif params[4] == -1 then
			skl = u:GetSkill(SKILL_SKILL, math.random(1, u:SkillCount(SKILL_SKILL)))
			if skl~= nil then
				add = math.ceil((params[7] / Pct100) * (skl:Cost() / 1000) + math.max((params[8] - (skl:Charge() * 1000) / skl:Cost()) * (skl:Cost() / 1000), 0))
				if u:EditSingleSCT(TARGSTAT_REAL, params[5] + add, params[6], skl:Index()) then Process:ShowPassive() end
			end
		end
	end
	Buff:Expire()
end

-- 対象ブレイク時単独SCT回復
-- params[1]:制限回数
-- params[2]:特技INDEX
-- params[3]:回復値
-- params[4]:回復倍率
-- params[5]:回復倍率(1ストック)
-- params[6]:回復値(ストック補完)
function buff1020201(_target, params)
Field:FrameUpdate(_target)
local skl
local u = Buff:Target()
local add = 0
local res = false
local cnt = (Buff:GetKeptParam(1) or 0) + 1
	if params[2] == 0 then
		for i = 1, u:SkillCount(SKILL_SKILL) do
			add = math.ceil((params[5] / Pct100) * (u:SKL_Cost(SKILL_SKILL, i) / 1000) + math.max((params[6] - (u:SKL_Charge(SKILL_SKILL, i) * 1000) / u:SKL_Cost(SKILL_SKILL, i)) * (u:SKL_Cost(SKILL_SKILL, i) / 1000), 0))
			res = u:EditSingleSCT(TARGSTAT_REAL, params[3] + add, params[4], i) or res
		end
		if res then Process:ShowPassive() end
	else
		if params[2] > 0 then
			skl = u:GetSkillFromIndexUI(params[2])
		elseif params[2] == -1 then
			skl = u:GetSkill(SKILL_SKILL, math.random(1, u:SkillCount(SKILL_SKILL)))
		end
		if skl~= nil then
			add = math.ceil((params[5] / Pct100) * (skl:Cost() / 1000) + math.max((params[6] - (skl:Charge() * 1000) / skl:Cost()) * (skl:Cost() / 1000), 0))
			if u:EditSingleSCT(TARGSTAT_REAL, params[3] + add, params[4], skl:Index()) then Process:ShowPassive() end
		end
	end
	if params[1] > 0 and cnt >= params[1] then
		Buff:Expire()
	else
		Buff:KeepParam(1, cnt)
	end
end

-- 味方ステータス増減根性_制御用
-- params[1]:発生可能回数
-- params[2]:回復最低値
-- params[3]:回復倍率
-- params[4]:継続時間
-- params[5]:STR倍率
-- params[6]:DEF倍率
-- params[7]:INT倍率
-- params[8]:MND倍率
-- params[9]:演出レベル
function buff1020601(_target, params)
Field:FrameUpdate(_target)
local buid
-- t = 1:count 2:unitList 3:buidList 4:isEnd
local t = Buff:Parent():GetProcValue(Process:Affiliation(Process:UID(true)), Process:localID(Process:UID(true)), Process:Index(true)) or {0, {}, {}, false}
	-- 効果発揮直後にバフを削除すると、効果まで一緒に消えてしまう件の応急処置
	if t[4] then
		Buff:Expire()
	elseif Buff:Parent():Alive() and this:SetEndure(TARGSTAT_WORK, 0, -1, LIFETYPE_TRANSIENT) then
		t[1] = (t[1] or 0) + 1
		Buff:Parent():SubProc(1, this, Pct100, {params[2], params[3]})
		Buff:Parent():SubProc(2, this, Pct100, {params[4], 0, params[5], params[9]})
		Buff:Parent():SubProc(3, this, Pct100, {params[4], 0, params[6], params[9]})
		Buff:Parent():SubProc(4, this, Pct100, {params[4], 0, params[7], params[9]})
		Buff:Parent():SubProc(5, this, Pct100, {params[4], 0, params[8], params[9]})
		Process:ShowPassive(Buff:Parent())
		if params[1] > 0 and t[1] >= params[1] then
			t[4] = true
			for i,buffUid in pairs(t[3]) do
				if buffUid ~= Buff:UID() then
					Field:ExpireBuff(buffUid)
				end
			end
		end
		Buff:Parent():SetProcValue(t, false, Process:Affiliation(Process:UID(true)), Process:localID(Process:UID(true)), Process:Index(true))
	end
end

