-- params[9]:MND倍率
function buff1030103(_target, params)
-- pv = 1:defEdit 2:buid 3:isEnd
local pv
	Field:FrameUpdate(_target)
	if lottery(params[3]) then
		pv = this:GetProcValue(Process:Affiliation(Process:UID(true)), Process:localID(Process:UID(true)), Process:Index(true)) or {}
		if not toBoolean(pv[3]) then
			pv[1] = math.max((pv[1] or 0) + params[4], 0)
			if pv[2] and Field:IsBuffExists(pv[2]) then
				this:ExpireBuff(pv[2])
			end
			if pv[1] == 0 then
				if params[6] ~= 0 then Process:SubProc(1, this, Pct100, {params[5], 0, params[6], 1}) end
				if params[7] ~= 0 then Process:SubProc(2, this, Pct100, {params[5], 0, params[7], 1}) end
				if params[8] ~= 0 then Process:SubProc(3, this, Pct100, {params[5], 0, params[8], 1}) end
				if params[9] ~= 0 then Process:SubProc(4, this, Pct100, {params[5], 0, params[9], 1}) end
				pv[3] = true
				Process:ShowPassive()
			else
				pv[2] = this:SetBuff(BuffIds.P_DefEdit, {-1, 0, pv[1]})
			end
			this:SetProcValue(pv, false, Process:Affiliation(Process:UID(true)), Process:localID(Process:UID(true)), Process:Index(true))
		end
	end
end

