-- 瀕死時、親に鬼化バフを付与
-- params[1]:条件閾値方向
-- params[2]:条件HP閾値
-- params[3]:発動回数
-- params[4]:発生確率
-- params[5]:継続時間
-- params[6]:HP加算値
-- params[7]:HP倍率
-- params[8]:HP回復値
-- params[9]:SCT増減倍率(1ストック)
function buff1030500(_target, params)
Field:FrameUpdate(_target)
local u = Buff:Parent()
local pv = u:GetProcValue(Process:Affiliation(Process:UID(true)), Process:localID(Process:UID(true)), Process:Index(true)) or {}
local cnt = pv[1] or 0
	if not u:IsBuffCategory(BUFF_CATEGORY_DEMONIZATION) then
		if (params[3] <= 0 or cnt < params[3]) then
			if lottery(params[4]) then
				if u:SubProc(1, u, Pct100, {params[5], params[6], params[7], 1}) then
					u:SubProc(2, u, Pct100, {params[8], 0})
					u:SubProc(3, u, Pct100, {0, 0, 0, params[9]})
					Process:ShowPassive(u)
					cnt = cnt + 1
					pv[1] = cnt
					u:SetProcValue(pv, false, Process:Affiliation(Process:UID(true)), Process:localID(Process:UID(true)), Process:Index(true))
					if params[3] > 0 and cnt >= params[3] then
						Buff:Expire()
					end
				end
			end
		else
			Buff:Expire()
		end
	end
end

-- 指定時間毎最大HP累積減少
-- params[1]:指定間隔(フレーム)
-- params[2]:効果最小発動回数
-- params[3]:効果最大発動回数
-- params[4]:最大HP加算最大値
-- params[5]:最大HP倍率最大値
function buff1030502(_target, params)
Field:FrameUpdate(_target)
local coe
local cnt = Buff:GetKeptParam(2)
	if cnt == nil then cnt = 0 Buff:KeepParam(2, 0, CALCULATE_OVR) else cnt = cnt + 1 Buff:KeepParam(2, 1, CALCULATE_ADD) end
	coe = calcCoe(cnt, params[2], params[3])
	this:EditMaxHP(TARGSTAT_REAL, round(params[4] * coe), round(params[5] * coe), 0, LIFETYPE_CONTINUOUS)
end

