-- 黄金の威信(味方側)
-- params[1]:親ユニークID
-- params[2]:発動条件方向
-- params[3]:残りHP条件
-- params[4]:狙われやすさ加算値
-- params[5]:DEF加算値
-- params[6]:DEF倍率
-- params[7]:MND加算値
-- params[8]:MND倍率
function buff1032000(_target, params)
Field:FrameUpdate(_target)
local Over,Under = 1,0
local u = units:GetUnit(params[1])
local flag = false
local buid, ulist, find
-- t = 1:unitList 2:buid
local t = u:GetProcValue(Process:Affiliation(Process:UID(true)), Process:localID(Process:UID(true)), Process:Index(true)) or {}
	if this:Alive() and ((params[2]==Over and this:PerHP() >= params[3]) or (params[2]==Under and this:PerHP() < params[3])) then
		if not toBoolean(t[2]) then
			buid = u:SetBuff(BuffIds.GoldenPrestige, {-1, params[4], params[5], params[6], params[7], params[8]})
			if buid then
				t[2] = buid
				flag = true
			end
		end
	else
		if toBoolean(t[2]) then
			find = false
			for i,j in pairs(units:GetCondUnitList(TARGET_SIDE_ALLY, TARGET_COND_ALIVE, UNIT_COND_NONE)) do
				if j:ID() ~= u:ID() and (params[2]==Over and j:PerHP() >= params[3]) or (params[2]==Under and j:PerHP() < params[3]) then
					find = true
					break
				end
			end
			if not find then
				u:ExpireBuff(t[2])
				t[2] = nil
				flag = true
			end
		end
	end
	if flag then
		u:SetProcValue(t, false, Process:Affiliation(Process:UID(true)), Process:localID(Process:UID(true)), Process:Index(true))
	end
end

