-- 特定UIDバフ効果中特定攻撃時指定確率異常付与
-- params[1]:バフUID
-- params[2]:スキルタイプ条件
-- params[3]:発生確率
-- params[4]:状態異常種類
-- params[5]:状態異常継続時間補正値
-- params[6]:状態異常継続時間倍率
function buff1040000(_target, params)
	Field:FrameUpdate(_target)
	if not Field:IsBuffExists(params[1]) then
		Buff:Expire()
	else
		if lottery(params[3]) then
			if params[5]==0 and params[6]==0 then
				Bullet:Target():SetAilment(params[4])
			else
				-- 状態異常継続時間の変動を可能にするため、外部プロセスからのみ渡せる継続時間補正パラメータを加味して計算する
				Bullet:Target():SetAilment(params[4], math.max(math.floor((AilmentLifeTimes[params[4]] + params[5]) * (1 + (params[6] * Per2Num))), 1))
			end
		end
	end
end

-- 特定バレット検知物理被ダメージ増減
-- 指定したスキルPUIDのタイムラインから発生した特定バレットIDのバレットの処理終了を検知し、
-- ヒットした相手に物理被ダメージ増減バフを掛ける
-- params[1]:スキルPUID条件
-- params[2]:バレットID条件
-- params[3]:継続時間
-- params[4]:ダメージ倍率
-- params[5]:演出レベル
function buff1050200(_target, params)
	Field:FrameUpdate(_target)
	if not Bullet:Target():Alive() then
		Bullet:Target():SetBuff(BuffIds.S_FatalityReservSufferPhysDmgPer, {-1, params[3], params[4], params[5]})
	elseif params[4] < 0 then
		if Bullet:Target():SetBuff(BuffIds.SufferPhysDmgPer, {params[3], params[4]}) then Process:PlayTimelineLv(params[5], false, Buff:Parent(), Bullet:Target()) end
	elseif params[4] > 0 then
		if Bullet:Target():SetBuff(DebuffIds.SufferPhysDmgPer, {params[3], params[4]}) then Process:PlayTimelineLv(params[5], true, Buff:Parent(), Bullet:Target()) end
	end
end

-- 死亡者物理被ダメージ増減予約
-- params[1]:継続時間
-- params[2]:ダメージ倍率
-- params[3]:演出レベル
function buff1050201(_target, params)
	Field:FrameUpdate(_target)
	if params[2] < 0 then
		if Buff:Target():SetBuff(BuffIds.SufferPhysDmgPer, {params[1], params[2]}) then Process:PlayTimelineLv(params[3], false, Buff:Parent(), Buff:Target()) end
	elseif params[2] > 0 then
		if Buff:Target():SetBuff(DebuffIds.SufferPhysDmgPer, {params[1], params[2]}) then Process:PlayTimelineLv(params[3], true, Buff:Parent(), Buff:Target()) end
	end
	Buff:Expire()
end

-- ランナーズハイ制御
-- params[1]:付与間隔(秒)
-- params[2]:継続時間
-- params[3]:効果最小秒数
-- params[4]:効果最大秒数
-- params[5]:ダメージ倍率最大補正
-- params[6]:演出レベル
function buff1050202(_target, params)
Field:FrameUpdate(_target)
local cnt = Buff:GetKeptParam(1) or 0
local beforeCoe = Buff:GetKeptParam(2) or 0
local pv = Buff:Parent():GetProcValue(Process:Affiliation(Process:UID(true)), Process:localID(Process:UID(true)), Process:Index(true)) or {}
local coe,icoe, buid
	if params[1] > 0 and params[1] <= cnt then
		if isNumber(pv[2]) and not Field:IsBuffExists(pv[2]) then pv[1] = 0 end
		pv[1] = (pv[1] or 0) + cnt
		coe = math.max(math.min((pv[1] - params[3]) / (params[4] - params[3]), 1), 0)
		icoe = math.floor(coe * Pct100)
		if coe > 0 then
			buid = this:SetBuff(BuffIds.RunnersHigh, {params[2], 1, round(params[5] * coe), Buff:Parent():ID(), Process:UID(true), Process:Index(true)}, nil, nil, nil, {round(params[5] * coe * Pml2Pct)})
			if buid then
				pv[2] = buid
				if beforeCoe < icoe then
					Process:ShowPassive(Buff:Parent())
				end
				if params[6] > 0 then
					Process:PlayTimeline(5)
				end
			end
		end
		Buff:KeepParam(1, 1)
		Buff:KeepParam(2, icoe)
		Buff:Parent():SetProcValue(pv, false, Process:Affiliation(Process:UID(true)), Process:localID(Process:UID(true)), Process:Index(true))
	else
		Buff:KeepParam(1, 1, CALCULATE_ADD)
	end
end

