local cnt = 0
	Field:FrameUpdate(_target)
	cnt = cnt + #(this:GetVisibleBuff(true))
	for i,j in pairs(this:AilmentList()) do
		if j then cnt = cnt + 1 end
	end
	this:SetProcValue(cnt, true, Process:Affiliation(Process:UID(true)), Process:localID(Process:UID(true)), Process:Index(true))
end

