-- ドライビングハイ制御
-- params[1]:付与間隔(秒)
-- params[2]:継続時間
-- params[3]:効果最小秒数
-- params[4]:効果最大秒数
-- params[5]:ダメージ倍率最大補正
-- params[6]:演出レベル
function buff1050313(_target, params)
Field:FrameUpdate(_target)
local cnt = Buff:GetKeptParam(1) or 0
local beforeCoe = Buff:GetKeptParam(2) or 0
local pv = Buff:Parent():GetProcValue(Process:Affiliation(Process:UID(true)), Process:localID(Process:UID(true)), Process:Index(true)) or {}
local coe,icoe, buid
	if params[1] > 0 and params[1] <= cnt then
		if isNumber(pv[2]) and not Field:IsBuffExists(pv[2]) then pv[1] = 0 end
		pv[1] = (pv[1] or 0) + cnt
		coe = math.max(math.min((pv[1] - params[3]) / (params[4] - params[3]), 1), 0)
		icoe = math.floor(coe * Pct100)
		if coe > 0 then
			buid = this:SetBuff(BuffIds.DrivingHigh, {params[2], 1, round(params[5] * coe), Buff:Parent():ID(), Process:UID(true), Process:Index(true)}, nil, nil, nil, {round(params[5] * coe * Pml2Pct)})
			if buid then
				pv[2] = buid
				if beforeCoe < icoe then
					Process:ShowPassive(Buff:Parent())
				end
				if params[6] > 0 then
					Process:PlayTimeline(5)
				end
			end
		end
		Buff:KeepParam(1, 1)
		Buff:KeepParam(2, icoe)
		Buff:Parent():SetProcValue(pv, false, Process:Affiliation(Process:UID(true)), Process:localID(Process:UID(true)), Process:Index(true))
	else
		Buff:KeepParam(1, 1, CALCULATE_ADD)
	end
end

-- PB_味方HP条件被ダメージ増減付与から味方にかかるバフ
-- params[1]:条件閾値方向
-- params[2]:条件HP閾値
