-- params[4]:親ユニークID
-- params[5]:継続時間
-- params[6]:ダメージ倍率
-- params[7]:演出レベル
function buff1050400(_target, params)
Field:FrameUpdate(_target)
local u = units:GetUnit(params[4])
	if params[6] < 0 then
		if Buff:Target():SetBuff(BuffIds.SufferDmgPer, {params[5], params[6]}) then Process:ShowPassive(u) Process:PlayTimelineLv(params[7], false, u, Buff:Target()) end
	elseif params[6] > 0 then
		if Buff:Target():SetBuff(DebuffIds.SufferDmgPer, {params[5], params[6]}) then Process:ShowPassive(u) end
	end
end

-- PB_仲間想いから味方にかかるバフ
