-- params[7]:HP回復割合(最大HP割合)
-- params[8]:継続時間
-- params[9]:ダメージ倍率
function buff1050401(_target, params)
Field:FrameUpdate(_target)
local u = units:GetUnit(params[4])
local val = math.ceil(u:HP() * params[6] * Per2Num + u:MaxHP() * params[7] * Per2Num)
	if val + params[5] > 0 then u:HealPct(Buff:Target(), math.min(val, u:HP() - 1) + params[5], 0) u:DotDamage(val, false)  Process:ShowPassive(u) end
	if params[9] < 0 then
		if Buff:Target():SetBuff(BuffIds.SufferDmgPer, {params[8], params[9]}) then Process:ShowPassive(u) Process:PlayTimelineLv(1, false, u, Buff:Target()) end
	elseif params[9] > 0 then
		if Buff:Target():SetBuff(DebuffIds.SufferDmgPer, {params[8], params[9]}) then Process:ShowPassive(u) end
	end
end

