-- 騎士王_制御用1
-- params[1]:制限回数
-- params[2]:継続時間
function buff1050501(_target, params)
Field:FrameUpdate(_target)
local buid
local t = Buff:Parent():GetProcValue(Process:Affiliation(Process:UID(true)), Process:localID(Process:UID(true)), Process:Index(true)) or {0, {}, false, {}}
	-- 効果発揮直後にバフを削除すると、効果まで一緒に消えてしまう件の応急処置
	if t[3] then
		Buff:Expire()
	elseif Buff:Parent():Alive() and this:SetEndure(TARGSTAT_WORK, 0, -1, LIFETYPE_TRANSIENT) then
		t[1] = (t[1] or 0) + 1
		Buff:Parent():SubProc(1, this, Pct100, {params[2]})
		Process:ShowPassive(Buff:Parent())
		if params[1] > 0 and t[1] >= params[1] then
			t[3] = true
			for i,buffUid in pairs(t[2]) do
				if buffUid ~= Buff:UID() then
					Field:ExpireBuff(buffUid)
				end
			end
		end
		Buff:Parent():SetProcValue(t, false, Process:Affiliation(Process:UID(true)), Process:localID(Process:UID(true)), Process:Index(true))
	end
end

-- 騎士王_制御用2
-- params[1]:制限回数
-- params[2]:継続時間
function buff1050502(_target, params)
local buid, t
	Field:FrameUpdate(_target)
	local t = this:GetProcValue(Process:Affiliation(Process:UID(true)), Process:localID(Process:UID(true)), Process:Index(true)) or {0, {}, false, {}}
	for i,u in pairs(Process:TrigUnits()) do
		if u:RelativeSide(this) == TARGET_SIDE_ALLY and not toBoolean(t[4][u:ID()]) then
			buid = u:SetBuff(BuffIds.S_KingOfKnightControl_1, {-1, params[1], params[2]})
			if buid then
				table.insert(t[2], buid)
				t[4][u:ID()] = true
			end
		end
	end
	this:SetProcValue(t, false, Process:Affiliation(Process:UID(true)), Process:localID(Process:UID(true)), Process:Index(true))
end

-- 神業_制御用
-- params[1]:バフUID条件
