-- 指定UIDバフ終了時通常ステータスバフ・デバフ消去
-- params[1]:バフUID条件
-- params[2]:消去数
-- params[3]:1:STRバフ可否 2:DEFバフ可否 4:INTバフ可否 8:MNDバフ可否 16:STRデバフ可否 32:DEFデバフ可否 64:INTデバフ可否 128:MNDデバフ可否
function buff1080408(_target, params)
local flag, cnt
local condList
local cateList = {}
local tbl, ctbl, rtbl = {}, {}, {}
local unq, res = {}, {}
	Field:FrameUpdate(_target)
	condList = bitBooleanList(params[3])
	if condList[1] then table.insert(cateList, BUFF_CATEGORY_STR_UP_1) end
	if condList[2] then table.insert(cateList, BUFF_CATEGORY_DEF_UP_1) end
	if condList[3] then table.insert(cateList, BUFF_CATEGORY_INT_UP_1) end
	if condList[4] then table.insert(cateList, BUFF_CATEGORY_MND_UP_1) end
	if condList[5] then table.insert(cateList, BUFF_CATEGORY_STR_DOWN_1) end
	if condList[6] then table.insert(cateList, BUFF_CATEGORY_DEF_DOWN_1) end
	if condList[7] then table.insert(cateList, BUFF_CATEGORY_INT_DOWN_1) end
	if condList[8] then table.insert(cateList, BUFF_CATEGORY_MND_DOWN_1) end
	for i,cate in pairs(cateList) do
		tbl[cate] = {}
		for j,bff in pairs(target:GetBuffCategoryBuffs(cate)) do
			table.insert(tbl[cate], bff[BUFF_INFO_UID])
			flag = false
			for k,r in ipairs(rtbl) do
				if r < bff[BUFF_INFO_REMAIN] then
					table.insert(ctbl, k, cate)
					table.insert(rtbl, k, bff[BUFF_INFO_REMAIN])
					flag = true
					break
				end
			end
			if not flag then
				table.insert(ctbl, cate)
				table.insert(rtbl, bff[BUFF_INFO_REMAIN])
			end
		end
	end
	for i,cate in ipairs(ctbl) do
		if unq[cate] == nil then
			unq[cate] = true
			table.insert(res, 1, cate)
		end
	end
	cnt = 0
	for i,cate in ipairs(res) do
		if params[2] <= 0 or params[2] > cnt then
			for j,buid in pairs(tbl[cate]) do
				target:ExpireBuff(buid)
			end
			cnt = cnt + 1
		else
			break
		end
	end
	Buff:Expire()
end

-- 属性付き特定スキル被弾回数条件指定UIDバフ削除
