-- params[2]:スキルタイプ条件
-- params[3]:被弾回数条件
-- params[4] ～ params[10]:バフUID
function buff1080409(_target, params)
local cnt
	Field:FrameUpdate(_target)
	cnt = (Buff:GetKeptParam(1) or 0) + 1
	if cnt >= params[3] then
		for i = 4,10 do
			if params[i] ~= 0 then
				Field:ExpireBuff(params[i])
			else
				break
			end
		end
		Buff:Expire()
	else
		Buff:KeepParam(1, cnt)
	end
end

