-- 特定状態異常回復時指定UIDバフ削除
-- params[1]:バフUID
-- params[2]:指定間隔
-- params[3]:消費MP値
-- params[4]:消費MP倍率
-- params[5] ～ params[10]:バフUID
function buff1080413(_target, params)
local cost
	Field:FrameUpdate(_target)
	if not Field:IsBuffExists(params[1]) then
		Buff:Expire()
	else
		cost = math.max(math.ceil(params[3] + (this:MaxMP() * params[4] / Pct100)), 1)
		if this:MP() >= cost then
			this:DecMp(params[3], params[4]) 
		else
			for i = 5,10 do
				if params[i] ~= 0 then
					Field:ExpireBuff(params[i])
				else
					break
				end
			end
			Buff:Expire()
		end
	end
end

