-- デビルブレイカー制御
-- params[1]:2番目付与DB_INDEX
-- params[2]:3番目付与DB_INDEX
-- params[3]:4番目付与DB_INDEX
-- params[4]:DB破損確率
function buff1081601(_target, params)
Field:FrameUpdate(_target)
local triggers = {PROC_TRIGGER_DEVIL_BREAKER_1, PROC_TRIGGER_DEVIL_BREAKER_2, PROC_TRIGGER_DEVIL_BREAKER_3, PROC_TRIGGER_DEVIL_BREAKER_4}
local lv = Buff:GetProcValue() or 0
	if this:IsBuffCategory(BUFF_CATEGORY_DEVIL_BREAKER) then
		if lottery(params[4]) then
			lv = lv + 1
			this:RemoveBuff(BUFF_GROUP_DEVIL_BREAKER)
			if lv <= #triggers - 1 and params[lv] ~= 0 then
				this:RaiseTrigger(triggers[params[lv]])
				Buff:SetProcValue(lv, true)
			end
		end
	end
end

