-- 親UID生存中特定状態異常発生時サブプロセス発火
-- params[1]:親ユニークID
-- params[2]:サブプロセスINDEX(0～255)/制限回数(0～255)/発生確率(0～65535)
-- params[3]:状態異常条件
-- params[4] ～ params[10]:サブプロセスパラメータ
function buff1081608(_target, params)
Field:FrameUpdate(_target)
local buid, prm
-- t = 1:count 2:unitList 3:buidList 4:isEnd
local t = Buff:Parent():GetProcValue(Process:Affiliation(Process:UID(true)), Process:localID(Process:UID(true)), Process:Index(true)) or {0, {}, {}, false}
	-- 効果発揮直後にバフを削除すると、効果まで一緒に消えてしまう件の応急処置
	if t[4] then
		Buff:Expire()
	else
		prm = {(params[2]>>24)&255, (params[2]>>16)&255, params[2]&65535}
		if Buff:Parent():SubProc(prm[1], this, prm[3], {params[4], params[5], params[6], params[7], params[8], params[9], params[10]}) then
			t[1] = (t[1] or 0) + 1
			Process:ShowPassive(Buff:Parent())
			if prm[2] > 0 and t[1] >= prm[2] then
				t[4] = true
				for i,buffUid in pairs(t[3]) do
					if buffUid ~= Buff:UID() then
						Field:ExpireBuff(buffUid)
					end
				end
			end
			Buff:Parent():SetProcValue(t, false, Process:Affiliation(Process:UID(true)), Process:localID(Process:UID(true)), Process:Index(true))
			Buff:KeepParam(1, bitBooleanListToVal(this:AilmentList()))
		end
	end
end

