		else
			t[4] = true
			for i,buffUid in pairs(t[3]) do
				if buffUid ~= Buff:UID() then
					Field:ExpireBuff(buffUid)
				end
			end
		end
		Buff:Parent():SetProcValue(t, false, Process:Affiliation(Process:UID(true)), Process:localID(Process:UID(true)), Process:Index(true))
	end
end

-- 守護リブート
-- params[1]:ターゲットID
-- params[2]:最大HP加算値
-- params[3]:DEF加算値
function buff1081613(_target, params)
local u
local res = false
	Field:FrameUpdate(_target)
	u = this:GetProcessTarget(params[1])
	-- avoid for arena replay
	if u == nil then
		return
	end
	for i,j in pairs(Process:TrigUnits()) do
		if j:ID() == this:ID() or j:ID() == u:ID() then
			res = true
			break
		end
	end
	if res and this:Alive() and u:Alive() then
		Process:SubProc(2, u, Pct100, {-1, params[2], 0, 1, 1})
		Process:SubProc(3, u, Pct100, {-1, params[3], 0, 1, 1})
		Process:ShowPassive()
	end
end

