local cnt = (Buff:GetKeptParam(1) or 0) + 1
	if not this:IsBuffCategory(BUFF_CATEGORY_EXCLUSIVE_8) then
		buid = this:SetBuff(BuffIds.AT_SnapBlade, {-1, params[5], params[6]})
		if buid then
			this:SetBuff(BuffIds.S_HaveBuffUidSkillDmgPer, {-1, buid, SKILL_PHYSIC, params[4]})
			this:SetBuff(BuffIds.S_HaveBuffUidDmgLimitBreak, {-1, buid, ELEMENT_UNMENTIONED, SKILL_PHYSIC, params[2], params[3]})
			Process:ShowPassive()
			if params[7] ~= 0 then Process:PlayTimeline(5) end
			if params[1]>0 and params[1]<=cnt then
				this:ExpireBuff(params[8])
				Buff:Expire()
			else
				Buff:KeepParam(1, cnt)
			end
		end
	end
end

