-- 親UID生存中気絶・ブレイク時サブプロセス発火
-- params[1]:親ユニークID
-- params[2]:サブプロセスINDEX(0～255)/制限回数(0～255)/発生確率(0～16383)/対象(所持者:0 親:1)/パッシブ表示有無(0～1)
-- params[3]:エネミータイプ条件
-- params[4] ～ params[10]:サブプロセスパラメータ
function buff1081622(_target, params)
Field:FrameUpdate(_target)
local buid, prm
-- t = 1:count 2:unitList 3:buidList 4:isEnd
local t = Buff:Parent():GetProcValue(Process:Affiliation(Process:UID(true)), Process:localID(Process:UID(true)), Process:Index(true)) or {0, {}, {}, false}
	-- 効果発揮直後にバフを削除すると、効果まで一緒に消えてしまう件の応急処置
	if t[4] then
		Buff:Expire()
	else
		prm = {(params[2]>>24)&255, (params[2]>>16)&255, (params[2]>>2)&16383, (params[2]>>1)&1, params[2]&1}
		if Buff:Parent():SubProc(prm[1], prm[4] == 0 and this or units:GetUnit(params[1]), prm[3], {params[4], params[5], params[6], params[7], params[8], params[9], params[10]}) then
			t[1] = (t[1] or 0) + 1
			if prm[5] ~= 0 then Process:ShowPassive(Buff:Parent()) end
			if prm[2] > 0 and t[1] >= prm[2] then
				t[4] = true
				for i,buffUid in pairs(t[3]) do
					if buffUid ~= Buff:UID() then
						Field:ExpireBuff(buffUid)
					end
				end
			end
			Buff:Parent():SetProcValue(t, false, Process:Affiliation(Process:UID(true)), Process:localID(Process:UID(true)), Process:Index(true))
		end
	end
end

