-- エンゲージリング与ダメージアップ
-- params[1]:バフUID
-- params[2]:効果発生距離
-- params[3]:効果最大距離
-- params[4]:属性条件
-- params[5]:スキルタイプ条件
-- params[6]:与ダメージ最大倍率
function buff1081626(_target, params)
local buff, bid, coe
local compareFunc, t, dist
	Field:FrameUpdate(_target)
	if not Field:IsBuffExists(params[1]) then
		Buff:Expire()
	else
		buff = Field:GetBuffInfo(params[1])
		bid = buff[BUFF_INFO_ID]
		compareFunc = newCompare2(COMPARE_UNDER)
		t = {}
		for i,u in pairs(units:GetCondUnitList(TARGET_SIDE_ALLY, TARGET_COND_ALIVE, UNIT_COND_NONE + UNIT_COND_NOT_ME)) do
			if u:IsBuff(bid) then
				t, dist = compareFunc(u, this:Distance(u))
			end
		end
		if #t > 0 then
			coe = calcCoe(dist, params[2], params[3])
			Bullet:EditDamagePer(round(params[6] * coe) + 1000)
		end
	end
end

