-- params[1]:バフUID
-- params[2]:バフID
-- params[3]:サブプロセスINDEX(0～255)/制限回数(0～255)/発生確率(0～16383)/検索対象(敵+味方：0 敵:1 味方:2 +4:自分を含まない +8:死者を含む +16:死者のみ )/パッシブ表示有無(0～1)
-- params[4]:指定間隔(フレーム)
-- params[5] ～ params[10]:サブプロセスパラメータ
function buff1081635(_target, params)
	Field:FrameUpdate(_target)
	if not Field:IsBuffExists(params[1]) then
		Buff:Expire()
	else
	local cnt = Buff:GetKeptParam(2) or 0
	local prm = {(params[3]>>28)&255, (params[3]>>20)&255, (params[3]>>6)&16383, (params[3]>>1)&31, params[3]&1}
	local flag = false
		for i,u in pairs(units:GetCondUnitList(prm[4]&3, prm[4]&16==16 and TARGET_COND_DEAD or prm[4]&8==8 and TARGET_COND_BOTH or TARGET_COND_ALIVE, UNIT_COND_NONE + (prm[4]&4==4 and UNIT_COND_NOT_ME or 0))) do
			if params[2] == 0 or u:IsBuff(params[2]) then
				Buff:Parent():SubProc(prm[1], u, prm[3], {params[5], params[6], params[7], params[8], params[9], params[10]})
				flag = true
			end
		end
		if flag then
			cnt = cnt + 1
			if prm[5] ~= 0 then Process:ShowPassive(Buff:Parent()) end
			if prm[2] > 0 and cnt >= prm[2] then
				this:SetBuff(BuffIds.S_BuffControl, {-1, Buff:UID()})
			else
				Buff:KeepParam(2, 1, CALCULATE_ADD)
			end
		end
	end
end

