function buff1081639(_target, params)
Field:FrameUpdate(_target)
local cnt = Buff:GetProcValue() or 0
local prm = {(params[2]>>24)&255, (params[2]>>16)&255, (params[2]>>2)&16383, (params[2]>>1)&1, params[2]&1}
	if Buff:Parent():SubProc(prm[1], prm[4] == 0 and this or units:GetUnit(params[1]), prm[3], {params[4], params[5], params[6], params[7], params[8], params[9], params[10]}) then
		if prm[5] ~= 0 then Process:ShowPassive(Buff:Parent()) end
		cnt = cnt + 1
	end
	if prm[2] > 0 and cnt >= prm[2] then
		this:SetBuff(BuffIds.S_BuffControl, {-1, Buff:UID()})
	else
		Buff:CalcProcValue(nil, 1, CALCULATE_ADD)
	end
end

-- 特定PUIDスキル継続中属性付き特定スキル発動時サブプロセス発火
-- params[1]:スキルPUID
-- params[2]:サブプロセスINDEX(0～127)/制限回数(0～255)/発生確率(0～16383)/対象(所持者:0 親:1 スキル対象:2 params[6]で指定:3)/パッシブ表示有無(0～1)
-- params[3]:スキルロール条件
-- params[4]:属性条件
-- params[5]:スキルタイプ条件
-- params[6] ～ params[10]:サブプロセスパラメータ
function buff1081640(_target, params)
local tl, u
	Field:FrameUpdate(_target)
	tl = Field:GetTimeLine(params[1])
	if tl:IsLast() then
		Buff:Expire()
	else
	local cnt = Buff:GetKeptParam(1) or 0
	local prm = {(params[2]>>25)&127, (params[2]>>17)&255, (params[2]>>3)&16383, (params[2]>>1)&3, params[2]&1}
		if prm[4] == 0 then
			u = this
		elseif prm[4] == 1 then
			u = Buff:Parent()
		elseif prm[4] == 2 then
			u = TimeLine:Target()
		elseif prm[4] == 3 then
			u = units:GetUnit(params[6])
		end
		if Buff:Parent():SubProc(prm[1], u, prm[3], prm[4]==3 and {params[7], params[8], params[9], params[10]} or {params[6], params[7], params[8], params[9], params[10]}) then
			if prm[5] ~= 0 then Process:ShowPassive(Buff:Parent()) end
			cnt = cnt + 1
		end
		if prm[2] > 0 and cnt >= prm[2] then
			this:SetBuff(BuffIds.S_BuffControl, {-1, Buff:UID()})
		else
			Buff:KeepParam(1, 1, CALCULATE_ADD)
		end
	end
end

