-- 全体HP条件累積達成状況特定属性特定スキルダメージ上限増減_味方
-- params[1]:条件閾値方向
-- params[2]:条件HP閾値
-- params[3]:効果最小回数
-- params[4]:効果最大回数
function buff1082601(_target, params)
Field:FrameUpdate(_target)
local t = Buff:Parent():GetProcValue(Process:Affiliation(Process:UID(true)), Process:localID(Process:UID(true)), Process:Index(true)) or {}
local beforeCoe = t[3] or 0
	if Buff:Parent():Alive() then
		t[1] = (t[1] or 0) + 1
		t[3] = math.floor(math.max(math.min(((t[1] or 0) - params[3]) / (params[4] - params[3]), 1), 0) * Pct100)
		Buff:Parent():SetProcValue(t, false, Process:Affiliation(Process:UID(true)), Process:localID(Process:UID(true)), Process:Index(true))
		if t[3] ~= beforeCoe then Process:ShowPassive(Buff:Parent()) end
	end
end

