-- イクシード_ダメージ上限増減
-- params[1]:バフカテゴリ条件
-- params[2]:スキル属性条件
-- params[3]:スキルタイプ条件
-- params[4]:効果発生ヒット数
-- params[5]:効果最大ヒット数
-- params[6]:補正下限の上限
-- params[7]:ダメージ上限増減値上限
-- params[8]:ダメージ上限増減倍率上限
function buff1082607(_target, params)
Field:FrameUpdate(_target)
local coeMin, coe
local pv = this:GetProcValue(Process:Affiliation(Process:UID(true)), Process:localID(Process:UID(true)), Process:Index(true)) or 0
	coeMin = math.max(math.min((Bullet:Target():Hits() - params[4]) / (params[5] - params[4]), 1), 0) * params[6] * Per2Num
	coe = (1 - coeMin) * math.random() + coeMin
	if this:IsBuffCategory(params[1]) then coe = coe * 2 end
	if Bullet:EditDamageLimit(round(params[7] * coe), round(params[8] * coe)) then
		this:SetProcValue(coe, false, Process:Affiliation(Process:UID(true)), Process:localID(Process:UID(true)), Process:Index(true))
	end
end

