-- 錬金術
-- params[1]:特技INDEX
-- params[2]:消費MP
-- params[3]:ダメージ上限増減値
-- params[4]:ダメージ上限増減倍率
-- params[5]:与ダメージ倍率
function buff1083200(_target, params)
local skl, puid, buid
	Field:FrameUpdate(_target)
	skl = TimeLine:ParentSkill()
	if skl:Index() == params[1] and skl:Stock() == 0 then
		this:DecMp(params[2])
		puid = TimeLine:SKL_PUID()
		if params[3] ~= 0 or params[4] ~= 0 then
			buid = this:SetBuff(BuffIds.P_TargetSkillPUIDDamageLimit, {-1, puid, params[3], params[4]})
			if buid then this:SetBuff(BuffIds.S_SkillEndBuffControl, {-1, puid, buid}) end
		end
		if params[5] ~= 0 then
			buid = this:SetBuff(BuffIds.P_TargetSkillPUIDDmgPer, {-1, puid, params[5]})
			if buid then this:SetBuff(BuffIds.S_SkillEndBuffControl, {-1, puid, buid}) end
		end
		Process:ShowPassive()
	end
end

-- ギルドハント用HP分割
-- params[1]:HP初期値
-- params[2]:HP最大値
-- params[3]:分割回数
-- params[4]:成長曲線係数
function buff1083400(_target, params)
Field:FrameUpdate(_target)
	-- リモートは処理しない
	if this:IsRemote() then
		return
	end

local cnt = Buff:GetKeptParam(1)
	if cnt == nil then cnt = 1 Buff:KeepParam(1, 1) end
	Process:SetProcEventValue(PROC_TRIGGER_HP_BREAK, cnt)
	if cnt > params[3] then
		this:UpdateSplitHp(0)
		if Field:IsLoadedUI(UI_NAME_DROP_ITEM) and Field:GetItemDropTableCount() >= cnt - 1 then this:ItemDrop(cnt - 1) end
		Buff:Expire()
	elseif cnt == params[3] then
		this:UpdateSplitHp(0)
		if Field:IsLoadedUI(UI_NAME_DROP_ITEM) and Field:GetItemDropTableCount() >= cnt - 1 then this:ItemDrop(cnt - 1) end
		this:RaiseTrigger(PROC_TRIGGER_HP_BREAK, 0, RAISE_TRIGGER_OPTION_NOT_REMOTE + RAISE_TRIGGER_OPTION_FORCE_EXECUTE)
	elseif cnt > 1 then
		this:UpdateSplitHp(math.floor(params[1] + ((params[2] - params[1]) * ((cnt - 1)/(params[3] - 1)) ^ (params[4] * Per2Num))))
		if Field:IsLoadedUI(UI_NAME_DROP_ITEM) and Field:GetItemDropTableCount() >= cnt - 1 then this:ItemDrop(cnt - 1) end
		this:RaiseTrigger(PROC_TRIGGER_HP_BREAK, 0, RAISE_TRIGGER_OPTION_NOT_REMOTE + RAISE_TRIGGER_OPTION_FORCE_EXECUTE)
	end
	Buff:KeepParam(1, 1, CALCULATE_ADD)
end

-- 超必錬金術
-- params[1]:クエスト毎制限回数
-- params[2]:超必殺技INDEX
-- params[3]:消費MP
-- params[4]:ダメージ上限増減値
-- params[5]:ダメージ上限増減倍率
-- params[6]:与ダメージ倍率
function buff1083900(_target, params)
Field:FrameUpdate(_target)
local skl, puid, buid, flag
local pv = Buff:Parent():GetProcValue(Process:Affiliation(Process:UID(true)), Process:localID(Process:UID(true)), Process:Index(true)) or {cnt = 0, data = {}}
	skl = TimeLine:ParentSkill()
	if (params[1] <= 0 or pv.cnt < params[1]) and skl:Index() == params[2] and this:Ether() < skl:Cost() then
		this:DecMp(params[3])
		puid = TimeLine:SKL_PUID()
		if params[4] ~= 0 or params[5] ~= 0 then
			buid = this:SetBuff(BuffIds.P_TargetSkillPUIDDamageLimit, {-1, puid, params[4], params[5]})
			if buid then this:SetBuff(BuffIds.S_SkillEndBuffControl, {-1, puid, buid}) end
		end
		if params[6] ~= 0 then
			buid = this:SetBuff(BuffIds.P_TargetSkillPUIDDmgPer, {-1, puid, params[6]})
			if buid then this:SetBuff(BuffIds.S_SkillEndBuffControl, {-1, puid, buid}) end
		end
		pv.cnt = pv.cnt + 1
		if (params[1] > 0 and pv.cnt >= params[1]) then
			for i,tbl in pairs(pv.data) do
				if tbl[2] ~= nil then
					if tbl[2] ~= Buff:UID() then this:ExpireBuff(tbl[2]) end
					pv.data[i][2] = nil
				end
			end
			flag = true
		end
		Buff:Parent():SetProcValue(pv, true, Process:Affiliation(Process:UID(true)), Process:localID(Process:UID(true)), Process:Index(true))
		Process:ShowPassive()
		if flag then Buff:Expire() end
	end
end

-- カリスマ_制御用
-- params[1]:アクターUID
-- params[2]:バフUID
function buff2000000(_target, params)
	Field:FrameUpdate(_target)
	this:ExpireBuff(params[2])
	Buff:Expire()
end

-- カリスマ_後付制御用
-- params[1]:バフUID
-- params[2]:バフID
-- params[3]～params[10]:バフパラメータ
function buff2000001(_target, params)
local buid
	Field:FrameUpdate(_target)
	for i,u in pairs(Process:TrigUnits()) do
		if u:ID()==this:ID() then
			this:ExpireBuff(params[1])
			Buff:Expire()
			return nil
		end
	end
	for i,u in pairs(Process:TrigUnits()) do
		if u:RelativeSide(this) == TARGET_SIDE_ALLY and not u:IsBuff(params[2]) then
			buid = u:SetBuff(params[2], {-1, params[3], params[4], params[5], params[6], params[7], params[8], params[9], params[10]})
			if buid then u:SetBuff(BuffIds.C_Control, {-1, this:ID(), buid}) end
		end
	end
end

-- アニマ_制御用
-- params[1]:アクターUID
-- params[2]:バフUID
function buff2000050(_target, params)
	Field:FrameUpdate(_target)
	this:ExpireBuff(params[2])
	Buff:Expire()
end

-- アニマ_後付制御用
-- params[1]:バフID
-- params[2]～params[10]:バフパラメータ
function buff2000051(_target, params)
Field:FrameUpdate(_target)
local bCtrl = Field:GetValue(FIELD_VALUE_ANIMA_CONTROL_INFO)
local buid, ulist
	if not this:Alive() or (isTableOrClass(bCtrl) and bCtrl[1] ~= nil and bCtrl[1] ~= this:ID()) then
		Buff:Expire()
		if not this:Alive() and isTableOrClass(bCtrl) and bCtrl[1] == this:ID() then Field:SetValue(FIELD_VALUE_ANIMA_CONTROL_INFO, nil) end
	else
		ulist = Process:TrigUnits()
		if next(ulist) == nil then
			ulist = units:GetCondUnitList(TARGET_SIDE_OPPONENT, TARGET_COND_BOTH, UNIT_COND_NONE)
		end
		for i,u in pairs(ulist) do
			if u:RelativeSide(this) == TARGET_SIDE_OPPONENT and not u:IsBuff(params[1]) then
				buid = u:SetBuff(params[1], {-1, params[2], params[3], params[4], params[5], params[6], params[7], params[8], params[9], params[10]})
				if buid then u:SetBuff(BuffIds.C_Control, {-1, this:ID(), buid}) end
			end
		end
	end
end

