-- params[2]:女性専用被ダメージ倍率
function buff2050401(_target, params)
	Field:FrameUpdate(_target)
	if not this:IsRemote() then
		this:SetBuff(BuffIds.S_HaveBuffUidOwnerGenderElemSkillDmgPer, {-1, Buff:UID(), GENDER_MALE, ELEMENT_UNMENTIONED, 0, params[1]})
		this:SetBuff(BuffIds.S_HaveBuffUidOwnerGenderSufferElemSkillDmgPer, {-1, Buff:UID(), GENDER_FEMALE, ELEMENT_UNMENTIONED, 0, params[2]})
	end
end

-- カリスマ_グラッフル
