-- params[3]:一刀時樹属性ダメージ上限加算値
-- params[4]:魔法被ダメージ倍率
function buff2050402(_target, params)
	Field:FrameUpdate(_target)
	if not this:IsRemote() then
		if params[1] ~= 0 then this:SetBuff(BuffIds.S_HaveBuffUidElemSkillDmgPer, {-1, Buff:UID(), ELEMENT_TREE, skillTypeArrayToInt32({[SKILL_SKILL] = true, [SKILL_SPECIAL] = true}), params[1]}) end
		if params[2] > 0 then this:SetBuff(BuffIds.S_HaveBuffUidDmgLimitBreak, {-1, Buff:UID(), ELEMENT_TREE, skillTypeArrayToInt32({[SKILL_SKILL] = true, [SKILL_SPECIAL] = true}), params[2], 0}) end
		if params[3] > 0 then this:SetBuff(BuffIds.S_SingleWeaponHaveBuffUidDmgLimitBreak, {-1, Buff:UID(), 0, ELEMENT_TREE, skillTypeArrayToInt32({[SKILL_SKILL] = true, [SKILL_SPECIAL] = true}), params[3], 0}) end
		if params[4] ~= 0 then this:SetBuff(BuffIds.S_HaveBuffUidSufferSkillDmgPer, {-1, Buff:UID(), SKILL_MAGIC, params[4]}) end
	end
end

