-- params[4]:被ダメージ上限加算値
-- params[5]:被ダメージ上限倍率補正
function buff2050452(_target, params)
	Field:FrameUpdate(_target)
	if (params[1] ~= 0 or params[2] ~= 0) and Field:IsPvP() then this:EditRecoverSCT(TARGSTAT_REAL, params[1], params[2]) end
	if params[3] ~= 0 then this:SetBuff(BuffIds.S_HaveBuffUidSufferMultiElemSkillDmgPer, {-1, Buff:UID(), ELEMENT_ICE, ELEMENT_ICE, ELEMENT_ICE, ELEMENT_ICE, ELEMENT_ICE, ELEMENT_ICE, 0, params[3]}) end
	if params[4] ~= 0 or params[5] ~= 0 then this:SetBuff(BuffIds.S_HaveBuffUidSufferDmgLimitBreak, {-1, Buff:UID(), ELEMENT_ICE, 0, params[4], params[5]}) end
end

